window.HB_TR["isaiah"]["ks"]=["1.\\tاموزُک نیچو یسعیاہ سُند وژن، یُس تٔمۍ یہوداہ تہٕ یروشلم کِس زمانس مَنٛز وُچھمُت اوس، یُس یہوداہ کِس بادشاہن ہٕندِس زمانس مَنٛز وُچھمُت۔\n2. اے آسمان، بوزو تہٕ بوز زمین، کیازِ خداوند چُھ کتھ کٔرمٕژ، مے کٔر پرورش تہٕ بچہٕ پرورش کٔرۍمٕتۍ، تہٕ تِمو کٔر میانہِ خلاف بغاوت۔\n3.\\tبیل چھہ پننس مٲلکس زانان تہ گٔرِ چھہ پننس مٲلک سٕندِس کۅکرس زانان: {مگر} اسرٲیلِس چھہ نہ پتاہ، میانہِ قوم چھہ نہ سوچان۔\n4. اے گۅنہگار قوم، یُس بدکار سٍتـ̡ بٔرِتھ لُکھ چُھہ، بدکارن ہُند بیول چُھہ، یِمو چُھہ خداوند ترٲومُت، تِمو چُھ اِسرٲیلِس پاک سٍتـ̡ غصہٕ دِژمُت، تِم گٔیہِ پتھ کُن۔ {لادن: ہیب۔ وزن} {گٔیہِ...: ہیب۔ بیگانگی، یا، علیحدٕ}\n5.\\tژیہ کیازِ گژھہِ مزید دکھ دِنہٕ؟ تۅہہ کٔرِو زیادٕ کھۅتہٕ زیادٕ بغاوت: سورُے کلہٕ چُھ بیمار، تہٕ سورُے دِل چُھ بے ہوش۔ {بغاوت...: ہیب۔ بغاوتس منز اضافہ}\n6.\\tکھورِ پیٹھہ کلس تام چھہ نہ اتھ منز کانہہ صومت۔ {مگر}زخم، زخم تہٕ زخم تہٕ زخم: تم چھہِ نہ بند کرنہٕ آمٕتۍ، نہ بند، نہ مرہم سٍتۍ نرم کرنہٕ آمٕتۍ۔ {مرہم: یا، تیل}\n7. تُہند مُلُک {چُھ} ویران ، تُہند شہر {چُھ} نارٕ سٍتۍ زالنہٕ آمُت: تُہند سرزمین، اجنبی چھِ تُہنزِ موجودگی منز کھٮ۪وان، تہٕ {یہ} چھُ ویران ، یِتھ کٔنۍ اَپرَن ہٕندِ دٔسۍ پُراونہٕ آمُت۔ {الٹاونہٕ آمُت...: ہیب۔ اَتھ مَنٛز چھُ اَکھ مَضموٗن ہُنٛد اَکھ ا\n8. تہٕ صیون سٕنز کورِ چھے انگورن ہٕندِس باغس مَنٛز أکِس گھرس منز، ککڑن ہٕندِس باغس مَنٛز، أکِس محاصرٕ شدٕ شہرس پٲٹھۍ۔\n9.\\tلشکرن ہٕندِس رب سٍتـ̡ اسہِ سٍتـ̡ واریاہ لۄکُٹ باقیات ترووُن، اسہِ پزِ سدوم ہٕندۍ پٲٹھۍ، {تہٕ} أسـ̡ گومورہ ہٕندۍ پٲٹھۍ۔\n10. اے سدوم کِس حکمرانو، خداوند سُند کلام بوزو۔ سٲنِس خدایہ سٕندِس قانونس کٔرِو بوزُن، اے گومورہ ہٕندِس لوکو۔\n11.\\tچانہِ قربانی کتھ مقصدس پیٹھ چھہِ میانہِ خاطرہ؟ خداوند چُھس فرماوان: بہٕ چُھس ریمَن ہٕنزِ زٲلِتھ نذرانہ سٍتـ̡ بٔرِتھ تہٕ چارہ دِنہٕ آمٕژ درندَن ہٕنزِ چربی سٍتـ̡ بٔرِتھ چُھس۔ تہٕ بہٕ چُھس نہٕ بیلن ہٕندِس خونس سٍتـ̡ خۅش سپدان۔ {سُہ چھُ بَٹہٕ کَران۔ گریٹ سُہ گوٹس}\n12.\\tییلہ تہۍ میہ برونہہ کنہِ پیش سپدِو، میانہِ عدالتس منز قدم تراونہٕ خٲطرٕ کُس چُھس یہِ ضروری؟ {ظٲہر گژھُن: ہیب۔ وچھنہٕ خٲطرٕ}\n13.\\tمزید بے کار قربانی نہ انن؛ بخور چُھ میانہِ خٲطرٕ اکھ مکروہ ۔ نوِ زوٗن تہٕ سبت ، مجلسن ہٕنز بُلاون، بہٕ ہیوٚک نہٕ ژٔلِتھ۔ {یہِ} چھُ بدکاری، حتیٰ کہ سنجیدہ ملاقات۔ {بدکاری: یا، غم}\n14. چانہِ نوِ زوٗن تہٕ تُہٕندِس مُقرر شُدٕ دعوتس سٍتـ̡ چُھہ میانہِ خٲطرٕ مُشکِل ۔ بہٕ چُھس تِمن برداشت کرنہٕ خٲطرٕ تھوٚکمت ۔\n15.\\tتہٕ ییلہ ژیہ پنٕنۍ اتھہٕ پھٔہلٲوِو، بہٕ کٔرٕ ژے نِش پنٕنۍ أچھ پوشہٕ، آ، ییلہ تہٕ ژٕ واریاہ دُعا کٔرِو، بہٕ بوزٕ نہٕ بہٕ: چانہِ اتھہٕ چھِ خونس سٍتـ̡ بٔرِتھ۔ {بناوُن...: ہیب۔ دُعا ضرب کٔرِو} {خون: ہیب۔ بلڈز}\n16. واش کرُن، صاف کرُن؛ میانین اچھن برونہہ کنہِ ترٲو پننہ بد کاری دور۔ بد کار کرُن بند کرُن؛\n17. اصل کرُن ہیچھِو۔ فیصلہٕ ژھارُن، مظلومن راحت دِنۍ، بے باپ سُند فیصلہ کرُن، بیواہ ہٕندِ خٲطرٕ التجا کٔرِو۔ {ریلیف: یا، رائٹن}\n18.\\tیِہ چُھہ یِمن ہٕندِس سٍتـ̡ یِمن ہٕندِس سٍتـ̡ یێلہِ تہٕ تێلہِ گژھہِ تێلہِ سٍتـ̡ سُہ چُھہ یێلہِ سٍتـ̡ سٍتـ̡ سٍتـ� یوٚدوے تِم وۄزٕل آسن، تِم آسن ییرٕکۍ پٲٹھۍ۔\n19. اگر تم رضامند تہٕ فرمانبردار ٲسو، تیلہِ گژھو زمینچ خیر کھیوٚن:\n20. مگر اگر اِنکار کٔرِو تہٕ بغاوت کٔرِو، تیٚلہِ یِیہِ تلوار سٍتـ̡ کھٮ۪نہٕ، کیازِکہِ خداوند سٕندِ ٲسِس چُھ کَتھ کٔرمٕژ۔\n21.\\tوفادار شہر کِتھہ پاٹھۍ چھہ بدکار بنان۔ یہ اوس فیصلہٕ سۭتۍ بٔرتھ۔ اَتھ مَنٛز چھُ نیکی دِنہٕ آمٕژ؛ مگر وۄنۍ قاتل۔\n22.\\tتُہند رۄپہٕ چُھہ آبہٕ سٍتـ̡ رَلاونہٕ آمُت:\n23.\\tتُہٕندِ شہزادٕ چھِ باغی تہٕ چورن ہٕندِس سٲتھی: پرٮ۪تھ کانہہ چھُ تحفہٕ پسند کران، تہٕ ثواب پَتہٕ پَتہٕ پَتہٕ چھُ یِوان: تِم چھِنہٕ بٔرِس سٍتـ̡ انصاف کَران، تہٕ بیواہ ہُند مقصد چُھ تِمن تام واتان۔\n24. تێمہِ کِنۍ چُھ خداوند یُس لشکرن ہُند رب چُھ، یُس اسرٲیلُک طاقتور چُھ، آہ، بہٕ کٔرٕ پننین دشمنن نِش کم تہٕ پننین دُشمنن ہُند بدلہٕ کٔرِتھ:\n25.\\tتہٕ بہٕ کٔرٕ ژے پیٹھ اتھہٕ پھیُر، تہٕ خالص کٔرِتھ تُہند سٲرۍسٕے ٹِن: {خالص: حب۔ پاکیزگی مطٲبق}\n26. تہٕ بہٕ کٔرٕ تُہٕندِس مُشیرن ہٕندِس گۅڈنِکِس پٲٹھۍ، تہٕ تُہٕندِس مُشیرن ہٕندِس آغازس پٲٹھۍ، پَتہٕ یِیہٕ ژے وَننہٕ یِن، نیکی ہُند شہر، وفادار شہر۔\n27. صیون گژھہِ فیصلہٕ سٍتـ̡ نجات دِنہٕ، تہٕ تٔمۍ سٕندِس مذہبس سٍتـ̡ ییہِ نیکی سٍتـ̡ نجات دِنہٕ۔ {یہِ...: یا، تِم یِم أمِس واپس چھِ}\n28.\\tتہٕ گۅنہگارن تہٕ گۅنہگارن ہٕنز تباہی گژھہِ یکوٹہ سپدٕن، تہٕ یُس خداوند ترٲوِتھ روزِ تِم گژھن ختم کرنہٕ۔ {تباہی: ہیب۔ بریکنگ}\n29. تِم گژھن تِمن اوکَن سٍتـ̡ شرمندٕ یِم تۅہہِ یژھان چھِو، تہٕ یِمن باغن ہٕندِ خٲطرٕ گژھِو تۅہہِ ژٲرِمٕتـ̡ ۔\n30. تِکیازِ تُہۍ ٲسِو أکِس بلوطٕکۍ پٲٹھۍ، یٔمِس پنہٕ وُن چھُ، تہٕ أکِس باغٕکۍ پٲٹھۍ یُس نہٕ آب آسہِ۔\n31.\\tتہٕ طاقتور گژھہِ لۅتہِ ہیو تہٕ امیک بناون وول آسہِ چنگاری ہٕندۍ پٲٹھۍ، تہٕ تِم دۅشوے گژھن اکوٹہٕ دزان، تہٕ کانہہ تہِ کرِ نہٕ یِمن ہٕندِس دٔسۍ دٔزِتھ۔ {میکر...: یا، تہٕ تٔمۍ سٕنز کٲم}","1.\\tسُہ لفظ یُس اموز سٕندِس نیچوِس یسعیاہ یہوداہ تہٕ یروشلمس مُتلق وُچھمُت۔\n2. تہٕ یہِ گژھہِ ٲخری دۅہن مَنٛز سپدُن، {یُس}خداوند سٕندِ گرُک پہاڑ گژھہِ پہاڑن ہٕندِس تینتٲلِس پیٹھ قایم کرنہٕ، تہٕ یِیہِ بالہٕ پیٹھٕ تھزر۔ تہٕ تمام قومن گژھن اتھ کُن وسان۔ {قائم: یا، تیار}\n3. تہٕ واریاہ لُکھ گژھن تہٕ ونن، یێلہِ تہٕ أسۍ گژھو خداوند سٕندِس پہاڑس پیٹھ، یعقوب سٕندِس خدایہ سٕندِس گرس تام۔ تہٕ سُہ ہیٚچھناوِ اسہِ پَنٕنـ̡ وتہٕ پى۪ٹھ، تہٕ أسـ̡ پَکُن تٔمۍ سٕنزِ وتہِ پى۪ٹھ، تکیازِ صییون پى۪ٹھہٕ نیرِ شریعت تہٕ خداوند سُند کلام یروشلم پیٹھ۔\n4. تہٕ سُہ کرِ قومن مَنٛز فٲصلہٕ، تہٕ واریاہن لوٗکن ملامت کرِ۔ تہٕ تِم کرِ پنٕنۍ تلوار ہل تہٕ نیزٕ ژٔٹِتھ ژٔٹِھتھ تہٕ قوم تُلِن نہٕ قومس خلاف تلوار تُلنہٕ، تہٕ نہ کرِ تِم مزید جنگ ہیچھن۔ {pruninghooks: or, scythes}\n5. اے یعقوب سٕندِس گرس پٔکِو، تہٕ أسۍ پٔکِو خداوند سٕندِس گاشس مَنٛز پَکُن۔\n6. تێمہِ کِنۍ چُھہ ژے پَنٕنـ̡ لُکہٕ یعقوب سُند گرٕ ترٲومُت، تِکیازِ تِم چِھ مشرقس سٍتـ̡ بٔرِتھ بٔرِتھ تہٕ تِم چِھہ فلسطینن ہٕندِس شُرین سٍتـ̡ خوش گٔژھان۔ {منز...: یا، تمہ کھوتہ زیادہ} {مہربانی...: یا، بٔرِتھ دِ}\n7.\\tتِہُند زمین تہِ چُھہ رۄپہٕ تہٕ سۄنہٕ سٍتـ̡ بٔرِتھ، تہندِ خزانہٕ سٍتـ̡ چُھہ نہٕ کانہہ اند۔ تِہٕنٛز زمین تہِ چھِ گُرٮ۪و سۭتۍ بٔرِتھ، نَہ چھُنہٕ تِہٕنٛدِ رتھَن ہُنٛد کانٛہہ اند:\n8.\\tتِہُند سرزمینہٕ تہِ چھُ بُتَو سٍتۍ بٔرِتھ۔ تِم چھِ پننین اتھن ہٕنزِ کامہِ ہٕنز پوجا کران، یُس تِمن ہٕنزِ اونگجہِ ہٕندِس کامہِ سٍتـ̡ بنوومُت چُھ:\n9.\\tتہٕ کُنہِ سٍتـ̡ کٔرِتھ چُھہ بٔڈِس سٍتـ̡ کٔرِتھ تہٕ بٔڈ شخٕص چُھہ پانس عاجز ک\n10.\\tکٔنہِ منز اژُن تہٕ ژٔلِتھ تہٕ تٔمۍ سٕندِس عظمتس سٍتـ̡ ژٔلِتھ ۔\n11.\\tانسان سٕنزِ تھدِ نظرن گژھہِ عاجز کرنہٕ، تہٕ انسانن ہُند غرور گژھہِ نمُن، تہٕ اَمہ دۅہہٕ گژھہِ صرف خداوند سُند بلند۔\n12.\\tخداوند لشکرن ہُند دۅہ آسہِ پرٮ۪تھ أکِس پیٹھ یُس مغرور تہٕ تھوٚد آسہِ، تہٕ پرٮ۪تھ کُنہِ سٍتـ̡ یُس تُلِتھ آسہِ۔ تہٕ سُہ یِیہِ بۄن کَرنہٕ:\n13. تہٕ لبنان کین سارنٕے دیودارس پیٹھ، یُس تھدِ تہٕ تھزرس پیٹھ تہٕ بشان کین سارنٕے اوکس پیٹھ،\n14. تہٕ سارِنٕے تھدٮ۪ن بالن پیٹھ، تہٕ سارِنٕے بالن پیٹھ،\n15. تہٕ پرٮ۪تھ تھدِ مینارس پیٹھ، تہٕ پرٮ۪تھ کُنہِ باڑ وٲلِس دیوارس پیٹھ،\n16.\\tتہٕ ترشِش کِس سارِنٕے جہازس پیٹھ، تہٕ سارِنٕے خۄشگوار تصویرن پیٹھ۔ {خوشگوار...: ہیب۔ خواہشٕچ تصویرٕ}\n17. تہٕ انسان سُند تھزرٕ گژھہِ نمُن، تہٕ انسانن ہُند غرور گژھہِ کم کرنہٕ، تہٕ اَمہ دۅہہٕ گژھہِ صرف خداوند سُند تھزر۔\n18.\\tتہٕ یِم بُت کرِ سُہ پوٗرٕ پٲٹھۍ۔ {یہ...: یا، گژھہِ مکمل طور گزرُن}\n19. تہٕ تِم گژھن خداوند سٕندِ خوفہٕ سٍتـ̡ تہٕ تٔمۍ سٕندِس جلال سٕندِ عظمتس مۅکھہٕ کٔنـ̡ پتھرن ہٕندِس سوراخس مَنٛز تہٕ زمینہِ ہٕندِس غارس مَنٛز گژٕھن۔ {زمینہٕ: ہیب۔ گردِ ہُند}\n20.\\tاَمہِ دۅہہٕ کرِ اَکھ شخٕص پَنٕنـ̡ رۄپہٕ ہٕندِ بُت، تہٕ سۄنہٕ سٕندِ بُت، یِم تِمو پانس خٲطرٕ بنوومٕتـ̡ ، تِمن تہٕ راتہٕ کرٛیٖلن سٍتـ̡ ۔ {تٔمۍ سٕندِ رۄپہٕ ہٕندِس بُتھ...: ہیب۔ تٔمۍ سٕنٛدِ رۄپہٕ ہٕندۍ بُت، بیترِ} {پرٮ۪تھ کُن...: یا، أمِس خٲطرٕ}\n21. خداوند سٕندِ خوفہٕ سٍتـ̡ تہٕ تٔمۍ سٕندِس جلال سٕندِس جلال سٍتـ̡ کھسنہٕ خٲطرٕ، یێلہِ سُہ زمینہِ ہٕندِس خوفس سٍتـ̡ وۅتھان چُھ۔\n22.\\tانسان سٕندِس نِش کٔرِو یٔمۍ سٕندِس نَس مَنٛز شہس {چُھ} چُھ، تٔمِس کَمہِ خٲطرٕ چُھ حساب دِنہٕ یُن؟","1. یِکیازِ، وُچھِو، خداوند یُس لشکرن ہُند رب چُھ، یروشلم تہٕ یہوداہ نِش چھُ روزُن تہٕ لٔرۍ، روٹی ہُند سورُے روزُن، تہٕ آبُک سورُے قیام نِوان۔\n2. طاقتور انسان، تہٕ جنگی شخص، قاضی تہٕ پیغمبر، تہٕ ہوشیار تہٕ قدیم،\n3.\\tپنژاہ ہُند کپتان، تہٕ معزز انسان، تہٕ مُشیر، تہٕ چالاک کاریگر تہٕ فصیح مقرر۔ {محترم ...: ہیب۔ بُتھِ منز نامور شخص} {فصاحت...: یا، ہنرمند کتھ باتھ}\n4. تہٕ بہٕ دِیہٕ شُرۍ تِہٕندِ شہزادٕ تہٕ بچہٕ یِمن پیٹھ حُکوٗمت کرٕنۍ۔\n5. تہٕ عوامس گژھہِ ظلم کرنہٕ، پرٮ۪تھ أکِس سٍتـ̡ تہٕ پرٮ۪تھ أکِس سٍتـ̡ ہمساے سٍتـ̡\n6.\\tییلہ کانہہ انسان پننِس مٲلہِ سٕندِس گرس ہٕندِس بٲے سٍتـ̡ رٔٹِتھ {ونِتھ}، ژے چُھہ پوشہٕ پٲٹھۍ، تہٕ یہ بربادی گژھہِ پننِس اتھس تلہٕ:\n7. اَمہِ دۅہہٕ چُھہ سُہ قَسم کَرِتھ زِ بہٕ بنہٕ نہٕ شفا دِنہٕ۔ تکیازِ میٲنِس گرس مَنٛز چُھ نہٕ روٹی تہٕ نہ پلو: مے بناو نہٕ لوکن ہُند حکمران۔ {قسم: ہیب۔ اَتھٕ تُلِو} {شفا بخش: ہیب۔ binder up}\n8. یێلہِ یروشلم چُھہ برباد گومُت، تہٕ یہوداہ گۆو پۯاوُن: تِکیازِ تِہٕنزِ زبان تہٕ تِہٕنزِ کٲم چِھہ خداوند سٕندِس خٕلاف، تٔمۍ سٕندِس جلال ہٕنزِ نظرن ہُند اشتعال دِنہٕ مۅکھہٕ۔\n9. تِہُند بُتھ چھُ تِمن خلاف گواہی دِوان۔ تہٕ تِم چھِ پنُن گۅناہ سدوم قرار دِوان، تِم چھِ نہٕ ژوٗرِ تھاوان۔ تِہٕندِس روحس ہُند افسوس! تکیازِ تِمو چُھ پانس بُرِس سٍتـ̡ دِژمُت۔\n10.\\tصالحن ونِو زِ تِم گژھہِ تِمن ہٕندِس کامہِ ہُند پھل کھٮ۪نہٕ۔\n11. بدکارن ہٕندِ خٲطرٕ افسوس! {یہِ آسہِ} بُرٕ {أمِس سٍت} کیازِ تٔمِس دِنہٕ یِیہِ تٔمِس اتھن ہُند اجر دِنہٕ۔ {دِنہٕ آمُت...: ہیب۔ أمِس کٔرِتھ کرنہٕ}\n12.\\tمیانہِ لوک، شُرۍ چھہِ تِہندِ ظالم، تہٕ زنانہ چھیہ تمن پیٹھ حکمرٲنی کران۔ اے میٲنۍ لوکو، یِم تۅہہِ گمراہ کران چھِ، تہٕ تُہنزِ وتہِ برباد کَران۔ {لیڈ...: یا، وَنُن ژے بابرکت وَن} {تباہ: ہیب۔ نگلُن}\n13. خداوند چُھ دُعا کرنہٕ خٲطرٕ کھڑا سپدان تہٕ لوکن ہُند فیصلہ کرنہٕ خٲطرٕ کھڑا سپدان۔\n14.\\tخداوند کرِ پننین لوکن ہندین پرانین تہٕ تمن ہٕندِس شہزادن سٍتـ̡ فیصلہٕ کٔرِتھ، کیازِ تۅہہ چُھہ انگور کھیوٚمُت۔ غریبن ہُند غنیمت چُھ تہندٮ۪ن گَرن منز۔ {کھٮ۪نہٕ: یا، دزنہٕ}\n15.\\tتۅہہ کیا مطلب چھُکھ میانین لوکن ٹُکرٕ ٹُکرٕ کٔرِتھ تہٕ غریبن ہٕندِس بُتھِس گٔژھِتھ دِوان۔ خداوند خدایہ چُھ وَنان۔\n16.\\tامہ علاوہ چھہ خداوند فرماوان، کیازِ صییونچ کورِ چھیہ مغرور آسان، تہٕ گردن تہٕ بے راہ روی أچھ کٔرِتھ پکان۔ اچھن سیتۍ دھوکہ دِن} {mincing: یا، اَصٕل پٲٹھۍ}\n17. تێمہِ کِنۍ کرِ خداوند صیہون چہ کورِ ہٕندِس کلُک تاجس سٍتـ̡ کھورِ سٍتـ̡ تہٕ خداوند کرِ تِمن ہٕندِس راز سٍتـ̡ دِنہٕ۔ {دریافت: ہیب۔ ننگہٕ بناوُن}\n18.\\tاَمہِ دۅہہٕ نِیہِ خداوند تِمن ہٕندِس کھورَن مَنٛز {تِہٕندِ} ٹِنٕکِس زیورات تہٕ {تِہٕندِ} گول ٹٲر تہٕ {تِہٕندِ} گول ٹٲر ہٕنز بہادری نِش نِنہٕ\n19.\\tزنجیر، تہٕ کٔرۍ، تہٕ مفلر، {زنجیر: یا، مٔٹھۍ بالہٕ} {مفلرز: یا، چمکدار زیورات}\n20. بونٹ، تہٕ زنگن ہٕندۍ زیورات، تہٕ کلہٕ بینڈ، تہٕ گولہٕ، تہٕ بالہٕ، {گولہٕ: ہیب۔ روحک گھر}\n21.\\tوٲج تہٕ نَس ہٕندِس جواہرات،\n22.\\tبدلن وول سوٹ، تہٕ پردٕ، تہٕ وِمپٕل، تہٕ کرسپنگ پِن،\n23. شیش، تہٕ عمدہ کُن، تہٕ ہُڈ تہٕ وایل۔\n24.\\tتہِ گژھہِ یہ سپدِ، {یُس} مٔدٕرِ بجایہ گژھہِ بدبو۔ تہٕ گرڈٕ بدلہٕ کرایہٕ؛ تہٕ اصل پٲٹھۍ سیٹ مس گنج بجایہ؛ تہٕ پیٹ بدلہٕ کٔرِتھ کٔرِتھ کٔرِتھ۔ {تہٕ}خوبصورتی بدلہٕ دزان۔\n25. تُہٕندِ نفر گٔیہِ تلوار سٍتـ̡ تہٕ جنگس مَنٛز تُہٕندِس طاقتس سٍتـ̡ پۯاوٕنـ̡ ۔ {Mighty: Heb. شاید}\n26. تہٕ تٔمۍ سٕندِ دروازٕ گژھن ماتم تہٕ ماتم کرنہٕ۔ تہٕ سۅ {آسن} ویران گژھہِ زمینس پیٹھ بِہتھ۔ {ویران : یا، خٲلی: ہیب۔ صاف کٔرِتھ}","1. تہٕ اَمہِ دۅہہٕ گژھن سَتھ زنانہٕ أکِس مردس رٔٹِتھ ونان زِ أسۍ کھیون پنُن روٹی تہٕ پَنُن پَلَو لاگُن: صرف گژھہِ اسہِ پنُن ناوس سٍتـ̡ بُلاونہٕ یُن، پنُن ملامت دوٗر کرنہٕ خٲطرٕ۔ {let...: Heb. چانۍ ناو گژھہِ اسہِ پیٹھ پکارنہٕ یُن} {نِنہٕ خٲطرٕ...: نتہٕ نِش نِن}\n2. اَمہِ دۅہہٕ گژھہِ خداوند سٕنز لٔر خوبصوٗرت تہٕ شاندار تہٕ زمینُک پھل آسہِ تِمن ہٕندِ خٲطرٕ بہترین تہٕ خوبصورت یُس اسرٲیلِس نِش ژلِتھ آسہِ۔ {خوبصورت...: ہیب۔ خوبصورتی تہٕ عظمت} {تِم...: ہیب۔ فرار گژھُن}\n3. تہٕ یُس یُس صہیونس مَنٛز روزان چُھ، تہٕ یُس یروشلمس مَنٛز روزان چُھ، سُہ گژھہِ مقدس وننہٕ یُن، {حتیٰ کہ} یُس یروشلمس مَنٛز زندٕ روزن والین مَنٛز لیکھنہٕ آمُت چُھ: {among...: or, to life}\n4. یێلہِ خداوند صیون چہِ کورِ ہٕنز گندگی چھلناوِ، تہٕ یێلہِ یروشلمُک خون چُھہ فیصلہٕ کِس روحہٕ سٍتـ̡ تہٕ دزنہٕ سٍتـ̡ پاک کرُن۔\n5. تہٕ خداوند کرِ صیہون پہاڑ کِس پرٮ۪تھ أکِس مکانس پیٹھ، تہٕ تٔمۍ سٕنزِ مجلسن پیٹھ، دۅہلہٕ اوٚبر تہٕ دھونہٕ، تہٕ رٲژ دزنہٕ وٲلِس نارس سٍتـ̡ چمکُن، تکیازِ سارِنٕے جلال سٍتـ̡ آسہِ بچاو۔ {سارِنٕے پیٹھ: یا، سارِوٕے کھۄتہٕ زیادٕ} {دفاع: ہیب۔ کور کٔرِتھ}\n6. تہٕ دۅہلہِ گرمی نِش تہٕ پناہ گاہٕ خٲطرٕ تہٕ طوفانس تہٕ روٗد نِش روزنہٕ خٲطرٕ آسہِ اکھ خیمہ ۔","1.\\tوۅنۍ گٮ۪وٕ بہٕ پننِس معشوقس پننِس معشوقس سٍتۍ اکھ بٲتھ یُس تٔمۍ سٕندِس انگورس اتھہٕ لاگان چھُ۔ میٲنِس معشوقس چُھ أکِس سٮ۪ٹھاہ پھلہٕ دار بالس مَنٛز انگور باغ: {a very...: Heb. تیلُک نیچو سُند ہارن}\n2. تہٕ تٔمۍ کٔر اتھ تار تہٕ اَمہ کِس کٔنہِ کٔڈِتھ تہٕ لوٚگُن بہترین انگور تہٕ اتھ منز بنووُن اکھ مینار تہٕ اَتھ منز بنووُن شرابُک دباو تہٕ۔ {باڑ لگٲوتھ: یا، اکھ دیوار بنوو} {بنیومُت: ہیب۔ ہیوڈ}\n3. تہٕ وُنۍ، اے یروشلم کین بسکینو تہٕ یہوداہ کِس انسانو، مُنصیب، بہٕ چُھس ژےٚ دُعا کران زِ میانہِ تہٕ میٲنِس انگورس درمِیان کٔرِو۔\n4.\\tمیٲنس انگورس منز کیا ہیکہِ بییہ کٔرتھ، یُس نہ میہ اتھ منز کورمُت چھُ؟ کیازِ ییلہ میہ وچھ زِ یہ گژھہِ انگور نیرُن، اوٚن جنگلی انگور۔\n5. تہٕ وۅنۍ گژھِ؛ بہٕ وَنُن ژے کیا کرٕ بہٕ پننِس انگورس سٍتۍ: بہٕ نِیہٕ اَمہ ہُند باڑ تہٕ یہ کھٮ۪نہٕ یِنہٕ۔ {تہٕ} اَمہ کِس دیوارس پھُٹراوُن، تہٕ یہِ یِیہِ لَتہٕ دِنہٕ: {trodden...: Heb. ٹریڈنگ خٲطرٕ}\n6. تہٕ بہٕ کٔرٕ یہ ضایع: یہ گژھہِ نہ ژٹنہٕ تہٕ نہ کھننہٕ یُن۔ مگر تتہِ گژھن کۅکرِ تہٕ کانٹۍ: بہٕ دِیہ اوٚبرن تہِ حکم زِ تِم گژھن نہ اتھ پیٹھ روٗد برسان۔\n7.\\tخداوند لشکرن ہٕندِس انگور باغس منز چُھ اسرٲیلُک گرٕ تہٕ یہوداہ ہٕندِس مردس سٍتـ̡ تٔمۍ سُند خۅش کُل، تہٕ سُہ اوس فیصلہٕ ژھانڈان، مگر وُچھِو ظُلم۔ نیکی خٲطرٕ، مگر وُچھو اکھ فریاد۔ {امس...: ہیب۔ تٔمۍ سٕنزِ لذتن ہُند کُل} {ظلم: ہیب۔ اکھ سکیب}\n8.\\tتِمن ہُند افسوس یُس گرٕ گَرٕ رٔلِتھ چھُ، {یُس} کھہٕ کھہٕ بٔنِتھ، یوٚت تام نہٕ کانہہ جاے آسہِ، یُس تِم زمینہِ منز کُنی زٔنِتھ تھاونہٕ یِن! {تِم: ہیب۔ یے}\n9.\\tمیانین کنن مَنٛز {وۆن} رب لشکر، پٔزۍ پٲٹھۍ گژھن واریاہ گرٕ ویران تہٕ عظیم تہٕ خوبصورت، بسکیٖن بغیر۔ {منز...: یا، یہ چھہ میانین کنن منز، رب چھہ ونان وغیرہ} {آف ا...: ہیب۔ اگر نہ، وغیرہ}\n10. آ، داہ ایکڑ انگور سٍتـ̡ دِیہِ اَکہِ باتھ تہٕ ہومر سٕندِس بیٲلِس سٍتـ̡ دِیہِ اکھ ایفاہ۔\n11.\\tتِمن ہٕندِ خٲطرٕ افسوس یِم صُبحہ سُلہٕ وۅتھان چھِ، {یُتھ} تِم گژھن تیز شرابٕچ پیروی کٔرِتھ۔ یُس راتس تام جٲری روزان چُھ، {ٹِل} شراب چُھ تِمن دِوان! {infflame: of, pursue}\n12. تہٕ ہارپ، تہٕ وایول، ٹیبرٹ، پائپ تہٕ شراب، چِھہ پننین دعوتن مَنٛز، مگر تم چِھ نہٕ خداوند سٕنزِ کامہِ ہُند خیال تھاوان، تہٕ نہ چِھ تٔمۍ سٕندِس اتھن ہٕندِس عملس پیٹھ غور کران۔\n13.\\tتێلہِ گۆو میانہِ لُکھ قٲد، تکیازِ تِمن چھُنہٕ کانہہ علم: تہٕ تِہٕندِ عزتدار مرد چھِ فاقہٕ کٔرِتھ تہٕ تِہُند بٔڈ گٔیہِ ترشہٕ سٍتـ̡ خشک گومُت۔ {محترم...: ہیب۔ جلال چھِ قحطٕکۍ مرد}\n14. تێمہِ کِنۍ چُھ جہنمن پانس بٔڑٲومُت، تہٕ چُھس پَنُن چُھہ بےٚ پیمانہٕ کھولُن: تہٕ تِہُند عظمت، تہٕ تِہُند تعداد، تہٕ یُس خوش سپدِ، سُہ گژھہِ اَتھ مَنٛز وسان۔\n15.\\tتہٕ کُنہِ کُنہِ سٍتـ̡ یِیہِ بٔرِتھ تہٕ بٔرِس سٕنزِ أچھ یِیہِ عاجز کرنہٕ۔\n16. مگر لشکرن ہُند رب گژھہِ انصافس مَنٛز بلند، تہٕ یُس خدا پاک چُھ، یُس پاکیزگی سٍتـ̡ پاک سپدِ۔ {خدا...: یا، مقدس خدا: ہیب۔ خدایہ مقدس}\n17.\\tتیلہِ گژھن کٹہٕ بچہٕ پننہِ طریقہٕ سٍتـ̡ کھٮ۪نہٕ، تہٕ موٹٮ۪ن ہٕنزِ کُنہِ جایہِ کھٮ۪نہٕ یِن۔\n18.\\tتِمن ہٕندِ خٲطرٕ افسوس یِم بےٚ کار رَزِ سٍتـ̡ گۅناہ کٔرِتھ، تہٕ گۅناہ ہٕندِس سٍتـ̡ یِتھٕ پٲٹھـ̡ گاڑِ ہٕنزِ رزِ سٍتـ̡ گۅناہ کران چھِ:\n19.\\tیہ ونو زِ سُہ گژھہِ جلدی کرُن، تہٕ یُس اسہِ وُچھِتھ تہٕ اسرٲیلِس پاک سُند مشورٕ گژھہِ نزدیک، یُتھ أسۍ زانہِ۔\n20.\\tتِمن ہٕندِ خٲطرٕ افسوس یِم بد تہٕ نیکی بد ونان چھِ۔ یُس گاشس بدلہٕ انہِ گوٚٹ تہٕ گاش چھُ گاشس بدلہٕ گاش۔ یُس موٚدُر بدلہٕ تلخ تہٕ موٚدُر بدلہٕ موٚدُر! {کال...: ہیب۔ بدی متعلق ونو یہ چھہ خیر بیترِ}\n21.\\tتِمن ہٕندِس نظرِ سٍتـ̡ دانا تہٕ پننین نظرن منز ہوشیار آسن تِمن ہٕندِ خٲطرٕ افسوس! {تہندِس نظرس منز: ہیب۔ تہندس بُتھس برونہہ کنہِ}\n22. تِمن ہٕندِ خٲطرٕ افسوس، یُس شراب چیٚنہٕ خٲطرٕ طاقتور چُھ، تہٕ طاقتور نفرن ہٕندِس سٍتـ̡ رَلاونہٕ خٲطرٕ:\n23.\\tیُس بدکارن انعامن ہُند جواز دِوان چھُ، تہٕ نیکوکارن ہٕنز نیکی چھِ أمِس نِش نِش نِوان۔\n24. یێلہِ یێلہِ نار کھٮ۪وان چُھ، تہٕ نار چُھہ کھالہٕ کھٮ۪وان، تِتھے پٲٹھـ̡ گژھہِ تِہُند موٗل گٔژِھتھ تہٕ تِہُند پھول گٔژھہِ گردِ ہٕندِس پٲٹھۍ، کیازِ یِمو چُھ لشکرن ہٕندِس خداوند سُند شریعت ترٛٲومُت، تہٕ کٔرٕکھ اسرٲیلِک پاک سٕندِس کلامَس حقارت۔ {نار: ہیب۔ نارٕچ زبان}\n25. تێمہِ کِنۍ چُھ خداوند سُند غصہٕ پننِس لُکن سٍتـ̡ دِنہٕ آمُت، تہٕ تِمن سٍتـ̡ دِژُن پَنُن اَتھٕ تہٕ دِژُن تِمن ہٕندِس سٍتـ̡ تہٕ تِمن ہٕندِس لاشہٕ گٔیہِ سڑکن مَنٛز پھٔٹِتھ ۔ امہِ سارِوٕے کِنۍ چھُنہٕ تٔمۍ سُند شَرارتہٕ پھیُراونہٕ آمُت، مگر تٔمۍ سُند اَتھٕ چھُ وُنہِ تہِ پھٔہلِتھ۔ {پھٔٹۍ: یا، گوبر پٲٹھۍ گوبر}\n26. تہٕ سُہ تُلِہ دوٗرِ پیٹھٕ قومن خٲطرٕ اکھ جھنڈٕ تُلِتھ، تہٕ زمینہٕ کِس اندٕ پیٹھٕ کرِ تِمن نِش ہِش تہٕ وُچھِن تِم تیز رفتاری سان یِوان:\n27. تِمن منز گژھِ نہٕ کانہہ تھکان تہٕ ٹھوکر کھسنہٕ۔ کانہہ تہِ گژھہِ نہ نندر تہ نندر تہِ۔ نہ گژھہِ تِمن ہٕندِس کمرس ہُند لوٚٹ یلہٕ تہٕ نہ گژھِ تِہندِ کھورِ ہُند لوٚٹ پھُٹُن:\n28.\\tیمۍ سٕندِ تیر تیز، تہٕ تِہندِ سارِنٕے کمان چھِ، تہندٮ۪ن گُرٮ۪ن ہٕندِ کھُر گٔنزراوٕن، تہٕ تِہٕندِ چکرٕ یِن وُپھ ہٕندۍ پٲٹھۍ:\n29.\\tتِہُند گُرٕ چُھہ شیرٕکۍ پٲٹھۍ، تِم گٔژھن شیرن ہٕندۍ پٲٹھۍ، آ، تِم گٔرِن شِکارس تھپھ کٔرِتھ، تہٕ نِنہٕ یِنہٕ سٍتـ̡ تہٕ کانہہ تہِ دِیہِ نہٕ۔\n30.\\tتہٕ تمہِ دۅہہ گژھن تِمن سمندرٕچ گُرجہِ ہٕندۍ پٲٹھۍ، تہٕ یێلہِ زمینس کُن نظر تراوُن، وُچھِن انہِ گٹہِ تہٕ غم، تہٕ گاش چھُ آسمانس مَنٛز گٔژھان۔ {غم: یا، پریشانی} {تہٕ گاش...: یا، ییلہ یہ گاش آسہِ، سہ گژھہِ امہِ چہ تباہی منز انہِ گوٚٹ}","1. یێمہِ ؤریس منز بادشاہ عزیاہ مٔرۍ، میہ وُچھ رب تہِ أکِس تختس پیٹھ بِہتھ، تھدِ تھوٚد تہٕ تھوٚد تہٕ تٔمۍ سٕنزِ ٹرینہِ ٲس مندرس بٔرِتھ۔ {امس...: یا، امکۍ سکرٹ}\n2.\\tاتھ پیٹھ ٲس سیرافیم کھڑۍ: پریتھ اکس ٲسۍ شیہ پکھ۔ دۅشوے سیتۍ کور تمۍ پنن بُتھ تھپھ تہ دۅشوے سیتۍ کور پنن کھور، تہ دۅشوے سیتۍ اوس سہ وُڈان۔\n3.\\tتہٕ اَکھ وۆن بییِس کُن فریاد تہٕ وونُن، پاک، {چُھ} لشکرن ہُند رب چھُ، سورے زمین چھے تٔمۍ سٕندِ جلال سٍتـ̡ بٔرِتھ۔ {اکھ...: ہیب۔ یہ اوس اتھ کُن فریاد دِژمُت} {پورٕ...: Heb. تٔمۍ سُند جلال چُھ پورٕ زمینُک پورٕ}\n4.\\tتہٕ دروازٕکۍ ستون گٔیہِ أمِس سٕنزِ آوازِ سٍتۍ ہلکان تہٕ مکانہٕ گٔیہِ دھوکہٕ سٍتۍ بٔرِتھ۔ {دروازہ: ہیب۔ تھریشولڈز}\n5.\\tاَمہ پتہٕ ووٚن مے، ہا ہا میہ چھُ! تکیازِ بہٕ چُھس نہٕ ختم گومُت۔ تکیازِ بہٕ چُھس ناپاک وُٹھن ہُند انسان، تہٕ بہٕ چُھس ناپاک وٕٹھن ہٕندِس لُکن منز روزان: کیازِ میانہِ أچھن وُچھمُت بادشاہ، یُس لشکرن ہُند رب چھُ۔ {undone: Heb. کٹ آف}\n6.\\tاَمہ پتہٕ وُڈۍ میہ کُن اکھ سیرافیم، اتھس منز اکھ زِندٕ ژیلہٕ، {یُس} یُس تٔمۍ قربان گاہس پیٹھٕ ٹانگہٕ سٍتۍ نِمُت اوس: {ہاوُن...: ہیب۔ تہٕ تٔمۍ سٕنٛدس اتھس منٛز اکھ زندٕ کوئلہٕ}\n7. تہٕ تٔمۍ تھوو میٲنس ٲسس پیٹھ، تہٕ وونُن، یہ چُھس چُھس چُھس لوٚگمُت۔ تہٕ تُہند گناہ چُھ ختم کرنہٕ آمُت، تہٕ تُہند گناہ چُھ پاک کرنہٕ آمُت۔ {لیڈ...: ہیب۔ اَتھ کٔرِتھ چھُ اَتھ مَضموٗنَس مَنٛز\n8.\\tمیہ بوز خداوند سٕنز آواز یُس ونان چُھ، بہٕ کُس سوزٕ تہٕ کُس گژھہِ اسہِ خٲطرٕ؟ امہ پتہ ووٚن میہ یتھے {am} I؛ مے سوز۔ {یتہِ...: ہیب۔ وچھ مے}\n9.\\tتہٕ ووٚن، گژھ تہٕ أمِس لُکن وَنُن، بوزو پٔزۍ پٲٹھۍ، مگر سمجھ نہٕ۔ تہٕ وچھو پزۍ پٲٹھۍ، مگر سمجھ نہٕ۔ {پٔزۍ، مگر سمجھو: یا، رُکاونہٕ ورٲے وغیرہ: ہیب۔ سماعتس منز، وغیرہ}\n10. یِمن لُکن ہُند دِل کرُن موٚٹ، تہٕ تِمن ہٕندِس کَن گٔژھِتھ تہٕ أچھ بند کٔرِتھ۔ یێلہِ تِم گژھن پننیو أچھو سٍتـ̡ وُچھن، تہٕ کَنَو سٍتـ̡ بوزنہٕ، تہٕ دِلہٕ سٍتـ̡ سمجُن، تہٕ بدلاوٕن، تہٕ شفا گٔژھن۔\n11. پتہٕ ووٚن میہ خداوند، کوتاہ وقت؟ تہٕ تٔمۍ دیُت جواب، یوتام نہٕ شہر بسکیٖن ورٲے تباہ گژھن، تہٕ مکانہٕ بغٲر انسانہٕ گژھن، تہٕ زمین گژھن بالکل ویران گژھن، {بلکل...: ہیب۔ ویران گٔیہِ}\n12. تہٕ خداوند کٔر انسان دور دور، تہٕ زمینس مَنٛز چُھ اکھ بٔڈ ترک کرُن۔\n13.\\tمگر توتہِ آسہِ اتھ منز دہم حصہ، تہٕ یہ گژھہِ واپس تہٕ کھٮ۪نہٕ یِن: یِتھٕ پٲٹھۍ چھُ اکھ ٹیل کُلِ، تہٕ بلوط ہٕندۍ پٲٹھۍ، یٔمۍ سُند مادہ {چُھ} تِمن مَنٛز چُھ، یێلہِ تِم پنہٕ ؤتھٕر تراوان چھِ، یێلہِ تِمن ہُند مادہ آسہِ۔ {تہٕ یہ...: یا، ییلہ یہ واپس، تہٕ وُپھ آو کرنہٕ} {مادہ: یا، سٹاک، یا، سٹیم }","1. تہٕ یہِ سپُد یہوداہ کِس بادشاہ عزیاہ سٕندِس نیچو عزیاہ سٕندِس نیچو آحاز سٕندِس دۅہس مَنٛز سپُد، شامُک بادشاہ رِزین تہٕ اسرائیلُک بادشاہ رِمالیہ سُند نیچو پیکاہ یُس یروشلم کُن جنگ کرنہٕ خٲطرٕ ووت مگر ہیوٚک نہٕ اتھ خلاف فتح حٲصل کٔرِتھ۔\n2.\\tتہٕ داؤد سٕندِس گرس مَنٛز آو وننہٕ زِ شام چُھ افرائیمس سٍتـ̡ اتحاد۔ تہٕ تٔمۍ سُند دِل گۆو تہٕ تٔمۍ سٕندٮ۪ن لوکن ہُند دِل، یُتھ زن لٔکرِ ہٕندۍ کُلۍ ہوہس سٍتۍ ہلکان چھِ۔ {کنفیڈریٹ...: ہیب۔ آرام کٔرِتھ}\n3.\\tاَمہِ پَتہٕ ووٚن خداوند یسعیاہ سٍتـ̡ وۆن، وۅنۍ گژھ آہز، تہٕ شیرجاشوب پننِس نیچوِس سٍتـ̡ مِلنہٕ خٲطرٕ، یُس فلر سٕندِس کھاہس منز پیٹھمہِ تالاب کِس نالہِ ہٕندِس اندس پیٹھ نیرِ۔ {شیرجاشوب: یعنی باقیات گژھہِ واپس} {ہائی وے: یا، کاز وے}\n4. تہٕ أمِس وَنُن زِ ہوشیار روزُن تہٕ ژھۄپہٕ کرُن۔ خوفہٕ گژھ نہٕ یِمن دھواں دِنہٕ والٮ۪ن دۅن لٔچن ہٕندِس دۅن لٔچن ہٕندِس سٍتۍ تہٕ شامس سٍتۍ رِزین سٕندِس شدید غصہٕ سٍتۍ تہٕ رِمالیہ سٕندِس نیچوِس سٍتۍ تہٕ رِمالیہ سٕندِس نیچوِس سٍتۍ گژھ نہٕ بے ہوش۔ {نہ تہِ...: ہیب۔ چانہِ دِل گژھہِ نہٕ نرم آسُن}\n5.\\tکیازِ شام، افرائیم تہٕ رملیاہ سٕندِس نیچوِس چُھ تۅہہِ خلاف بد مشورٕ دِژمُت،\n6.\\tاسہِ گژھو یہوداہ سٍتـ̡ تہٕ یێمہِ سٍتـ̡ پى۪ٹھ\n7. یِتھٕ پٲٹھـ̡ چُھ خداوند خدایہ ونان زِ یہِ گژھہِ نہٕ کھڑا تہٕ نہ گژھہِ یہِ سپدُن۔\n8.\\tشامُک سربراہ {is} دمشق، تہٕ دمشقُک سربراہ {is} ریزن۔ تہٕ تریہ تہٕ پانژن ؤرین اندر گژھہِ افرائیم پھُٹراونہٕ، یُس نہٕ اکھ قوم آسہِ۔ {یہ...: ہیب۔ اَکہِ لُکہٕ سٕندِس سٍتـ̡\n9.\\tتہٕ افرائیم سُند کلہٕ تہٕ سامریہ سُند کلہٕ چُھ رملیاہ سُند نیچو۔ اگر نہ یقین کرو تیلہِ ہیکو نہ قائم سپدِو۔ {اگر...: یا، کیا تُہۍ چھِو نہٕ یقین کران؟ اَمیُک وجہ چھُ زِ تُہۍ چھِو نہٕ مستحکم آسان}\n10.\\tامہِ علاوہ وۆن رب آحازس سٍتـ̡ دُبارٕ کتھ کٔرِتھ، {بییہِ...: ہیب۔ تہٕ خداوند کٔر کتھ کرنہٕ خٲطرٕ اضافہٕ}\n11.\\tپنہٕ نِس خدایہ سٕنز نشانی پرژھہٕ۔ یہ پرژھو یا تہ گہرایی منز، نتہ پیٹھمہِ تھزرس منز۔ {پرژھو...: یا کرو پنٕنۍ عرضی گہرا}\n12.\\tمگر احازن ووٚن بہٕ پرژھہٕ نہٕ تہٕ نہ کرٕ بہٕ خداوند سٕندِس آزمائشس سٍتـ̡ ۔\n13.\\tتہٕ ووٚن، اے داؤد سٕندِس گھرس سٍتـ̡ بوزو۔ {کیا یہ} تۅہہِ ہٕندِ خٲطرٕ لۅکٹ کتھ چھےٚ، مگر کیا تُہۍ چھِو میانہِ خدایہ تہِ تھکان ؟\n14. تَمہِ کِنۍ دِیہِ خداوند پانہٕ تۄہہِ اکھ نشانہٕ۔ وچھ اکھ کنواری حاملہ تہٕ نیچو زیٚیہ، تہٕ أمس ناو عمانویل ناو۔ {بلاو: یا، تو، اے کنواری، بلاو}\n15. سُہ گژھہِ بُرِس نِش انکار کرُن، تہٕ نیکی ہُند انتخاب کرُن۔\n16. تکیازِ امہ برونہہ زِ شُرۍ گژھہِ بدی نِش انکار کرُن، تہٕ نیکی ہُند انتخاب کرُن، سُہ زمین یُس ژے نفرت کران چھُ، سُہ زمین گژھہِ پننین دۅشوٕے بادشاہن نِش تراونہٕ یُن۔\n17.\\tخداوند کرِ توے تہٕ تۅہہِ سٕندِس لوکَس پیٹھ، تہٕ تہندِس مٲلہِ سٕندِس گرس پیٹھ، یُس نہٕ یُس نہٕ یُس افراہم یہوداہ پیٹھٕ نیران چُھ۔ {حتیٰ کہ} اسریاہُک بادشاہ۔\n18.\\tتہٕ یہ سپدِ تمہِ دۅہہٕ سپدِ، {یُس}خداوند کرِ تٔمِس مکِس خٲطرٕ یُس مصر کِس دریاوَن ہٕندِس اندِس حصس مَنٛز {چُھ}، تہٕ اَسِریہٕ کِس سرزمینس مَنٛز {چُھ} ماچھ ہٕندِ خٲطرٕ۔\n19. تہٕ تِم یِن تہٕ یِم سارِنٕے ویران وادین منز، تہٕ کٔنٮ۪ن ہٕندِس سوراخن منز، سارِنٕے کانٹَن تہٕ سارنٕے کُنہِ تہٕ سارنٕے کُنہِ {جھاڑی: یا، قابل تعریف کُل}\n20. اَمی دۅہہٕ گژھِ خداوند اَکہِ استرا سٍتـ̡ کھوٗر کٔرِتھ، یُس دٔریاوٕ اپارِ یِمن ہٕندِس دٔرِس سٍتـ̡ کلہٕ تہٕ کھورِ ہُند مَس آسہِ۔\n21.\\tتہٕ تمہِ دۅہہ سپدِ یہِ زِ اَکھ انسان کرِ أکِس جوان گاو تہٕ زٕ دانٛد رچھُن۔\n22.\\tتہٕ یێلہِ گژھہِ دۄدٕ سٍتـ̡ یُس تِم دِنہٕ سٍتـ̡ چُھہ سُہ کھٮ۪نہٕ یُس زمینس مَنٛز بَچُھہٕ روزُن۔ {زمین: ہیب۔ زمینس منٛز}\n23.\\tتہٕ یہ سپدِ تمہِ دۅہ، {یُس} پریتھ جایہ آسہِ، ییتہِ ساس رۅپہٕ سٍتـ̡ ساس بیل آسہِ، سُہ آسہِ برِین تہٕ کانٹَن ہٕندِ خٲطرٕ۔\n24.\\tتیر تہٕ کمانہٕ سٍتـ̡ یِن {انسان} تتہِ یِن۔ تکیازِ سورے زمین گژھہِ کۅکرِ تہ کانٹہ بنان۔\n25.\\tتہٕ سارِنٕے بالہٕ یِم گٹہٕ سٍتـ̡ کھنٛنہٕ یِن، تتہِ گژھہِ نہٕ کۅکرِ تہٕ کانٹَن ہُند خوف یِنہٕ، بلکہ آسہِ یہِ بیلن ہٕندِ سوزنہٕ خٲطرٕ، تہٕ کم چارواین ہٕندِس قدمس مۅکھہٕ۔","1.\\tامہِ علاوہ چھہ رب میہ ووٚنمُت، ژے رٔٹِتھ اکھ بٔڈ رول تہٕ اتھ منز لیکھِکھ مہرشلالہش بازس متعلق۔ {مہرشلالہشباز: ہیب۔ غنیمتس تام تیز رفتاری دِنس منز چھہ سہ شکارس جلدی کران، یا رفتار بناوان بیترِ}\n2. تہٕ مے رٔٹۍ وفادار گواہ یوریاہ پادٕر، تہٕ زکریاہ یبریخیاہ سُند نیچو۔\n3. تہٕ بہٕ گۆو پیغمبرن نِش۔ تہٕ أمِس گٔیہِ حاملہٕ، تہٕ کوٚرُن اکھ نیٚچُو۔ اَمہِ پتہٕ ووٚن رب مےٚ زِ أمۍ سُنٛد ناو وَنُن مہرشلالہشباز۔ {گٔیہ: ہیب۔ اپروچس}\n4.\\tیِہ زِ شُرِس روُنُک علم گژھہِ، میانہِ مول تہٕ میانہِ موج، دمشقٕچ دولت تہٕ سامریاہٕچ غنیمت یِن اسریاہٕکِس بادشاہس برونہہ کُن نِنہٕ۔ {دولت...: یا، یُس اسریاک بادشاہس برونہہ کُن آسہِ، سہ گژھہِ دولت نِتھ وغیرہ}\n5.\\tخداوند تہِ ووٚن میہ سٍتـ̡ بییہِ وونُن،\n6. یێلہِ لُکھ چھُ شیلوہٕکِس آبس نِش انکار کران یُس نرمی سان وسان چھُ، تہٕ ریزن تہٕ رملیاہ سٕندِس نیچوِس سٍتـ̡ خوش سپدان۔\n7. تێمہِ وُن، وُچھِو خداوند تِمن پیٹھ دٔریاوُک آب یُس مضبوٗط تہٕ واریاہ چھُ، حتیٰ کہ اشورُک بادشاہ تہٕ تٔمۍ سُند سورُے جلال تہٕ سُہ گژھہِ پنہٕ نِس سارِنٕے نالہِ پیٹھ، تہٕ پنہٕ نِس سارِنٕے بٔٹھِس پیٹھ۔\n8. تہٕ سُہ گژھِ یہوداہ کِنۍ نیرُن۔ سُہ گژھہِ وُچھِتھ تہٕ اَتھ تام واتہِ، سُہ گژھہِ گردنہِ تام وٲتِتھ۔ تہٕ تٔمۍ سٕندِ پَکھہٕ سٍتـ̡ پھٔہلِتھ بٔرِتھ چُھہ تُہٕندِس زمینہٕ سٍتـ̡ بٔرِتھ، اے عمانویل۔ {کھینچ ...: ہیب۔ چانہِ زمینہِ ہٕندِس پکھہٕ سٍتـ̡ پھٔلِتھ آسہِ}\n9. اے لوکو، رٔلِو پان رٔلِو، تہٕ یِم گژھِو ٹُکرٕ ٹُکرٕ کرنہٕ۔ تہٕ دِیُو، سارِنٕے دورِ مُلکن ہٕندِس سٍتـ̡ رٔٹِو، تہٕ ژٔٹِو ٹُکرٕ ٹُکرٕ کرنہٕ۔ پَنُن پان رٔٹِو، تہٕ یِیہِ ٹُکرٕ ٹُکرٕ کرنہٕ۔ {لوٗکھ تہٕ: یا، لوک، توتہِ}\n10. یکوٹہ مشورٕ کرُن، تہٕ یہ گژھہِ ناکام۔ لفظ بولو، تہٕ یہ گژھِ نہٕ کھڑا روزُن: کیازِ خدا چُھ اسہِ سٍتـ̡ ۔\n11.\\tکیازِ خداوند کٔر میہ سٍتـ̡ مضبوطہٕ اتھہٕ سٍتـ̡ کتھ کرنہٕ، تہٕ دیتُن میہ ہدایت زِ بہٕ پزِ نہٕ یِمن لُکن ہٕنزِ وتہِ منز پکان تہٕ وونُن، {سٍت...: ہیب۔ اَتھٕ کِس طاقتس منز}\n12.\\tیہ ونو نہ، اکھ کنفیڈریسی، سارِنٕے سٍتـ̡ یِمن سٍتـ̡ یہ لوکھ وَنُن، اکھ کنفیڈریسی؛ تہندِس خوفس منز گژھہِ نہ کھوژان تہ نہ کھوژُن۔\n13. لشکرن ہٕندِس خداوند سٕندِس پانہٕ پاک کرُن؛ تہٕ {آسُن} سُہ {آسُن} پنُن خوف، تہٕ {آسُن} پنُن خوف۔\n14. تہٕ سُہ گژھِ أکِس مقدس مقامس خٲطرٕ آسُن۔ مگر ٹھوکر کھسنہٕ خٲطرٕ تہٕ اسرائیلٕکۍ دۄشوٕنی گرن خٲطرٕ جرم کرنہٕ خٲطرٕ، اکھ جِن تہٕ یروشلم کین بسکینن خٲطرٕ پھنساونہٕ خٲطرٕ۔\n15. تہٕ یِمو منزٕ واریاہ گژھن ٹھوکر کھسنہٕ، تہٕ پٔسِتھ پھُٹنہٕ یِن، پھُٹنہٕ یِن، تہٕ یِن رٔٹنہٕ۔\n16.\\tگوٲہی بند کرُن، میانین شاگردن منز کٔرِو شریعت مُہر ۔\n17. تہٕ بہٕ کَرٕ خداوند سُند انتظار، یُس یعقوب سٕندِس گرس نِش بُتھ ژوٗرِ تھاوان چُھ، تہٕ بہٕ کَرٕ أمِس ژھانڈان۔\n18.\\tوُچھو، میہ تہٕ تِم شُرۍ یِم خداوند میہ دِژمٕژ چھِ، یُس صیہون کِس پہاڑس مَنٛز روزان چُھ، یُس اسرٲیلِس مَنٛز لشکرن ہٕندِس خداوند سٕندِ طرفہٕ معجزاتن تہٕ عجائب خٲطرٕ دِژمُت چھُ۔\n19. تہٕ ییلہ تِم تۅہہِ وَنُن، تِمن نِش ژھٲرِو یِمن واقف روح آسہِ، تہٕ تِمن جادوگرن نِش یِم نظر دِوان چھِ، تہٕ یِم بڑبڑاوان چھِ: کیا لُکھ پزِ نہٕ پننِس خدایس سٍتـ̡ ژھارُن؟ زندن ہندِ خاطرہ مرن تام؟\n20. شریعت تہٕ گوٲہی کُن: اگر تِم یَتھ لفظس مُطٲبق کتھ کران چھِ، {یہ} چُھہ تکیازِ {تِمن مَنٛز چُھنہٕ کانہہ گاش}۔ {نہ...: ہیب۔ نو مارننگ}\n21. تہٕ تِم گژھن اَتھ مٔنزۍ نیران، مُشکِل تہٕ فاقہٕ کٔرِتھ، تہٕ یہِ سپدِ، یێلہِ تِم فاقہٕ آسہِ، تِم گژھن پانَس پریشان تہٕ پننِس بادشاہس تہٕ پننِس خداہس لعنت، تہٕ ہیوٚر کُن نظر۔\n22. تہٕ تِم گژھن زمینس کُن نظر۔ تہٕ وُچھِو مصیبت تہٕ انہِ گٹہِ، غصٕچ مدھم۔ تہٕ {تِمَن} یِن انہِ گٹہِ کُن دِنہٕ۔","1.\\tبہر حال چھہ نہ گۅڈنچہ لٹہِ تمۍ سٕندِس سرزمینس تہٕ نفتالی ہٕندِس سرزمینس ہلکہ پٲٹھۍ، تہٕ امہ پتہ کورُن سمندرٕچ وتہِ یُس اردن اپارِ قومن ہٕندِس گلیلس مَنٛز سمندرٕچ وتہِ سٍتـ̡ زیادٕ سٍتـ̡ مُتٲثِر کٔرِتھ۔ {قومن منز: یا، آبادی}\n2. یِمو لُکھ یِم اوندِپِس مَنٛز پکان چِھ، تِمو چُھ اکھ بٔڈ گاش وُچھمُت: یِم موتٕکِس سایہِ ہٕندِس سرزمینس مَنٛز روزان چِھ، تِمن پیٹھ چُھ گاش گاش دِنہٕ آمُت۔\n3.\\tژے کٔر قوم بڑاوُن، {تہٕ} ہُرراوُن نہٕ خوشی: تِم چھِ توے برونہہ کنہِ فصلہٕ سٕنزِ خوشی مطٲبق خوش گژھان، {تہٕ} یِتھٕ پٲٹھۍ {انسان} چھِ غنیمت بٲگراونہٕ وِزِ خوش گژھان۔ {نہٕ: یا أمِس کُن}\n4. تکیازِ ژے پھُٹرٲو تٔمۍ سٕندِس بورُک جو، تہٕ تٔمۍ سٕندِس ظٲلم سٕنز لٔرۍ، یِتھ کٔنۍ مدیان کہ دۅہہٕ پٲٹھۍ۔ {for...: یا، ییلہ ژیہ بریکسٹ}\n5.\\tجنگجو سٕندِس پرٮ۪تھ کُنہِ جنگہٕ سٍتـ̡ چُھہ گٔژھِتھ گٔژِھتھ شورٕ سٍتـ̡ تہٕ پلو خونس سٍتـ̡ ؤلِتھ گٔژھِتھ ۔ مگر {یہ} آسہِ نارُک دزنہٕ سٍتـ̡ {تہٕ} دزنہٕ سٍتـ̡ ۔ {for...: یا، ییلہ جنگجو سُند سورے جنگ اوس، وغیرہ} {مگر...: یا، تہٕ یہِ اوس، وغیرہ} {ایندھن: ہیب۔ ماز}\n6. تکیازِ اسہِ خٲطرٕ چُھ اکھ بچہ زامُت، اسہِ خٲطرٕ چُھ اکھ نیچو دِنہٕ آمُت: تہٕ تٔمۍ سُند ناو گژھہِ شاندار، مشیر، طاقتور خدا، ابدی باپ، امنُک شہزادٕ وننہٕ۔\n7. داؤد سٕندِس تختس تہٕ تٔمۍ سٕنزِ سلطنتس پیٹھ گژھہِ نہٕ اتھ حکم دِنہٕ خٲطرٕ تہٕ اَمہ سٍتـ̡ انصاف تہٕ انصاف سٍتـ̡ قایم کرنہٕ خٲطرٕ کُنہِ تہِ خاتمہٕ۔ لشکرن ہٕندِ رب سُند جوش کرِ یہِ انجام دِنہٕ۔\n8. خداوند سوز یعقوبس مَنٛز اکھ لفظ، تہٕ سُہ چُھ اسرٲیلِس پیٹھ روشن گومُت۔\n9. تہٕ سارِنٕے لُکھ گژھہِ پتاہ زِ افرائیم تہٕ سامریہ ہٕندِس بسکینس سٍتـ̡ یُس دِل کِس غرور تہٕ مضبوطی سٍتـ̡ ونان چُھ،\n10.\\tسیرِ گٔیہِ پٔسۍ، مگر أسۍ کرو ژٔٹِتھ کنیو سٍتـ̡ تعمیر کرنہٕ: سِکومور چھِ ژٹنہٕ آمٕتۍ، مگر أسۍ بدلٲوِو تِمن دیودارس منز۔\n11.\\tتێلہِ کرِ خداوند پننس خلاف ریزن سٕندِس دُشمن سٍتـ̡ رٔلِتھ تہٕ دُشمن رٔلِتھ رٔلِتھ ۔ {جوائن: ہیب۔ رَلنہٕ آمُت}\n12.\\tشامٕکۍ برونہہ، تہٕ پَتہٕ پَتہٕ فلسطینی۔ تہٕ تِم گژھن اِسرٲیلِس کھٮ۪نہٕ سٍتـ̡ کھٮ۪وان۔ امہِ سارِوٕے کِنۍ چھُنہٕ تٔمۍ سُند شَرارتہٕ پھیُراونہٕ آمُت، مگر تٔمۍ سُند اَتھٕ چھُ وُنہِ تہِ پھٔہلِتھ۔ {کھول: ہیب۔ پورٕ}\n13.\\tتکیازِ لُکھ چُھہ نہٕ تٔمِس سٍتـ̡ پھیران یُس تِمن ماران چُھ، تہٕ تِم چِھہ لشکرن ہٕندِس رب سٕندِس سٍتـ̡ ژھاران۔\n14. تێمہِ کِنۍ کرِ خداوند اِسرٲیلِس نِش کلہٕ تہٕ لٔٹ، لٔج تہٕ دوڑ، أکِس دۅہس مَنٛز ژٹِتھ ۔\n15. قدیم تہٕ عزت، سُہ چُھ کلہٕ۔ تہٕ یُس پیغمبر اپُز ہیچھناوان چُھ، سُہ چُھ لٔٹ آسان۔\n16.\\tیِمن لوکن ہٕندِس رہنُما سٍتـ̡ چُھہ غلطی ہُند سبب بنان۔ تہٕ {تِم یِمَن} چھِ تِمَن مَنٛز {تِم} تباہ گٔمٕتۍ۔ {رہنما: یا، تم یم یمن بابرکت ونان چِھ} {لیڈ آف: یا، وَننہٕ آمُت بابرکت آف} {تباہ: ہیب۔ نِگِل}\n17. تێمہِ کِنۍ گژھہِ نہ خداوند پننین جوانن منز کانہہ خوشی تہٕ نہ تہندِس بے باپ تہٕ بیواہ سٍتـ̡ رحم کرُن، یێلہِ زن پرٮ۪تھ کانہہ منافق تہٕ بدکار چُھ، تہٕ پرٮ۪تھ کانہہ چُھ بیوقوفی کَران۔ امہِ سارِوٕے کِنۍ چھُنہٕ تٔمۍ سُند شَرارتہٕ پھیُراونہٕ آمُت، مگر تٔمۍ سُند اَتھٕ چھُ وُنہِ تہِ پھٔہلِتھ۔ {فولی: یا، وِلنی}\n18.\\tیِکیازِ بد کار چُھ نارٕکۍ پٲٹھۍدزان: سُہ چُھ نار تہٕ کانٹہٕ کھٮ۪وان، تہٕ جنگلٕچ جھاڑِ مَنٛز دزِ، تہٕ تِم گژھن دوٚہہٕ تُلنہٕ سٍتـ̡ کھسنہٕ۔\n19. خداوند سٕندِس قہر سٍتـ̡ چُھہ زمینہٕ تاریک تہٕ عوام گژھن نارُک تیٖل پٲٹھۍ: کانہہ تہِ انسان گژھِ نہٕ پننِس بٲیِس بخشان۔ {ایندھن: ہیب۔ ماز}\n20. تہٕ سُہ گژھہِ دچھنہِ اتھس تھپھ کٔرِتھ، تہٕ فاقہٕ روزِ۔ تہٕ سُہ کھیوٚن کھوورِ اتھہٕ کھٮ۪ن، تہٕ تِم گژھن نہٕ تسلی کٔرِتھ: تِم کھٮ۪ن پرٮ۪تھ أکِس انسانس پننہِ نرِ ہُند ماز کھٮ۪ن: {ژٔٹِتھ: ہیب کٹ}\n21. مناسی، افرائیم۔ تہٕ افرائیم، منسیہ: {تہٕ} تِم یِکہٕ وٹہٕ یہوداہَس خلاف گژھن۔ امہِ سارِوٕے کِنۍ چھُنہٕ تٔمۍ سُند شَرارتہٕ پھیُراونہٕ آمُت، مگر تٔمۍ سُند اَتھٕ چھُ وُنہِ تہِ پھٔہلِتھ۔","1.\\tتِمن ہٕندِ خٲطرٕ افسوس یِم ناپاک حکم دِوان چھِ، تہٕ یِم غمگین لیکھان چھِ، یُس تِمو مقرر کورمُت چھُ۔ {یُس لیکھان چھُ...: یا تِمن ادیبن خٲطرٕ یِم غم لیکھان چھِ}\n2. ضرورتمندن فیصلہٕ نِش دور کرُن، تہٕ میانین لوکن ہٕندِس غریبن نِش حق نِنہٕ خٲطرٕ، یُتھ بیواہ آسن تِہند شکار، تہٕ یِم گژھن بے باپ لوٹ!\n3. تہٕ زیارت کِس دۅہس تہٕ ویرٲنی مَنٛز کیا کٔرِو؟ ژیہ کمہِ نِش ژٔلِتھ مدد؟ تہٕ ژٕ کتہِ تراوٕ پنٕنۍ شان؟\n4. میانہِ بغٲر گژھن تِم قٲدٮ۪ن تل نمُن، تہٕ تِم گژھن مقتولن تل گَژھن۔ امہِ سارِوٕے کِنۍ چھُنہٕ تٔمۍ سُند شَرارتہٕ پھیُراونہٕ آمُت، مگر تٔمۍ سُند اَتھٕ چھُ وُنہِ تہِ پھٔہلِتھ۔\n5.\\tاے اسیری، میانہِ شرارتچ لاٹھ، تہٕ تِہندس اتھس منز لٔرِتھ چھُ میٲنۍ شرارت۔ {O...: یا، اسوری سٕندِ خٲطرٕ افسوس: ہیب۔ اَشُر} {تہٕ: یا، اگرچہِ}\n6. بہٕ سوزٕ سُہ أکِس منافق قومس خٕلاف، تہٕ پننہ قہر ہٕندِس لُکن خٕلاف بہٕ دِیہ أمِس غنیمت نِنُک تہٕ شِکار نِنہٕ خٲطرٕ، تہٕ تِمن سڑکہِ ہٕندِس دلدَس ہٕندۍ پٲٹھۍ۔ {ٹریڈ...: ہیب۔ تمن تھوو اکھ ٹریڈنگ}\n7. توتہِ چھہ نہ تسند مطلب تہ نہ چھہ تسند دل تہِ سوچان۔ مگر {یہٕ} چُھ تٔمۍ سٕندِس دِلس منز زِ سُہ کرِ قومن تباہ تہٕ ژٹُن نہٕ۔\n8.\\tتکیازِ سُہ چُھ ونان زِ کیا میٲنۍ شہزادٕ چھِنہٕ پوٗرٕ پٲٹھۍ بادشاہ؟\n9. {کیا } کالنو چُھ نہٕ کارکیمش پٲٹھۍ ؟ {چھا} ہامتھ بطور ارپاد؟ {کیا} سامریہ چھہ نہ دمشقس؟\n10. یێلہِ میانہِ اَتھٕ سٍتـ̡ بُتن ہٕنزِ بادشٲہی لٔبِتھ تہٕ یێمہِ سٕنزِ بُتٕچ بُتلہٕ تہٕ یێمہِ سٕنزِ بُتٕچ بُتٕہ سٍتـ̡\n11. کیا بہٕ کٔرِو نہٕ یِتھٕ پٲٹھۍ سامریاہس تہٕ تٔمۍ سٕندِس بُتن سٍتـ̡ تہٕ یِتھے پٲٹھۍ کرُن؟\n12.\\tتێلہِ سپدِ یہِ سپدِ، یێلہِ خداوند کوہ صیون تہٕ یروشلمس پیٹھ پنُن سورُے کٲم کرِ، بہٕ دِیہٕ اسریاک بادشاہ سٕندِس مضبوٗط دِلُک پھل تہٕ تٔمۍ سٕنزِ تھدِ نظرن ہٕندِس جلال سٍتـ̡ سزا۔ {سزا: ہیب۔ وزِٹ on} {stout...: Heb. دِلٕچ عظمت}\n13.\\tتکیازِ سُہ چُھ ونان زِ میہ چُھ پننہِ اتھہٕ کہِ طاقتہٕ سٍتـ̡ تہٕ پننہِ دانشہٕ سٍتـ̡ کورمُت۔ تکیازِ بہٕ چُھس ہوشیار تہٕ مے چھُ لوکن ہٕندِ حَد ہٹٲومٕتۍ، تہٕ تِہُند خزانہٕ لُٹمُت، تہٕ مے چھُس بسکیٖن دِنہٕ وٲلِس بہادر سٕندۍ پٲٹھۍ، {اکھ بہادر...: یا، واریاہ لوکھ}\n14. تہٕ میانہِ اتھہٕ لوٚب لُکن ہُند مال تہٕ یُتھ زن أکِس ٹھوٗل جمع کٔرِتھ، مے کٔر سٲرۍسٕے زمینہٕ جمع کرنہٕ۔ تہٕ اوس نہٕ کانٛہہ تہِ یُس پکھہ ہلٲوِتھ، یا ٲس ٲس کھولمٕژ، یا نظر۔\n15.\\tکلہٕ کُلہٕ کٔرِتھ یُس اتھ سٍتـ̡ ہُرِ کٔرِتھ؟ {یا} کیا آرہ پانس سیتۍ واٹھ دِتھ یُس اتھ ہلاوان آسہِ؟ گویا یہ لٔر تُلِتھ {لاٹھ...: یا، اکھ لٔر گژھہِ تِمن ہلاونہٕ یُس تُلِتھ تُلِتھ} {پانہٕ، یتھہٕ پٲٹھۍ...: یا، سُہ یُس نہٕ لٔکر چُھ}\n16. تێمہِ کِنۍ سوزُن خداوند یُس لشکرن ہُند رب چھُ، سُہ سوزُن پنہٕ نِس موٚٹِس مَنٛز دِنہٕ۔ تہٕ تٔمۍ سٕندِس جلال سٍتـ̡ سُہ دزُن نار ہٕندۍ پٲٹھۍ۔\n17. تہٕ اسرٲیلُک گاش آسہِ نارٕ خٲطرٕ، تہٕ تٔمۍ سُند مقدس نار آسہِ، تہٕ سُہ گژھہِ أکِس دۅہس منز تٔمۍ سٕندِس کانٹَن تہٕ تٔمۍ سٕندِس دٔرِس تہٕ کھٮ۪نہٕ۔\n18.\\tتہٕ کرِ پننہِ جنگلٕچ شان تہٕ پننہِ پھلہٕ دار کھہُن، روح تہٕ جسمہٕ سٍتـ̡ کھٮ۪نہٕ، تہٕ تِم گژھن تِتھے پٲٹھۍ یێلہِ اکھ معیارٕ بردار بے ہوش گژھہِ۔ {دۄشوے...: ہیب۔ روح پیٹھہ تہ مازس تام تہِ}\n19.\\tتہٕ أمۍ سٕندِس جنگلٕکۍ باقٕے کُلۍ آسن کم، یُتھ زن اکھ شُر لیکھِتھ آسہِ۔ {کینٛہہ: ہیب۔ نمبر}\n20.\\tتہٕ تمہِ دۅہہ سپدِ یُس اسرٲیلُک باقی، تہٕ یُس یعقوب سٕندِ گرٕ نِش ژلِتھ آسہِ، تِمن ہُند دُبارٕ روزُن نہٕ۔ مگر روزِ حقیقتس منز رب اسرٲیلِکِس پاکس سٍتـ̡ روزُن۔\n21. یعقوب سُند باقیات گژھہِ یعقوب سُند باقیات یُس طاقتور خدایہ سٕندِس نِش واپس۔\n22. یێلہِ تہِ تُہٕندِس قومس سمندرٕچ سیکہِ ہیوٗ آسہِ، {توتہِ} یِمن ہُند باقیات گژھہِ واپس۔ {یمن منز: ہیب۔ in, or, among, etc} {with: or, in}\n23.\\tیِکیازِ خداوند خدایہِ سٍتـ̡ سارِنٕے زمینہٕ کِس درمِیان کھٮ۪نہٕ یُن، حتیٰ کہ طے تہِ کرُن۔\n24. تێمہِ کِنۍ چُھ خداوند لشکرن ہُند خدا، اے صیہونس مَنٛز روزن وٲلس لوکو، اسوری سٍتـ̡ گژھ نہٕ کھوژُن، سُہ کرِ تۅہہِ لورِ سٍتـ̡ تہٕ تُلِتھ تُلِتھ پَنُن عصا تُلِتھ تہٕ تُلِتھ تہٕ تُلِتھ تُلِتھ تہٕ تُلِہ پَنُن لٔرِتھ تہٕ تُلِتھ تُلِتھ تہٕ تُلِتھ تہٕ تُلِتھ {تہٕ کرِ...: یا، مگر سُہ تُلِتھ پنُن عصا}\n25.\\tکینژس کالس تام، تہٕ غصہ گژھہِ ختم، تہٕ تِمن ہٕنزِ تباہی پیٹھ گژھہِ میون غصہٕ۔\n26.\\tتہٕ لشکرن ہُند رب کرِ أمِس خٲطرٕ اکھ عذاب: یِتھٕ پٲٹھۍ تٔمۍ سٕنز لٔر سمندرس پیٹھ ٲس، تِتھے پٲٹھۍ تُلِہ سُہ مصرٕچ وتہٕ پٲٹھۍ۔\n27.\\tتہٕ تمہِ دۅہہ سپدِ تٔمۍ سُند بار تُہندِ پھیکہٕ پیٹھٕ تُلنہٕ تہٕ تٔمۍ سُند جوُر یِیہِ تُہنزِ گردنہٕ پیٹھ، تہٕ مسح کرنہٕ سٍتـ̡ گژھہِ تُہند بار ختم کرنہٕ۔ {رٹُن...: ہیب۔ ہٹاونہٕ آمُت}\n28.\\tسُہ چُھ آیاتھس مَنٛز آمُت، سُہ چُھ مِگرون کُن منتقل کرنہٕ آمُت۔ مِخماشَس مَنٛز چھِ تٔمۍ پَنٕنۍ گاڑِ ترٛٲومٕژ:\n29.\\tتِم گٔیہِ وتہِ پیٹھ: تِمو چھِ گیباہَس مَنٛز پنٕنۍ روزنٕچ جاے رٔٹمٕژ۔ رامہ چھہ کھوژان۔ ساؤل سُند گیبیاہ ژوٚل ژلان۔\n30.\\tپَنٕنۍ آواز تُلِو اے گالِم سٕنزِ کورِ، اے بیچارہ اناتھوتھ، یہ بوزناوُن لیش۔ {لِفٹ...: ہیب۔ کٔرِتھ کٔرِتھ کٔرِتھ}\n31. مدمینہ آو ہٹاونہٕ۔ گیبِمٕکۍ بسکیٖن در چھِ ژلنہٕ خٲطرٕ جمع گژھان۔\n32.\\tسُہ روزِ تمہِ دۅہہ نوبس منز: سُہ کرِ یروشلم کِس پہاڑس پیٹھ صییون سٕنزِ کورِ ہٕندِس پہاڑس پیٹھ اتھہٕ رلاونہٕ۔\n33.\\tوُچھِو، خداوند یُس لشکرن ہُند رب چھُ، دِیہِ خوفہٕ سٍتـ̡ لٔٹِتھ تہٕ تھدِ تھدِ یِن ژٹنہٕ یِن، تہٕ مغرور گژھن عاجز کرنہٕ۔\n34. تہٕ سُہ ژٹِن جنگلٕچ کٔنڈۍ ششتٕرٕ سٍتۍ، تہٕ لبنان گٔیہِ أکِس زورٕ سٍتـ̡ پٔرِتھ۔ {by...: یا، زورور}","1. تہٕ یسی سٕندِ ڈنجہِ منزٕ نیرِ اکھ لٔر نیرِ، تہٕ تٔمۍ سٕندِس موٗلہٕ منزٕ نیرِ اکھ لنجہِ۔\n2. تہٕ خداوند سُند روح روزِ تس پیٹھ، حکمت تہٕ فہم ہُند روح، مشورٕ تہٕ طاقتُک روح، علمُک روح تہٕ خداوند سُند خوف۔\n3.\\tتہٕ کرِ تس خداوند سٕندِس خوفس سٍتـ̡ جلدٕے سمجھ دِنہٕ: تہٕ سُہ کرِ نہٕ پننین أچھن ہٕندِس نظرس سٍتـ̡ فٲصلہٕ تہٕ نہ کرِ پننین کنن ہٕندِس بوزنہٕ پتہٕ ملامت کرنہٕ: {جلدی...: ہیب۔ خوشبو یا، خوشبو}\n4. مگر نیکی سٍتـ̡ کرِ سُہ غریبن ہُند فیصلہ تہٕ زمینہِ ہٕندِس عاجزس سٍتـ̡ دِیہِ برابری سٍتـ̡ ملامت تہٕ سُہ کرِ پننہِ ٲسٕچ لٔرِ سٍتـ̡ زمینس پیٹھ تہٕ چپنہٕ سٍتـ̡ دِیہِ بدکارن ہُند قتل۔ {ملامت کٔرِو: یا، دلیل کٔرِو}\n5. تہٕ نیکی آسہِ تٔمۍ سٕنزِ کمرٕچ بند، تہٕ وفاداری آسہِ تٔمۍ سٕنزِ لگام ہٕنز بند۔\n6.\\tرامہٕ تہِ روزِ کۅکرِ سٍتـ̡ تہٕ سٕہہ سٕندِس شُرِس سٍتـ̡ شُرِتھ روزُن۔ تہٕ بَچھرٕ تہٕ جوان شیر تہٕ موٚٹُر یکوٹہٕ؛ تہٕ اکھ لۄکُٹ شُر کرِ تِمن رہنُمٲیی کرنہٕ۔\n7. تہٕ گاو تہٕ ریچھ کھیٚنہٕ۔ تِہٕندِ بچہٕ گژھن اکوٹہٕ لٔگِتھ: تہٕ شیر کھیٚیہِ گاسہٕ داند ہٕندۍ پٲٹھۍ۔\n8.\\tتہٕ چوسُن وول شُر گِندُن گِندُن تہٕ دوٚد دِنہٕ وول شُر گِندُن کۅکرِ ہٕندِس گۅپھس پیٹھ۔ {کاکاٹریس': یا، ایڈرز}\n9. تِم گژھن نہٕ میانہِ سارِنٕے مقدس پہاڑس مَنٛز تکلیف دِنہٕ تہٕ تباہ کٔرِتھ، تکیازِ زمین آسہِ خداوند سٕندِ علمہٕ سٍتـ̡ بٔرِتھ، یِتھٕ کٔنۍ آب سمندرس سٍتـ̡ بٔرِتھ آسہِ۔\n10. تہٕ اَمہِ دۅہہٕ آسہِ یسی سُند موٗل یُس لُکن ہٕندِس نشانس سٍتـ̡ کھڑا آسہِ۔ اَتھ کُن گژھن غیر قومن ہٕنز تلاش تہٕ تٔمۍ سُند آرام آسہِ شاندار۔ {شاندار: ہیب۔ عظمت}\n11. تہٕ یہ سپدِ تمہِ دۅہہ سپدِ، {یُس} خداوند دوٚیمہِ لٹہِ پنٕنـ̡ لُکن ہٕندِس باقیات بازیافت کرنہٕ خٲطرٕ دُبارٕ اتھہٕ تھووُن، یُس اشوریا پیٹھ، تہٕ مصرہٕ پیٹھ، تہٕ پتھراس پیٹھ، کُش پیٹھ، تہٕ ایلام پیٹھ، تہٕ شِنار پیٹھ، تہٕ حمتھ پیٹھ، تہٕ سمندرٕ کِس جزیرٕ پیٹھ۔\n12. تہٕ سُہ کرِ قومن ہٕندِ خٲطرٕ اکھ جھنڈٕ قٲیم، تہٕ کرِ اسرٲیلٕکۍ کٔرِتھ کٔرِن جمع تہٕ یہوداہ ہٕندِس ژۅشونی کُنـ̡ سٍتـ̡ جمع کرُن۔ {کون: ہیب۔ ونگس}\n13.\\tافرائیم سُند حسد تہِ گژھہِ ژٔٹِتھ تہٕ یہوداہ سٕندِس مُخٲلِف گژھِ ژٹنہٕ: افرائیم گژھِ نہٕ یہوداہ سٕندِس حسد سٍتـ̡ تہٕ یہوداہ گژھِ نہٕ افرائیمس پریشان کرنہٕ۔\n14.\\tمگر تِم گژھن مغربس کُن فلسطینن ہٕندِس پھیکس پیٹھ وُڑان۔ تِم کرِ یکوٹہ مشرقس منز یکوٹہ تِم اَتھ سٍتـ̡ اَدَم تہٕ موآبس پیٹھ اتھہٕ تراونہٕ۔ تہٕ عمون سٕندِ بچہٕ کٔرِن تِمن ہٕنز فرمانبردار۔ {تِم: ہیب۔ بچہٕ {تِم دِنہٕ یِن...: ہیب۔ ادوم تہٕ موآب گژھن پننس اتھس پیٹھ تراوُن} {اطاعت کرُن...: حب۔ تہنز فرمانبرداری}\n15. تہٕ خداوند کرِ مصری سمندرٕچ زبان مکمل طور تباہ کرنہٕ۔ تہٕ پننہ طاقتور واو سٍتۍ کرِ سُہ دریاوس پیٹھ اتھہٕ ہلاوان، تہٕ سَتن نالن منز مارِ تہٕ کرِ {انسان} خشک کُنہِ ک {dryshod: Heb. شوٹس منز}\n16. تہٕ تٔمۍ سٕندِس لُکن ہٕندِس باقیاتس خٲطرٕ آسہِ اَکھ شاہراہ یُس اَسِریا پؠٹھٕ روزِ۔ یتھے پاٹھۍ چھہ تمہِ دۅہہ اسرٲیلِس سٍتـ̡ ییلہ سُہ مصرہٕ کہِ سرزمینہٕ منزہ نیبر آو۔","1. تہٕ اَمہِ دۅہہٕ چُھہ ژے وَنُن، اے خداوند، بہٕ کٔرٕ تُہٕندِس تعریف: یێلہِ تہٕ ژے ژے میہ سٍتـ̡ ناراض ٲس، تہٕ ژے کٔر میہ تسلی دِنہٕ۔\n2. وُچھو، خدا چُھہ میٲنۍ نجات بہٕ کَرٕ بھروسہٕ، تہٕ کھوژٕ نہٕ: خداوند یہوواہ چُھہ میٲنۍ طاقت تہٕ میٲنۍ نغمہٕ۔ سُہ تہِ چُھ میٲنۍ نجات بنیومُت۔\n3. تَمہِ مۄکھٕ کٔرِو خوشی سٍتـ̡ نجات دِنہٕ کِس کۄرَس مَنٛز آب کڈنہٕ۔\n4. تہٕ اَمہِ دۅہہٕ کٔرِو تُہۍ وَنُن، خداوند سٕندِ سٍتـ̡ سُند ناو پۯاوُن، تٔمۍ سٕندِس ناوُک اعلان کٔرِو تہٕ تٔمۍ سُند ناو چُھہ بلند۔ {کال...: یا، اعلان کٔرِو}\n5. خداوند سٕندِ خٲطرٕ گٮ۪وُن؛ تکیازِ تمۍ چھہ عمدہ کٲم کٔرمٕژ: یہ {چُھ} سارِنٕے زمینس منز زاننہٕ آمُت۔\n6. کٔرِو کرٛٮ۪کھ تہٕ کرٛٮ۪کہٕ دِیُن، اے صیہونُک بسکیٖن: تِکیازِ تُہٕندِس درمِیان چُھہ اِسرٲیلُک مقدس چُھ۔ {بسکین: ہیب۔ بسکین}","1.\\tبابل ہُند بوجھ، یُس اموز سٕندِس نیچوِس یسعیاہ ہن وُچھمُت۔\n2.\\tتھدِ بالس پیٹھ تُلِو جھنڈٕ تُلِتھ، تِمن تام کٔرِو آواز تھزراونہٕ، اتھہٕ رلٲوِو، یُتھ تِم رئیسن ہٕندِس دروازس منز اژِتھ۔\n3.\\tمیہ چُھس پننین مقدسن ہُند حُکُم دِژمُت، میہ چُھس پننین طاقتورن تہِ پننہِ شرارت خٲطرٕ بلاومُت، {حتیٰ کہ} تِمن تہِ یِم میانہِ عظمتس منز شاد سپدان چھِ۔\n4.\\tپہاڑن منز ہٕندِس بٔڈِس لُکن ہٕندۍ پٲٹھۍ، ہیوٗ بٔڈۍ لُکن ہُند شور۔ قومن ہٕنزِ سلطنتن ہُند اکھ ہنگامہ خیز شور: لشکرن ہُند رب چُھ جنگُک لشکر جمع کران۔ {یِتھ کٔنۍ...: ہیب۔ ہشر}\n5. تِم چھِ أکِس دوٗر مُلکہٕ پیٹھٕ یِوان، آسمانہٕ کِس اندٕ پیٹھ، خداوند تہٕ تٔمۍ سٕندِ غصہٕ ہٕندِ ہتھیار، سٲرۍسٕے زمینس تباہ کرنہٕ خٲطرٕ۔\n6. ہُل یے؛ کیازِ خداوند سُند دۅہ چُھہ اتھس پیٹھ؛ یہ گژھہِ خدایہ سندِ طرفہٕ تباہی ہٕندِس طورس پیٹھ یِنہٕ۔\n7.\\tتێلہِ گژھہِ سارِنٕے اتھہٕ بێہوش، تہٕ پرٮ۪تھ أکِس انسانس دِل گٔژھِن: {بێہوش گژھُن: نتہٕ پیوٚو}\n8. تہٕ تِم گژھن کھوژان: غم تہٕ غم گٔژھن تِمن رٔٹِتھ ۔ تِم گژھن أکِس زنانہِ ہٕندۍ پٲٹھۍدَگ دِنہٕ یِوان: تِم گژھن اکھ أکِس پیٹھ حٲران گَژھان۔ تہند بُتھ گژھن نارک پٲٹھۍ۔ {حیران گژھو: ہیب۔ حیرت انگیز} {اکھ...: ہیب۔ پرتھ کانہہ نفر پننس ہمساین پیٹھ} {شعلہٕ: ہیب۔ نارن ہند بُتھ}\n9.\\tوُچھِو خداوند سُند دۅہ یُس غصہٕ تہٕ شدید غصہٕ سٍتـ̡ ظالمانہٕ سٍتـ̡ زمینہٕ ویران کرُن، تہٕ سُہ کرِ اَمہ منزٕ گۅنہگارن تباہ کرنہٕ۔\n10. تکیازِ آسمانک تارکھ تہٕ تِمن ہٕندِس برج دِن نہٕ پنُن گاش: آفتاب گژھہِ پننہِ نیرنس منز تاریک تہٕ زون گژھہِ نہٕ پنُن گاش گاش دِنہٕ۔\n11. تہٕ بہٕ دِیہ دنیاہس تہٕ بدکارن تہنزِ بدکارن ہٕنزِ بدکٲری ہُند سزا۔ تہٕ بہٕ کٔرٕ مغرورن ہُند غرور ختم، تہٕ کرٕ خوفناک سٕنز تکبر کم۔\n12. بہٕ بناوٕ انسان سۄنہٕ کھوتہٕ زیادٕ قیمتی ۔ اوفیر سٕندِ سنہری پچر کھۅتہٕ تہِ اکھ انسان۔\n13. تێمہِ کِنۍ کرٕ بہٕ آسمانن ہٕندِس قہر سٍتـ̡ تہٕ زمین ہٹٲوِتھ تہٕ تٔمۍ سٕندِس شدید غصہٕ سٍتـ̡ ہٹاوٕنـ̡ ۔\n14.\\tتہٕ یہِ گژھہِ پٲٹھـ̡ پى۪ٹھ، تہٕ کُنہِ ہٕندِس پٲٹھـ̡ تُلنہٕ یِنـ̡ پى۪ٹھ۔\n15.\\tپریتھ کانہہ یُس لبنہٕ ییہِ سُہ گژھہِ دِنہٕ یُن۔ تہٕ پریتھ کانہہ یُس {تمن سٍتۍ} رٔلِتھ آسہِ، سُہ گژھہِ تلوار سٍتۍ پیوٚو۔\n16. تِہٕندِس شُرِ تہِ یِن تِمن ہٕندِس أچھن برونہہ کُن ٹُکرٕ کرنہٕ۔ تِہٕندِ گرٕ یِن برباد کرنہٕ، تہٕ تِہٕنزِ زنانہٕ یِن تباہ کرنہٕ۔\n17.\\tوچھ، بہٕ کٔرٕ تِمن خلاف میڈس ہٕندِس خٕلاف ہنگامہ کٔرِتھ، یُس نہٕ رۄپہٕ سٍتـ̡ رۄپہٕ سٍتـ̡ سٍتـ̡ س� تہٕ {یوت} سۄنہٕ خٲطرٕ، تم گژھن نہٕ اتھ منٛز خۄش۔\n18.\\t﴿تِہٕندِس کمان﴾ سٍتـ̡ تہِ کرِ جوان ٹُکرٕ ٹُکر۔ تہٕ تِمن گژھہِ نہٕ رحم کِس پھلس پیٹھ کانہہ رحم کھسان۔ تِہٕنزِ أچھ گژھِ نہٕ شُرِ بخشان۔\n19.\\tتہٕ بابل یُس بادشاہتن ہُند جلال تہٕ کلدین ہٕنزِ عظمتٕچ خوبصورتی آسہِ تِتھۍ پٲٹھۍ، یێلہِ خداین سدوم تہٕ عمورہ ہُند تختہ الٹٲو۔ {as...: Heb. یتھ کٔنۍ زِ تختہٕ الٹنہٕ}\n20.\\tاَتھ منز گژھِ نہٕ زانہہ آباد سپدُن، نہ گژھِ اَتھ منز نسل در نسل روزُن، تہٕ نہ گژھِ اَتہِ عربُک خیمہ لاگُن۔ نَہ کٔرِن اَتہِ پَنٕنہِ گٔژھِتھ تہٕ کٔرِتھ گٔژھ\n21.\\tمگر صحراہٕکۍ جنگلی جانور آسن اتہِ روزان۔ تہٕ تِہُند گرٕ گژھن بدبخت مخلوقاتو سٍتۍ بٔرِتھ۔ تہٕ راتہٕ مۄغل روزن تتہِ روزان، تہٕ ساتیر روزن تتہِ نژان۔ {جنگلی...: ہیب۔ Ziim} {doleful...: Heb. اوچِم} {راتہٕ مۄغل: یا، شترمرغ: ہیب۔ راتہٕ مۄغلہٕ سٕنٛز کورِ}\n22.\\tتہٕ جزیرٕکۍ جنگلی جانور چھِ پننین ویران گَرن منز، تہٕ اژدٕن ہٕندِس خۅش محلن منز: تہٕ تٔمۍ سُند وق چُھ یِنہٕ نزدیک، تہٕ تٔمۍ سٕندِ دۅہ گژھن نہٕ زیچھر۔ {دی وائلڈ...: ہیب۔ Iim} {ویران ...: یا، محل}","1. یعقوب سٕندِس گرس سٍتـ̡ کرِ یعقوب سٍتـ̡ رحمت، تہٕ توتہِ کرِ اسرٲیلُک انتخاب تہٕ تِم کرِ پننِس سرزمینس مَنٛز۔\n2. تہٕ لوکھ نِن تِمن تہٕ تِمن ہٕنزِ جایہ أنِن، تہٕ اسرٲیلُک گرٕ رٔٹِن خداوند سٕندِس سرزمینس مَنٛز نوکرَن تہٕ دٲیرَن ہٕندِ خٲطرٕ، تہٕ تِم رٔٹِن یِمن قٲد، یِمن ہٕندِس قٲدِس سٍتـ̡ ٲسۍ۔ تہٕ تم کرن پننین ظالمن پیٹھ حکومت۔ {کُس...: ہیب۔ یمۍ تم قٲد ٲسۍ کٔرۍمٕتۍ}\n3. تہٕ یہِ سپدِ تمہِ دۅہہٕ یُس خداوند تُہٕندِس غمَس نِش تہٕ تُہٕندِس خوفہٕ نِش تہٕ سخٕت غلامی نِش آرام دِیہِ، یَتھ مَنٛز ژےٚ خدمت کرنہٕ آمٕژ ٲس،\n4.\\tیُس ژے بابل کِس بادشاہس خلاف یہ محاورہ تُلِتھ ونُن، ظالم کِتھہ پاٹھۍ گۆو ختم۔ گولڈن سٹی گوٚو بند! {محاورہ: یا، طعنہ آمیز تقریر} {گولڈن...: یا، ایکسیکٹریس آف گولڈ}\n5. خداوند چُھ بدکارن ہُند عصا پھُٹرٲومُت، {تہٕ} حکمرانن ہُند عصا۔\n6.\\tیُس لُکن ہُند غصہٕ سٍتـ̡ لُکن ہُند شِرارتہٕ سٍتـ̡ دِوان چُھ، سُہ چُھہ ستاونہٕ آمُت، تہٕ سُہ چُھہ نہٕ کانہہ تہِ رُکاوٹ کٔرِتھ۔ {اکھ مسلسل...: ہیب۔ ہٹاونہٕ ورٲے اکھ فالج}\n7.\\tسورے زمین چھیہ آرام کران، {تہِ} چھہ خاموش: تم چھہِ گیونس منز پھٹان۔\n8.\\tآ، فر کُلۍ چھِ توے سٍتـ̡ خوش گژان، {تہٕ} لبنان کِس دیودارس {ونن}، یێلہِ تہٕ ژے چھُکھ بٔرِتھ دِنہٕ آمُت، اسہِ خلاف آو نہٕ کانہہ تہِ بٔرۍ۔\n9. جہنم چُھ تۅہہِ ہٕندِ یِنہٕ وِزِ {ژے} سٍتـ̡ مِلنہٕ خٲطرٕ منتقل کرنہٕ آمُت: یہِ چُھہ تۅہہِ ہٕندِ خٲطرٕ مُردن ہٕندِ خٲطرٕ ہلچل دِوان، {حتیٰ کہ} زمینہٕ کین سارِنٕے اہم شخصن تہِ۔ أمۍ کٔر قومن ہٕندۍ سٲری بادشاہ پننیو تختو پیٹھٕ تھوٚد۔ {جہنم: یا، قبر} {چیف...: ہیب۔ رہنما، یا، عظیم ژھاوٕل}\n10.\\tتِم سارِنٕے کَتھ تہٕ وَنُن تہٕ وَنُن، کیا تُہۍ تہِ چھِو اسہِ ہٕندۍ پٲٹھۍکمزور گٔژھمٕتۍ؟ کیا تُہۍ چھوا اسہِ ہِش بنیومُت؟\n11.\\tتۅہہِ ہُند شوکت چھُ قبرس تام اننہٕ آمُت، {تہٕ} تہٕ چُھہ تۅہہِ ہٕندِس شورس منز: کیمہٕ چُھہ ژے تۅہہِ تلہ پھٔہلِتھ تہٕ کیمہٕ چھُس ژے ؤلِتھ۔\n12. اے لوسیفر، صبحُک نیٚچُو، کِتھہ پٲٹھـ̡ ووت اسمانہٕ پى۪ٹھ! {کِتھہ پٲٹھۍ}ژے ژٔٹِتھ ، یٔمۍ قومن کمزور کٔرۍ! {اے لوسیفر: یا، اے ڈے سٹار}\n13. تکیازِ ژے چُھہ پننِس دِلس منز وونمُت، بہٕ کھسُن اسمانس منز، بہٕ کرٕ پنُن تخت خدایہ سٕندِس ستارن پیٹھ، بہٕ شمالس کِس اندۍ پکھۍ جماعت کِس پہاڑس پیٹھ تہِ بِہتھ:\n14. بہٕ کھسُن اوٚبرن ہٕندِس تھزرس پیٹھ۔ بہٕ آسہٕ سارِوٕے کھۄتہٕ تھدِ ہیوٗ۔\n15. توتہِ یِیہِ جہنمَس مَنٛز والنہٕ، کھۅنہٕ کِس اندۍ پکھۍ۔\n16.\\tیُس تۅہہِ وُچھان چھُ، تۅہہِ وُچھِن تۅہہِ سٍتـ̡ وُچھن، {تہٕ ونان} چُھہ سُہ انسان یٔمۍ زمینہٕ تھرٲوِتھ دِژ، یٔمۍ سلطنتن ہٕندِس لرِ ہٕندِس سٍتـ̡ دِژمٕژ چھِ۔\n17.\\t{یێمہِ} بنیوو دُنیا بیابان تہٕ اَمہ کِس شہر کٔرِن تباہ۔ {یُس} اوس نہٕ تٔمۍ سٕندٮ۪ن قٲدٮ۪ن ہُند گرٕ کھولنہٕ آمُت؟ {کھولنہٕ آمُت...: یا دِژ نہٕ پننین قٲدٮ۪ن گَرٕ کُن یلہٕ؟}\n18.\\tقومن ہٕندِ سارِنٕے بادشاہ، {حتیٰ کہ} سارِنٕے بادشاہ چھِ جلال سٍتـ̡ روزان، پرٮ۪تھ کانہہ چُھ پننِس گرس مَنٛز۔\n19.\\tمگر ژے چھُکھ پننہِ قبرِ منزٕ أکِس مکروہ لنجہِ ہٕندۍ پٲٹھۍ، {تہٕ} مارنہٕ یِنہٕ والٮ۪ن ہٕندِس پوشاکَس سٍتـ̡ تلوار سٍتـ̡ دِنہٕ آمُت، یُس کھۅنہٕ کِس کنن تام وسان چھُ۔ یتھہ پاٹھۍ کھۅرن تلہ کنہِ لٔگتھ لاش۔\n20. تُہۍ گژھ نہٕ تِمن سٍتـ̡ دفنَس مَنٛز شٲمِل گٔژھِتھ، تِکیازِ ژے چُھکھ پَنٕنـ̡ پَنٕنـ̡ زمینہٕ تباہ کٔرمٕژ، {تہٕ} پَنٕنـ̡ پَنٕنـ̡ لُکھ مارُن: بدکارن ہُند بُل گژھہِ نہٕ زانہہ تہِ بدنام کرنہٕ۔\n21.\\tپننین شُرین ہٕندِ خٲطرٕ کٔرِو تِمن ہٕندِس مٲلِس سٕندِ بدکٲری ہٕندِ خٲطرٕ ذبح کرنٕچ تیاری۔ زِ تِم چھِنہٕ وۅتھان تہٕ نہ زمینہٕ حٲصِل کٔرِتھ، تہٕ نہ چھِ دُنیاہُک بُتھ شہرو سٍتۍ بٔرِتھ۔\n22.\\tکیازِ بہٕ کرٕ تِمن خلاف کھڑا گژھُن، خداوند چُھ فرماوان تہٕ بابل نِش ناو ژٹِتھ تہٕ بچیمُت، تہٕ نیچو تہٕ بابتھٕر ژٹِتھ کرُن۔\n23. بہٕ بناوٕ یہِ تلخ تہٕ آبہٕ خٲطرٕ تہٕ آبہٕ ہٕندِس تالابَس سٍتـ̡ تہٕ بہٕ کٔرٕ یہِ تباہی ہٕندِس سٍتـ̡ صاف کٔرِتھ، لشکرن ہُند رب چُھ وَنان۔\n24. لشکرن ہٕندِس رب سٕندِس سٍتـ̡ چُھہ حلف کھٲلِتھ وَنُن زِ یێلہِ سٍتـ̡ یێلہِ سٍتـ̡ سپدِ۔ تہٕ یِتھٕ پٲٹھۍ مےٚ چُھ ارادٕ کوٚرمُت، {تِتھٕ پٲٹھۍ} گژھہِ یہِ کھڑا روزُن:\n25.\\tزِ بہٕ پھُٹراوٕ آشوری پننِس زمینس منز، تہٕ پننین پہاڑن پیٹھ گژھہِ أمِس قدمن تل پکان، تیلہِ گژھہِ تٔمۍ سُند جوُر تِمن نِش نیرُن، تہٕ تٔمۍ سُند بار گژھہِ تِمن ہٕندِس پھیکس پیٹھ۔\n26.\\tیہِ چُھ سُہ مقصد یُس سارِنٕے زمینس پیٹھ مقصود چُھ: تہٕ یہِ چُھ سُہ اَتھٕ یُس سارِنٕے قومن پیٹھ پھٔہلِتھ چُھ۔\n27. کیازِکہ لشکرن ہُند رب چُھ ارادہ کورمُت، تہٕ کُس کرِ منسوخ کرنہٕ؟ تہٕ تٔمۍ سُند اَتھٕ چُھس پھٔہلِتھ تہٕ کُس کرِ واپس۔\n28.\\tییمہ ؤریس منز بادشاہ احاز مرُن اوس، سہ اوس یہ بوجھ۔\n29.\\tژے گژھ نہ خوش گژھُن، سٲرے فلسطین، تکیازِ یُس ژیہ ماران چھُ، سُہ چھُ پھُٹمُت: تکیازِ ناگ سٕندِ موٗلہٕ منزٕ نیرِ اکھ کۅکر، تہٕ تٔمۍ سُند پھل آسہِ اکھ نار وُڑن وول ناگ۔ {کاکاٹریس: یا، ایڈر}\n30. تہٕ غریبن ہُند گۅڈٕ زُو کھیٚنہٕ تہٕ ضرورت مند روزِ رٲچھ سان لٔگِتھ تہٕ بہٕ مارٕ تُہند مول قحطہٕ سٍتـ̡ تہٕ سُہ مارِ تُہند باقی۔\n31. ہاؤل، او گیٹ؛ کرو اے شہر؛ تۅہہ، سورے فلسطین، {آرٹ} تحلیل گومُت: کیازِ شمالہٕ پیٹھہٕ ییہِ اکھ دھواں، تہٕ کانہہ تہِ آسہِ نہٕ پننِس مقرر وقتس منز کُنی زُن۔ {کانہہ تہِ...: یا، سہ گژھہِ نہ کُنی کُنی} {مقرر کرنہٕ...: یا، اسمبلی}\n32.\\tتیلہِ کیا کرِ قوم کین رسولن جواب دِنہٕ؟ زِ خداوند چُھ صییونٕچ بنیاد ترٛٲومٕژ، تہٕ تٔمۍ سٕندِس لوکن ہٕندِس غریبن گژھن اتھ پیٹھ بھروسہٕ۔ {بھروسہ...: یا، پانس کٔرِو اتھ پیٹھ رٔٹتھ}","1. موآب سُند بوجھ۔ تکیازِ راتس منز چھہ موآبُک آرہ ویران سپدان، {تہٕ} ژھۄپہٕ کرنہٕ آمُت۔ تکیازِ رٲژ چھہ موآبُک کیر ضایع سپدان، {تہٕ} ژھۄپہٕ کرنہٕ آمُت۔ {اننہٕ آمُت...: یا، ژٹنہٕ آمُت}\n2.\\tسُہ چُھ باجیتس تام تہٕ تھدٮ۪ن جاین تام وُننہٕ خٲطرٕ: موآب چُھ نیبوہس تہٕ مدیباہس پیٹھ کرٛاوُن: تِمن سارِنٕے کلَن پیٹھ گژھہِ گنج تہٕ پرٮ۪تھ کُنہِ داڑھ ژٹنہٕ۔\n3.\\tپننین سڑکن منز چھِ تِم بۄٹہٕ پلو لٲگِتھ: پننین گَرن ہٕندِس تینتٲلِس پیٹھ، تہٕ تِہنزن سڑکن مَنٛز، پرٮ۪تھ کانہہ چُھ کرٛٮ۪کہٕ دِوان، سٮ۪ٹھاہ وَنان۔ {وُن...: ہیب۔ روُن وُنُن، یا وُچھِتھ وُچھُن}\n4.\\tتہٕ ہیشبون کرِ فریاد تہٕ الیالہ: تہنز آواز گژھہِ جہازس تام بوزنہٕ، لہذا گژھن موآبٕکۍ مسلح سپاہ کرٛٮ۪کہٕ دِنہٕ۔ تٔمۍ سٕنٛز زندگی آسہٕ تٔمِس خٲطرٕ غمگیٖن۔\n5. میون دِل کرِ موآبس خٲطرٕ فریاد ۔ تٔمۍ سٕندِ ژٔلِتھ تِم وُہُر وُہُر کٔرِتھ وُچھِتھ تِم ہیوٚر کھسنہٕ آمٕتۍ۔ تکیازِ ہورونیم کِس وتہِ منز گژھن تِم تباہی ہٕنز فریاد تُلان۔ {تٔمِس...: یا تِمن ہٕندِس سرحدس تام، حتیٰ کہ زورس تہِ، بطور گاو} {تباہی: ہیب۔ بریکنگ}\n6. تِکیازِ نِمرِمُک آب گژھہِ ویران گژھُن: کیازِ گاسہ چُھ مرزاونہٕ آمُت، گاسہٕ چُھ ناکام گَژھان، اَتہِ چُھ نہٕ سبز چیز۔ {ویران : ہیب۔ ویرانی}\n7.\\tتێلہِ یُس کثرت تِمو میلہِ تہٕ یُس تمو دِژمُت چُھ، سُہ نِن تِم وِلہٕ کِس نالہِ کُن نِنـ̡ ۔ {بروک...: یا، وادی عرب}\n8. کیازِ چُھ موآب کِس سرحدس اندۍ پکھۍ گٔژھمُت۔ اَمہ ہُند کُلہٕ وُچھُن تہٕ اَمہ ہُند ہُرٕ وُچھُن بیریلِمَس تام۔\n9.\\tتکیازِ دیمون سُند آب گژھہِ خونس سٍتـ̡ بٔرِتھ، تکیازِ بہٕ اَنِہ زیادٕ دِمونس پیٹھ، یُس موآب نِش ژلِتھ تہٕ زمینہٕ کِس باقیاتس پیٹھ تہٕ یُس بہٕ دِیہٕ دِنہٕ۔ {مٔزیٖد : ہیب۔ اضٲفہٕ}","1.\\tسوز کۅکرِ کُنہِ زمینہِ ہندس حاکمس سیلا پیٹھہ بیابانس تام، صییون کورِ ہندس پہاڑس تام۔ {سیلا: یا، پیٹرا: ہیب۔ اکھ راک}\n2. تکیازِ یہِ آسہِ، {یہ}، یِتھٕ پٲٹھۍ، یُس آوارٕ جاناوار یُس گرٕ منزٕ کڈنہٕ آمُت چُھ، {یِتھٕ پٲٹھۍ} آسہِ موآب سٕنزِ کورِ آرنون کِس فورڈس پیٹھ۔ {کاسٹ ...: یا، اکھ گھونسلہ ترک کرنہٕ}\n3. وکیل کرُن، فیصلہٕ انجام دِیُن۔ پنُن ژھایہ بناو دوپہرس منز رٲژ ہٕندۍ پٲٹھۍ۔ کٔرِتھ کٔرِو ژوٗر۔ یُس پھیران چھُ، تٔمِس سٍتـ̡ چُھہ نہٕ سٍتـ̡ {رٔٹِو: ہیب۔ برِنگ}\n4.\\tمیانہِ بے دخل گژھن پانس سٍتـ̡ روزُن، موآب۔ تِمن ہٕندِس بُتھِس سٍتـ̡ بُتھِ سٍتـ̡ بٔنِتھ بٔنِتھ روزُن: کیازِ زَب خور چُھس ختم سپدان، بدکار چُھہ رُکاونہٕ آمُت، ظالم چھِ زمینہٕ منزٕ کھٮ۪نہٕ یوان۔ {بھتہ خور: ہیب۔ رِنگر} {ظالم: ہیب۔ ٹریڈرز ڈاون}\n5. تہٕ رحمتہٕ سٍتـ̡ گژھہِ تخت قایم کرنہٕ، تہٕ سُہ بِہِتھ سُہ پٔزۍ پٲٹھـ̡ داؤد سٕندِس خیمہ مَنٛز بِہِتھ، انصاف کٔرِتھ، تہٕ نیکی ہٕندِس سٍتـ̡ جلدی کٔرِتھ۔ {قائم: یا، تیار}\n6. اسہِ چُھ موآب سٕندِ غرورٕچ خبر بوزمٕژ۔ {سُہ} چُھ} سٮ۪ٹھاہ فخر: {حتی} پننِس تکبر تہٕ غرورُک تہٕ تٔمۍ سُند غصہٕ: {مگر} تٔمۍ سُند اپُز {گژھِ نہ} تِتھۍ۔\n7. تَمہِ مۄکھٕ چُھہ موآب ہٕندِ خٲطرٕ کرٛٮ۪کہٕ دِنہٕ، پرٮ۪تھ کانہہ کُنہِ سٍتـ̡ کُنہِ سٍتـ̡ ہُند ماتم کرُن۔ یقینا {تِم} چھِ مُتٲثِر۔ {ماتم : یا، بڑبڑاو}\n8.\\tہیشبون کِس کھہَس مَنٛز چھُ سِبمہٕ سٕندِس کُلِس سٍتـ̡ پھُٹرٲومُت، تِم چھِ یازرس کُن آمٕتۍ، تِم گٔیہِ بیابانن مَنٛز: تٔمۍ سٕنزِ لنجہِ پھٔہلِتھ گٔیہِ، سمندرٕ کُن گٔیہِ۔ {کھینچ کٔرتھ...: یا، تُلتھ کٔرتھ}\n9. تێمہِ کِنۍ کٔرٕ بہٕ سِبمہِ ہٕندِس وُپھ سٍتـ̡ یازر سٕندِ وَننہٕ سٍتـ̡ ماتم کٔرِتھ، اے حشبون تہٕ الیالہ، تێلہِ چُھہ ژے پنٕنـ̡ اوٚش سٍتـ̡ آب دِنہٕ۔ {کرٛٮ۪کہٕ دِنہٕ...: یا، الارم چُھ پیوٚو، وغیرہ}\n10. تہٕ خوشی چھِ نِنہٕ آمٕژ، تہٕ خوشی چھِ کٔرِتھ دِنہٕ آمٕژ۔ تہٕ انگورن منز گژھہِ نہ کانہہ گیون، نہ گژھہِ کرٛٮ۪کہٕ دِنہٕ: ٹریڈر گژھن نہٕ تِمن ہٕندِس دباوس منز شراب۔ میہ چھہ {تہند ونٹیج} بند کرُن۔\n11.\\tلہذا گژھہِ میانہِ أندرِ موآب سندِ خاطرہ ہارپ ہیو تہ میانہِ اندرم حصہ کرہریش سندِ خاطرہ بوزن۔\n12. تہٕ یێلہِ یہِ سپدِ، یێلہِ یہِ وُچھنہٕ ییہِ زِ موآب چُھہ تھزرس پیٹھ تھوٚکمت ، سُہ گژھہِ پننِس مقدس مقامس مَنٛز دعا کرنہٕ خٲطرٕ۔ مگر سُہ گژھِ نہٕ غالب۔\n13. یہِ چُھ سُہ لفظ یُس خداوند تَمہِ وقتہٕ پیٹھٕ موآبس مُتلق بولمُت چُھ۔\n14. مگر وۅنۍ چُھ خداوند کتھ کٔرمٕژ زِ ترٮ۪ن ؤرین اندر یِتھ کٔنۍ زَن کرایہ دار سٕندِ ؤری تہٕ موآبُک جلال گژھہِ تِمن سارِنٕے بٔڈِس بٔڈِس سٍتـ̡ بدنام کرنہٕ۔ تہٕ باقیات آسہِ واریاہ لۄکُٹ {تہٕ} کمزور۔ {کمزور: یا، واریاہ نہٕ}","1. دمشقُک بوج۔ وچھو دمشق چھہ شہر آسنہ نش نِنہٕ آمُت، تہٕ یہ آسہِ اکھ تباہ کن ڈھیر۔\n2.\\tاَرویٖرٕکۍ شہر چھِ ترٲوِتھ: تِم گژھن ریوڑن خٲطرٕ، یِم بٔرِتھ روزن، تہٕ کانٛہہ تہِ گژھِ نہٕ تِمن خوفزدہ کرنہٕ۔\n3. قلعہ تہِ گژھہِ افرائیم نِش تہٕ دمشقس نِش سلطنت تہٕ شامٕچ باقیات تہٕ یِم گژھن بنی اسرٲیلِس ہٕندِس جلال ہٕندۍ پٲٹھۍ، لشکرن ہُند رب چُھ ونان ۔\n4.\\tتہٕ تمہِ دۅہہ سپدِ یۅہے یعقوب سُند جلال گژھہِ پتلہٕ تہٕ تٔمۍ سٕندِس مازُک چربی گژھہِ دوٚب۔\n5.\\tتہٕ یِتھٕ پٲٹھۍ گژھہِ یِتھٕ پٲٹھۍ ییلہ فصلہٕ کُن کُن جمع کرِ، تہٕ پننہِ نرِ سٍتـ̡ کٔنـ̡ لُٹِتھ کٔرِ۔ تہٕ سُہ آسہِ یُس رفیم کِس وادی منز کَن جمع کرِ۔\n6. توتہِ گژھہِ اتھ منز انگور ژٹنہٕ یُن، یِتھٕ پٲٹھـ̡ زیتون کُلِس ہٕندِس لرزاونہٕ سٍتـ̡ زٕ {یا} تریہ بیر، ژور {یا} پانژھ پھلہٕ دار لنجہِ منز، یێلہِ ہٕندِس نیبرِمِس پھلہٕ دار لنجہِ مَنٛز ژور {یا} پانژھ بێیہِ۔\n7. اَمہِ دۅہہٕ گژھہِ انسان پننِس خالقس کُن نظر، تہٕ تٔمۍ سٕنزِ نظرن گژھہِ اسرٲیلِس مقدس سُند احترام۔\n8.\\tتہٕ سُہ گژھِ نہٕ قربان گاہن کُن، پننین اتھن ہٕنزِ کٲم، تہٕ نہ کرِ تٔمِس احترامس کُن یُس تٔمۍ سٕنزِ اونگجہِ آسہِ بنٲومٕژ، یا تہٕ تِمن ہٕندِس باغس یا تصویرن ہُند احترام۔ {تصویٖرٕ: یا، آفتاب تصویٖرٕ}\n9.\\tاَمہِ دۅہہٕ گژھن تٔمۍ سٕندِ مضبوٗط شہر أکِس ترٲومٕژ کُلہِ ہٕندِس پٲٹھۍ، تہٕ یُس تِمو بنی اِسرٲیلِیو ہٕندِ وجہ سٍتـ̡ ترٲومُت چُھ، تہٕ تتہِ گژھہِ ویران۔\n10. کیازِ ژے چُھہ پننہِ نجات ہُند خدا مٔشِد گومُت، تہٕ چُھہ نہٕ پننہِ طاقتہٕ ہٕندِس کُلِس سٍتـ̡ یاد تھاوُن، تێلہِ کٔرِو خۅش کُلۍ کُلۍ، تہٕ کٔرِو عجیب پرچی سٍتـ̡ تھاوُن:\n11.\\tدۅہہٕ کٔرِو پَنُن کُل وۄپداونہٕ، تہٕ صُبحَس کٔرِو پَنُن بُل پھۄلاونہٕ: {مگر} دُکھ تہٕ مایوسی ہٕندِس دۅہس مَنٛز گژھہِ فصلُک ڈھیر۔ {اکھ ڈھیر...: یا، وراثت کس دۅہس منز ہٹاونہٕ آمُت، تہٕ تتہِ گژھہِ مہلک غم}\n12.\\tواریاہن لوکن ہٕندِس بٔڈِس پیٹھ افسوس، {یُس} سمندرن ہٕندِس شورس ہٕندۍ پٲٹھۍشور کران چھُ۔ تہٕ قومن ہٕندِس دوڑس کُن، {یُس} چُھ طاقتور آبٕچ دوڑٕکۍ پٲٹھۍ! {کثیر: یا، شور} {طاقتور: یا، واریہ}\n13.\\tقومہٕ گژھن واریہن آبن ہٕندِس وسوٕکۍ پٲٹھۍ، مگر {خدایہ} کرِ تِمن ملامت تہٕ تِم ژلِن دور دور، تہٕ ہوہس برونہہ کُن پہاڑن ہٕندِس کھالٕکۍ پٲٹھۍ، تہٕ واو برونہہ کُن وُچھن وٲلِس چیزٕکۍ پٲٹھۍ۔ {اکھ رولنگ...: یا، تھیسل ڈاون}\n14. تہٕ وُچھِو شامٕچ مصیبت {تہ} صبحس برونہہ چھہ نہ سہ {چُھ}۔ یہِ چھُ تِمَن ہُند سُہ حصہٕ یُس اسہِ خراب کران چھُ، تہٕ تِمن ہُند سُہ حصہٕ یُس اسہِ لُٹان چھُ۔","1.\\tپکھہ سٍتۍ ژھایہ واجنہِ زمینہِ ہُند افسوس، یُس ایتھوپیا کین دریاون نیبر چھُ:\n2. یُس سمندرٕ کِس نِش سفیر سوزان چُھ، حتیٰ کہ آبس پیٹھ بُلبرن ہٕندِس جہازس منز تہِ، {ونُن}، اے تیز پیغامبرو ، أکِس قومس کُن یُس بکھرِتھ تہٕ چھلنہٕ آمُت چُھ، تِتھِس قومس کُن یُس تِمن ہٕندِس آغازس پیٹھٕ خوفناک آسہِ۔ اکھ قوم کٔر لوٚگ تہٕ لوٚگ، یٔمۍ سٕنٛز زمین دریاو خراب کٔرمٕژ چھِ! {بکھرِتھ...: یا، پھٔہلِتھ تہٕ پالش کٔرِتھ} {meted...: یا، یُس مِٹِتھ تہٕ پٔکِتھ چُھ: ہیب۔ لٲنہِ، لٲنہِ تہٕ کھۄرَن تَل پَکُن} {have...: یا، حقارت کَرنہٕ آمُت}\n3.\\tاے دنیاہٕکۍ بسکین، تہٕ زمینس پیٹھ روزن والۍ، وُچھِو یێلہِ سُہ پہاڑن پیٹھ اکھ جھنڈٕ تُلان۔ تہٕ ییلہ سُہ بُرٕ وُن چُھ، بوزو۔\n4. یِتھٕ پٲٹھۍ چُھس خداوند مےٚ ووٚنمُت، بہٕ نِش آرام کٔرِتھ، تہٕ بہٕ کَرٕ پننِس مکانس مَنٛز جڑی بوٹین پیٹھ صاف گرمی ہٕندۍ پٲٹھۍ، {تہٕ}فصلہٕ کِس گرمی مَنٛز شبنم ہٕندِس پٲٹھۍ۔ {غور کرو...: یا، میانہِ سیٹ رہائش گاہ وچھو} {on...: یا، روٗد پتہٕ}\n5.\\tفصلہٕ برونہہ ییلہ کلین کامل آسہِ، تہٕ کھٹۍ انگور پوشس منز پکنہٕ آسہِ، سُہ ژٹِن دۅشوے ژٹنہٕ والیو ہُک سٍتۍ ژٹِتھ تہٕ لنجہِ ژٹِتھ ژٹِن۔\n6. تِم گژھن پہاڑن ہٕندٮ۪ن جاناوارن تہٕ زمینہٕ کِس درندَن خٲطرٕ رٔلِتھ تراونہٕ۔\n7. اَتھ وقتس مَنٛز یِیہِ موجودٕ خداوند سٕندِس نِش اننہٕ یِنہٕ یِنہٕ وٲلِس لُکن ہٕندِس لشکرس سٍتـ̡ یُس تِمن ہٕندِس ابتداہس پیٹھٕ خوفناک آسہِ۔ اکھ قوم آو کھستھ تہٕ قدمن تل لٔگتھ، یٔمۍ سٕنز زمینہٕ دریاو تباہ کٔرۍمٕژ، لشکرن ہٕندِس رب سٕندِس ناوس پیٹھ، کوہ صیون سٕندِس مقامس تام۔ {بکھرِتھ...: یا، پھٔہلِتھ تہٕ پالش کٔرِتھ}","1. مصرُک بوج۔ وُچھِو، خداوند چُھ تیز اوبرس پیٹھ سوار سپدان، تہٕ یِیہِ مصرس مَنٛز: تہٕ مصرٕکۍ بُت یِن أمۍ سٕندِس حضورس سٍتـ̡ منتقل کرنہٕ، تہٕ مصرُک دِل گٔیہِ اَتھ مَنٛز پَلہٕ۔\n2. تہٕ بہٕ کرٕ مصری مصرین خلاف تہٕ تم کرن پرتھ أکس پننس بٲیس خلاف تہٕ پرتھ اکس پننس ہمساین خلاف لڑان۔ شہر بمقابلہ شہر، {تہٕ} بادشٲہی خلاف سلطنت۔ {سیٹ: ہیب۔ رَلنہٕ آمُت}\n3. تہٕ مصرُک روح گژھہِ اتھ منز ناکام۔ تہٕ بہٕ کٔرٕ اَمہ ہُند مشورٕ ختم: تہٕ تِم ژھانڈن بُتن تہٕ جادوگرن نِش، تہٕ تِمن ہٕندِس نِش یِمن واقف روح آسہِ، تہٕ جادوگرن نِش۔ {ناکام: ہیب۔ خٲلی گژھُن} {تباہ: Heb. نگلُن}\n4. تہٕ مصری بہٕ دِیہٕ أکِس ظالم آقا سٕندِس اتھس مَنٛز۔ تہٕ یِمن پیٹھ کرِ اکھ زبردست بادشاہ حکوٗمت، خداوند چُھ وَنان۔ {دِو...: یا، شُٹ اپ}\n5. تہٕ سمندرٕ سٍتـ̡ گژھہِ آب ختم تہٕ دریاو گژھہِ ضایع تہٕ خشک گژھن۔\n6. تہٕ تِم کٔرِن دٔریاوَن دوٗر دوٗر۔ {تہٕ} دفاعٕچ نالہٕ گژھن خٲلی تہٕ خشک کرنہٕ: نٔر تہٕ جھنڈٕ گژھن مرزاونہٕ۔\n7.\\tنالہِ سٍتـ̡ کُنہِ چیزس سٍتـ̡ یُس کُنہِ تہِ سٍتـ̡ وُنـ̡ سٍتـ̡ گٔژھِتھ گٔژھِ {تہٕ بے...: ہیب۔ تہٕ گژھِ نہٕ آسُن}\n8.\\tگاڈٕ رٔٹِتھ تہِ گژھن ماتم تہٕ یُس نالہِ منز زاویہِ تراوان چھُ، تِم گژھن ماتم تہٕ یِم آبس پیٹھ جال تراوان چھِ۔\n9.\\tتِم یِم باریک فلکسس منز کٲم کران چھِ، تہٕ یِم نیٹ ورک بناوان چھِ، گژھن الجھان۔ {نیٹ ورکس: یا، وائٹ ورکس}\n10.\\tتہٕ یِم گژھن اَمہ کِس مقصدس منز پھُٹراونہٕ یِن، یِم گاڈَن ہٕندِ خٲطرٕ سلہٕ تہٕ تالاب بناوان چھِ۔ {مقاصد: ہیب۔ بنیاد} {گاڈٕ خٲطرٕ: ہیب۔ زندٕ چیزن ہٕندِ}\n11.\\tیقینا چھہ زونکۍ شہزادہ بیوقوف، فرعون سٕندٮ۪ن دانشمندن ہٕندِ مشیرن ہُند مشورٕ چھُ وحشیانہ بنیومُت: فرعونس کِتھہ کٔنۍ چُھکھ ونان، بہٕ چُھس دانشمندن ہُند نیچو، قدیم بادشاہن ہُند نیچو۔\n12.\\tتم کتہِ چھہِ؟ تہند عقلمند {مرد} کتہِ چھہِ؟ تہٕ تِم وَنُن وُن، تہٕ تِمن زانن زِ لشکرن ہٕندِس رب سٕندِ مِصرس پیٹھ کیا چُھ ارادٕ کورمُت۔\n13.\\tزوآنٕکۍ شہزادٕ چھِ بیوقوف بنیمٕتۍ، نوفٕکۍ شہزادٕ چھِ دھوکہٕ دِنہٕ آمٕتۍ۔ تِمو چُھ مصرس تہٕ بہکاومُت، {یوتام زِ تم تہٕ یم امہٕ کین قبیلن ہند قیام چِھ}۔ {تم یہ...: یا، گورنر: ہیب۔ کونر}\n14.\\tخداوند چُھ اَتھ مَنٛز اکھ بدکار روح رَلاونہٕ آمُت، تہٕ یِمو چُھ مصرس پرٮ۪تھ کامہِ مَنٛز غلطی کٔرمٕژ، یِتھٕ پٲٹھۍ اکھ شرابہٕ انسان چُھ اُلٹی مَنٛز لڑکھان۔ {اکھ غلط ...: ہیب۔ اکھ روح انحراف}\n15.\\tمصرس خٲطرٕ گژھہِ نہ کانہہ کٲم یُس کلہٕ یا لٔٹۍ، لنجہِ یا دوڑ ہیکہِ کٔرِتھ۔\n16.\\tاَمہِ دۅہہٕ گژھہِ مصر زنانن ہٕندِ ہیوٗ تہٕ سُہ گژھہِ لشکرن ہٕندِس رب سٕندِ اتھہٕ ہلاونہٕ سٍتـ̡ کھوژُن تہٕ خوفہٕ۔\n17.\\tتہٕ یہوداہ ہٕچ سرزمین گژھہِ مصرہٕ خٲطرٕ دہشت ، یُس تہٕ یُس اتھ ہُند ذکر کرِ، سُہ گژھہِ پانس مَنٛز خوفزدہ گژھُن، یُس لشکرن ہٕندِس خداوند سٕندِ مشورٕ سٍتـ̡ یُس تٔمۍ اتھ خلاف طے کورمُت چُھ۔\n18. اَمہِ دۅہہٕ گژھن مصرٕچ زمینہِ ہٕندِس پانژھ شہر کنعانٕچ زبان بولن، تہٕ لشکرن ہٕندِس رب سٕندِس سٍتـ̡ حلف کَرٕن؛ أکِس یِیہِ وننہٕ یُن، تباہی ہُند شہر۔ {زبان: ہیب۔ وُٹھ {تباہی ہُند: یا، ہیرسُک، یا، آفتابُک}\n19. اَمہِ دۅہہٕ آسہِ خداوند سٕندِ خٲطرٕ اکھ قربان گاہ تہٕ اَمہِ کِس اندس پیٹھ آسہِ خداوند سٕندِ خٲطرٕ اکھ تھم۔\n20. تہٕ یہِ آسہِ اَکہِ نشانہٕ خٲطرٕ تہٕ مصر کِس سرزمینس مَنٛز لشکرن ہٕندِس خداوند سٕندِ خٲطرٕ گواہ دِنہٕ خٲطرٕ، تِکیازِ تِم گژھن ظالمن ہٕندِ خٲطرٕ خداوند سٕندِ خٲطرٕ فریاد کرنہٕ، تہٕ سُہ سوزِ تِمن نجات دِنہٕ وول تہٕ اکھ بٔڈ تہٕ سُہ کرِ تِمن نجات دِنہٕ۔\n21. تہٕ خداوند گژھہِ مصرس زاننہٕ، تہٕ مصری گژھن تمہِ دۅہہٕ خداوند سٕندِس سٍتـ̡ زاننہٕ، تہٕ کرِ قربانی تہٕ قربانی۔ آ، تِم کرَن خداوند سُند عہد تہٕ پورٕ کرُن۔\n22. تہٕ خداوند کرِ مصرس پیٹھ حملہٕ، سُہ دِیہِ تہٕ شفا دِیہِ، تہٕ تِم گژھن خداوند سٕندِس نِش واپس، تہٕ سُہ گژھِ تِمن نِش دِنہٕ تہٕ تِمن شفا دِنہٕ۔\n23. اَمہِ دۅہہٕ گژھہِ مصرہٕ پٮ۪ٹھٕ اَسوٗرِس تام اکھ وَتھ تہٕ اَشوٗرِیَن یِن مصرس مَنٛز، تہٕ مصری یِن اسوٗرِین سٍتـ̡ خدمت کرنہٕ۔\n24.\\tاَمہِ دۅہہٕ آسہِ اِسرٲیلِس سٍتـ̡ تریم مصرس سٍتـ̡ تہٕ اَشریاہس سٍتـ̡ یێلہِ سٍتـ̡ برکت حٲصل سپدِ۔\n25. یٔمِس خداوند لشکرن برکت دِیہِ، یہِ ؤنِتھ زِ میٲنۍ قوم مصر تہٕ اشوریا میانہِ اتھن ہٕنز کٲم تہٕ اسرٲیلِس میانہِ وراثتس سٍتـ̡ برکت دِیہِ۔","1.\\tیتھ ؤریس منز ییلہ ترتن اشیعادس منز آو، (ییلہ اسریاہک بادشاہ سرگون سُہ سوزمُت،) تہٕ لوٚڑ اشدتس خلاف تہٕ کوٚرُن یہ قبضہٕ۔\n2. اَمہِ وِزِ ووٚن خداوند اموزُک نیچو یسعیاہ سٕندِ دٔسۍ وَنُن زِ گژھ تہٕ پَنٕنِس کھورِ پیٹھٕ ژٔلِتھ ژٔلِتھ تہٕ پَنُن جوُر ژٔلِتھ ژٔلِتھ پَنٕنہِ کھورِ پیٹھ۔ تہٕ تٔمۍ کٔر یہِ ننگہٕ تہٕ ننگہٕ پیر پکان۔ {by: Heb. اتھہٕ سٍتۍ }\n3. تہٕ خداوند ووٚن یِتھٕ پٲٹھۍ میانہِ خادم یسعیاہ تریہ ؤری ننگہٕ تہٕ ننگہٕ پکان چُھہ مصرس تہٕ ایتھوپیاہس پیٹھ اکھ نشانی تہٕ عجائب ۔\n4. یِتھے پٲٹھۍ کرِ اشورُک بادشاہ مصری قٲد، تہٕ ایتھوپیا ہٕکۍ قٲد، جوان تہٕ بُزرگ، ننگہٕ تہٕ ننگے پیر، حتیٰ کہ تِہٕندِس کولہٕ نِش تہٕ نٮ۪بر کٔرِتھ، مصرٕچ شرمندگی کُن۔ {مصری...: ہیب۔ مصرچ قید} {شرم: حب۔ ننگہٕ}\n5.\\tتہٕ تِم گژھن ایتھوپیا سٕندِ وۅمید تہٕ مصرس سٍتـ̡ تِمن ہٕندِس جلال سٍتـ̡ کھوژان تہٕ شرمندٕ۔\n6.\\tتہٕ اَمہ جزیرٕکۍ روزن وول وَنُن تمہِ دۅہ، وُچھِو، یۅہے چھُ سانہِ وۅمید زِ اسہِ کتہِ ژٔلِتھ اسہِ اشوریہ کِس بادشاہس نِش نجات حٲصل کرنہٕ خٲطرٕ: تہٕ أسۍ کِتھٕ کٔنۍ ژٔلِو؟ {جزیرٕ: یا، ملک}","1. سمندرُک صحرا ہُند بوج۔ یُتھ زن جنوبس منز سمندری طوفان نیران چھُ؛ {توتہ} یہ چھہ صحرا پیٹھہ آمت، اکس خوفناک زمینہ پیٹھ۔\n2.\\tمیہ چھہ اکھ غمگین وژن اعلان کرنہ آمت۔ غدار ڈیلر چُھ غداری سان سودا کران، تہٕ خراب کرن وول چُھ خراب کران۔ ہیوٚر گژھو، اے ایلام: محاصرہ، اے میڈیا۔ اَمہ سٍتۍ چھُ میہ سارِوٕے شۅنگہٕ بند کٔرمٕژ۔ {دردناک: ہیب۔ ہارڈ}\n3. اَمہِ کِنۍ چھُ میانہِ کمر دَگ سٍتـ̡ بٔرِتھ: دَگ چُھس میہ رٔٹمُت، یِتھٕ پٲٹھـ̡ زنانہِ ہٕندِس دَگ سٍتـ̡ چُھس سٍتـ̡ گٔژھمُت: بہٕ اوسُس بوزنـ̡ سٍتـ̡ نمُت۔ میہ گوو یہ وچھتھ مایوس۔\n4.\\tمیہ دِل دِل دِژ، خوفہٕ ووت میہ خوفہٕ: میانہِ خوشی ہٕنزِ رٲژ گٔیہِ سُہ میانہِ خٲطرٕ خوف۔ {دل...: یا، دماغ پھیُر} {موڑ: ہیب۔ پُٹ}\n5.\\tٹیبل تیار کرُن، نگراں برجس منز وچھو، کھیون پیو: وۅتھ، اے شہزادو، {تہٕ} ڈھال مسح کرُن۔\n6.\\tیِتھٕ پٲٹھـ̡ چُھہ میہ ووٚنمُت، یێلہِ چُھہ یێلہِ چُھہ یێلہِ وُچھمُت چُھہ سُہ دِیُن۔\n7. تہٕ وُچھ اکھ رتھ یتھ منز زٕ گُرۍ سوار، گَرَن ہُند اکھ رتھ، تہٕ اونٹٮ۪ن ہُند اکھ رتھ۔ تہٕ تٔمۍ بوز وارِیاہ توجہ سان غور سان :\n8.\\tتہِ وۆن اکھ شیر: میانہِ مالہ، بہٕ چُھس دۅہلہِ پٲٹھۍواچ ٹاورس پیٹھ کھڑا روزان، تہٕ بہٕ چُھس سارِنٕے رٲژ پننِس وارڈس منز روزان: {سُہ...: یا، شیرٕکۍ پٲٹھۍ} {پورٕ...: یا، پرٮ۪تھ رٲژ}\n9.\\tتہٕ وُچھِو یِتھے نفرن ہُند اکھ رتھ یِوان، یِمن سٍتۍ کینہہ گُرۍ سوار تہِ۔ تہٕ تٔمۍ دیُت جواب تہٕ وونُن، بابل چُھ پیوٚومُت، پیوٚو پیوٚو۔ تہٕ تٔمۍ سٕندٮ۪ن دیوتاہن ہٕنزِ سٲری کھٔنِتھ شکلہٕ چھِ تٔمۍ زمینس پیٹھ پھُٹرٲومٕژ۔\n10. اے میٲنۍ تھٕرِس تہٕ میانہِ فرشُک مَکُل: یُس مے لشکرن ہٕندِس خداہس مُتلق بوزمُت چُھ، یُس مے چُھہ ژے سٍتـ̡ اعلان کورمُت۔ {مکایہ: ہیب۔ نیٚچُو}\n11.\\tدومہ ہُند بوج۔ سُہ چُھ میہ سیر منزٕ بلاوان، چوکیدار، رٲژ کیا چُھ؟ چوکیدار، رٲژ کیا گوو؟\n12.\\tچوکیدارن ووٚن صبحس تہٕ رٲژ تہِ: اگر ژیہ پرژھہ گٲر کرِ، پرژھہ: واپس، یِن۔\n13.\\tعربس پیٹھ بوج۔ عرب کِس جنگلس منز روزو اے دیدانم سٕنزِ سفری کمپنی۔\n14.\\tتیما کِس زمینہٕ کِس روزن والیو اوٚن أمِس نِش آب یُس ترشیہ اوس، تِمو رُکٲوِکھ پننہِ روٹی سٍتۍ یُس ژلُن اوس۔ {أنِتھ: یا، أنِو}\n15.\\tتِکیازِ تِم ژٔلِتھ تلوار نِش، تلوار نِش تہٕ کمانہٕ نِش تہٕ جنگہٕ کِس عذابَس نِش۔ {تلوار منز: یا، خوفہٕ خٲطرٕ، بیترِ: ہیب۔ بُتھِ پیٹھ، بیترِ}\n16. یِتھٕ پٲٹھۍ چُھ خداوند مےٚ ووٚنمُت، أکِس ؤرۍ یَس اندر، کرایہ دار سٕندِ ؤری مطٲبق، تہٕ کیدار سٕنز سورے شان گژھِ ناکام:\n17.\\tتہٕ تیر اندازن ہٕندِس تعدادس ہُند باقی، یُس کیدار کین اولادن ہٕندِس طاقتور نفرن ہُند تعداد گژھہِ کم سپدُن، تکیازِ اسرٲیلُک خداوند چُھ کتھ کٔرمٕژ۔ {تیر انداز: ہیب۔ کمان}","1. وادی وژنُک بوج۔ وۅنۍ کیا چُھہ ژیہ ژیہ پورٕ پٲٹھۍمکانن تام وٲتِتھ؟\n2. ژے یُس ہلچل سٍتـ̡ بٔرِتھ چُھ، اکھ ہنگامہ خیز شہر، اکھ خوشی ہُند شہر: تُہند مارنہٕ آمُت {انسان} چُھنہٕ تلوار سٍتـ̡ مارنہٕ آمُت، تہٕ نہ چُھہ جنگس مَنٛز مٔرِتھ۔\n3. تُہٕندِس سارِنٕے حُکُمران چھِ اَکہٕ وَٹہٕ ژٔلِتھ، تِم چھِ تیر اندازن ہٕندِس سٍتـ̡ پابند گٔمٕتۍ: یُس سارِوٕے یُس ژٔلِتھ چُھ، سُہ چُھہ دوٗرِ پیٹھٕ ژٔلِمُت۔ {by...: ہیب۔ کمانُک}\n4.\\tتێلہِ وۆن میہ نِش نظر۔ بہٕ کٔرٕ سختی سان رووُن، پننین لوکن ہٕنزِ کورِ ہٕنزِ خرابی مۅکھہٕ کٔرِتھ کٔرٕ نہٕ میہ تسلی دِنہٕ خٲطرٕ۔ {ویپ...: ہیب۔ روونَس منٛز گژھ تلخ}\n5.\\tیِہ چُھہ مصیبت ہُند دۅہ، تہٕ وژنٕچ وادی مَنٛز لشکرن ہٕندِ خدایہِ سٕندِ طرفہٕ پریشٲنی ہُند دۅہ، دیوار پھُٹراونُک تہٕ پہاڑن کُن روُنُک دۅہ۔\n6.\\tتہٕ ایلامَن کٔر گُرِ سوارَن ہٕندِس رتھَو سٍتـ̡ کُلہٕ تہٕ کیرَن کٔر ڈھال کُن۔ {بے نقاب کٔرتھ: ہیب۔ ننگہٕ بناونہٕ آمُت}\n7. تہٕ یہِ گژھہِ سپدُن، {یُس} چانہِ پسندیدٕ وادی گژھن رتھَو سٍتۍ بٔرِتھ، تہٕ گُرۍ سوار گژھن دروازس پیٹھ صفس منز کھڑا گژھن۔ {thy...: Heb. پننہ وادی ہند انتخاب} {at: یا، کُن}\n8.\\tتہٕ تٔمۍ وُچھ یہوداہُک پردٕ تہٕ ژے وُچھکھ تمہِ دۅہہ جنگلُک گرٕ کِس ہتھیارس کُن۔\n9.\\tتہِ وُچھمُت داؤد شہرٕچ پھٕرِ تہِ، یِم چھِ واریاہ تہٕ تہٕ ژے کٔرِو بٔنِمِس تالابُک آب جمع کٔرِتھ۔\n10. تہٕ یِمو چُھہ یروشلمٕکۍ گرٕ گٔمٕتۍ، تہٕ یِم گرٕ چھِو دیوار مضبوط کرنہٕ خٲطرٕ پھُٹرٲومٕتۍ۔\n11.\\tژے بنوو دۅن دیوارن درمیان پرانہِ تالابُک آبہٕ خٲطرٕ اکھ کھۅڈ تہِ، مگر تۅہہ کٔر نہ یہ بناون وٲلس کُن نظر، تہٕ نہ اوسُکھ أمس احترام کران یُس واریاہ کالہ برونہہ یہ بنوومُت اوس۔\n12. تہٕ اَمہِ دۅہہٕ دِژ خدایہِ لشکرن ہٕندِس خداہس روُن، ماتم کرنہٕ خٲطرٕ، تہٕ گنج گژھنٕچ تہٕ بۄٹہٕ پلو لاگنہٕ خٲطرٕ بُلاونہٕ:\n13. تہٕ وُچھِو خوشی تہٕ خۅش ، بیل مارٕن، ماز کھٮ۪وان تہٕ شراب چیٚوُن: أسۍ کھیوٚو تہٕ چیٚو۔ تکیازِ پگہہ گژھہِ اسۍ مرُن۔\n14. تہٕ یہِ آو میانین کنن منز لشکرن ہٕندِس رب سٕندِ طرفہٕ ظٲہر کرنہٕ، یێلہِ یێلہِ نہٕ یہِ بدکاری ژے نِش پاک کرنہٕ یِن، یێلہِ یێلہِ تہٕ یێلہِ سٍتـ̡ خدایہِ ہُند خدایہ\n15.\\tیِتھٕ پٲٹھۍ چُھ خداوند لشکرن ہُند خدایہ فرماوان، گژھ تہٕ گژھ اتھ خزانس نِش، {حتیٰ کہ} شیبناہس نِش، یُس {چُھ} گرس پیٹھ، {تہٕ ونُن}،\n16.\\tژیہ کیا چُھہ یتہِ؟ تہٕ ژے کُس چُھہ یتہِ، یُس تٔمِس تھزرس پیٹھ قبر کڈان چُھ، {تہٕ} یُس پانس خٲطرٕ کُنہِ کنہِ کُنہِ قبر کٔرِتھ؟ {as...: یا، O he}\n17. وُچھِو، خداوند کرِ ژےٚ أکِس زبردست قٲد سٍتـ̡ نِنہٕ، تہٕ یٔقیٖنی طور کرِ ژےٚ پردٕ۔ {تُلِتھ کرُن...: یا یمۍ ژے اکھ بہترین پردہ لٲگتھ تہٕ خوبصورتی سان پلو لٲگِتھ، (بیاکھ شعر) گژھہِ یقینا وغیرہ} {اکھ طاقتور...: ہیب۔ انسان سٕنز قید}\n18.\\tسُہ کرِ یٔژ پٲٹھـ̡ تۅہہِ بٔڈِس مُلکس مَنٛز اکھ بالہٕ لٔگِتھ تہٕ تتہِ گژھہِ تۅہہِ ہٕندِس عٔلمہٕ سٍتـ̡ بٔڈِس مُلکَس مَنٛز مَرُن، تہٕ تَتہِ گژھہِ تُہٕندِس رَتھٕ سٍتـ̡ تُہٕندِس آقا سٕندِس گرٕچ شرمندگی۔ {بٔڑ: ہیب۔ بٔڑ جاے}\n19. تہٕ بہٕ کٔرٕ ژےٚ پننہِ جایہِ نِش کٔڑِتھ تہٕ سُہ کٔرِو ژےٚ ژےٚ بۄن کُن۔\n20.\\tتہٕ تمہِ دۅہہ سپدِ بہٕ پنُن خادم الیاقیم حلقیاہ سُند نیچو وُن:\n21. تہٕ بہٕ کرٕ أمِس چانہِ پوشہٕ لاگُن، تہٕ بہٕ کرٕ تُہند حُکوٗمت تٔمۍ سٕندِس اتھس مَنٛز، تہٕ سُہ بنہٕ یروشلم کین بسکینن تہٕ یہوداہ کِس گرس ہُند مول۔\n22. تہٕ داؤد سٕندِس گرٕچ کُنز تھٲوِتھ بہٕ تٔمۍ سٕندِس پھیکس پیٹھ۔ تہ سہ گژھہِ کھولُن، تہ کانہہ تہِ گژھہِ نہ بند۔ تہٕ سُہ گژھہِ بند، تہٕ کانہہ تہِ گژھِ نہٕ یلہٕ۔\n23.\\tتہٕ بہٕ کٔرٕ أمِس أکِس پژھہٕ جایہ کیل لٲگِتھ۔ تہٕ سُہ آسہِ مٲلہِ سٕندِس گرس خٲطرٕ أکِس شاندار تختس خٲطرٕ۔\n24. تہٕ تِم گژھن أمِس مٲلہِ سٕندِس گرٕچ سارِنٕے عظمت، اولاد تہٕ شُر، سارِنٕے بانہٕ ہٕندِس بانہٕ پیٹھٕ پیالہ ہٕندِس بانس تام، حتیٰ کہ سارِنٕے بانن تام۔ {فلیگنن ہٕندۍ برتن: یا، وایلن ہٕندۍ آلات}\n25. اَمہِ دۅہہٕ یُس لشکرن ہُند رب چُھ ونان زِ یُس کیل یُس یقینی جایہِ لاگنہٕ آمُت چُھ، یُس یقینی جایہِ لاگنہٕ یِنہٕ یُن، تہٕ یِیہِ ژٹنہٕ تہٕ پیوٚو۔ تہٕ یُس بوجھ {اوس} یُس اتھ پیٹھ اوس، سہ گژھہِ ژٹنہٕ یُن: کیازِ خداوند چُھ کتھ کٔرمٕژ۔","1. صور سُند بوجھ۔ اے ترشِش ہٕندِس جہازس ہٕندِس جہازس ہٕندِس کُنہِ س� تکیازِ یہ چھہ ویران سپدان، یتھہ پاٹھۍ چھہ نہ کانہہ مکانہ، نہ اژُن: چِٹِم چہ زمینہٕ پیٹھہ چھہ یہ تِمن برونہہ کُن ظٲہر سپدان۔\n2. اے جزیرٕکۍ روزن والیو خاموش روزو۔ ژے یُس سمندرٕ اپارِ نیرن وٲلِس زیدونٕکۍ سوداگرو بٔرِتھ چھُ۔ {توتہِ: ہیب۔ ژھۄپہٕ}\n3.\\tتہٕ بٔڈۍ آبہٕ سٍتـ̡ سِہوٗرُک بیٲل، دریاوُک فصل، {چُھ} تٔمۍ سٕنز آمدنی۔ تہٕ سۄ چھِ قومن ہُند اکھ مارٹ۔\n4.\\tاے زیدون، شرم گژھ تکیازِ سمندرُک طاقتہٕ تہِ چُھس کتھ کٔرمٕژ، بہٕ چُھس نہٕ مُشکِل کٔرِتھ، نہ چُھس بچہٕ پٲدٕ کٔرِتھ، نہ چُھس جوان پرورش کٔرِتھ، {تہٕ نہ} کُنوارِ ہٕنز پرورش کٔرِتھ۔\n5.\\tمصرس متعلق یتھے پاٹھۍ چھہ یمن صور سنزِ خبر وچھتھ سیٹھا تکلیف گژھان۔\n6.\\tترشیشس کُن منتقل کرُن۔ اے جزیرہ کین بسکینو کٔرۍ۔\n7. {کیا یہ} چُھ تُہند خوشی {شہر}، یٔمۍ سُند قدیم زمانہٕ چُھ؟ تٔمۍ سٕندِس کھۅر نِن أمِس دور تام نِنہٕ۔ {دور ...: ہیب۔ دور پیٹھ}\n8.\\tصور سٕندِس بادشاہس سٍتـ̡ کٔمۍ سٕندِس سوداگرس {چِھ} شہزادہٕ، یێمہِ سٕندِس سوداگرس {چِھ} دٔسۍ دٔرِتھ دِنہٕ آمٕتۍ؟\n9.\\tلشکرن ہٕندِس خداوند سٍتـ̡ چُھ یہِ ارادٕ کورمُت زِ سارِنٕے عظمتُک غرور داغ دِنہٕ خٲطرٕ، {تہٕ} زمینہٕ کِس سارِنٕے عزتَس سٍتـ̡ اننہٕ خٲطرٕ۔ {داغ دِنہٕ خٲطرٕ: ہیب۔ آلودہ کرُن}\n10. اے ترشِش سٕنزِ کورِ پَنٕنہِ زمینہِ مَنٛز دٔریاوٕکۍ پٲٹھۍ، {اَتہِ چُھنہٕ کانہہ طاقت}۔ {طاقت: ہیب۔ گرڈل}\n11.\\tتٔمۍ تروو سمندرس پیٹھ اتھہٕ، تٔمۍ کٔرٕن بادشٲہی ہِلاونہٕ: خداوند چُھ سوداگرس {شہر} سٍتـ̡ حُکُم دِژمُت، یُس تِمن ہٕندِس مضبوٗط قلعس تباہ کرُن۔ {خٕلاف...: یا، أکِس سوداگر سٕندِس متعلق} {تاجر شہر: ہیب۔ کنعان} {مضبوط...: یا، طاقت}\n12.\\tتہٕ ووٚن ژے گژھ نہٕ مزید خۅش گژھُن، اے زیدون سٕنزِ کورِ، وۅتھٕ وُتھ، چِتِم کُن وُچھِو۔ تتہِ تہِ گژھہِ نہٕ آرام دِنہٕ۔\n13.\\tوچھو کلدانن ہٕنز زمین۔ یِم لُکھ اوس نہٕ، یوتام زِ اسیرین کٔر یہِ تِمن خٲطرٕ قٲیم یِم بیابانن منٛز روزان ٲسۍ: تِمو کٔر اَمہِ ہٕندِ مینار قٲیم، تِمو کٔرِکھ اَمہِ ہٕندِس محل بٔنِتھ۔ {تہٕ} تٔمۍ اوٚن یہِ برباد۔\n14.\\tاے ترشِش ہٕندِس جہازس ہٕندِس جہازس سٍتـ̡ چُھہ تُہند طاقت ضایع گومُت۔\n15.\\tتہ تمہِ دۅہہ سپدِ یہ زِ صور گژھہِ ستتھ ؤری مشراونہ یُن، أکِس بادشاہ سٕندِ دۅہہٕ مطٲبق: ستتھ ؤری ختم گژھنہٕ پتہٕ گژھہِ صور بدکار بنان۔ {کیا ٹائر...: ہیب۔ یہ گژھہِ صور سٕندِ گیونٕکۍ پٲٹھۍ آسُن}\n16.\\tاکھ ہارپ رٔٹِتھ، شہرس منز پھیُر پھیُر، اے حرام یُس مشتھ گومُت چھُ۔ مٔدٕر راگ بناوُن، واریاہ بٲتھ گیو، تاکہ ژے گژھہِ یاد روزُن۔\n17. تہٕ ستتھ ؤری سپدِتھ سپدِ زِ خداوند کرِ صورس نِش تہٕ سُہ کرِ پننہِ کرایہ کُن پھیرِ، تہٕ کرِ زمینہٕ کِس بُتھِس پیٹھ دُنیا کین سارنٕے بادشاہتن سٍتـ̡ زناکاری کرنہٕ۔\n18. تہٕ تٔمۍ سُند مال تہٕ تٔمۍ سُند کرایہ گژھہِ خداوند سٕندِ خٲطرٕ پاکیزگی آسُن: یہ گژھِ نہٕ خزانہٕ کرنہٕ یُن تہٕ نہ تھاونہٕ یُن۔ تِکیازِ تٔمۍ سُند مال گژھِ تِمن ہٕندِ خٲطرٕ یُس خداوند سٕندِ برونہہ کُن روزان چُھ، سٮ۪ٹھاہ کھٮ۪نہٕ خٲطرٕ تہٕ پایدار پلون ہٕندِ خٲطرٕ۔ {پائیدار: ہیب۔ پرانہِ}","1. وچھو خداوند چُھ زمینہِ خٲلی بناوان، تہٕ اَتھ کُن پھیُر کٔرِتھ تہٕ اَتھ منز روزن وٲلِس بسکیٖن بٔنِتھ پھٔہلِتھ دِوان۔ {turneth...: Heb. اتھ بُتھِس پھیُر کٔرِتھ}\n2. تہٕ یِتھٕ پٲٹھۍ، لُکن سٍتـ̡ تہٕ پادٕرِس سٍتـ̡ آسہِ۔ یتھے پاٹھۍ نوکر سٍتۍ، تتھے پاٹھۍ چھہ پننس آقا سٍتۍ۔ یِتھے پٲٹھۍ نونہِ ہٕندِس مالکن سٍتۍ تہِ۔ یِتھ کٔنۍ زَن خٔریٖدارَس سٕتۍ، یِتھ کٔنۍ کٕنَن وٲلِس سٕتۍ۔ یِتھ کٔنۍ زَن قرض دِنہٕ وٲلِس سٕتۍ؛ یتھے پاٹھۍ چھہ سود خور تہ سود دنہ وٲلس سٍتۍ۔ {پادری: یا، شہزادہ}\n3. زمین گژھہِ پوٗرٕ پٲٹھـ̡ خٲلی کرنہٕ یُن، تہٕ پوٗرٕ پٲٹھـ̡ برباد کرنہٕ یُن: کیازِ خداوند چُھ یہِ کلام کٔرمُت۔\n4.\\tزمین چھہ ماتم کران {تہٕ} ختم سپدان، دنیا چھہ ختم گژھان {تہٕ} ختم سپدان، زمینہِ ہندۍ مغرور لوکھ چھہِ کمزور گژھان۔ {مغرور...: ہیب۔ لوکن ہند تھزر}\n5.\\tزمین تہِ چھیہ امہ کین بسکینن تل ناپاک کرنہ آمژ۔ تِکیازِ تِمو چُھ قونوٗنٕچ خلاف ورزی کٔرمٕژ، آرڈیننس بدلٲومُت، ابدی عہد پھُٹرٲومُت۔\n6. تێمہِ کِنۍ چُھ لعنتَن زمینہِ کھٮ۪نہٕ آمُت، تہٕ یێمہِ مَنٛز روزن وٲلِس چھِ ویران گٔمٕتۍ، تێمہِ مۄکھٕ گٔیہِ زمینہِ ہٕندِس بسکیٖن دٔسۍ زٲلِتھ تہٕ واریاہ کم انسان باقٕے گٔیہِ۔\n7. نوِ شرابُک ماتم چُھ، بیل چھُ ماتم کران، سارِنٕے خۅش دِل چھِ شہہ دِوان۔\n8.\\tتِمن ہُند خۅش چُھ بند سپدان، یِمن ہُند شور چُھ ختم سپدان، ہارپٕچ خوشی چھِ ختم گژھان۔\n9. تِم گژھِ نہٕ گٮ۪ونَس سٍتـ̡ شراب۔ یُس یہ چیوان چُھ، تِمن ہٕندِ خٲطرٕ گژھہِ تِمن ہٕندِ خٲطرٕ تلخ روزُن۔\n10.\\tانتشار ہُند شہر چُھ پھُٹمُت: پرٮ۪تھ کانہہ گرٕ چُھ بند کرنہٕ آمُت، یُتھ نہٕ کانہہ تہِ انسان اژِتھ۔\n11. سڑکن منز چُھ شرابُک فریاد ۔ سورے خوشی چھیہ گٔژھمژ، زمینچ خوشی چھیہ ختم۔\n12. شہرس منز چُھ ویران تہٕ دروازٕ چُھ تباہی سٍتـ̡ مارنہٕ آمُت۔\n13.\\tیێلہِ یِتھٕ پٲٹھۍ آسہِ لُکن ہٕندِس زمینس مَنٛز، {تہٕ} یِتھٕ پٲٹھۍ آسہِ زیتونُک کُلِس ہِلاونہٕ یِن، {تہٕ} یِتھٕ پٲٹھۍ آسہِ زِ وُنٹیج سپدِ۔\n14. تِم تُلِن پنٕنۍ آواز تُل، تِم گٮ۪وَن خداوند سٕنزِ عظمتٕ خٲطرٕ، تِم گَژھن سمندرٕ پیٹھٕ بَڑِ پٲٹھۍ۔\n15. لہٰذا کرو نارس مَنٛز خداوند سُند حمد تہٕ سمندرٕ کِس جزیرس مَنٛز اسرٲیلُک خداوند خدا سُند ناو۔ {نار: یا، وادی}\n16.\\tزمینہِ ہندِ اندۍ پکھۍ پیٹھے چھہِ اسہِ بٲتھ بوزمُت، {حتیٰ کہ} صالحن ہُند جلال تہِ۔ مگر میہ ووٚن، میٲنۍ پتلی، میٲنۍ پتلی، افسوس! غدار سوداگر چھہ غداری سان ورتاومت۔ آ، غدار ڈیلرَو چھُ واریاہ غدٲری سان نمٹان۔ {مطلق...: ہیب۔ ونگ} {میون لوٚب: ہیب۔ میانہِ خٲطرٕ لٔکۍ، یا میون راز}\n17.\\tخوف، تہٕ کھۅپھ تہٕ جال، اے زمینہِ ہندس بسکینس پیٹھ۔\n18.\\tتہٕ یُس خوفہٕ کہِ شورٕ نِش ژلہِ سُہ گژھہِ کھۅنہِ مَنٛز پیوٚو۔ تہٕ یُس کھۅنہٕ منزہ نیرِ، سُہ گژھہِ جالس منز نِنہٕ: تکیازِ تھزرِ پیٹھٕ دارِ چھِ یلہٕ تہٕ زمینہِ ہٕنز بُنیاد چھِ لرزان۔\n19.\\tزمین چھیہ یکسر پھٹمژ، زمین چھیہ صاف پاٹھۍ تحلیل سپدان، زمین چھیہ سیٹھا ہلان۔\n20.\\tزمین گژھہِ شرابہٕ سٕندۍ پٲٹھۍ، تہٕ یِیہِ کُنہِ کُنہِ پٲٹھۍہٹاونہٕ۔ تہٕ اَمہ سٍتـ̡ گُرٕ گٔژھِتھ تہٕ یہ گژھہِ پیوٚو، تہٕ دُبارٕ وۅتھان نہٕ۔\n21. تہٕ یێمہِ دۅہہٕ سپدِ یہِ سپدِ، {یێلہِ}خداوند دِیہِ تھدٮ۪ن ہٕندِس لشکرس تہٕ زمینس پیٹھ موجود بادشاہن ہٕندِس لشکرس سزا۔ {سزا: ہیب۔ وزِٹ کٔرِو}\n22.\\tتہٕ یِم یِن جمع کرنہٕ، یِتھ کٔنۍ قٲدۍ یِن کھۅڈس مَنٛز جمع کرنہٕ، تہٕ یِم یِن جیلس مَنٛز بند کرنہٕ، تہٕ واریاہن دۅہن پَتہٕ یِن تِمن نِش یِنہٕ یِنہٕ۔ {بطور قید...: ہیب۔ قٲدٮ۪ن ہٕندِس اجتماعس سٍت} {دِنہٕ آمُت: یا، لٔبنہٕ آمُت}\n23. تیلہٕ گژھہِ زوٗن الجھاونہٕ تہٕ آفتاب گژھہِ شرمندٕ، یێلہِ لشکرن ہُند رب کوہ صہیون تہٕ یروشلمس مَنٛز تہٕ پننین بُتٮ۪ن پنہٕ نِس پنہٕ نِس بُتِس پٲٹھـ̡ بادشاہی کرِ۔ {امہ برونہہ...: یا، تمۍ سندِ قدیم برونہہ کنہِ جلال آسہِ}","1. اے خداوند، تو چُھہ میٲنۍ خدا۔ بہٕ کَرٕ ژےٚ تعریف، بہٕ کَرٕ چانہِ ناوٕچ تعریف۔ تکیازِ ژے چھے حیرت انگیز {چیز﴾ کٔرمٕژ؛ پرانہِ ہٕندِ مشورٕ {چِھ} وفاداری {تہٕ} سٍتـ̡\n2. تکیازِ ژے چُھ أکِس شہرس اکھ ڈھیر بنوومُت۔ {of} اکھ دفاعی شہر، اکھ کھنڈرات: اجنبین ہُند محل، یُس نہٕ شہر؛ یہٕ گژھِ نہٕ زانہہ بناونہٕ۔\n3. تێمہِ کِنۍ کٔرِن طاقتور لوٗکھ تۅہہِ ہٕنز حمد کَرٕن، خوفناک قومن ہُند شہر گژھہِ ژےٚ کھوژان۔\n4. تِکیازِ تُہۍ چھِو غریبن ہٕندِ خٲطرٕ طاقت، ضرورتمندَن ہٕندِ مصیبتس مَنٛز اکھ طاقت، طوفانہٕ نِش پناہ گاہ، گرمی نِش ژھایہ، ییلہ خوفناک لوکن ہُند دھماکہٕ دیوارس خلاف طوفانٕکۍ پٲٹھۍ۔\n5.\\tژے کٔرِو وُپرن ہُند شور یُس خشک جایہِ ہٕندِس گرمی ہٕندۍ پٲٹھۍ۔ {حتیٰ کہ} اوٚبرُک ژھایہ سٍتۍ گرمی تہِ: خوفناکَن ہٕنز لٔر یِن بۄن کٔرِتھ۔\n6. تہٕ یَتھ پہاڑس مَنٛز کرِ خداوند لشکرن سارنٕے لُکن ہٕندِ خٲطرٕ چربی چیزن ہٕنز ضیافت، لِیس پیٹھ شرابُک دعوت، موٚٹۍ چیزو سٍتـ̡ بٔرِتھ چُھہ شرابُک دعوت۔\n7. تہٕ سُہ کرِ اتھ پہاڑس مَنٛز سارنٕے لُکن ہٕندِس پردٕ سُند بُتھ تہٕ سارنٕے قومن مَنٛز پھٔہلِتھ پردٕ تہٕ سُہ پردٕ تباہ کرُن۔ {تباہ: ہیب۔ نگلُن} {کاسٹ: Heb. کور کٔرِتھ}\n8. سُہ گِلہِ فتحس منز موت؛ تہٕ خداوند خدا کرِ سارنٕے بُتھِس پیٹھٕ اوٚش صاف کرنہٕ۔ تہٕ تٔمۍ سٕندِس لوکن ہٕنز ملامت کٔرِن سٲرۍسٕے زمینہٕ نِش نِنہٕ، کیازِ خداوند چُھ کتھ کٔرمٕژ۔\n9. تہٕ تمہِ دۅہہ ییہ وننہٕ یُن، لو، یہ چُھ سون خدا۔ أسـ̡ أسـ̡ أمِس انتظار، تہٕ سُہ کرِ اسہِ بچاو: یہِ چُھہ خداوند أسۍ چھِ تٔمۍ سُند انتظار کٔرِتھ، أسۍ روزو تٔمۍ سٕنزِ نجات سٍتـ̡ خوش تہٕ شاد۔\n10.\\tیِتھ کِنہِ یَتھ پہاڑس مَنٛز گژھہِ خداوند سُند اَتھٕ آرام تہٕ موآب یِیہِ أمِس تَل دِنہٕ، یِتھٕ پٲٹھۍ گُرِ خٲطرٕ گاسہٕ لَتہٕ یِنہٕ یِوان۔ {Tradden down under: or, threshed وغیرہ} {لٔگِتھ دِنہٕ آمُت...: یا، مڈمیناہس منز تھٔرِتھ}\n11.\\tتہٕ سُہ پھٔہلٲوِن پنٕنۍ اتھہٕ یِمن منز، یِتھٕ پٲٹھۍ یُس ژھانٛٹھ وایِتھ چھُ سُہ تِمن ہٕندِس اتھہٕ سٍتـ̡ پھٔہلٲوِتھ تہٕ سُہ کرِ تِمن ہٕندِس غنیمتس سٍتـ̡ تِمن ہٕندِس غنیمتس سٍتـ̡ اَننہٕ۔\n12.\\tتہٕ تُہنزِ دیوارٕ ہٕندِس تھدِ قعلُک قعلہٕ یُس سُہ والہِ پٲٹھۍ، بٔنِتھ تہٕ زٔمیٖنس پٲٹھۍ۔","1. اَمہِ دۅہہٕ یِیہِ یہِ گٮ۪وُن یہوداہ کِس سرزمینس مَنٛز گیونہٕ۔ اسہِ چھُ اکھ مضبوٗط شہر۔ نجات دِیہِ {خدایہ} دیوارن تہٕ دیوارن ہٕندِ خٲطرٕ مُقرر کرنہٕ۔\n2. دروازٕ کھولو، یُس نیک قوم یُس حقیقتس برقرار تھاوان چُھ، اژِتھ اژِتھ۔ {حقیقت: ہیب۔ پزر }\n3.\\tژے تھاوُن سُہ پورٕ سُکوٗن سٍتـ̡ {یُس} دٮ۪ماغ {چُھ} تُہٕندِس سٍتـ̡ روزُن: کیازِ سُہ چُھہ توے پیٹھ بھروسہٕ کٔرِتھ۔ {کامل...: ہیب۔ امن، امن} {ذہن: یا، سوچ، یا، تخیل}\n4.\\tخداوند سٕندِس پٲٹھـ̡ پٲٹھـ̡ بھروسہ کرُن: کیازِکہِ خداوند یہوواہ سٕندِس سٍتـ̡ چُھہ ابدی قوت: {ابدی...: ہیب۔ دی راک آف ایجز}\n5.\\tتکیازِ سُہ چھُ تِمن ہٕندِس تھزرس پیٹھ روزن وٲلِس سٍتـ̡ بۄن کَران۔ تھدِ شہر، سہ چھہ یہ پست کران۔ سُہ چُھ اتھ بۄن کُن ترٛاوان، {حتیٰ کہ} زمینس پیٹھ۔ سُہ چُھ یہِ {حتیٰ کہ} گردِ منز انان۔\n6.\\tکھۅر گژھہِ غریبن ہٕندِس قدمس تہٕ ضرورتمندن ہٕندِس قدمس پیٹھ۔\n7.\\tصالحچ وتھ چھیہ سیدِ سیدھی: ژے چھہ نیک سنزِ وتہِ تولان۔\n8. آ، اے خداوند، چانہِ فٲصلن ہٕندِس وتہِ پى۪ٹھ، أسـ̡ چُھہ چانہِ ہُند انتظار۔ {سانہ} روحچ خواہش {چِھ} چُھہ تُہند ناو تہٕ تُہند یاداشت خٲطرٕ۔\n9. میہ کٔر پننہ روحہ سٍتۍ ژے رٲژ ہٕنز خواہش آ، پنُن روح پانس اندر آسنہٕ سٍتـ̡ بہٕ ژے سُلی ژھانڈان: یێلہِ تێلہِ تێلہِ چُھہ تُہند فیصلہٕ زمینس مَنٛز سپدِ، دُنیاہٕکۍ روزن وٲلِس نیکی ہیچھناوٕنـ̡ ۔\n10.\\tبدکارن سٍتـ̡ گژھہِ احسان کرنہٕ، {توتہِ} کیا سُہ ہیچھِ نہٕ نیکی ہیچھان: نیکی ہٕندِس ملکس مَنٛز کرِ سُہ ناانصافی سٍتـ̡ تہٕ کرِ نہٕ خداوند سٕنز عظمت وُچھان۔\n11.\\tخداوند، {ییلہِ} تُہند اَتھٕ تُلِتھ تُلِتھ، تِم گژھن نہٕ وُچھِن: {مگر} تِم گژھن وُچھن، تہٕ لُکن سٍتـ̡ حسد کرنہٕ خٲطرٕ گژھن شرمندٕ۔ آ، چانہِ دُشمن ہُند نار دِیہِ تِمن کھٮ۪وان۔ {پیٹھ...: یا، پننین لوکن کُن}\n12. اے خداوند، ژے کٔرِکھ سانہِ خٲطرٕ امنُک حکم، کیازِ ژے تہِ کٔر سانہِ سارِنٕے کامہِ اسہِ مَنٛز کٔرمٕژ۔ {اسہِ منز: یا، اسہِ خٲطرٕ}\n13. اے خداوند سٲنـ̡ خدایہ، تێے سٍتـ̡ چُھہ اسہِ سٍتـ̡ باقٕے خداوندَن ہٕندِس سٍتـ̡ حُکوٗمت حٲصِل کٔرمٕژ: {مگر} چُھہ تُہٕندِس ناوُک ذِکر۔\n14. {تِم چِھ} مٔرۍمٕتۍ، تِم گژھن نہٕ زندٕ۔ {تِم چھِ} مٔرۍمٕتۍ، تِم گژھن نہٕ وۅتھنہٕ: تَمہِ مۄکھٕ چھُکھ تِمن ہُند دورٕ تہٕ تباہ کٔرِتھ تہٕ تِہُند سورُے یاداشت ختم کٔرِتھ۔\n15. اے خداوند، ژے کٔر قومس ہُریر: ژے چُھکھ عظمت حٲصل کٔرمٕژ: ژے چُھہ زمینہٕ کِس سارِنٕے اندس تام ہٹٲومُت۔\n16.\\tخداوند، مصیبت مَنٛز چُھ تِمو تۅہہِ سٍتـ̡ دُعا دُعا دِژمٕژ۔ {دُعا: ہیب۔ خفیہ تقریر}\n17.\\tیِتھٕ پٲٹھـ̡ زنانہِ ہٕندِس زینہٕ وِزِ وِزِ وُچھان چُھ، دگ چُھہ دگ دِوان، {تہٕ} چُھہ دَگ دِوان۔ اے خداوند، تِتھے پٲٹھۍ چھِ أسۍ تہندِس نظرس منز ٲسمٕتۍ۔\n18.\\tأسۍ چھہِ شُرِ سٍتۍ، اسہِ چھہ دگ گومت، اسہِ چھہ واو نیران۔ اسہِ چُھ نہٕ زمینس منز کانہہ نجات حٲصل کٔرمٕژ۔ نہ چھہ دنیاہکۍ روزن وٲلۍ۔\n19.\\tتُہند مُردٕ {انسان} زندٕ، {رٔلِتھ} میانہِ مردہ جسمس سٍتـ̡ گژھن تِم زندٕ۔ بیدار کرو تہٕ گیو، اے یُس گردِ منز روزان چُھ، تکیازِ تُہند شبنم چُھ جڑی بوٹین ہٕنز شبنم ہٕندۍ پٲٹھۍ، تہٕ زمینہٕ کٔرِ مُردن کڈنہٕ۔\n20.\\tیِمو پَنٕنِس کمرس مَنٛز اژِو، تہٕ پَنٕنہِ دروازٕ بند کٔرِو: پَنُن پان ژوٗرِ تھووُن یِتھٕ پٲٹھۍ، یوتام نہٕ غصہٕ ژٔٹِتھ ژٔلِتھ۔\n21.\\tیِہ چُھہ خداوند پننہِ جایہِ نیبر نیران زِ زمینہِ ہندین روزن والین تہنزِ بدکاری ہُند سزا دِنہٕ خٲطرٕ: زمینہِ تہِ کرِ پنُن خوُن ظٲہر تہٕ بییہِ کرِ نہٕ تٔمۍ سٕندِس مارنہٕ آمتس پردٕ۔ {خون: ہیب۔ بلڈز}","1. اَمہِ دۅہہٕ دِیہِ خداوند پَنٕنِس دَگ تہٕ بٔڈ تہٕ مضبوٗط تلوار سٍتـ̡ دِیہِ لیویتھن، یێمہِ سٍتـ̡ سُہ کُلہٕ ناگ تہِ سزا۔ تہٕ سُہ مارِ سُہ ڈریگن یُس سمندرس منز {چُھ}۔ {سوراخ کٔرتھ: یا، بارک پٲٹھۍ عبور کران}\n2. اَمہِ دۅہہٕ گٮ۪وُن أمِس سٍتـ̡ وۄزلہِ شرابُک انگور۔\n3. بہٕ چُھس خداوند یہ رژھران۔ بہٕ کٔرٕ اتھ پریتھ ساعتہ آب دِنہٕ: نہ کنہِ تہِ تکلیف دِیہ، بہٕ تھاوٕ یہ رٲژ تہٕ دۅہ۔\n4. غصہ {چُھ} نہٕ میٲنس منٛز: جنگس منٛز کُس کرِ میٲنس خلاف بریئرس {تہٕ} کانٹہٕ؟ بہٕ اوسس تمن منزۍ نیران، بہٕ زالان یکوٹہ۔ {گژھو...: یا، مارچس خلاف مارچ}\n5.\\tیا سُہ رٔٹِتھ میانہِ طاقتس رٔٹِتھ، {یُتھ} سُہ کرِ میہ سٍتـ̡ صلح کرنہٕ۔ {تہٕ} سُہ کرِ میہ سٍتۍ صلح۔\n6. یعقوب سٕندِ سٍتـ̡ یِمن ہٕندِس سٍتـ̡ یێلہِ سٍتـ̡ بٔرِتھ تہٕ دُنِیاہ\n7.\\tکیا تٔمۍ چھُ أمِس مارٕ دِژمُت، یِتھٕ پٲٹھۍ أمِس مارٕ دِنہٕ آمُت چھُ؟ {یا} کیا سُہ چُھ تِمن ہٕندِس ذبح مطٲبق مارنہٕ آمُت یِم أمِس مارنہٕ آمٕتۍ چھِ؟ {as...: Heb. سٹروک آف } مطٲبق\n8.\\tییلہ یہ نیرِ، توے کرِ اتھ سٍتۍ بحث: سُہ چُھ مشرقی واو کِس دۅہس منز پنُن کھرٕ واو روزان۔ {یہ چُھ شوٹ کران...: یا، ژے سوزان چُھ} {یہ...: یا، ییلہ سہ یہ ہٹاوان چھُ}\n9. اَمہِ سٍتـ̡ گژھہِ یعقوب سٕنز بدکاری پاک کرنہٕ۔ تہٕ یہِ {چُھ} سٲرِے پھل یُس تٔمۍ سُند گۅناہ دوٗر کرنہٕ خٲطرٕ۔ ییلہِ سُہ قربان گاہٕکۍ تمام کٔنہِ چاک کٔنہِ بناوان چھِ، یِم سُہ ژٔٹِتھ چھِ، باغہٕ تہٕ مجسمہٕ گژھن نہٕ کھڑا گژھن۔ {تصویٖرٕ: یا، آفتاب تصویٖرٕ}\n10.\\tتوتہِ گژھہِ دفاع کٔرِتھ شہر ویران تہٕ بستی ترٲوِتھ بیابان ہٕندۍ پٲٹھۍ، اتہِ گژھہِ بچھرِ کھٮ۪نہٕ، تہٕ تتہِ گژھہِ سُہ لٔگِتھ تہٕ اَمہ چہ لنجہِ کھٮ۪نہٕ۔\n11.\\tیێلہِ یێلہِ یِمن ہٕندِس کُنہِ لُکھ یِمن ہٕندِس کُنہِ تہِ سٍتـ̡ یِمن ہٕندِس کُنہِ تہِ سٍتـ̡ یِمن ہٕندِس کُنہِ کُنہِ تہِ سٍتـ̡ دِنہٕ یِنـ̡ یێلہِ یێلہِ یِمن ہٕندِس کُنہِ کُنہِ تہِ سٍتـ̡ یِمن ہٕندِس سٍتـ̡ دِنہٕ یِنـ̡ ۔\n12. تہٕ یێمہِ دۅہہٕ سپدِ یێلہِ خداوند دریاو کِس نالہٕ پیٹھٕ مصر کِس نالہِ تام ژٔٹِتھ تہٕ اے بنی اِسرٲیلِو یِن اَکھ أکِس پٲٹھـ̡ جمع کرنہٕ۔\n13.\\tتہٕ یێمہِ دۅہہ سپدِ، یێلہِ بٔڈ بُر یِیہِ وُننہٕ، تہٕ تِم یِن یِم اسریاہس مَنٛز مرنہٕ خٲطرٕ تیار ٲسۍ، تہٕ یِم یِم مصرٕکِس سرزمینس مَنٛز مرنہٕ خٲطرٕ تیار ٲسۍ، تہٕ یِم یِن یروشلمس مَنٛز مقدس پہاڑس مَنٛز خداوند سٕنز پوٗزا کرنہٕ۔","1.\\tافرائیم سٕندِس شرابس ہٕندِس تاجس ہٕندِس سٍتـ̡ افرائیم سٕندِس شرابس ہٕندِس سٍتـ̡ ہٕندِس سٍتـ̡ پھیُر پوش چھُ، یُس شرابہٕ سٍتـ̡ ژٔلِتھ گٔژھِتھ چھُ، یُس موٚٹۍ وادی ہٕندِس کلس پیٹھ {چھُ} یِمن ہٕندِس شرابس سٍتـ̡ دِنہٕ آمُت چھُ! {مغلوب: ہیب۔ پھُٹمُت}\n2. وُچھِو، خداوند چُھ اَکھ طاقتور تہٕ مضبوٗط، {یُس} ہٕندِس طوفانٕکۍ پٲٹھۍ، یِتھٕ پٲٹھۍ، یُس زبردست آبُک سٔہلاب یُس اَتھٕ سٍتـ̡ زمینس پیٹھ تراوُن۔\n3.\\tفخرُک تاج، افرائیم سٕندِس شرابس یِن کھۅرن تَل لَگاونہٕ: {تل...: حب۔ کھۅرن سٍتۍ}\n4.\\tتہٕ سُہ شاندار خوبصورتی، یُس موٹۍ وادی ہٕندِس کلس پیٹھ {چُھ}، سُہ آسہِ اکھ ژھوٚٹُن پوش، {تہٕ} یُس رٮ۪تہٕ کالہٕ برونہہ جلدی پھل آسہِ۔ یُس {ییلہ} یُس اتھ وچھان چُھ، سہ چُھ وُچھان، ییلہ زن یہ وُنہِ تہِ پننس اتھس منز آسان چُھ، سُہ چُھ یہ کھیوان۔ {کھٮ۪وان: ہیب۔ نگلُن}\n5. اَمہِ دۅہہٕ آسہِ لشکرن ہُند رب جلال ہُند تاج، تہٕ خوبصورتی ہٕندِس تاج خٲطرٕ، پننین لوکن ہٕندِس باقیاتس خٲطرٕ،\n6.\\tتہٕ یُس فیصلس منز بِہتھ آسہِ، تہٕ تِمن ہٕندِ خٲطرٕ یُس جنگہٕ دروازس کُن پھیرِ۔\n7.\\tمگر تِمو چُھ شرابہٕ سٍتـ̡ غلطی کٔرمٕژ، تہٕ تیز شرابہٕ سٍتـ̡ چُھہ وتہٕ نِش دوٗر گٔمٕتـ̡ پادٕرۍ تہٕ نبی صلی اللہ علیہ وآلہ وسلم چِھ گٔمٕتۍ، تِم چِھ شرابہٕ سٍتـ̡ نِنہٕ آمٕتۍ، تِم چِھہ شرابہٕ سٍتـ̡ وتہٕ نِش نیران۔ تم چھہِ وژنس منز غلطی کران، تم چھہِ فیصلس منز ٹھوکر کھیوان۔\n8.\\tسارِنٕے ٹیبل چھِ اُلٹی {تہٕ} گندٕ سٍتۍ بٔرِتھ، {یُتھ} جاے آسہِ نہٕ۔\n9. سُہ کُس علم ہیچھناوُن؟ تہٕ سُہ کُس کرِ نظریہٕ سمجھنہٕ خٲطرٕ؟ {تِم یِم دۄدٕ نِش چھِ} دۄدٕ نِش دِنہٕ آمٕتۍ، {تہٕ} چھِ سینو منزٕ کڈنہٕ آمٕتۍ۔ {نظریہ: ہیب۔ سماعت؟}\n10.\\tاصولس پیٹھ {گژھہِ آسُن}، حکم پیٹھ حکم۔ لٲنہٕ پتہٕ لٲنہٕ، لٲن پتہٕ لائن؛ ییتہِ تھوڑا تھوڑا ، {تہ} تتہِ تھوڑا سا : {گژھہِ آسن: یا، ہا ہا ہا}\n11.\\tتکیازِ سُہ کرِ یِمن لوکن سٍتـ̡ کتھ کرنہٕ۔ {ٹھٹھاہ کٔرتھ...: ہیب۔ وٕٹھن ہٕنز ٹھٹھاہ} {وِل...: یا، تٔمۍ کٔر بولہٕ}\n12.\\tیمۍ ووٚن زِ یہ چھہ باقی {یُس سٍت} تۅہہ تھکان وٲلس آرام دِتھ۔ تہٕ یہ {چُھ} تازگی بخش: توتہِ ٲسۍ نہٕ تِم بوزان۔\n13. مگر خداوند سُند کلام اوس تِمن خٲطرٕ حکمہٕ پتہٕ حکم، حکمہٕ پتہٕ حکم۔ لٲنہٕ پتہٕ لٲنہٕ، لٲن پتہٕ لائن؛ ییتہِ تھوڑا تھوڑا ، {تہ} تتہِ تھوڑا ؛ تاکہ تِم گژھن، تہٕ پتھ کُن پیٚتھ، تہٕ پھُٹنہٕ یِن، تہٕ پھٔٹِتھ تہٕ رٔٹِتھ نِنہٕ۔\n14. یێمہِ کِنۍ بوزو خداوند سُند کلام یُس یِمن لُکن پیٹھ یُس یروشلمس مَنٛز {چُھ} چُھ۔\n15.\\tکیازِ تۅہہ چُھ ووٚنمُت، اسہِ چُھ موتس سٍتـ̡ عہد کورمُت، تہٕ جہنمس سٍتـ̡ چُھہ أسـ̡ معاہدٕ۔ ییلہ یُس وُپھ وُپھ وُچھِ، سُہ واتہِ نہٕ اسہِ نِش: کیازِ أسۍ چھِ اپُز پنُن پناہ بنوومُت، تہٕ اپزس تل چھُ أسۍ پنُن پان ژوٗرِ تھوومُت:\n16. تێمہِ کِنۍ چُھہ خداوند خدایہ ونان، وُچھو بہٕ زیونس مَنٛز اکھ کٔن، اکھ آزماونہٕ آمُت کٔن، اکھ قیمتی کونہٕ، اکھ یقینی بنیاد: یُس ایمان تھاوان چُھ، سُہ گژھہِ نہٕ جلدی کرُن۔\n17. فیصلہٕ تہِ کرٕ بہٕ لٲنہِ پیٹھ، تہٕ نیکی تہٕ ژٔٹِتھ ژٔلِتھ تہٕ آبہٕ ژٔلِتھ\n18. تہٕ تُہند موتس سٍتـ̡ عہد گژھہِ منسوخ کرنہٕ، تہٕ جہنمس سٍتـ̡ گژھہِ نہٕ تُہند معاہدٕ قٲیِم روزُن۔ ییلہِ وُپھ وُپھ وُچھِو، تیلہِ گژھہِ تۅہہِ اتھ سٍتۍ لَسنہٕ۔ {trodden...: Heb. اَتھ کُن پَکُن}\n19.\\tیێلہِ یێلہِ یہِ نیرِ، یێلہِ سٍتـ̡ یہِ چُھہ صُبحہٕ سٍتـ̡ نیرِ، دۅہہٕ تہٕ رٲژ نیرِتھ، تہٕ یہِ آسہِ صرف یہِ رِپوٹ سمجنہٕ خٲطرٕ پریشٲنی ہٕندِس سٍتـ̡ ۔ {to...: یا، ییلہ سُہ ژیہ نظریہ سمجھناوِ}\n20.\\tتکیازِ بسترس چھہ امہِ کھۅتہ ژھوٚٹ آسان {انسان} چھہ پنن پان {اتھ پیٹھ} پھیُرِتھ: تہ پوشہ چھہ تمہِ کھۅتہ تنگ تہ تنگ ہیکہِ پانس {اتھ منز} ؤلتھ۔\n21. یێلہِ خداوند گژھہِ {منز} پہاڑ پیرازمس سٍتـ̡ وۅتھان تہٕ سُہ گژھہِ گِبیونٕچ وادی ہٕندِس پٲٹھـ̡ غصہٕ سٍتـ̡ یُتھ سُہ پَنٕنـ̡ کامہِ کامہِ سٍتـ̡ کٔرِتھ، پنٕنـ̡ عجیب کامہِ ہٕندِس سٍتـ̡ کرُن؛ تہٕ اَنُن پنُن عمل، تٔمۍ سُند عجیب عمل۔\n22. تێمہِ کِنۍ گژھ نہٕ تم ٹھٹھہٕ کٔرِو، یێلہِ گژھن تُہٕندِس لشکرس سٍتـ̡ مضبوٗط کرنہٕ، کیازِ مے چُھہ لشکرن ہٕندِس خداہس سٍتـ̡\n23.\\tبوز تہٕ بوز میٲنۍ آواز۔ بوزو تہٕ بوزو میون کلام۔\n24.\\tہل چُھ سٲرۍسٕے دۅہس ہل دِوان؟ کیا سُہ چھُ پننہِ زمینہِ ہٕندِس گٔنڈِس کھولان تہٕ پھُٹراوان؟\n25.\\tییلہ سہ امیک بُتھ صاف کرِ، کیا سُہ چھُنہٕ پھیپھ کٔرِتھ، تہٕ کٔرِتھ کُنُک تہٕ مُقرر کٔرِتھ تہٕ تِمن ہٕندِس جایہ کُنُک تہٕ مُقرر کٔرِتھ؟ {پرنسپل...: یا، اصل جایہِ پیٹھ کٕنُک، تہٕ مقرر جایہِ پیٹھ جو} {ری: یا، اسپیلٹ} {جاے: ہیب۔ بارڈر؟}\n26. تکیازِ تٔمۍ سُند خدا چُھ أمِس صوابدید کرنُک حکم دِوان، {تہٕ} چُھ أمِس ہیچھناوان ۔ {کیازِ...: یا، تہٕ سُہ چُھ اتھ تِتھۍ پٲٹھۍ پابند کران یُس تٔمۍ سُند خدایہ أمس ہیچھناوان چُھ}\n27.\\tتکیازِ کُنہ مگر فِچس چھِ لٔرِ سٍتۍ مارنہٕ یِوان، تہٕ کُمن چھِ لٔرِ سٍتۍ مارنہٕ یِوان۔\n28.\\tبریڈ {مکایہ} چھہ زخم لگان۔ تکیازِ سُہ کرِ نہٕ زانہہ تہِ اتھ تھپھ کٔرِتھ، نہ پھُٹراوِ پننہِ گاڑِ ہٕندِس چکرس سٍتۍ، تہٕ نہ کرِ پننین گُرۍ سوارَن سٍتۍ زخم۔\n29.\\tیہِ تہِ چُھ خداوند سٕندِ طرفہٕ نیران، {یُس} مشورس مَنٛز شاندار چُھ، {تہٕ} کامہِ مَنٛز بہترین۔","1. ایریئلُک افسوس، ایریئل، شہر {ییتہِ} ڈیوڈ روزان اوس! ؤری پتہٕ ؤری شٲمِل کٔرِو؛ تِم گژھن قربانی مارٕنۍ۔ {افسوس...: یا، اے ایریئل، یعنی خدایہ سُند شیر} {شہر: یا، شہرُک} {مارُن: ہیب۔ کلہٕ ژٹِو}\n2.\\tتوتہِ کرِ بہٕ ایریئلس پریشان تہٕ اتہِ گژھہِ گۅب تہٕ غم: تہٕ یہ آسہِ میانہِ خٲطرٕ ایریئل سٕندۍ پٲٹھۍ۔\n3. تہٕ بہٕ کَرٕ ژےٚ اندۍ پٔکھۍ خٕلاف ڈیرٕ، تہٕ کَرٕ ژےٚ خٕلاف أکِس پہاڑ سٍتـ̡ محاصرٕ، تہٕ بہٕ کَرٕ ژےٚ خٕلاف قٕلہٕ۔\n4.\\tتہٕ ژے گژھہِ زمینہِ منزہ کتھ کرنہٕ، تہٕ تہنز کتھ گژھہِ میژِ منزہ نیرِ، تہٕ تہنز آواز گژھہِ تٔمِس سٍتـ̡ یُس مانوس روح آسہِ، زمینہٕ منزٕ نیرِ، تہٕ تُہند کلام گژھہِ گردِ منزٕ سرگوشی کرنہٕ۔ {سرگوشی: ہیب۔ پیپ، یا، چِرپ}\n5.\\tامہِ علاوہ گژھہِ تۅہہِ ہٕندِس اجنبی ہٕندِس بٔڈِس لۅکٹِس گردِ ہٕندۍ پٲٹھۍ، تہٕ خوفناکَن ہٕنز بٔڈِتھ آسہِ ژٔلِتھ: آ، یہ گژھہِ اَکہِ ساتہٕ اَکہِ ساتہٕ۔\n6. لشکرن ہٕندِس رب سٕندِ سٍتـ̡ گُرگٕر، تہٕ زلزلہٕ سٍتـ̡ تہٕ بٔڈۍ شورٕ سٍتـ̡ تہٕ طوٗفہٕ سٍتـ̡ تہٕ نارٕ سٍتـ̡ دِنہٕ یُن۔\n7.\\tتہٕ سارِنٕے قومن ہُند بٔڈ یُس ایریلس خلاف لڑان چُھ، حتیٰ کہ یِم سٲری أمِس تہٕ تٔمۍ سٕندِس گولہٕ بارودس خلاف لڑان چھِ، تہٕ یِم أمِس پریشان کران چھِ، سُہ آسہِ رٲژ ہُند خواب۔\n8.\\tیہ تہِ گژھہِ یُتھ زن اکھ فاقہٕ {انسان} خواب وچھان چھُ، تہٕ وُچھِتھ چھُ سُہ کھٮ۪وان۔ مگر سُہ چُھ بیدار سپدان، تہٕ تٔمۍ سُند روح چُھ خٲلی: یا یِتھے پٲٹھۍ ییلہ اکھ ترشیہ انسان خواب چُھ وچھان، تہٕ وُچھ، سُہ چُھ چُھ؛ مگر سُہ چُھ بیدار سپدان، تہٕ وُچھ، {سُہ} چُھہ بے ہوش گومُت، تہٕ تٔمۍ سٕندِس روحس چُھ بھوک: یِتھے پٲٹھۍ گژھہِ سارِنٕے قومن ہٕنز بٔڈِتھ یُس کوہ صییونس خلاف لڑان چُھ۔\n9.\\tپان رٔٹِتھ تہٕ حیران۔ تُہۍ چِھ کرٛٮ۪کھ دِوان، تہٕ چُھکھ کرٛٮ۪وان: تِم چِھ شرابہٕ سٍتۍ، مگر شرابہٕ سٍتـ̡ نہٕ۔ تِم چھِ لڑکھران، مگر تیز شرابہٕ سۭتۍ نہٕ۔ {کرو یے...: یا، پنٕنۍ خوشی نِن، تہٕ ہنگامہٕ}\n10.\\tکیازِ خداوند چُھہ تۅہہِ سٍتـ̡ گۆو نِندرِ ہُند روح تہٕ چُھہ تُہٕنزِ أچھ بند کٔرمٕژ: پیغمبرن تہٕ تُہٕندِس حُکُرانن ہٕندِس سٍتـ̡ چُھہ تُہٕندِس سٍتـ̡ پردٕ کورمُت۔ {حکمران: ہیب۔ ہیڈز}\n11.\\tتہٕ سارِنٕے ہُند وژن چُھہ تۅہہِ خٲطرٕ أکِس کتابہِ ہٕندِس کلامٕکۍ پٲٹھۍ، یُس {انسان} عالمس تام واتناوان چھُ، یہِ پٔرِو، بہٕ چھُس دُعا کران تہٕ سُہ چُھس ونان زِ بہٕ چُھس نہٕ کٔرِتھ۔ تکیازِ اتھ {is} مہر: {کتاب: یا، خط}\n12.\\tتہٕ کتاب چھے تٔمِس نِش دِنہٕ آمٕژ یُس نہٕ پران آسہِ، تہٕ سُہ چُھس ونان زِ بہٕ چُھس نہٕ عٲلِم۔\n13. اَمہِ مۄکھٕ چُھہ خداوند وۆنُن، یێلہِ یِم لُکھ چُھس میہ نِش تہٕ چپنہٕ سٍتـ̡ چُھہ میہ عزت کران، مگر چُھکھ پنُن دِل میانہِ نِش دور کٔرِتھ، تہٕ تِہُند خوف چُھہ اِنسانن ہٕندِ حکمہٕ سٍتـ̡ ہیچھناونہٕ آمُت:\n14. تێمہِ کِنۍ، وُچھِو بہٕ یِمن لُکن مَنٛز اکھ حیرت انگیز کٲم کٔرِتھ، {حتیٰ کہ} اکھ حیرت انگیز کٲم تہٕ اکھ عجائب تہٕ: تِکیازِ تِہٕندِس دانشمندَن ہٕنز حکمت گژھہِ ختم تہٕ تِہٕندِس ہوشیار {انسان} ہٕنز سمجھ گژھہِ پوشیدٕ۔ {برونٹھ کُن: ہیب۔ add}\n15.\\tتِمن ہٕندِ خٲطرٕ افسوس یُس خداوند نِش پنُن مشورٕ ژوٗرِ تھاوُن یژھان چھِ، تہٕ تِہٕندِ اعمال چھِ اندپِس مَنٛز، تہٕ تِم چھِ ونان زِ اسہِ کُس چُھ وُچھان؟ تہٕ اسہِ کُس چُھ زانان؟\n16.\\tیقینا یُس تۅہہِ چیزن الٹا پھیُر کرُن ییہ کمہار سٕنزِ میژِ ہٕندۍ پٲٹھۍ، تکیازِ یُس یہ کٲم بنوومُت چھُ، تٔمۍ بنوو نہٕ میہ کٔرِتھ؟ نتہ یُس چیز فریم کرنہ آمت اوس، سہ چھہ نہ تس کانہہ سمجھ تھاوان۔\n17.\\tکیا یہ چھہ نہ وُنہِ تہِ کم کال، تہ لبنان ییہ پھلہٕ دار کھیت بننہ، تہٕ پھلہٕ دار کھیت ییہ جنگل ماننہٕ؟\n18. تہٕ اَمہِ دۅہہٕ بٔرِس کتابہِ ہٕندِ کلامٕچ کتھ بوزنہٕ تہٕ اَنہِ گُملہٕ منزٕ تہٕ انہِ گٹہِ منزٕ وُچھن ۔\n19.\\tعاجز تہِ گژھن خداوند سٕندِس سٍتـ̡ خوشی ہُرراوٕن، تہٕ انسانن مَنٛز غریبن گژھن اسرٲیلِس مُقدس سٍتـ̡ شاد سپدٕنـ̡۔ {اضافہ: ہیب۔ add}\n20. تکیازِ خوفناک چُھ ختم سپدان، تہٕ بدکار چُھ کھٮ۪نہٕ یوان، تہٕ بدکاری ہٕندِس سارِنٕے سٍتـ̡ چُھ ژٹنہٕ یِوان:\n21.\\tیُس انسانس کُنہِ لفظہ خٲطرٕ مجرم بناوُن، تہٕ یُس دروازس پیٹھ ملامت کران چھُ، تہٕ یُس کُنہِ چیزس پیٹھ انصاف کرِ۔\n22. تێمہِ کِنۍ چُھ یعقوب سٕندِس گرس مُتعلِق یعقوب سٕندِس گرس مُتعلِق یێلہِ یعقوب سٕندِس گرس مُتعلِق یێلہِ نہٕ یعقوب شرمندٕ سپدُن، تہٕ تٔمِس بُتھ گژھہِ نہٕ وُنہِ شرمندٕ۔\n23. مگر ییلہ سُہ پننین شُرین میانین اتھن ہٕنز کٲم وُچھِ، تِم گژھن میٲنۍ ناو پاک تہٕ یعقوب سُند پاک کرُن، تہٕ کرِ اسرٲیلِکِس خدایہِ سُند خوف۔\n24. یِم روحس منز غلطی کٔرۍ، تِم تہِ گژھن سمجھ تہٕ یِم سرگوشی کٔرِن تِم گژھن نظریہٕ ہیچھن۔ {آ...: ہیب۔ سمجھ زانو}","1. خداوند چُھ ونان زِ باغی شُرین ہٕندِ خٲطرٕ افسوس، یُس مشورٕ نِوان چُھ، مگر میانہِ سٍتـ̡ نہٕ۔ تہٕ یُس پردٕ سٍتـ̡ پردٕ کٔرِتھ، مگر میانہِ روحُک نہٕ، یُتھ تِم گۅنہٕ سٍتـ̡ گۅنہٕ سٍتـ̡ شٲمل کٔرِتھ:\n2.\\tسُہ پَکُن مصرس مَنٛز گژھُن، تہٕ چُھس نہٕ میٲنِس ٲسس مَنٛز پرژھمُت۔ فرعون سٕندِس طاقتس منز پنُن پان مضبوٗط کرنہٕ خٲطرٕ، تہٕ مصر کِس ژھایہِ پیٹھ بھروسہٕ کرنہٕ خٲطرٕ!\n3. تێمہِ کِنۍ گژھہِ فرعون سُند طاقت تۅہہِ شرم تہٕ مصر کِس ژھایہِ پیٹھ بھروس۔\n4.\\tتکیازِ تٔمۍ سٕندِ شہزادٕ ٲسۍ زونس منز، تہٕ تٔمۍ سٕندِ سفیر آیہ ہینس کُن۔\n5.\\tتِم سارِنٕے ٲسۍ أکِس یِتھِس لُکہٕ سٍتـ̡ شرم کٔرِتھ {یُس نہٕ تِمن فٲیدٕ دِتھ تہٕ نہٕ فٲیدٕ دِنہٕ سٍتـ̡ بٔنِتھ بلکہ ٲس شرمندگی تہٕ ملامت تہِ۔\n6.\\tجنوبٕکۍ درندَن ہُند بوج: مصیبت تہٕ اذیت ہٕندِس سرزمینس منز، ییتہِ پیٹھہٕ جوان تہٕ بُزرگ شیر، سانپ تہٕ آتش وُڑن ناگ، تِم نِن پنُن دولت جوان گَرَن ہٕندِس پھیکس پیٹھ، تہٕ پنُن خزانہٕ اونٹٮ۪ن ہٕندِس گٔنڈِس پیٹھ، تِمن لُکن ہٕندِس فٲیدٕ کُن یُس نہٕ تِمن فٲیدٕ دِیہِ۔\n7. مصری گژھن بیکار تہٕ کُنہِ تہِ فٲیدٕ سٍتـ̡ مدد، تێمہِ مۅکھہ چُھس بہٕ وۆنمُت، تِہُند طاقت چُھہ بِہنہٕ خٲطرٕ۔ {متعلق...: یا، أمِس کُن}\n8.\\tوۅنۍ گژھِ، یہ لیکھِو تِمن برونہہ کُن أکِس میزس منز، تہٕ کُنہِ کتابہِ منز لیکھِتھ، یُتھ زِ یہ گژھہِ یِنہٕ وٲلِس وقتس خٲطرٕ: {the...: Heb. ٲخری دۄہ}\n9. یہِ {چُھ} اکھ باغی لُکھ، اپُز بچہٕ، بچہٕ {یُس} چُھہ نہٕ خداوند سُند شریعت بوزُن:\n10.\\tیُس وُچھن والٮ۪ن ونان چھِ، وُچھِو نہٕ۔ تہٕ پیغمبرن کُن، اسہِ سٍتـ̡ کٔرِو نہٕ صحیح چیزن ہٕنز پیشن گوئی، اسہِ سٍتـ̡ کتھ کرٕن، پیشن گویی کٔرِو دھوکہٕ:\n11. وتہِ نِش ہٹاوُن، وتہِ نِش پھیرُن، اسرٲیلُک پاک کرُن اسہِ برونہہ کُن رُکاونہٕ۔\n12. اَمہِ مۄکھٕ چُھ اسرٲیلُک مقدس فرماوان، کیازِ تُہۍ چھِو اتھ لفظس حقارت کران، تہٕ ظلمس تہٕ بدکاری پیٹھ بھروسہ کران چھِو، تہٕ اتھ پیٹھ روزان چھِو: {ظلم: یا، دھوکہ}\n13.\\tتێلہِ گژھہِ یہ بدکاری ژۅہہِ ہٕندِ خٲطرٕ یُس تھدِ دیوارس منز پھُٹان چھُ، یێمِس پھُٹُن اچانک سپدِ۔\n14.\\tتہٕ سُہ پھُٹراوُن یُس کمہارن ہٕندِس بانس پھُٹراونہٕ یُس ٹُکرٕ ٹُکرٕ پھُٹِتھ آسہِ۔ سُہ گژھہِ نہٕ تراوُن: یُتھ زِ اتھ پھٹنس منز گژھہِ نہ کانہہ شُکرٕ لبنہٕ یُس نارٕ منزٕ نار نِنہٕ خٲطرٕ، یا کھۅلہٕ منزٕ آب نِنہٕ خٲطرٕ۔ {کمہارن ہٕندِ...: ہیب۔ کمہارن ہٕنٛز بوتل}\n15. یِتھٕ پٲٹھۍ چُھ خداوند خدا، یُس اسرٲیلُک مقدس چُھ، ونان چُھ؛ واپس یِنہٕ سٍتـ̡ تہٕ آرام کرنہٕ سٍتـ̡ یِیہِ نجات دِنہٕ۔ خاموشی تہٕ اعتمادس منز آسہِ تُہند طاقت: تہٕ تۅہہ کرِ نہٕ۔\n16.\\tمگر تۅہہ ووٚن نہ۔ تکیازِ أسۍ ژٔلِو گُرٮ۪ن پیٹھ ژلان۔ لہٰذا ژٔلِو ژٔلِتھ: تہٕ أسۍ کٔرِو تیز رفتارس پیٹھ سوارِ۔ تَمہِ مۄکھٕ گژھن تُہُند تعاقب کرن وٲلۍ۔\n17.\\tاکھ ساس ژلِتھ ژلِتھ أکِس سٕندِس ملامت سٍتـ̡ پانژن ہٕندِس ملامت سٍتـ̡ ژٔلِتھ ژٔلِو: یوتام نہٕ تۅہہ أکِس بالہٕ کِس تینتٲلِس پیٹھ تہٕ بالہٕ پٲٹھـ̡ نِش بٔنِتھ تراونہٕ یِو۔ {اکھ بیکن: یا، اکھ کُل یُس لنجہِ نِش محروم چُھ، یا، لنجہِ: یا، اکھ مستول}\n18. تہٕ تێمہِ کِنۍ روزِ خداوند انتظار، یێلہِ سُہ گژھہِ تۅہہِ سٍتـ̡ مہربان تہٕ تێلہِ گژھہِ سُہ تۅہہِ پیٹھ رحم کرُن، تکیازِ خداوند چُھہ انصاف سُند خدا: سُہ چُھہ سارِنٕے سٍتـ̡ یُس أمِس پیاران چُھ، سُہ چُھہ مُبارک۔\n19.\\tیِکیازِ لُکھ روزِ یروشلمس مَنٛز صییونس مَنٛز روزُن: تہٕ تُہٕندِس فریاد سٍتـ̡ گژھِ نہٕ تۅہہِ سٍتـ̡ سٮ۪ٹھاہ مہربان ۔ ییلہ سُہ یہ بوزِ، سُہ کرِ تۅہہِ جواب۔\n20. تہٕ {یودوَن}خداوند چُھہ ژے مُصیبتٕچ روٹی تہٕ مصیبتُک آب دِوان، توتہِ گژھِ نہٕ تُہند وۄستاد کُنہِ کونس مَنٛز ہٹاونہٕ یِن، مگر تۅہہِ ہٕنزِ أچھ وُچھن تُہٕندِس وۄستادَن ہٕندِس اُستادَس سٍتـ̡ {مصیبت: یا، ظلم}\n21.\\tتہٕ تُہٕندِس کَن بوزِن پَتہٕ کُن اکھ لفظ، یێلہِ تہٕ یێلہِ دٔچھُن کُن پھیرِو، تہٕ ییلہ کھوورِ کُن پھیرِو۔\n22.\\tژے کٔرِو پننہِ رۅپہِ ہٕنزِ کھٔنِتھ تہٕ پنہٕ نِس سۄنہٕ سٕندِس زیورٕ سٍتـ̡ تہِ ناپاک کٔرِتھ، تہٕ ژے کٔرِو یِم ماہواری ہٕندِس پلوس ہٕندِس پٲٹھۍ۔ ژے وَنُن اَتھ کُن نیرُن۔ {تیری قبر...: ہیب۔ تُہنزِ رۄپہٕ ہٕنز کھٔنِتھ بٔنِتھ تصویرٕ} {کاسٹ: ہیب۔ بکھرُن}\n23.\\tتیلہِ دِیہِ سُہ چانہِ بیٲلہِ ہُند روٗد، یُتھ ژٕ ژٕ وُنُن زمین۔ تہٕ زمینہِ ہٕندِس بڑاونُک روٹ، تہٕ یہِ آسہِ چربی تہٕ سٮ۪ٹھاہ زیادٕ: تمہِ دۅہہٕ گژھہِ تُہند چاروٕ بٔڑٮ۪ن مرگہن منز چارہٕ۔\n24.\\tیِتھے پٲٹھۍ چھِ بیل تہٕ جوان گَرٕ یِم زمینہٕ کٔنۍ کٔرِتھ کھٮ۪وان چھِ، یُس بیلچہٕ تہٕ پنکھہٕ سٍتۍ ژٔٹِتھ آسہِ۔ {صاف: یا، ذائقہ: ہیب۔ خمیر}\n25.\\tتہٕ پرٮ۪تھ تھدِ بالس پیٹھ، تہٕ پرٮ۪تھ تھدِ بالس پیٹھ، عظیم قتل عام کِس دۅہس پیٹھ آسہِ آبٕکۍ نالہٕ تہٕ آبٕکۍ نالہٕ، ییٚلہِ مینار پیٚیہِ۔ {ہائی ہل: ہیب۔ تُلِتھ وغیرہ}\n26. امہِ علاوہ گژھہِ زونہِ ہُند گاش آفتابُک گاش ہیوٗ تہٕ آفتابُک گاش گژھہِ ستن دۅہن ہٕندِس گاشس ہٕندۍ پٲٹھۍ، یێلہِ خداوند پننین لوکن ہٕندِس گاشس رٔٹِتھ تہٕ تِہٕندِس زخمُک زخم ٹھیک کرِ۔\n27.\\tوُچھِو خداوند سُند ناو دوٗرِ پیٹھٕ یِوان، تہٕ تٔمِس سٍتـ̡ چُھہ بٔرِتھ تہٕ تٔمۍ سٕنز زبان چُھہ دِنہٕ وٲلِس نارس سٍتـ̡ بٔرِتھ: {بوجھ...: یا، نارُک گُر} {گۄب: ہیب۔ وزن}\n28.\\tتہٕ تٔمۍ سُند دم گژھہِ گردنہِ منز وُچھِتھ تہٕ قومن ہٕندِس بٔڈِس سٍتۍ واتہِ: تہٕ لُکن ہٕندِس مٔنزِس مَنٛز گژھہِ اکھ لگام تہٕ یِمن ہٕندِس گۅپھ سٍتـ̡ گٔژھِتھ گٔژھِ۔\n29. یێلہِ رٲژ مَنٛز یێلہِ مُقدس عبادت کرنہٕ ییہِ، یێلہِ تہٕ یێلہِ رٲژ ہُند گیت چُھہ تھاونہٕ یِوان۔ تہٕ دِلٕچ خوشی، یِتھٕ پٲٹھـ̡ یێلہِ کانہہ نالہ ہٮ۪تھ خداوند سٕندِس پہاڑس مَنٛز یِنہٕ خٲطرٕ چُھ، اسرٲیلِس کِس طاقتور شخصس نِش یِنہٕ خٲطرٕ۔ {mighty...: Heb. راک}\n30. تہٕ خداوند کرِ پنٕنۍ شاندار آواز بوزناوٕن، تہٕ کرِ پننہِ نرِ ہٕندِ گاش سٍتـ̡ ہاونہٕ، تہٕ دِیہِ کھٮ۪نہٕ وٲلِس نارُک شعلہٕ، {سٍت} بکھرِتھ تہٕ طوفان، تہٕ ڈولہٕ کٔنـ̡ ۔ {تٔمۍ سُند شاندار...: ہیب۔ تٔمۍ سٕنٛزِ آوازِ ہٕنٛز عظمت}\n31.\\tکیازِ خداوند سٕنزِ آوازِ سٍتـ̡ ییہِ اسیرین مارنہٕ، {یُس} لٔرِ سٍتـ̡ مارنہٕ ییہِ۔\n32.\\tتہٕ پریتھ جایہ ییتہِ زمینہِ ہُند عصا نیرِ، یُس خداوند أمِس پیٹھ تراوِ، سُہ آسہِ تِمن سٍتـ̡ تہٕ ہارپَن سٍتـ̡ تہٕ لَگنہٕ کِس جنگس مَنٛز آسہِ سُہ اتھ سٍتـ̡ لڑان۔ {پریتھ منز...: ہیب۔ لاٹھی ہند پرتھ کانہہ گزرُن} {lay...: Heb. وجہ چھہ آرام کرُن} {اتھ سٍتۍ: یا، تمن خلاف}\n33.\\tٹوفیٹ سٍتـ̡ {چُھ} پرٲنِس مُقرر کرنہٕ آمُت۔ آ، بادشاہ سٕندِ خٲطرٕ چُھ یہِ تیار کرنہٕ آمُت۔ تٔمۍ چھُ {یہ} سرٛوٚن {تہٕ} بوٚڈ بنوومُت: اَمیُک ڈھیر {چُھ} نار تہٕ واریاہ لٔکر۔ خداوند سُند شاہ چُھ گندھک نالہٕ ہٕندۍ پٲٹھۍ، اتھ زالان۔ {پرانہِ: ہیب۔ راتھ پیٹھ}","1. تِمن ہُند افسوس یُس مدتہٕ خٲطرٕ مصرس منز گژھان چھُ۔ تہٕ گُرٮ۪ن پیٹھ روزُن، تہٕ رتھن پیٹھ بھروسہ کرُن، کیازِ {تِم} چھِ واریاہ ؛ تہٕ گُرۍ سوارَن منٛز، تِکیازِ تِم چھِ واریاہ مضبوٗط۔ مگر تِم چھِنہٕ اسرٲیلِس مُقدسَس کُن نظر تھاوان، تہٕ نہ چھِ خداوند سٕندِس سٍتـ̡ ژھاران۔\n2.\\tتوتہِ چُھ سُہ عقلمند تہٕ بد کار تہٕ کرِ نہٕ پنہٕ نِس کلامَس واپس، بلکہ کرِ بدکارن ہٕندِس گرس خلاف تہٕ بدکار سٕندِس مدتس خلاف پٲدٕ سپدُن۔ {کال...: ہیب۔ ہٹاونہٕ آمُت}\n3.\\tوۅنۍ چھہِ مصری انسان تہ خدایہ نہ۔ تہٕ تِہُند گُرِ ماز، نہ کہ روح۔ یێلہِ خداوند پَنُن اَتھٕ پھٔہلٲوِ، یُس مدد کرِ، سُہ گژھہِ پیوٚو، تہٕ یُس رٔلِتھ آسہِ، تہٕ یِم سٲری گژھن اِکہٕ وٹہٕ ناکام۔\n4. یِتھٕ پٲٹھـ̡ چُھہ خداوند میانہِ سٍتـ̡ کتھ کٔرمٕژ، یِتھٕ پٲٹھـ̡ شیر تہٕ جوان شیر پننِس شکارس پیٹھ گُزار کران چُھ، یێلہِ أمِس خٕلاف چرواہَن ہُند بٔڈ بُلاونہٕ ییہِ، {سُہ گژھہِ نہٕ تِہٕنزِ آوازِ سٍتـ̡ کھوژان، تہٕ یِمن ہٕندِس شورٕ سٍتـ̡ گژھہِ پانس ذلیل کرنہٕ: یِتھٕ پٲٹھـ̡ گژھہِ لشکرن ہُند رب صییون پہاڑ خٲطرٕ لڑنہٕ خٲطرٕ بۄن،  تہٕ امہٕ کس پہاڑس خاطرٕ۔ {شور: یا، کثیر}\n5. یِتھٕ پٲٹھـ̡ جاناوار وُڑان چِھ، تِتھے پٲٹھـ̡ کرِ لشکرن ہُند رب یروشلمُک بچاو۔ دفاع کٔرِتھ تہِ کرِ سُہ رژھرِتھ تہِ۔\n6. تٔمِس سٍتـ̡ پھیرِو یٔمِس سٍتـ̡ بنی اسرٲیلـ̡ سٍتـ̡ سٍتـ̡ بغاوت کٔرمٕژ۔\n7.\\tتکیازِ اَمہِ دۅہہٕ گژھِ پرٮ۪تھ کانہہ انسان پَنٕنـ̡ رۄپہٕ ہٕندِ بُت، تہٕ سۄنہٕ سٕندِ بُت، یُس تۅہہِ ہٕندِس اَتھَو سٍتـ̡ بنوومُت چھُ۔ {تٔمۍ سٕندِ سۄنہٕ ہٕندِس بُت: ہیب۔ تٔمۍ سٕنٛدِ سۄنہٕ ہٕنٛدۍ بُت}\n8.\\tتیلہِ گژھہِ اسوری تلوار سٍتـ̡ پۯاونہٕ، نہ کہ کُنہِ طاقتور شخصہٕ سٕندِس تلوارس سٍتـ̡ ۔ تہٕ تلوار، یُس نہٕ کُنہِ حقیر نفرٕ سُند چھُ، أمِس کھٮ۪یہِ مگر سُہ ژلہِ تلوار نِش، تہٕ تٔمۍ سٕندِ جوان گژھن پریشان۔ {منز: یا، خوفہٕ سٍتۍ} {discomfited: یا، معاون: Heb. پگھلنہٕ خٲطرٕ، یا، خراج تحسین خٲطرٕ}\n9. تہٕ سُہ گژھہِ خوفہٕ کِنۍ پننِس مضبوطس کُن نیرُن، تہٕ تٔمۍ سٕندِ شہزادٕ گژھن جھنڈٕ نِش کھوژان، خداوند چُھ ونان یٔمۍ سُند نار صییونس مَنٛز چُھ، تہٕ یروشلمس مَنٛز تٔمۍ سٕنز بھٹی چُھ۔ {وہ...: ہیب۔ تٔمۍ سٕنز کٔنہِ ژٔلِتھ","1. وچھو بادشاہ نیکی سٍتۍ راج کرُن، تہٕ شہزادن کرِ فٲصلس منز حکمرٲنی کرنہٕ۔\n2. تہٕ انسان گژھہِ ہوہس نِش پوشہِ روزنٕچ جاے تہٕ طوفانس نِش پوشہٕ روزُن۔ خشک جایہ آبکۍ دریاوکۍ پٲٹھۍ، تھکہٕ آمتس زمینس منز اکہِ بٔڈۍ کٔنہِ ہٕندِ ژھایہ ہٕندۍ پٲٹھۍ۔ {عظیم: ہیب۔ گوٚب}\n3.\\tتہٕ یِمن ہٕنزِ أچھ گژھن نہٕ کم تہٕ بوزن والٮ۪ن ہٕندِس کَن گژھن بوزنہٕ۔\n4.\\tدِل تہِ گژھہِ علمس سمجُن، تہٕ ہٕندِس دِلس تہِ گژھہِ سیدِ سیود کتھ کرنہٕ خٲطرٕ تیار۔ {راش: ہیب۔ جلدی} {سیدِ سیدِ پٲٹھۍ: یا، خوبصورتی}\n5.\\tبدکار شخصس گژھہِ نہ ونہِ فراخ دل وننہ یُن، تہ نہ گژھہِ کُنہ\n6.\\tیِکیازِ بدکار شخص کرِ بدکار کتھ تہٕ تٔمۍ سُند دِل کرِ بدکاری کٔرِتھ، منافقت کرُن، تہٕ خداوند سٕندِس خلاف غلطی کرِ، فاقہٕ مُتلق روح خٲلی کرُن، تہٕ سُہ کرِ پیاسہٕ سُند شراب۔\n7. چُھہ بُرِ ہٕندِس آلہٕ سٍتـ̡ تہِ بد کار بناوان: سُہ چُھہ غریبن اپُز لفظو سٍتـ̡ تباہ کرنہٕ خٲطرٕ بدکار سازان ، یێلہِ تہِ محتاج صحیح کتھ کران چُھ۔ {ضرورتمند...: یا، سُہ چُھ غریبن خلاف فیصلس منز کتھ کران}\n8.\\tمگر لبرل چھہ لبرل چیز بناوان۔ تہٕ لبرل چیزن سٍتۍ گژھہِ سُہ کھڑا روزُن۔ {سٹینڈ: یا، گژھ قٲیم}\n9. وۅتھٕ وُتھ، اے آرام دہ زنانہٕ۔ میٲنۍ آواز بوزو، اے لاپرواہ کورِ؛ میانہِ کلامَس کٔرِو کَن۔\n10. واریہن دۅہن تہٕ ؤرین روزو پریشان، اے لاپرواہ زنانہٕ، کیازِ ونٹیج گژھہِ ناکام، اجتماع گژھہِ نہٕ یِنہٕ۔ {واریاہ ...: ہیب۔ ؤری کھوتہ زیادٕ دۅہ}\n11.\\tتھر کرو اے زنانہٕ یُس آرام سان چھُ۔ پریشان گژھو، اے لاپرواہ: کٔرِو کُنہِ تہٕ کٔرِتھ {پنہٕ نِس} کمرس پیٹھ گٔنڈِتھ۔\n12.\\tتِم چھِ دِنہٕ خٲطرٕ، خۅش کھاہن ہٕندِس خٲطرٕ، پھلہٕ دار بیلن ہٕندِ خٲطرٕ ماتم کران۔ {خوشگوار...: ہیب۔ خواہشُک شعبہٕ}\n13.\\tمیانہِ قوم ہٕندِس سرزمینس پیٹھ یِن کانٹہٕ تہٕ برِیر۔ آ، خوشی ہٕندِس سارِنٕے گرس پیٹھ: {آ...: یا، دزان}\n14. کیازِ محل گژھن ترک کرنہٕ۔ شہرُک کثیر گژھہِ تراونہٕ؛ قلعہ تہٕ مینار روزن ہمیشہٕ خٲطرٕ گۅپھن خٲطرٕ، جنگلی گَرَن ہٕنٛز خوشی، ریوڑن ہُند مرگہٕ۔ {قلعہٕ...: یا، کلفٹ تہٕ واچ ٹاور}\n15. یوتام نہٕ روح اسہِ پیٹھ تھزرٕ پیٹھٕ تراوُن، تہٕ بیابان گژھہِ اکھ پھلدار کھیت تہٕ پھلہٕ دار کھیت گژھہِ جنگل گنزراونہٕ۔\n16. تیلہٕ روزِ فیصلہٕ بیابانن مَنٛز روزُن، تہٕ نیکی روزِ پھلہٕ دار میدانس مَنٛز۔\n17. تہٕ نیکی ہٕنز کٲم گژھہِ امن آسٕنۍ۔ تہٕ نیکی ہُند اثر، خاموشی تہٕ یقین ہمیشہٕ خٲطرٕ۔\n18.\\tتہٕ میانہِ لُکھ روزن پُر امن رہٲیشی، تہٕ یقینی روزن مَنٛز، تہٕ پُرسکون آرام گاہَن مَنٛز۔\n19.\\tییلہ وَنُن وَنُن وَسُن؛ تہٕ شہر گژھہٕ پست جایہٕ پیٹھ۔ {کم منز...: یا، سراسر بے عزتی}\n20.\\tبابرکت چھِو تم یُس سارِنٕے آبس سٍتـ̡ ووت دِوان چُھ، یُس داند تہٕ گَرِ ہٕندِس کھۅر سٍتـ̡ سوزان چھُ۔","1. افسوس چھکھ ژے یُس خراب تہٕ ژے چھکھ نہٕ خراب گومُت۔ تہٕ غداری کٔرِتھ تہٕ تِمو کٔر نہٕ توے سٍتۍ غداری! ییلہ ژیہ خراب گژھُن بند گژھہِ، تہِ گژھہِ برباد۔ {تہٕ} ییلہ ژیہ غداری ہُند خاتمہ کرِ، تِم کرِ توے سٍتۍ غداری۔\n2. اے خداوند، اسہِ سٍتـ̡ رحم کرُن؛ أسـ̡ چُھہ چانہِ ہُند انتظار کٔرِتھ: پرٮ۪تھ صُبحَس روزُن تِہُند نٔر تہٕ مصیبت وِزِ تہِ أسـ̡ نجات دِنہٕ۔\n3.\\tہنگامہ ہٕندِس شورس پیٹھ ژٔلِتھ ژٔلِتھ لُکھ ژٔلِتھ۔ تُہٕندِس پانس تُلنہٕ وِزِ گٔیہٕ قومن بکھرِتھ۔\n4.\\tتہٕ تُہُند غُنیمت گژھہِ جمع کرنہٕ یِتھ کٔنۍ یِتھ کٔنۍ ٹِڈی دِنہٕ یِنہٕ وٲلِس سٍتـ̡ یِتھٕ پٲٹھۍ۔\n5. خداوند چُھ بلند۔ تکیازِ سُہ چُھ تھزرس پیٹھ روزان: تٔمۍ چُھ صییون فیصلہٕ تہٕ نیکی سٍتۍ بٔرِتھ۔\n6. تہٕ حکمت تہٕ علم آسہِ تُہندِ زمانُک استحکام، {تہٕ}نجات ہٕنز طاقت: خداوند سُند خوف {چُھ} تٔمۍ سُند خزانہٕ۔ {نجات: ہیب۔ نجات }\n7. وُچھِو تِہٕندِس بہادر سٍتـ̡ وَنُن: امنٕکۍ سٔفیٖر گٔژھن وَنُن۔ {بہادر...: یا، قاصد}\n8. شاہراہٕ چِھ ویران گٔژھان، وَتھ چُھ رُکاونہٕ آمُت: تٔمۍ چُھ عہد پھُٹراومُت، شہرن ہٕنز حقارت، سُہ چُھ نہٕ کٲنسہ تہِ انسانس سٍتـ̡\n9.\\tزمین چھہ ماتم کران {تہ} لبان چھہ شرم {تہ} ژٹنہِ: شیرون چھہ بیابان ہیو۔ تہٕ بشن تہٕ کارمل چھِ {پنٕنۍ پھل} ہلاوان۔ {ژٔٹۍ...: یا، مرزاونہٕ آمُت}\n10. وۅنۍ گژھہِ بہٕ وۅتھ، خداوند چُھ فرماوان۔ وۅنۍ گژھہِ میہ بلند۔ وۅنۍ کٔرٕ بہٕ پان تُلان۔\n11.\\tژیہ ژٔٹِتھ ژٔل\n12.\\tتہٕ لُکھ گژھن چونہٕ سٍتـ̡ زالنہٕ یِنـ̡ {یِتھ} کٔرِتھ زالنہٕ یِن نارس مَنٛز زالنہٕ۔\n13.\\tبوزو، یُس دور چھُ، میہ کیا کورمُت۔ تہٕ یُس نزدیکی چھِو، میانہِ طاقتُک اعتراف کٔرِو۔\n14.\\tصییونس منز چھہ گۅنہگار کھوژان۔ خوفہٕ سٍتۍ چھُ منافقن حیران گومُت۔ اسہِ منزٕ کُس روزِ کھٮ۪نہٕ وٲلِس نارس سٍتۍ؟ اسہِ منز کُس روزِ ابدی دزنس سٍتۍ؟\n15. یُس نیکی پکان چُھ، تہٕ سیدِ سٍتـ̡ کتھ کرِ۔ یُس ظلمن ہٕندِس فٲیدٕ سٍتـ̡ حقارت کران چُھ، یُس رُشوت رٹنہٕ نِش اَتھٕ ہلاوان چُھ، یُس پننین کَن خوُن بوزنہٕ نِش رُکاوان چُھ، تہٕ بُرٕ وُچھنہٕ نِش أچھ بند کٔرِتھ چُھ؛ {صحیح پٲٹھۍ: ہیب۔ نیکی منز} {سیدِ پٲٹھۍ: عبرانی۔ اَمہ کِس سٍتـ̡ {ظلم: یا، فریب دِنہٕ} {خون: حب۔ بلڈز}\n16.\\tسُہ روزِ تھزرس پیٹھ: تٔمِس بچاوٕچ جاے آسہِ کَنہِ ہٕندِس بارود سٍتـ̡ دِنہٕ۔ تٔمۍ سُند آب {گژھہِ} پکہٕ پٲٹھۍ۔ {تھزر: ہیب۔ تھزر، یا، تھدِ مقامات}\n17.\\tچانہِ أچھ وُچھن بادشاہ سٕنزِ خوبصورتی منز: تِم وُچھن سُہ زمین یُس واریاہ دور چھُ۔ {یہ...: ہیب۔ دور فاصلہٕ}\n18.\\tچانہِ دِل کرِ دہشت گردی پیٹھ مراقبہ۔ کاتب کتہِ چھُ؟ رسیور کَتہِ چھُ؟ سُہ کتہِ چُھ یُس مینار گٔنزراوان اوس؟ {رسیور: ہیب۔ وزن؟}\n19.\\tژے وُچھِو نہٕ اکھ خوفناک لُکھ یُس تۅہہِ سٍتـ̡ اکھ ٹھٹھاہ زبان سٍتۍ، {یُس نہ ژیہ سمجھتھ ہیکو}۔ {ٹھٹھاہ کٔرتھ: یا، مضحکہ خیز}\n20.\\tوُچھِو صییون، یُس سانہِ تقریبن ہُند شہر چُھہ: تۅہہِ ہٕنزِ أچھ وُچھن یروشلم، اکھ خاموش بستی، اکھ خیمہ {یُس} یُس نہٕ والنہٕ یُن۔ امیک اکھ تہِ دوٚپ گژھہِ نہ زانہہ ہٹاونہٕ یُن، نہ گژھہِ کانہہ تہِ ڈور پھُٹنہٕ۔\n21. مگر اَتہِ آسہِ شاندار، خداوند اسہِ خٲطرٕ بٔڈۍ دریاوَن ہٕنز جاے {تہٕ} نالہٕ۔ یتھ منز نہ کانہہ گیلی آسہِ کھورِ ہیتھ نیرِ، نہ گژھہِ بہادر جہاز۔ {of...: ہیب۔ وسیع جاے، یا، اتھہٕ}\n22. خداوند چُھہ سون قاضی، خداوند چُھہ سون شریعت دِنہٕ وول، خداوند چُھہ سون بادشاہ۔ سُہ بچاوِ اسہِ۔ {قانون ساز: ہیب۔ statutemaker}\n23.\\tتُہٕندِس کُنہِ سٍتـ̡ چُھہ یێلہٕ دِنہٕ آمُت۔ تِم ہیوٚک نہٕ پَنُن مستول مضبوط، تِم ہیوٚک نہٕ جہازٕ پھٔہلٲوِتھ: تیلہٕ چُھ أکِس بٔڈِس غنیمتُک شِکار تقسیٖم کرنہٕ آمُت۔ لنگڑۍ چھہ شکارس نوان۔ {تُہٕندِ...: یا، تِمو چُھ تُہند ٹیکلنگ ترٲومُت}\n24.\\tتہٕ روزن وول گژھہِ نہٕ وَنُن، بہٕ چُھس بٮ۪مار: یِم لُکھ اَتھ مَنٛز روزان چھِ، تِمن ہٕندِس گُناہ سٍتـ̡ گژھِ معاف۔","1. اے قومن بوزنہٕ خٲطرٕ آو نزدیک۔ تہٕ بوزو، اے لوکو: زمینہِ بوزُن تہٕ اتھ منز موجود سورُے چیز۔ دنیا، تہٕ اَمہ منزٕ نیرن وٲلۍ سٲری چیز۔ {یہ سورُے...: ہیب۔ امچ مکمل آسن}\n2. خداوند سُند غصہٕ چُھہ سارنٕے قومن پیٹھ، تہٕ تِمن سارِنٕے لشکرن پیٹھ غصہٕ: تٔمۍ کٔر تِم پوٗرٕ پٲٹھۍتباہ کٔرِتھ تہٕ تِمن ہٕندِس ذبحس تام واتناوُن۔\n3. تِہُند مقتل تہِ یِن کڈنہٕ، تہٕ تِہٕنزِ لاشہٕ منزٕ یِن تِہٕنزِ بدبو نیرنہٕ، تہٕ پہاڑ یِن تِہٕندِس خونہٕ سٍتـ̡ پگلاونہٕ۔\n4. تہٕ اسمانُک سورُے لشکر یِن تحلیل کرنہٕ، تہٕ آسمانہٕ یِن أکِس طومار سٕندِ پٲٹھۍ، تہٕ تِہُند سورُے لشکر پیوٚو یِتھٕ پٲٹھۍ، انجیر کُلِس پیٹھ۔\n5.\\tمیٲنۍ تلوار گژھہِ جنتس مَنٛز سننہٕ یِن: وُچھِو یہِ اِدومیاہس تہٕ میانہِ لعنتٕکۍ لوکَن پیٹھ یِنہٕ وٲلِس سٍتـ̡ انصاف کرنہٕ خٲطرٕ۔\n6. خداوند سٕنز تلوار چِھ خونہٕ سٍتـ̡ بٔرِتھ، یہِ چُھہ چربی سٍتـ̡ بٔرِتھ بَناونہٕ آمُت، {تہٕ} کۅکرِ تہٕ ژھاوٕرِ ہٕندِس خونہٕ سٍتـ̡ چُھہ رٔنگـ̡ سٍتـ̡ بٔرِتھ تہٕ کۅکرِ ہٕندِس گردن ہٕندِس چربہٕ سٍتـ̡ بٔرِتھ بٔرِتھ بَناونہٕ آمُت۔\n7.\\tتہٕ یِمن سٍتـ̡ یِمن سٍتـ̡ بٔرِتھ تہٕ بیلن سٍتـ̡ بٔرِتھ۔ تہٕ تِہٕنٛز زمین گژھہِ خونہٕ سٍتۍ بٔرِتھ، تہٕ تِہٕنزِ گردِ گژھہِ چربی سٍتۍ موٚٹۍ۔ {یونیکورن: یا، گینڈٕ} {بٔرِتھ: یا، شراب}\n8. کیازِ {یہ} چُھ خداوند سٕندِ انتقامُک دۄہ، {تہٕ} صہیون کِس تنازعہٕ کِس بدلہٕ ہُند ؤری۔\n9. تہٕ اَمہ کِس نالہٕ یِن گٹہٕ بٔنِتھ تہٕ اَمہ ہٕنز گرد گٔژھِتھ تہٕ اَمہ ہٕنز زمین گژھہِ دزنہٕ واجنہِ گٹہٕ بٔنِتھ۔\n10. یہ گژھِ نہ رٲژ تہٕ نہ دۅہہٕ بٔرِتھ۔ اَمیُک دھواں روزِ ہمیشہٕ خٲطرٕ: نسل در نسل روزِ یہِ ضایع۔ کانہہ تہِ گژھہِ نہ اَتھ منزٕ ہمیشہٕ خٲطرٕ نیرِتھ۔\n11.\\tمگر کورمورنٹ تہٕ تلخ گژھہِ یہ پانس سیتۍ وابستہ۔ راتہٕ مۄغل تہٕ کاو تہِ روزن اَتھ مَنٛز: تہٕ سُہ پھٔہلِتھ اَتھ پیٹھ افراتفری ہٕنز لٲنہٕ، تہٕ خٲلی پنٕچ کٔنہِ۔ {کورمورینٹ: یا، پیلیکن}\n12. تِم بُلاونہٕ آمٕتۍ رئیسَن بادشاہتس مَنٛز، مگر تَتہِ گژھِ نہٕ کانٛہہ تہِ آسُن، تہٕ تٔمۍ سٕندِ سارِنٕے شہزادٕ گژھن نہٕ کیٚنٛہہ۔\n13.\\tتہٕ تٔمۍ سٕندِس محلس منز گژھن کانٹۍ، یِمن ہٕندٮ۪ن قعلن مَنٛز گٔنڈۍ تہٕ کُلہٕ تہٕ یِمن ہٕندِس قلعس مَنٛز بٔنِتھ تہٕ یِہ آسہِ ڈریگن ہٕنز بستی تہٕ راتہٕ مۄغلن ہٕندِ خٲطرٕ اکھ دربار۔ {راتہٕ مۄغل: یا، شترمرغ: ہیب۔ راتہٕ مۄغلہٕ سٕنٛز کورِ}\n14.\\tصحراہٕکۍ جنگلی جانور تہِ میلہِ جزیرہ کین جنگلی درندن سٍتۍ، تہٕ سیٹر کرِ پننِس سٲتھیس کُن فریاد ۔ کرٛیٚچ راتہٕ مۄغل تہِ روزِ تتہِ آرام، تہٕ پانس خٲطرٕ ژھٲنڈِن آرام کرنٕچ جاے ۔ {جنگلی ... صحرا: ہیب۔ Ziim} {جنگلی ... جزیرٕ: ہیب۔ Ijim} {screech...: یا، رٲژ راکشس}\n15.\\tتتہِ گژھہِ بٔڈۍ راتہٕ مۄغل پنُن گرٕ بناوُن، تہٕ کٔرِن تہٕ کٔرِتھ تہٕ پننہِ ژھایہ تَل جمع کٔرِتھ، اَتہِ گژھن گُدھ تہِ جمع کرنہٕ، پرٮ۪تھ کانہہ یِن پننِس سٲتھی سٍتـ̡ ۔\n16.\\tخداوند سٕنزِ کتابہِ منزٕ ژھٲرِو تہٕ پٔرِو: یِمو منزٕ گژھِ نہٕ کانہہ تہِ ناکام گژھُن، کانہہ تہِ گژھِ نہٕ تسٕندِس سٲتھیس یژھان، تکیازِ میانہِ ٲسِس چُھہ حُکُم کورمُت تہٕ تٔمۍ سٕندِس روحس سٍتـ̡ چُھہ تِم جمع کٔرِمٕتۍ۔\n17.\\tتہٕ تٔمۍ کٔر تِمن ہٕندِ خٲطرٕ لاٹ، تہٕ أمۍ سٕندِ اتھہٕ سٍتـ̡ چُھہ تِمن سٍتـ̡ لٲنہٕ سٍتـ̡ تقسیم کٔرِتھ، تِمن ہٕندِس نِش روزن یہِ ہمیشہٕ خٲطرٕ، نسل در نسل روزن۔","1.\\tبیابان تہٕ کُنُے جاے گژھہِ تِمن ہٕندِ خٲطرٕ خۄش۔ تہٕ صحرا گژھہِ خۅش تہٕ گلابکۍ پٲٹھۍ پھۅلان۔\n2. سُہ گژھہِ واریاہ پھۅلُن، تہٕ خوشی تہٕ گیونہٕ سٍتـ̡ تہِ گژھہِ خۅش سپدُن: لبنانُک جلال ییہ اتھ دِنہٕ، کارمل تہٕ شیرون سٕنزِ عظمت، تِم وُچھن خداوند سُند جلال {تہٕ} سانہِ خدایہ سٕنز عظمت۔\n3. کمزور اتھن کٔرِو مضبوط، تہٕ کمزور کۅٹھن کٔرِو پٲٹھۍ۔\n4.\\tتِمن وَنُن یُس خوفزدہ دِل آسہِ، مضبوٗط روزُن، خوفہٕ مہٕ کرُن: وُچھِو تُہند خدا یِنہٕ سٍتـ̡ انتقام سٍتـ̡ یِنہٕ سٍتـ̡ خدایہ سٍتـ̡ بدلہٕ سٍتـ̡ دِنہٕ۔ سُہ یِیہِ تہٕ بچاوِ ژےٚ ۔ {خوف: ہیب۔ جلدی }\n5. تیلہ گژھن انہِ سٕنزِ أچھ یلہٕ تہٕ زرن ہٕندِ کَن گژھن رُکاونہٕ۔\n6.\\tتیلہِ گژھہِ لوٚنگہِ ہٕندِس پٲٹھۍ، تہٕ کۅنگہٕ سٕنز زبان گیوان تہٕ بیابانن مَنٛز گژھہِ آب پھٔٹِتھ تہٕ ریگستانس مَنٛز نالہٕ۔\n7.\\tتہٕ خشک زمین بنہِ اکھ تالاب تہٕ ترشیہ زمینہٕ بنہِ آبُک چشمہٕ: ڈریگن ہٕندِس بستس منز، ییتہِ پرٮ۪تھ کانہہ آسہِ، گاسہٕ آسہِ نِش تہٕ رٔلِتھ گاسہٕ۔ {گاسہٕ...: یا، نَر خٲطرٕ اکھ کورٹ بیترِ}\n8. تہٕ اَکھ شاہراہ آسہِ، تہٕ اَکھ وَتھ، تہٕ اَتھ گژھہِ پاکیزگی ہٕنز وَتھ وَننہٕ۔ ناپاک گژھِ نہٕ اَتھ پیٹھٕ گزرُن؛ مگر یہِ آسہِ تِمن ہٕندِ خٲطرٕ: وَتہٕ وَتھ کَرن وٲلہِ یِمن ہٕندِ خٲطرٕ، یِمن ہٕندِس سٍتـ̡ گٔژھِتھ گٔژھِتھ۔ {مگر...: یا، تکیازِ سہ آسہِ تمن سٍتۍ}\n9. اَتہِ گژھہِ نہٕ کانہہ شیر آسُن، تہٕ نہ گژھہِ کانہہ تہِ بٔرِتھ درندٕ تتہِ لبنہٕ یِنہٕ۔ مگر نجات دِنہٕ وول گژھہِ پکان {تتہِ}:\n10. تہٕ خداوند سُند فدیہ دِنہٕ آمُت یُس واپس یِن تہٕ گٮ۪وُن تہٕ ابدی خوشی ہٮ۪تھ یِن تِمن ہٕنز خوشی تہٕ خوشی حٲصل سپدِ، تہٕ غم تہٕ آہ ژلِن ژلان۔","1.\\tوۅنۍ سپد یہِ بادشاہ حزقیاہ سٕندِس ژۄدہٲمِس ؤریس مَنٛز، یُس اسریاہُک بادشاہ سیناخریب، یہوداہ کین سارنٕے دفٲعی شہرن خلاف آو تہٕ کوٚرُن تِمن پیٹھ قبضہٕ۔\n2.\\tتہٕ اَشوٗرِیاہٕکۍ بادشاہن سوٗز ربشیح أکِس بٔڈ لشکر ہیتھ لاخیش پیٹھٕ یروشلم بادشاہ حزقیاہس نِش۔ تہٕ سُہ اوس فلر سٕندِس کھہٕ کِس شاہراہس منز پیٹھمہِ تالابٕچ نالہِ پیٹھ کھڑا۔\n3.\\tاَمہِ پَتہٕ آو أمِس نِش حِلکیاہ سُند نیچو، یُس گرس پیٹھ اوس، تہٕ شیبنا کاتب تہٕ جوہ، یُس اساف سُند نیچو اوس۔ {کاتب: یا، سیکرٹری}\n4.\\tتہٕ رَب شَخہن ووٚن تِمن وَنُن، یێلہِ وَنُن حزقیاہ سٍتـ̡ وَنُن، یِتھٕ پٲٹھـ̡ چُھہ عظیم بادشاہ، یێلہِ سٍتـ̡ تۅہہِ بھروسہ چُھہ کٔرِتھ؟\n5.\\tبہٕ چُھس ونان، {تُہۍ چُھہ ونان}، (مگر {تِم چِھہ بےکار کلام) {مے چُھہ} جنگہٕ خٲطرٕ مشورٕ تہٕ طاقت: وۅنۍ چُھکھ ژے کٔمِس پیٹھ بھروسہ کران زِ ژٕ چُھکھ میانہِ خلاف بغاوت کٔرِتھ؟ {بیکار...: ہیب۔ چپنہِ ہند اکھ لفظ} {میہ چھہ...: یا، مگر مشورہ تہ قوت چھیہ جنگہ خاطرہ}\n6. توے چُھہ مصرس پیٹھ اتھ پھُٹمٕژ نِلہٕ سٕندِس لٔرِس پیٹھ بھروسہٕ کٔرِتھ۔ یتھ پیٹھ اگر کانہہ انسان جھکِتھ آسہِ، سُہ گژھہِ أمس اتھس منز، تہٕ یِتھے پٲٹھۍ چھُ فرعون مصرُک بادشاہ یُس تس پیٹھ بھروسہٕ کران چھُ۔\n7. مگر اگر ژیہ میہ ؤنِتھ زِ أسۍ پننِس خداہس پیٹھ بھروسہٕ کران چھِ: کیا یہ چھُنہٕ سُہ یٔمۍ سٕنزِ تھدِ جایہِ تہٕ یٔمۍ سٕنزِ قربان گاہ حزقیاہ نِش نِتھ تہٕ یہوداہ تہٕ یروشلمس ووٚنمُت، تہٕ یێمہِ سٍتـ̡ یێمہِ قربان گاہٕ برونہہ کُن پوٗزا کٔرِو؟\n8. تێمہِ کِنۍ دِیُس بہٕ ژے پننِس آقا اشوریا کِس بادشاہس سٍتـ̡ عہد کٔرِتھ، تہٕ بہٕ دِیہٕ ژے زٕ ساس گُرۍ، اگر ژٕ تِمن پیٹھ سوار بناونس قٲبل آسہِ۔ {عہد: یا، یرغمال}\n9.\\tتیلہِ کِتھہ کٔنۍ کٔرِکھ میانہِ آقا سٕندِس سارِوٕے سٕندِس أکِس کپتان سُند بُتھ پھیُرِتھ، تہٕ رتھَن تہٕ گُرۍ سوارَن ہٕندِ خٲطرٕ کٔرِکھ مصرس پیٹھ پَنُن بھروسہٕ۔\n10. تہٕ کیا بہٕ چُھس وۅنۍ خداوند سٕندِ بغٲر اتھ زمینس تباہ کرنہٕ خٲطرٕ وۅتھان ؟ خداوند ووٚن مے زِ اتھ زمینس خلاف گژھ تہٕ یہ کرو تباہ کرنہٕ۔\n11.\\tاَمہِ پَتہٕ ووٚن الیاقیم تہٕ شبنا تہٕ جوح رَبشکہِ سٍتـ̡ کتھ کرٕن، بہٕ چُھس ژے پننین خادمَن سٍتـ̡ شامی زبانہِ مَنٛز کتھ کٔرِتھ۔ تکیازِ أسۍ چھہِ سمجھان {یہ}: تہٕ اسہِ سٍتـ̡ یہودین ہٕنزِ زبانہِ منز، تِمن لوکن ہٕندِس کنن منز کتھ کران یِم دیوارس پیٹھ چھِ۔\n12.\\tمگر ربشکہ ووٚن زِ کیا میہ آقا چھہ میہ پننس آقا نِش تہ ژیہ یہ لفظ وننہ خاطرہ سوزمُت؟ {تٔمۍ چھُنہ} تِمن نفرن نِش سوزمُت یِم دیوارس پیٹھ بِہتھ چھِ، تاکہ تِم ہیکن پنُن گُر کھٮ۪ن، تہٕ تۅہہِ سٍتۍ پنُن پیشاب پییہِ؟\n13.\\tاَمہِ پتہٕ ووت رَبشکہٕ وُتھ، تہٕ ووٚنُن یہودی زبانہِ ہٕنزِ بَڑِ آوازٕ سٍتـ̡ تہٕ وونُن، بٔڈِس بادشاہ سٕندِس کلامَس بوزو۔\n14. بادشاہ چُھ یِتھٕ پٲٹھۍ ونان زِ حزقیاہ گژھِ نہٕ توہہِ دھوکہٕ دِتھ، تِکیازِ سُہ ہیوٚک نہٕ تۅہہِ نجات دِتھ۔\n15.\\tحزقیاہ گژھہِ نہٕ تہِ خداہس پیٹھ بھروسہ کرُن، یہ ونُن زِ خداوند کرِ اسہِ نجات دِنہٕ۔ یہ شہر گژھہِ نہٕ اسریاک بادشاہ سٕندِس اتھس منز دِنہٕ۔\n16.\\tحزقیاہ سُند کُل نہٕ بوزُن، یِتھٕ پٲٹھۍ چُھ اسریاہُک بادشاہ ونان، میانہِ سٍتـ̡ کرو اکھ تحفہٕ، تہٕ یێمہِ سٕندِس پرٮ۪تھ أکِس سٍتـ̡ کھٮ۪وُن تہٕ تٔمۍ سٕندِس پرٮ۪تھ أکِس سٍتـ̡ تہٕ تٔمۍ سٕندِس انجیرُک کُلِس کھٮ۪وُن تہٕ پرٮ۪تھ أکِس سٕندِس حوضُک آب چیٚو۔ {بناو...: یا، میٲنۍ عنایت کرو اکھ تحفہٕ: ہیب۔ میہ سٍتۍ بناو اکھ دعا}\n17. یوتام نہٕ بہٕ یِنہٕ تہٕ ژےٚ پننہِ زمینہِ ہِش زمینہٕ نِن، مَکٲے تہٕ شرابٕچ سرزمین، روٹی تہٕ انگورن ہٕنز سرزمین۔\n18.\\t{خبردار} گژھہِ حزقیاہ یہ ؤنِتھ زِ خداوند کرِ اسہِ نجات دِنہٕ۔ کیا قومن ہٕندیو دیوتاہو چُھ پنن زمین اسریاک بادشاہ سٕندِ اتھہٕ نِش بچٲومُت؟\n19.\\tحمتھ تہٕ ارپھدکۍ دیوتا کتہِ چھہِ؟ سیفرویم سٕندۍ دیوتا کتہِ چھِ؟ تہٕ کیا تِمو چھُ سامریہ میانہِ اتھہٕ نِش دِنہٕ آمُت؟\n20.\\tیِمن زمینن ہٕندِس سارِنٕے دیوتاہن مَنٛز کُس چُھ، یِمو پَنٕنۍ زمین میانہِ اتھہٕ نِش بچٲومٕژ چھِ، یُس خداوند یروشلم میانہِ اتھہٕ نِش بچٲوِتھ؟\n21.\\tمگر تِمو تھوو خاموش تہٕ تٔمِس کُنہِ تہِ لفظُک جواب دِیُت، تکیازِ بادشاہ سُند حُکُم اوس یہِ زِ أمِس دِیُن نہٕ جواب۔\n22.\\tاَمہِ پَتہٕ آو حِلکیاہ سُند نیچو الیاقیم، یُس گرس پیٹھ اوس، تہٕ شیبنا کاتب تہٕ یُس اساف سُند نیچو یوح، یُس رَبشکہٕ سٕندِ کلامَس سٍتـ̡ دِنہٕ آمُت اوس، تہٕ وونُن أمِس رَبشکہٕ سٕندِ کلام۔","1.\\tتہٕ ییلہ بادشاہ حزقیاہ بوٗز، تٔمۍ کٔر پَنٕنۍ پلو ژٔٹِتھ تہٕ لوٚگ پَنُن پان بۄٹہٕ پلو لٲگِتھ تہٕ ژاو خداوند سٕندِس گرس منز۔\n2. تہٕ تٔمۍ سوٗز الیاکیم، یُس گرس پیٹھ اوس، تہٕ شیبنا کاتب تہٕ پادٕرین ہٕندۍ زِٹھۍ یِم بوری پوشہٕ ؤلِتھ ٲسۍ، یسعیاہ پیغمبر یُس عموز سٕندِس نیچوُس اوس۔\n3. تہٕ تِمو ووٚن أمِس یِتھٕ پٲٹھۍ چُھ حزقیاہ ونان، یہِ دۅہ چُھ مصیبتُک تہٕ ملامت تہٕ کُفر ہُند دۅہ، کیازِ بچہٕ چھِ زینہٕ وِزِ یِوان تہٕ پٲدٕ کرنٕچ طاقت چُھنہٕ۔ {توہین رسالت: یا، اشتعال انگیز}\n4. یێمہِ سٍتـ̡ چُھہ خداوند تُہند خدا رَبشکہٕ سٕندِ کلامَس بوزمُت، یُس اَشورُک بادشاہ تٔمۍ سُند آقا چُھہ زندٕ خدایہ سٕندِس ملامت خٲطرٕ سوزمُت، تہٕ تِمن کلامَن ہُند مذمت کرُن یُس تُہٕندِس خداہس بوزمُت چُھ۔ {دٔچھۍ: ہیب۔ لٔب}\n5.\\tتہٕ بادشاہ حزقیاہ سٕندِ خادم آیہِ یسعیاہ نِش۔\n6. تہٕ یسعیاہ ہن ووٚن تِمن زِ یِتھٕ پٲٹھۍ کٔرِو تُہۍ پننِس آقا سٍتـ̡ وَنُن، یِتھٕ پٲٹھۍ چُھ خداوند فرماوان زِ تِمن کلامَن سٍتـ̡ گژھ نہٕ خوفہٕ یُس ژے بوزمُت چُھ، یێمہِ سٍتـ̡ اَشِریا کِس بادشاہ سٕندِس خادمَو سٍتـ̡ میانہِ کفر کٔرِمٕژ چھِ۔\n7. وچھ بہٕ سوزٕ أمِس پیٹھ اکھ دھماکہٕ، تہٕ سُہ بوزِ اکھ افواہ تہٕ واپس۔ تہٕ بہٕ کرٕ سُہ تلوار سٍتـ̡ پننِس سرزمینس منز پنہٕ نـ̡ ۔ {سوزو...: یا، تراوو تس منز اکھ روح}\n8.\\tیِتھٕ رَبشہ آو واپس، تہٕ وُچھُن اشورُک بادشاہ لِبناہس سٍتـ̡ جنگ کران، تکیازِ أمِس اوس بوزمُت زِ سُہ چُھ لاچِش نِش نیران۔\n9. تہٕ تٔمۍ بوز ایتھوپیا کِس بادشاہ ترہکہ مُتعلِق یہِ ونُن زِ سُہ چُھ توے سٍتـ̡ جنگ کرنہٕ خٲطرٕ برونہہ کُن آمُت۔ تہٕ ییلہ تٔمۍ بوز، تمٔۍ سوٗزۍ حزقیاہ نِش قاصد تہٕ وونُن،\n10. یِتھٕ پٲٹھـ̡ کٔرِو تُہۍ یہوداہ کِس بادشاہ حزقیاہ سٍتـ̡ کتھ کٔرِتھ، یێمہِ سٍتـ̡ ژے پۯاوُن چُھ، یێمہِ سٍتـ̡ یێلہِ تہٕ یێلہِ نہٕ یُس یورشلِم یێلہِ اَسِریاہٕکِس بادشاہس دِنہٕ یُن۔\n11.\\tوُچھِو ژے بوزمُت زِ اَشورٕکۍ بادشاہو کیا کوٚر سارنٕے زمینن سٍتـ̡ یِم پوٗرٕ پٲٹھـ̡ تباہ کٔرِتھ۔ تہٕ ژٕ یِیہٕ نجات دِنہٕ؟\n12.\\tقومن ہندیو دیوتاہن چھا تم نجات دِژمٕتۍ یِم میانیو بابو تباہ کٔرۍمٕتۍ، گوزان، تہٕ ہاران، تہٕ رزیف تہٕ عدن ہٕندِ شُرۍ یِم تِلسرس مَنٛز ٲسۍ؟\n13.\\tحمتُک بادشاہ تہٕ ارپھدُک بادشاہ تہٕ سیفرویم، ہینا تہٕ ایواہ شہرُک بادشاہ کتہِ چھُ؟\n14. تہٕ حزقیاہ آو رسولن ہٕندِ اتھہٕ سٍتـ̡ چِٹھہِ رٔٹِتھ تہٕ پٔرِتھ پٔرِتھ تہٕ حزقیاہ ووت خداوند سٕندِس گرس نِش تہٕ ووت یہِ خداوند سٕندِس برونہہ کُن۔\n15.\\tتہٕ حزقیاہ کٔر خداوند سٍتـ̡ دُعا ،\n16.\\tاے لشکرن ہُند خدا، یُس کرُبن درمِیان روزان چُھ، تہٕ چُھہ خدا، یُس زمینہِ ہٕندِس سارِنٕے بادشاہتن ہُند خدا، تہٕ ژے چھُکھ آسمانس تہٕ زمینہٕ بنوومُت۔\n17. اے خداوند، پَنُن کَن کٔرِو تہٕ بوزو۔ اے خداوند، پَنٕنۍ أچھ کھولِو، تہٕ وُچھِو: تہٕ بوزِو سناخریب سٕندۍ سٲری کلام، یُس زندٕ خدایہ سٕندِس ملامت خٲطرٕ سوزمُت چھُ۔\n18.\\tپٔزۍ پٲٹھـ̡ اے خداوند، اَشوٗریا کٮ۪و بادشاہو چھِ سارنٕے قومن تہٕ تِہٕندِس ملکَس تباہ کٔرِمٕتۍ، {قوُم: حب۔ زمین}\n19.\\tتہٕ کٔرِکھ پنٕنـ̡ دیوتا نارس مَنٛز، تکیازِ تِم ٲسۍ نہٕ کانہہ دیوتا، مگر انسانن ہٕندِ اتھن، لٔکرِ تہٕ کنن ہٕنزِ کٲم، تێمہِ مۅکھہ کٔر تِمو تِم تباہ ۔ {کاسٹ: ہیب۔ دِنہٕ آمُت}\n20. تێمہِ وۆن، اے خداوند، اسہِ بچاو تٔمۍ سٕندِ اتھہٕ نِش، یُتھ زِ زمینہٕ کین سارنٕے بادشٲہی گژھن زانن زِ تہٕ چُھکھ خداوند چُھ، {حتی} تہِ۔\n21. اَمہِ پَتہٕ سُہ اوس اَموز سٕندِس نیچِوِ یِسعیاہ حزقیاہ نِش وَنُن زِ یِتھٕ پٲٹھـ̡ چُھ اسرٲیلُک خدا، یێلہِ تہٕ ژے چُھہ اسرٲیہِ کِس بادشاہ سَناخرِبَس خٕلاف دُعا کٔرمٕژ:\n22. یہِ چُھ سُہ لفظ یُس خداوند تٔمِس متعلق کتھ کورمُت چُھ۔ کُنوارِی، صیہون سٕنزِ کورِ کٔر تۅہہِ حقارت کٔرِتھ، {تہٕ} کٔرٕن ژےٚ حقارت کرنہٕ خٲطرٕ اسُن۔ یروشلمٕچ کورِ چُھ ژےٚ کلہٕ ہلٲومُت۔\n23.\\tژے کُس کُس ملامت تہٕ کفر کورمُت؟ تہٕ کٔمِس خلاف کٔر ژے پننہ آواز تھزرٲومٕژ، تہٕ پنٕنۍ أچھ تھزرس پیٹھ تُلٕن؟ {حتیٰ کہ} اسرٲیلِس مُقدسَس خٕلاف۔\n24.\\tپننین خدمتگارن سٍتـ̡ چُھہ ژے خداوند سٕندِس ملامت کٔرِتھ وونُن، میانین رتھن ہٕندِس بٔڈِس سٍتـ̡ چُھس بہٕ لبنان کِس اندس تام پہاڑن ہٕندِس تھزرس تام ووتمُت۔ تہٕ بہٕ ژٹٕ تِمن ہٕندِس تھدِ دیودار کُلۍ، {تہٕ} تِمن ہٕندِس کُلِس منز: تہٕ بہٕ ژٔٹِتھ تہٕ تٔمۍ سٕندِس کارمل کِس جنگلس منز۔ {بذریعہ تُہٕندِ...: ہیب۔ پننین خدمتگارن ہٕندِ اتھہٕ سٍتۍ} {تھد...: ہیب۔ اَمہ کِس دیودارُک تھزر تہٕ اَمہ کُلٮ۪ن ہُند انتخاب} {جنگل...: یا، جنگل تہٕ تٔمۍ سُند پھلہٕ دار کھہ}\n25. مے چُھس کھٔنِتھ آب چُھمُت۔ تہٕ میہ کٔر پننیو کھۅرن ہٕندِ تلہٕ سٍتۍ محصور جاین ہٕندۍ سٲری دریاو خشک ۔ {محاصرہٕ: یا، تار لگٲوِتھ تہٕ بند}\n26.\\tژے چھُنہٕ واریاہ کالہٕ برونہہ بوزمُت، {کِتھہ پٲٹھۍ} مے چُھ یہِ کورمُت۔ {تہٕ} قدیم زمانہٕ، زِ مے چُھ یہٕ تشکیل دِژمُت؟ وۅنۍ ووت میہ یہ پورٕ زِ ژے گژھہِ دفاع کٔرِتھ شہرن برباد کٔرِتھ۔ {جلدی...: یا، ژیہ کیا بوزمُت زِ میہ کِتھہ پاٹھۍ چھُ یہ واریاہ کالہ برونہہ بنوومُت، تہٕ یہ قدیم زمانہٕ بنوو؟ کیا بہٕ پزیا وۅنۍ یہ ویران کرنہٕ خٲطرٕ، تہٕ دفاع کٔرِتھ شہر تباہ کن ڈھیر بناوُن؟}\n27.\\tلہذا ٲسۍ تِہندِ بسکین، تِم ٲسۍ مایوس تہٕ پریشان: تِم ٲسۍ کھہُک گاسہٕ، تہٕ {یِتھٕ کٔن} سبز کُلۍ کُلۍ، {یِتھکٕن} مکانن پیٹھ گاسہٕ، تہٕ {یِتھٕ پٲٹھۍ مکایہ} بڑنہٕ برونہہ۔ {لۅکٹۍ...: ہیب۔ اَتھٕ کِس شارٹ}\n28. مگر بہٕ چُھس تُہند روزن گاہ، تہٕ تُہند نیرُن، تہٕ تُہند یِن، تہٕ میانہِ خلاف چُھس غصہٕ زانان۔ {رہائش: یا، بِہتھ}\n29.\\tکیازِ چانۍ غصہٕ تہٕ تُہند غصہٕ چُھس میانین کنن منز ووتمُت، اَمہِ مۄکھٕ تھاوٕ بہٕ پنُن ہُک ہُک تہٕ پنُن لگام چانہِ وٕٹھن منز، تہٕ بہٕ کٔرٕ ژے واپس۔\n30. تہٕ یہِ {گژھہِ} تۅہہِ خٲطرٕ اکھ نشانہٕ، تہٕ یُس وُہُن وُہُن کھٮ۪وان چُھ، یُس پانس سٍتـ̡ کھٮ۪وان چُھ۔ تہٕ دۆیم ؤری یُس امی سٍتـ̡ نیران چُھ، تہٕ تریمہِ ؤریس مَنٛز کٔرِو تُہۍ ووتُن، تہٕ لُٹِتھ تہٕ ووت تہٕ تِمن ہُند پھل کھٮ۪وان۔\n31. تہٕ یُس یہوداہ کِس گرس نِش بچان چُھ، سُہ گژھہِ دُبارٕ بۄن کُن موٗل نِنہٕ، تہٕ ہیوٚر کُن پھل دِنہٕ: {باقی...: ہیب۔ یہوداہ کِس گرس نِش ژلُن یُس باقٕے چُھ}\n32.\\tیِکیازِ یروشلم نیبر نیرِتھ گژھہِ اکھ باقی، تہٕ یُس پہاڑ صیون منزٕ ژلِتھ نیرِ، لشکرن ہٕندِس رب سُند جوش گژھہِ یہِ کرُن۔ {تِم...: ہیب۔ فرار گژھُن}\n33.\\tتێلہِ چُھ خداوند یِتھٕ پٲٹھۍ اسریاک بادشاہس مُتلق ونان زِ سُہ گژھِ نہٕ اتھ شہرس مَنٛز یِنہٕ، نہ تتہِ تیر چلاوُن، تہٕ نہ گژھِ اتھ برونہہ کُن ڈھال ہیتھ یِنہٕ، تہٕ نہ کرِ اتھ پیٹھ کانہہ بٹھہٕ۔\n34. یێلہِ سُہ آو تہٕ یێمہِ سٍتـ̡ یێلہِ سُہ واپس، تہٕ یێمہِ شہرس مَنٛز ییہِ نہٕ، خداوند چُھ فرماوان۔\n35. تکیازِ بہٕ کَرٕ اتھ شہرس پننہِ خاطرٕ تہٕ پننِس خادم ڈیوڈ سٕندِ خٲطرٕ بچاونہٕ خٲطرٕ۔\n36. اَمہِ پتہٕ درٛاو خداوند سُند فرشتہٕ تہٕ دِتُن اشورین ہٕندِس خٲمس مَنٛز اکھ ہتھ ژۄغہٕ تہٕ پانژھ ساس۔ تہٕ ییلہ تِم صُبحٲے سُلہٕ وُتھ، وُچھ تِم سارِنٕے لاشہٕ۔\n37.\\tیێلہِ گۆو اسیریُک بادشاہ سیناکریب، تہٕ گۆو نینوا ہس مَنٛز روزُن۔\n38.\\tتہٕ سپُد یہِ سپُد، ییلہ سُہ پننِس دیوتا نِسرخ سٕندِس گرس مَنٛز عبادت کران اوس، زِ ادرمیلک تہٕ شریزرن دِژ تٔمِس تلوار سٍتـ̡ مار۔ تہٕ تِم ژٔل آرمینیا کِس سرزمینس منٛز: تہٕ تٔمۍ سٕنٛدِ نیچوۍ ایسرہڈن کٔر أمِس بدلہٕ حکوٗمت۔ {آرمینیا: ہیب۔ ارارات}","1.\\tتِمن دۅہن اوس حزقیاہ بیمار مرُن۔ تہٕ یسعیاہ پیغمبر آموز سُند نیچو آو أمِس نِش، تہٕ وونُن تٔمِس یِتھٕ پٲٹھۍ چُھ خداوند فرماوان پَنُن گرٕ ترتیب دِنہٕ، تِکیازِ تُہۍ گژھِو مٔرِتھ تہٕ زِندٕ روزُن نہٕ۔ {سیٹ...: ہیب۔ پننِس گرس متعلق دِیُن ذمہ داری}\n2. اَمہِ پَتہٕ کٔر حزقیاہ پَنُن بُتھ دیوارس کُن، تہٕ کٔرٕن خداوند سٕنز دُعا،\n3.\\tتہٕ وونُن، اے خداوند، بہٕ چُھس ژے یاد تھاوُن، کِتھہ پٲٹھـ̡ چُھس ژے برونہہ کُن پٔکِتھ پٲٹھـ̡ تہٕ کامل دِلہٕ سٍتـ̡ پٔکِتھ پٲٹھـ̡ تہٕ یُس چُھہ تۅہہِ ہٕندِس نظرِ سٍتـ̡ نیکی کٔرمٕژ۔ تہٕ حزقیاہ ووٚتھ دَگ دَگ۔ {سور: ہیب۔ سٮ۪ٹھاہ روُن سٍتۍ}\n4. اَمہِ پَتہٕ آو خداوند سُند کلام یسعیاہ ہس نِش وونُن،\n5.\\tگژھ تہٕ حزقیاہ وَنُن، یِتھٕ پٲٹھـ̡ چُھہ خداوند تُہند مٲل سُند خدا، مے چُھہ تُہند دُعا بوزمُت، مے چُھہ تُہند اوٚش وُچھمُت، وُچھمُت چُھس تہندِس دۅہس منز پندہ ؤری ہُران۔\n6. تہٕ بہٕ کَرٕ ژے تہٕ یہِ شہرس اَشوٗریا کِس بادشاہ سٕندِ اتھہٕ نِش نِش بچاو، تہٕ بہٕ کَرٕ یَتھ شہرس بچاو۔\n7. تہٕ یہِ آسہِ تۅہہِ خٲطرٕ خداوند سٕندِ طرفہٕ اکھ نشانہٕ، زِ خداوند کرِ یہِ کتھ یُس تٔمۍ کٔرمٕژ چھِ۔\n8.\\tوچھ میہ بییہ ڈگرین ہند ژھایہ یُس آہاز کس آفتابس منز داہ ڈگری پتھ کُن وۅتلان چھہ۔ چنانچہ آفتاب آو داہ ڈگری واپس، یتھ ڈگری تام یہ ڈوبُن گوو۔ {سن ڈائل: ہیب۔ ڈگری بائی، یا، آفتابس سۭتۍ}\n9. یہوداہ کِس بادشاہ حزقیاہ سُند تحریر، ییلہ سُہ بیمار اوس، تہٕ پنہٕ نِس بیمارِ نِش صحت یاب گومُت:\n10.\\tمیہ ووٚن پننین دۅہن ژٹنس منز، بہٕ گژھہٕ قبرِ ہندس دروازس پیٹھ: بہٕ چھُس پننین ؤرین ہٕندِ باقیات نِش محروم گومُت۔\n11.\\tمیہ ووٚن، بہٕ وُچھٕ نہٕ خداوند تہِ، زندٕ سٕندِس سرزمینس مَنٛز، بہٕ وُچھٕ نہٕ انسانس دُنیا کین بسکینن سٍتـ̡ ۔\n12.\\tمیٲنۍ وٲنسہِ گٔیہِ ژٔٹِتھ تہٕ چُھس میہ نِش کٔرِتھ پٔرِتھ کٔرِتھ ژٔٹ {سۭتۍ...: یا، تھرم پیٹھ}\n13.\\tمیہ اوس صبحس تام سٍتـ̡ س�\n14.\\tکۅکرِ ہٕندۍ پٲٹھۍ، یِتھے پٲٹھۍ کٔر میہ کۅتر سٍتـ̡ ماتم کرنہٕ: میٲنۍ أچھ چھے ہیوٚر کُن وُچھان: اے خدا، بہٕ چُھس مظلوم۔ میانہِ خٲطرٕ کٔرِو ذمہ داری۔ {انڈر ٹیک...: یا، آرام کٔرِو}\n15. بہٕ کیا وَنُن؟ تمۍ چھہ میہ سیتۍ کتھ کرمژ تہ پانہ کورمُت: بہٕ روزٕ پننین سارنٕے ؤرین پننہ روح چہ تلخی منز نرمی سان۔\n16.\\tاے خداوند، یِمو {چیزن سٍتـ̡ چُھہ انسان زندٕہ روزان، تہٕ یِمن سارِنٕے چیزن مَنٛز چُھہ میانہِ روحٕچ زندگی: تێتھہ پٲٹھـ̡ کٔرِکھ میہ بحال تہٕ بہٕ زِندٕ روزُن۔\n17.\\tوُچھِو میہ سٍتـ̡ سٮ۪ٹھاہ تلخی مگر ژے کٔر میانہِ روحس سٍتـ̡ محبت، یێلہِ ژے کٔر میٲنۍ سٲری گۅناہ پتھ کُن۔ {امن...: یا، میانہِ امن پیٹھ آو سٮ۪ٹھاہ تلخی} {ژے چُھس منز...: ہیب۔ ژے چُھکھ میانہِ روحس کھۅنہٕ پیٹھٕ محبت}\n18.\\tقبر ہیکہِ نہ تۅہہِ تعریف کٔرِتھ، موت ہیکہِ نہ تۅہہِ ہُند جشن مناوِتھ: یُس کھۅنہِ منز وسان چھہِ تم ہیکن نہ چانہِ حقیقتچ وۅمید کٔرتھ۔\n19. زندٕ، زندٕ، سُہ کرِ تۅہہِ ہٕنز تعریف، یِتھٕ کٔنۍ بہٕ از تہِ کران چُھس: شُرین ہُند مول کرِ تُہند پزر ظٲہر۔\n20.\\tخداوند اوس میہ بچاونہٕ خٲطرٕ تیار: تێمہِ مۅکھہ گۆو أسۍ پننہ زندگی ہندین سارنٕے دۅہن خدایہ سٕندِس گرس مَنٛز تارن ہندین سازن پیٹھ میٲنۍ بٲتھ گیو۔\n21.\\tیِکیازِ یسعیاہ اوس ووٚنمُت زِ تِم رٔٹِن انجیر ہُند اکھ گانٹھ، تہٕ تھووُن پھورِ پٲٹھۍ، تہٕ سُہ گژھہِ ٹھیٖک۔\n22.\\tحزقیاہ ہن اوس یہ تہِ وونمُت زِ بہٕ گژھہِ خداوند سٕندِس گرس تام گژھُن؟","1.\\tتمہِ وِزِ سوُز بابل کِس بادشاہ بلدان سٕندِ نیچِوِ میرودچبالادانن حزقیاہ ہس چِٹھہِ تہٕ اکھ تحفہٕ، تکیازِ تٔمِس اوس بوزمُت زِ سُہ چُھ بیمار گومُت، تہٕ سُہ آو صحت یاب کرنہٕ۔\n2.\\tتہٕ حزقیاہ ہٲو تِمن سٍتـ̡ خۅش تہٕ ہٲوِن تِمن ہُند قیمتی چیز، رۄپہٕ تہٕ سۄن، تہٕ مسالہٕ، تہٕ قیمتی مرہم تہٕ سارِنٕے ہُند گرٕ تہٕ یُس تٔمۍ سٕندِس خزانس مَنٛز لبنہٕ آو، تٔمۍ سٕندِس گرس مَنٛز اوس نہٕ کانہہ تہِ یُس حزقیاہ ہن ہٲومُت اوس۔ {قیمتی چیز:  یا، مسالہٕ} {آرمر: یا، جواہرات: ہیب۔ جہاز، یا، آلات}\n3.\\tاَمہِ پَتہٕ آو یسعیاہ پیغمبر بادشاہ حزقیاہ نِش تہٕ وونُن یِمو نفرو کیا ووٚن؟ تہٕ تِم کتہِ آیہ تۅہہِ نِش؟ تہٕ حزقیاہ ووٚن زِ تِم چھِ أکِس دور مُلکہٕ پٮ۪ٹھٕ میانہِ نِش آمٕتۍ، {حتیٰ کہ} بابل پیٹھ۔\n4.\\tاَمہِ پتہٕ ووٚن تِمو کیا وُچھمُت تُہٕندِس گَرَس مَنٛز؟ تہٕ حزقیاہ دیُت جواب، میانِس گرس مَنٛز یُس {چُھ} چُھہ تِمو وُچھمُت: میانین خزانن مَنٛز چُھ نہٕ کانہہ تہِ یُس نہٕ میہ ہٲومُت چُھ۔\n5. اَمہِ پَتہٕ ووٚن یسعیاہ حزقیاہ سٕندِس خداوندِ سُند کلام بوزُن:\n6. وُچھِو یِم دۅہ یِوان زِ تُہٕندِس گَرَس مَنٛز یُس {چُھ} تہٕ یُس تُہٕندِس مٲلِس اَز تام رٔٹِتھ چُھ، سُہ گژھہِ بابل نِنہٕ یُن: کُنہِ تہِ گژھِ نہٕ باقٕے روزُن، خداوند چُھ فرماوان۔\n7. تہٕ تُہٕندِس نیچوِس سٍتـ̡ یُس ژے نِش پٲدٕ سپدِ، یِم ژے پٲدٕ کرِ، تِم نِن نِنہٕ۔ تہٕ تِم گژھن بابل کِس بادشاہ سٕندِس محلس مَنٛز خواجہ سرا آسن۔\n8. اَمہِ پَتہٕ ووٚن حزقیاہ یسعیاہ سٍتـ̡ یُس خداوند سُند کلام چُھہ یُس ژے کٔرِتھ چُھ۔ تٔمۍ ووٚن بییہِ زِ میانین دۅہن منز آسہِ امن تہٕ حقیقت۔","1. تُہُند خدایہ چُھ ونان زِ تُہٕندِس خدایہِ سٍتـ̡ کٔرِو تسلی دِنہٕ۔\n2. یروشلمس سٍتـ̡ کٔرِو تسلی سان کتھ تہٕ أمِس کٔرِو فریاد زِ تٔمۍ سُند جنگ چُھ مُکمل سپُدمُت، یێلہِ تٔمِس گۅنہٕ سٍتـ̡ چُھہ خداوند سٕندِ اتھہٕ سٍتـ̡ دۄگنہٕ پٲٹھـ̡ مِلاونہٕ آمُت۔ {آرام سان: ہیب۔ دلس تام} {جنگ: یا، مقرر وقت}\n3. یُس بیابانس مَنٛز فریاد دِوان چُھ، یُس خداوند سٕنز وتھ تیار کٔرِو، صحراہس مَنٛز بناو سٲنِس خداہٕ سٕندِ خٲطرٕ اکھ شاہدہ۔\n4.\\tپرٮ۪تھ وادی گژھہِ تھزراونہٕ یُن، تہٕ پرٮ۪تھ پہاڑ تہٕ بالہٕ گژھہِ پوٚت کرنہٕ، تہٕ کھرِ کھرِ جاے یِن سیدِ سیدٕ بناونہٕ: {سید: یا، سیدِ جاے} {سادٕ: یا، اکھ سادٕ جاے}\n5. تہٕ خداوند سُند جلال گژھہِ ظٲہر سپدُن، تہٕ سارِنٕے ماز گژھہِ اِکہٕ وٹہٕ وُچھن: کیازِ خداوند سٕندِ ٲسِس چُھ کتھ کٔرمٕژ۔\n6.\\tآوازِ ووٚن روُن۔ تہٕ أمۍ ووٚن، بہٕ کیا روُن؟ سارِنٕے ماز چھُ گاسہٕ تہٕ اَمہ سٍتۍ سارِنٕے خوبصورتی کھہِ ہٕندِس پوشٕکۍ پٲٹھۍ:\n7.\\tگاسہٕ چُھہ وُچھان، پوش چھُ ژھانپھ گژھان: کیازِ خداوند سُند روح چُھ اتھ پیٹھ وُپھ دِوان: یقینا لوکھ چُھ گاسہٕ۔\n8. گاسہٕ چُھ وُچھان، پوش چُھ ژھٹان مگر سانہِ خدایہ سُند کلام روزِ ہمیشہٕ خٲطرٕ۔\n9. اے صییون، یُس خوشخبری دِوان چُھ، ژے تھدِس بالس پیٹھ کھس۔ اے یروشلم، یُس خوشخبری دِوان چُھ، تُل پنٕنۍ آواز طاقتہٕ سٍتـ̡ تُلان۔ تُلِتھ تھوٚد کٔرِتھ، کھوژُن نہٕ؛ یہوداہ کین شہرن وُچھِو پنُن خدا! {اے صہیون...: یا، اے ژے یُس صیونس خوشخبری دِوان چُھ} {اے یروشلم...: یا، اے یُس یروشلمس خوشخبری دِوان چُھ}\n10. وُچھِو، خداوند خدا ییہِ مضبوٗط اتھہٕ سٍتـ̡ تہٕ تٔمۍ سٕنز نٔر کرِ أمِس سٍتـ̡ حکمرٲنی کرنہٕ: وُچھِو، تٔمِس سُند ثواب {چُھ} أمِس سٍتـ̡ تہٕ تٔمِس برونہہ کُن تٔمۍ سٕنز کٲم۔ {مضبوطس سٍتۍ...: یا، مضبوطس خلاف} {تہنز کٲم: یا، تیم سٕنزِ کامہٕ ہند معاوضہٕ}\n11.\\tسُہ کرِ پَنٕنـ̡ پى۪ٹھٕ پى۪ٹھ، تہٕ پى۪ٹھٕ پى۪ٹھـ̡ پى۪ٹھـ̡ پى۪ٹھہٕ پى۪ٹھ۔ {یہ...: یا، یہ دِوان چُھ}\n12. کٔمۍ چُھ پننِس اَتھٕ کِس کھوکھرِس مَنٛز آبٕچ پیمٲئش کٔرمٕژ، تہٕ کٔرٕن اسمانس سٍتـ̡ سٍتـ̡ تہٕ زمینہِ ہٕنزِ گردِ ہٕندِس پیمانس سٍتـ̡ سمجُن، تہٕ پہاڑن تول کٔرِتھ تہٕ بالن توازنس سٍتـ̡ تول کورمُت؟ {اکھ پیمانہٕ: ہیب۔ a tierce}\n13. خداوند سٕندِس روحس کُس چُھ ہدایت دِژمُت، یا تٔمۍ سٕندِس مُشیرن چُھ أمِس ہیچھناومُت؟ {امس...: ہیب۔ مین آف ہٕنز کونسل}\n14.\\tکٔمۍ سٍتـ̡ مشورٕ دِژ، تہٕ یٔمِس ہیچھناوُن تہٕ کٔرِن أمِس حکمہٕ دِنٕچ وتہٕ تہٕ ہیچھناوٕنـ̡ تہٕ تمِس فہم ہٕنز وتھ ہٲوٕنـ̡ ۔ {ہدایت...: ہیب۔ سُہ سمجھُن} {سمجُن: ہیب۔ تفہیم؟}\n15.\\tوچھو قومہٕ چھہِ بالٹی ہٕندِس قطرس ہٕندۍ پٲٹھۍ، تہٕ توازنٕچ لۅکٹٕچ گردِ ماننہٕ یوان چھِ: وُچھِو، سُہ چُھ جزیرن ہٕندِس سٮ۪ٹھاہ لۅکٹِس چیزس سٍتۍ رٹان۔\n16.\\tلبنان چُھہ نہٕ دزنہٕ خٲطرٕ کافی، تہٕ نہ چُھہ امکۍ جانور زالنہٕ خٲطرٕ کٲفی۔\n17. أمِس برونہہ کُن سارِنٕے قومہٕ چھِنہٕ کُنہِ تہِ کُنہِ چیز۔ تہٕ تِم چھِ أمِس خٲطرٕ کُنہِ تہِ کم تہٕ بےکار گٔنزِتھ۔\n18.\\tتیلہِ کٔرِو خدایہ سٍتـ̡ کُس تشبیہ؟ نتہٕ تُہۍ کُس ہشر کٔرِو أمِس سٍتۍ؟\n19.\\tکامہِ سٍتـ̡ چُھہ سۅنہٕ سٍتـ̡ رۄپہٕ زنجیر تراوان۔\n20. یُس {چُھ} یوتاہ مفلس آسہِ زِ أمِس چُھنہٕ کانہہ نذرانہٕ آسہِ، سُہ چُھ تِتھۍ کُلِس ژاران {یُس نہٕ سڑِ}۔ سُہ چُھ أمِس أکِس چالاک مزورس منگان زِ سُہ کٔرِن اکھ کھٔنِتھ تصویر تیار کرنہٕ، {یُس} گژھِ نہٕ منتقل کرنہٕ۔ {چُھ یہ...: ہیب۔ نذر کٔرِتھ چھُس غریب}\n21.\\tژیہ چھیہ نہ خبر؟ کیا ژیہ بوز نہ؟ کیا یہ چھُنہٕ ژےٚ شروع پیٹھے وننہٕ آمُت؟ کیا ژیہ چُھہ نہٕ زمینہِ ہنزِ بنیادو پیٹھٕ سمجِتھ؟\n22. {یہ} چُھ سُہ یُس زمینہٕ کِس دٲیرس پیٹھ بِہتھ چُھ، تہٕ اَتھ منز روزن وٲل {چِھ} ٹڈِکۍ پٲٹھۍ۔ یُس آسمانس پردٕ ہٕندۍ پٲٹھۍپھٔہلٲوِتھ تہٕ یُس روزنہٕ خٲطرٕ خیمہ ہٕندۍ پٲٹھۍ پھٔہلاوان چُھ: {یہِ چُھ...: یا، سُہ چُھ}\n23.\\tیُس شہزادن کُنہِ سُہ چُھ زمینہٕ کِس قاضس باطل بناوان۔\n24. آ، یِم گژھِ نہٕ لگاونہٕ یِن۔ آ، تِم گژھن نہٕ وونہٕ: آ، تِہُند ذخیرٕ گژھِ نہٕ زمینس منز موٗل رٔٹِتھ، تہٕ سُہ تہِ وُپھ دِیہِ تِمن پیٹھ تہٕ تِم مرزاونہٕ تہٕ واو نِیہِ تِمن کٔرِتھ کٔرِتھ۔\n25.\\tتیلہِ کٔرِو میہ کمہِ سٍتـ̡ تشبیہ، کِنہ بہٕ ہشر کٔرِتھ؟ مقدس چُھ وَنان۔\n26.\\tپَنٕنۍ أچھ تُلِو تھزرس کُن تہٕ وُچھِو یِم {چیز} کٔمۍ چھِ تخلیق کٔرمٕژ، یُس تِہُند میزبان تعداد سٍتـ̡ نیران چُھ، سُہ چُھ یِمن سارِنٕے ناوو سٍتـ̡ بلاوان، تکیازِ سُہ چُھہ طاقتس مَنٛز مضبوط۔ کانہہ تہِ چھہ نہ ناکام سپدان۔\n27. اے یعقوب کیازِ چُھہ ونان تہٕ کتھ کران زِ اے اسرائیل، میٲنۍ وتھ چُھہ خداوند نِش پوشیدٕ تہٕ میون فیصلہ چُھ میانہِ خدایہ سٕندِ طرفہٕ دِنہٕ آمُت؟\n28.\\tژیہ چھا نہ خبر؟ کیا ژے چُھہ نہٕ بوزمُت، زِ ابدی خدا، یُس زمینہِ ہٕندِس اندس پیٹھ پٲدٕ کرن وول چُھ، چُھہ نہٕ بیہوش سپدان تہٕ نہ چُھہ تھکان تہٕ نہ چُھہ تھکان ؟ {تٔمۍ سٕنٛدِس فہم ہٕنٛز کانٛہہ تہِ تلاش} چھِنہٕ۔\n29. سُہ چُھ کمزورن طاقت دِوان۔ تہٕ یِمن ہٕندِ خٲطرٕ چُھنہٕ سُہ طاقت ہُرراوُن۔\n30. جوان تہِ گژھن بیہوش تہٕ تھکان تہٕ جوان گژھن پوٗرٕ پٲٹھۍ:\n31. مگر یُس خداوند سُند انتظار کران چُھ، تِم گژھن تِمن ہٕندِس طاقتس نٔو پٲٹھۍ۔ تِم گژھن پَکھہٕ سٍتۍ گُرِ ہٕندِس پٲٹھۍ؛ تِم گژھن ژلُن، تہٕ تھکان نہٕ۔ {تہٕ} تِم گژھن پَکُن، تہٕ نہٕ بیہوش۔ {تجدید: ہیب۔ تبدیلی}","1. اے جزیرٕ، میانہِ برونہہ کُن ژھۄپہٕ تھاوُن۔ تہٕ لوٗکھ گژھن تِمن ہٕندِس طاقتس تازٕ کرنہٕ: تِم گژھن نزدیک۔ تیلہِ گژھن تِم کتھ کرنہٕ: أسۍ یکوٹہٕ اِکہٕ وٹہٕ فٲصلس نزدیک۔\n2. مشرقہٕ پیٹھٕ کٔمۍ کٔر نیک {انسان} تھوٚد، أمِس بُلووُن پننِس قدمس پیٹھ، پانس برٛونٛہمہِ قومن دِژٕن، تہٕ بادشاہن پیٹھ کٔرٕن حکومت؟ تٔمۍ دِژ {تِم} پننہِ تلوارِ ہٕندۍ پٲٹھۍ، {تہٕ} پننِس کمانس پیٹھ کھسنہٕ آمٕژ کٔرِتھ۔ {نیک ...: حب۔ نیکی }\n3.\\tتِمن ہُند پَتہٕ لوٚگ، {تہٕ} گٔیہِ محفوٗظ پٲٹھۍ۔ {حتیٰ کہ} وتہِ اوس نہ سہ پننین کھۅرن سیتۍ پکان۔ {محفوٗظ پٲٹھۍ: ہیب۔ امن}\n4.\\tشروع پیٹھے نسلن بلاوُن کٔمۍ چھہ تہٕ کٔرمُت تہٕ کٔرۍمٕتۍ؟ بہٕ چُھس خداوند، گۄڈنیُک، تہٕ ٲخری سٍتـ̡ بہٕ چھُس یہِ۔\n5. جزیرن وُچھ {یہ}، تہٕ کھوژُن۔ زمینہِ ہندۍ اندۍ کھوژۍ، نزدیک تہ آیہ۔\n6. تِمو کٔر پرٮ۪تھ أکِس ہمساین ہٕندِس مدد۔ تہٕ {پرٮ۪تھ کٲنسہِ} ووٚن پننِس بٲیِس زِ اصل ہمت کرُن۔ {بے...: ہیب۔ مضبوٗط روٗزِو}\n7.\\tتہ چھانن کٔر سونارس حوصلہٕ افزٲیی، {تہٕ} یُس ہتھوڑٕ سٍتۍ ہتھوڑٕ دِوان چھُ، یہِ چھُ سُہ چُھہ سُہ دِنہٕ خٲطرٕ تیار، تہٕ تٔمۍ کٔر یہ کیلو سٍتۍ بند، {یُس} یہ گژھہِ نہٕ ہُلاونہٕ یُن۔ {گولڈ سمتھ: یا، بانی} {سُہ...: یا، مارُن} {ونان...: یا، سوڈرس متعلق ونن، یہ چھہ اصل}\n8. مگر تو، اسرائیل، میون خادم یعقوب یُس میہ منتخب کورمُت چُھ، ابراہیم سُند اولاد، میون دوس۔\n9. {ژے} یُس میہ زمینہِ ہٕندِس اندس پیٹھٕ نِتھ تہٕ ژے بُلوومُت تہٕ ژے چُھکھ میٲنۍ خادم۔ مے چُھکھ ژےٚ ژٲرمٕژ، تہٕ ژےٚ ترٛٲومٕژ نہٕ۔\n10. ژیہ نہ کھوژُن۔ تکیازِ بہٕ چُھس ژے سٍتۍ: خوفزدہ گژھ نہٕ؛ تکیازِ بہٕ چُھس تُہند خدا: بہٕ کرٕ ژے مضبوط۔ آ، بہٕ کٔرٕ ژےٚ مدد۔ آ، بہٕ کَرٕ ژےٚ پننہِ نیکی ہٕندِ دٔچھنِس اتھہٕ سٍتـ̡ رژھراوٕنـ̡ ۔\n11.\\tوُچھِو، یِم سٲری تۅہہِ سٍتـ̡ شرمسار گٔژھِتھ تہٕ پریشان گٔژھن: تِم گژھن نہٕ کُنہِ تہِ ہٕندِس پٲٹھۍ۔ تہٕ یِم تۅہہِ سٍتـ̡ جدوجہد کران چِھ، تِم گژھن ختم گٔژھنـ̡ {تم یم کوشش کران چِھ...: ہیب۔ تُہٕندِس کشمکشَس ہٕندِس مردس\n12.\\tتُہۍ ژھانڈِو تِمن ہٕندِس سٍتـ̡ تہٕ تِم تہِ لٔبِتھ یِم توے سٍتـ̡ جنگ کٔرِتھ، تِم گژھن نہٕ کُنہِ چیزس سٍتـ̡ تہٕ کُنہِ چیزس سٍتـ̡ ۔ {تم یہ...: ہیب۔ تُہٕندِس تنازعس ہٕندِس مردس ﴿تِم...: ہیب۔ تیری جنگٕکۍ مرد}\n13. یێلہِ بہٕ چُھس خداوند تُہُند خدا تُہُند دٔچھُن اتھٕ رٔٹِتھ، تہٕ ژے وَنُن زِ ژےٚ گژھ نہٕ خوف۔ بہٕ کٔرٕ ژےٚ مدد۔\n14.\\tیعقوب کٔرِو نہٕ خوفہٕ، یعقوب تہٕ اے اسرٲیلٕکۍ انسان۔ خداوند تہٕ تُہند نجات دِنہٕ وول چُھس اسرٲیلُک پاک شخص چُھس ونان زِ بہٕ کٔرٕ تُہٕنز مدد۔ {مرد: یا، کم مرد}\n15.\\tوچھ بہٕ بناو ژے اکھ نوو تیزدار تھریشنگ آلہ یتھ منز دند آسہِ: ژے کرٕ پہاڑ ژٔٹِتھ تہٕ لۅکٹۍ لٔٹِتھ تہٕ بالہٕ بناوُن چھاپ۔ {دند: ہیب۔ ٲس}\n16.\\tتُہۍ کٔرِو تِمن پھپھ دِنہٕ، تہٕ واو نِیہِ تِم نِنہٕ، تہٕ واو کرِ تِمن پھِرِتھ، تہٕ تہٕ ژے گژھہِ خداوند سٕندِس مُقدس سٍتـ̡ جلال حٲصل کرنہٕ۔\n17. {یێلہِ} غریبن تہٕ محتاجن آب ژھاران چُھ، تہٕ {تہٕ} تِہٕنزِ زبان تراونہٕ خٲطرٕ، بہٕ چُھس خداوند تِمن بوزناوُن، بہٕ چُھس نہٕ تِمن تراوُن۔\n18.\\tبہٕ کھولہٕ تھدٮ۪ن جاین دریاو تہٕ وادین مَنٛز چشمہٕ: بہٕ بناوٕ بیابان آبُک تالاب، تہٕ خشک زمینہٕ آبُک چشمہٕ۔\n19.\\tبہٕ کٔرٕ بیابانن منز دیودار، شیتہ کُل، تہٕ مِرٹل تہٕ تیٖل کُل؛ بہٕ تھاوٕ ریگستانس منز فر کُل، {تہٕ} دیودار تہٕ ڈبہٕ کُلِس یکوٹہٕ:\n20. یُتھ زن تِم وُچھِن، زانِتھ، تہٕ غور کٔرِتھ تہٕ یِکہٕ وَٹہٕ سمجِتھ زِ خداوند سٕندِ اَتھن چُھ یہِ کورمُت تہٕ اسرٲیلِکِس پاکَن چُھ یہِ تخلیق کورمُت۔\n21.\\tپَنُن مقصد پٲدٕ کرُن، خداوند چُھ فرماوان۔ یعقوب سُند بادشاہ چُھ ونان زِ پَنُن مضبوٗط {وجوہات} کٔرِو برونہہ کُن۔ {پیداوار: ہیب۔ نزدیک یِنُک وجہ}\n22.\\tتِم أنِن تِمن برونہہ کُن، تہٕ اسہِ ہٲوِن کیا سپدِ، تِم ہٲوِن گۅڈنِچ چیز، یُس تِم کیا آسہِ، یُتھ أسۍ تِمن پیٹھ غور کٔرِتھ، تہٕ تِمن ہُند پٔتِم انجام زانہِ۔ یا اسہِ یِنہٕ والہِ چیزن ہُند اعلان کرُن۔ {غور کرُن...: ہیب۔ سون دِل تھٲوِو تمن پیٹھ}\n23.\\tیِم چیز ہٲوِو یِم یِنہٕ وٲلِس پَتہٕ یِنہٕ وٲلۍ، یُتھ اسہِ زانہِ زِ تُہۍ چھِو خدا: آ، نیکی کٔرِو، یا بد کٔرِو، یُتھ أسۍ مایوس گٔژھِو، تہٕ یِہ وُچھِو۔\n24.\\tوُچھو، تۅہہ چُھہ نہٕ کُنہِ چیزُک تہٕ تُہٕنز کٲم چھِنہٕ کُنہِ تہِ کُنہِ کُنہِ تہِ کُنہِ تہِ کُنہ {کُنہِ چیزُک: یا، کُنہِ کھوتہٕ بدتر} {of nought: یا، اکھ وائپر کھوتہٕ بدتر}\n25.\\tمیہ ووت شمالہٕ پیٹھٕ تھوٚد، تہٕ سُہ ییہ آفتابہٕ کھسنہٕ پیٹھٕ میٲنۍ ناو: تہٕ سُہ گژھہِ شہزادن پیٹھ یِنہٕ تہٕ میژِ ہٕندِس پٲٹھۍ۔\n26.\\tشروع پیٹھے کُس اعلان کورمُت، یُتھ اسہِ پتاہ آسہِ؟ تہٕ امہ برونہہ زِ أسۍ ونِتھ، {سُہ چُھ} نیک ؟ آ، {تتہِ} چھُنہٕ کانہہ تہِ یُس اعلان کران چھُ، آ، {تتہِ} چھُنہٕ کانہہ تہِ یُس تُہند کلام بوزان چھُ۔\n27.\\tگۅڈنچہ لٹہِ وُچھِتھ وُچھِتھ تہٕ بہٕ دِیہ یروشلمس سٍتـ̡ یُس خوشخبری دِیہِ۔\n28.\\tکیازِ میہ وُچھ تہٕ {اتہِ} اوس نہٕ کانہہ انسان۔ تمن منز تہِ، تہٕ {اتہِ} اوس نہٕ کانہہ مُشیر، یُس ییلہ میہ تمن متعلق پرژھہ، تہٕ ہیکہِ کُنہِ لفظس جواب دِتھ۔ {جواب: ہیب۔ واپسی}\n29.\\tوچھو، تِم چھِ سارِنٕے باطل ۔ تہنز کٲم {چِھ} کنہہ نہٕ: تہنز پگھلتھ تصویرٕ {چِھ} ہوا تہٕ کنفیوژن ۔","1. وُچھو میون خادم، یُس بہٕ رچھان چھُس؛ میٲنۍ چُھس ژارنہٕ آمُت، {یٔمِس سٍتـ̡ میون روح خۅش چُھہ؛ میہ چُھ پنُن روح أمِس پیٹھ تھوومُت: سُہ کرِ غیر قومن ہُند فیصلہٕ۔\n2. سُہ گژھِ نہٕ روُن، نہ تُلِتھ تہٕ نہ سڑکہِ منز پنٕنۍ آواز بوزناوٕنۍ۔\n3.\\tاکھ زخم دار نِلہٕ پھُٹُن نہٕ تہٕ سُہ پھُٹُن تہٕ سُہ کرِ نہٕ سُہ فٲصلہٕ سٍتـ̡ دِنہٕ۔ {سگریٹ نوشی: یا، ہلکہ دزان} {Quench: Heb. یہ کٔرِو بنٛد کٔرِتھ}\n4. سُہ گژھِ نہٕ ناکام تہٕ مایوس، یوٚت تام نہٕ سُہ زمینس مَنٛز فٲصلہٕ دِیہِ: تہٕ جزیرٕ گژھِ تٔمۍ سٕندِس قانونُک انتظار۔ {حوصلہ شکنی کٔرِتھ: ہیب۔ پھُٹمُت}\n5. یِتھٕ پٲٹھـ̡ چُھ خدایہِ خداوند فرماوان یُس اسمانن بنووُن تہٕ تِمن پھٔہلٲوِتھ دِژُن۔ سُہ یُس زمینہٕ پھٔہلٲوِتھ تہٕ یُس اَمہ منزٕ نیران چُھ؛ یُس اتھ پیٹھ لوکن شاہ دِوان چُھ، تہٕ یُس اتھ منز پکان چُھہ تِمن روح دِوان:\n6. بہٕ چُھس خداوند چُھہ ژے نیکی سٍتـ̡ بُلاونہٕ آمُت، تہٕ چُھہ تُہُند اَتھٕ رٔٹِتھ تہٕ رٔٹِتھ تہٕ دِیہٕ تہٕ دِیہٕ تُہٕندِس عہدٕ سٍتـ̡ تہٕ دِیہٕ قومن ہٕندِ گاشہٕ خٲطرٕ۔\n7.\\tانہِ أچھ کھولنہٕ خٲطرٕ، قٲدۍ جیلہٕ منزٕ نٮ۪بر کڈنہٕ خٲطرٕ، {تہٕ} یِم قٲدٕ خانہٕ منزٕ انہِ گٹہِ منز بِہتھ روزان چھِ۔\n8. بہٕ چُھس خداوند چُھس: یُس {چُھ} میون ناو: تہٕ بہٕ دِیہ نہٕ بییِس سٍتـ̡ تہٕ نۂ کٔرِتھ مجسمن ہٕنز تعریف۔\n9.\\tوچھو، گۅڈنِکۍ چیز چھہِ سپدان تہ نوۍ چیز چھہ میہ اعلان کران: امہ برونہہ زِ تم نیرنہ برونہہ چھہ بہٕ ژیہ تمن متعلق ونان۔\n10. خداوند سٕندِ خٲطرٕ گیو اکھ نوٚو گٮ۪وُن، {تہٕ} زمینہٕ کِس اندس پیٹھٕ تٔمۍ سٕنز تعریف، یُس سمندرس تام وسان چُھ، تہٕ اَتھ مَنٛز موجود سارِنٕے چیز۔ جزیرٕ تہٕ تِمن ہٕندۍ بسکین۔ {سٲری ...: ہیب۔ امچ مکمل آسن}\n11.\\tبیابان تہٕ تِمن ہٕندِس شہرس تُلِتھ تُلُن، یِمن گامن ہٕندِس کُنہِ ہٕندِس بسکیٖن سٍتـ̡ گٮ۪وُن تہٕ تِم گٔژھن بالہٕ پیٹھٕ کرٛٮ۪کہٕ دِنہٕ۔\n12. تِم گژھن خداوند سُند جلال دِن، تہٕ جزیرن مَنٛز گژھن تٔمۍ سٕندِ تعریفُک اعلان کرنہٕ۔\n13.\\tخداوند گژھہِ اکھ طاقتور انسان سٍتـ̡ نیرُن، سُہ کرِ جنگہٕ سٕندِ پٲٹھـ̡ حسد پٲدٕ کرُن: سُہ چُھہ کُنہِ سٍتـ̡ کٔرِتھ، آ، گُرجہٕ۔ سُہ کرِ پننین دُشمنن خلاف فتح۔ {غالب: یا، پانس کرو زوردار برتاو}\n14.\\tمیہ چھہ واریاہ کالہ پنُن سکون تھاوان۔ بہٕ اوسُس رُکُن، {تہٕ} رُکٲوِتھ: {وُن} بہٕ روو أکِس مُشکِل زنانہِ ہٕندۍ پٲٹھۍ۔ بہٕ کٔرٕ اکی ساتہٕ تباہ تہٕ کھٮ۪وان۔ {کھیوٚن: ہیب۔ نِنگلُن، یا، سوپ اپ}\n15. بہٕ بناوٕ پہاڑ تہٕ بالہٕ تہٕ تِہٕنزِ سارِنٕے جڑی بوٹی خشک کٔرِتھ۔ تہٕ بہٕ بناوٕ دریاو جزیرٕ، تہٕ بہٕ کرٕ تالاب خشک کرنہٕ۔\n16.\\tتہٕ بہٕ أنِتھ اَنہِ وتہِ {یُس} یُس نہٕ تِمن پتاہ آسہِ۔ بہٕ کٔرٕ تِمن تِمن وتن پیٹھ یِم نہٕ تِمن پتاہ آسہِ: بہٕ بناوٕ تِمن برونہہ کُن انہِ گوٚٹ گاش، تہٕ کٔرِتھ کٔرِتھ کُنہِ چیزس سید۔ یِم کٔرٕ بہٕ تِمن سٍتۍ، تہٕ یِم تراوٕ نہٕ۔ {سید: ہیب۔ سیدِ سیود منز}\n17. تِم گژھن واپس پھیرنہٕ، تِم گژھن واریاہ شرمندٕ، یُس کھٔنِتھ بُتن پیٹھ بھروسہٕ کرُن، یُس پٔہلِمٕژ تصویرن ونان چھِ، تُہۍ چھِو سٲنۍ دیوتا۔\n18. بوزو، اے بہر؛ تہٕ وُچھو، اے انہِ، تاکہ تم وچھو۔\n19.\\tکُس چھہ انہِ مگر میون خادم؟ یا بہر، میون قاصد {یُس} میہ سوزمُت؟ کُس چُھ {یُس} کامل چُھ، تہٕ خداوند سٕندِ خادم سٕندِ پٲٹھـ̡ کُس چُھہ انہِ؟\n20. واریاہ چیز وُچھِتھ مگر توے چُھہ نہٕ وُچھان۔ کَن کھولُن، مگر سُہ چُھ نہٕ بوزان۔\n21. خداوند چُھ پننہِ نیکی خٲطرٕ خوش گومُت۔ سُہ کرِ شریعت بڑاو، تہٕ بَناوِ یہِ عزتدار۔ {یہ: یا، سُہ}\n22.\\tمگر یہ {چھُ} اکھ لُکھ یُس لُٹنہٕ آمُت تہٕ خراب کرنہٕ آمُت چھُ۔ {تِم} چھِ سارِنٕے گَردَن مَنٛز پھٔٹِتھ تہٕ یِم چھِ قٲدَن مَنٛز ژوٗرِ تھاونہٕ آمٕتۍ: تِم چھِ شِکارٕ خٲطرٕ، تہٕ کانٛہہ تہِ چھُنہٕ دِنہٕ آمُت۔ غنیمت خٲطرٕ، تہٕ کانٛہہ تہِ چھُنہٕ وَنُن، بحال۔ {تِم چھِ سارِنٕے ...: یا، تِمن سارِنٕے نوجوانَن پھانس منز} {اکھ غنیمت خٲطرٕ: ہیب۔ اکھ ٹریڈنگ}\n23.\\tتوہہِ منزٕ کُس کرِ اتھ بوزُن؟ {یِنہٕ وٲلِس وقتس خٲطرٕ کُس بوزِ تہٕ بوزنہٕ؟ {for...: ہیب۔ پتہٕ وقتس خٲطرٕ؟}\n24. یعقوب کٔمۍ دِژ لوُٹنہٕ خٲطرٕ، تہٕ اسرٲیلِس کٔمۍ دِیُت ڈاکوَن دِنہٕ؟ کیا خداوند چُھہ نہٕ یٔمِس خلاف أسـ̡ گۅناہ کورمُت؟ تکیازِ تِم ٲسۍ نہٕ تٔمۍ سٕنزِ وتہِ پیٹھ پکان تہٕ نہ ٲسۍ تٔمۍ سٕندِس قانونس فرمانبردار۔\n25. تێمہِ کِنۍ دِژ أمِس پَنٕنہِ شَرارُک قہر تہٕ جنگُک طاقت، تہٕ أمۍ دِژ أمِس اندۍ پکھۍ نار، توتہِ اوس نہٕ تس خبر۔ تہٕ یہ دزُن أمِس دِل، توتہِ تھوو نہٕ تٔمۍ دِلس پیٹھ۔","1. مگر وۅنۍ چُھ خداوند یُس ژے تخلیق کورمُت چُھ، اے یعقوب، تہٕ یُس تۅہہِ بناوُن چُھ، اے اسرائیل، خوف نہٕ کرُن، کیازِ مے چُھہ ژے نجات دِژمُت، مے چُھہ ژے تہندِ ناوٕ سٍتـ̡ بنومُت۔ ژے چھکھ میٲنۍ\n2. ییلہ ژیہ آبس منزہ نیرِ، بہٕ آسہٕ ژے سٍتۍ۔ تہٕ دریاوَن مَنٛز، تِم گژھِ نہٕ تۅہہِ سٍتـ̡ وَسٕنـ̡ یێلہِ تہٕ یێلہِ تہٕ دَزنہٕ یِیہِ نہٕ۔ نہ گژھہِ ژیہ نار دِنہٕ۔\n3. کیازِ بہٕ چُھس خداوند تُہند خدا، اسرٲیلُک پاک، تُہند نجات دِنہٕ وول تہٕ تُہند نجات دِنہٕ وول مصر۔\n4. چونکہ ژٕ ٲس میانہِ نظرِ خٲطرٕ قیمتی ٲس، تہٕ بہٕ چُھس ژے محبت کٔرمٕژ، تہٕ بہٕ دِیہ ژےٚ خٲطرٕ انسان تہٕ لوکھ پننہِ زندگی خٲطرٕ۔ {زندگی: یا، شخص}\n5. خوفزدہ گژھ نہٕ: کیازِ بہٕ چُھس ژے سٍتـ̡ تہٕ بہٕ اَنـ̡ چُھہ تُہُند بُل مشرقہٕ پیٹھٕ تہٕ ژے مغرب پیٹھٕ جمع کٔرِتھ۔\n6.\\tبہٕ وَنُن شمالس کُن، تراوُن تہٕ جنوبس کُن، پتھ کُن تھاوُن نہٕ: میانین نیچوۍ أنِن دوٗر پیٹھ، تہٕ میانین کورِ أنِن زمینہٕ کِس اندس پیٹھ۔\n7. {حتی} پریتھ کانہہ یُس میانہِ ناوٕ سٍتـ̡ وننہٕ چُھ یوان: کیازِ مے چُھس سُہ پننہِ جلال خٲطرٕ تخلیق کورمُت، مے چُھہ سُہ بنوومُت۔ آ، میہ چھہ سہ بنوومت۔\n8.\\tأچھ وٲلِس اَنٮ۪ن تہٕ کَن وٲلِس زٔرِس کٔرِو کٔرِتھ۔\n9.\\tسارِنٕے قومن گژھن جمع کرنہٕ یُن، تہٕ عوام گژھن جمع کرنہٕ: یِمو منزٕ کُس ہیکہِ یہ اعلان کٔرِتھ، تہٕ اسہِ ہٲوِتھ پرانہِ چیز۔ تِم گژھن پنٕنۍ گواہ برونہہ کُن، تاکہ تِم گژھن صٲحی ثٲبت کرنہٕ، یا بوزُن تہٕ ونن، {یہٕ چُھ} صحیح۔\n10. خداوند چُھہ ونان تہٕ میون خادم یُس میہ منتخب کورمُت چُھ، تہٕ یُس میہ زانِتھ تہٕ پژھ کٔرِتھ تہٕ سمجِتھ زِ بہٕ چُھس سُہ چُھس: میانہِ برونہہ اوس نہٕ کانہہ خدا بنیومُت، تہٕ نہ آسہِ میانہِ پتہٕ۔ {نہ...: یا، خدایہ سُند کانہہ تہِ بنیومُت}\n11. بہ، {حتیٰ کہ} بہ، {am} رب تہٕ میانہِ علاوٕ چُھنہٕ کانہہ نجات دِنہٕ وول ۔\n12. میہ چُھہ اعلان کورمُت، تہٕ بچٲومُت، تہٕ مے چُھس ہٲومُت، یێلہِ چُھہ نہٕ تۅہہِ مَنٛز کانہہ عجیب {خدا} اوسمُت، تێلہِ چُھہ تہٕ تێلہِ چُھہ میٲنۍ گواہ ، خداوند چُھس ونان زِ بہٕ چُھس خدا چُھس۔\n13. آ، امہ دۅہہ برونہہ {اوس} میہ {am} him؛ تہٕ {تتہِ} چُھنہٕ کانہہ تہِ یُس میانہِ اتھہٕ نِش نِش نِش ہٮکہٕ دِتھ: بہٕ کٔرٕ کٲم، تہٕ کُس دِیہِ یہِ؟ {یہ گژھہِ: ہیب۔ واپس پھیرُن؟}\n14. یِتھٕ پٲٹھـ̡ چُھہ خداوند یُس تُہُند نجات دِنہٕ وول، اسرٲیلُک پاک چُھہ فرماوان۔ چانہِ خٲطرٕ چُھس مے بابل سوزمُت، تہٕ تِہٕندِ سارِنٕے رئیس، تہٕ چالدیَن ہٕندِس سٍتـ̡ یِمن ہٕنزِ فریاد جہازن مَنٛز چُھ۔ {رئیس: ہیب۔ بارز}\n15. بہٕ چُھس خداوند چُھ، تُہند پاک، اسرٲیلُک خالق، تُہند بادشاہ۔\n16. یِتھٕ پٲٹھۍ چُھ خداوند فرماوان، یُس سمندرس مَنٛز وتھ بناوان چُھ، تہٕ طاقتور آبس مَنٛز وتھ بناوان چُھ۔\n17. یُس رتھ تہٕ گُر، فوج تہٕ طاقت نیران چھُ۔ تِم گژھن اکوٹہٕ لٔگِتھ، تِم گژھن نہٕ وۅتھنہٕ: تِم چھِ ختٕم گٔمٕتۍ، تِم چھِ ژٔٹِتھ بٔرِتھ۔\n18.\\tگۅڈنچہ چیزن یاد تھاوُن تہ نہ پرانہِ چیزن پیٹھ غور کرُن۔\n19.\\tوچھ، بہٕ کرٕ اکھ نۆو کٲم۔ وۅنۍ گژھہِ یہ پھۅلُن۔ کیا ژیہ یہ پتاہ آسہِ؟ بہٕ بناو بیابانن منز تہِ اکھ وتھ، {تہٕ} ریگستانس منز دریاو۔\n20.\\tمیدانُک درندٕ کَرِ مےٚ، ڈریگن تہٕ راتہٕ مۄغلن ہُند احترام: کیازِ بہٕ چُھس بیابانن مَنٛز آب دِوان، تہٕ ریگستانس مَنٛز دریاو، پننین لوکن چِنہٕ خٲطرٕ۔ {راتہٕ مۄغل: یا، شترمرغ: ہیب۔ راتہٕ مۄغلہٕ سٕنٛز کورِ}\n21. یِم لُکھ چھِ مے پانس خٲطرٕ بَنوومُت۔ تِم کرِ میٲنۍ تعریف۔\n22. مگر ژے چُھہ نہٕ میہ بُلاونہٕ آمُت، اے یعقوب۔ مگر ژے چھے میہ نِش تنگ گومُت، اے اسرٲیل۔\n23.\\tژے چھُنہٕ میہ پننہِ دزنہٕ آمٕژ نذرانہ ہٕندِ لۄکٕٹۍ چاروٲے اوٚنمٕتۍ۔ نہ چھکھ ژے میہ پننہ قربانی سٍتۍ عزت دِژمژ۔ مے چُھس نہٕ ژے کُنہِ نذرانہ سٍتـ̡ خدمت کٔرمٕژ، تہٕ نہ چُھکھ ژے بخور سٍتـ̡ تھکان دِژمٕژ۔ {لۄکٹ...: ہیب۔ کٹہٕ بچہٕ، یا بچہٕ}\n24.\\tژے ہیوٚت نہ میہ پونسہٕ سٍتۍ کانہہ مٔٹھۍ لور، نہ چھکھ میہ پننہِ قربانی ہٕنز چربی بٔرِتھ، مگر ژے چھکھ میہ پننیو گۅنہو سٍتۍ خدمت کرنہٕ خٲطرٕ بنوومُت، ژے چھُکھ میہ پننہِ بدکاریو سٍتۍ تھکان دِژمُت۔ {بٔرِتھ...: ہیب۔ میہ کٔر شرابہ، یا واریا زیادٕ نم کٔرتھ}\n25. بہٕ چُھس، {حتیٰ کہ} بہٕ چُھس سُہ یُس پننہِ خٲطرٕ چانہِ گناہ ختم کران چُھ، تہٕ چُھہ نہٕ چانہِ گۅناہ یاد روزان۔\n26.\\tمیہ یاد تھاوُن: أسۍ کرو اِکہٕ وٹہٕ درخواست کرنہٕ: ژے کرو عیٲلِم، یُتھ تہٕ ژے گژھہِ عادل سپدُن۔\n27. چانہِ گۅڈنِکِس مٲلہِ سٍتـ̡ چُھہ گۅناہ کورمُت، تہٕ تێہٕندِس وۄستادَن کٔر میانہِ خلاف زیادٕ۔ {اساتذہ: ہیب۔ ترجمان}\n28. تێمہِ کِنۍ چُھس مے مقدس مقامہٕ کِس شہزادن بے حرمتی کٔرمٕژ، تہٕ یعقوب تہٕ اسرٲیلِس دِژمُت ملامت کرنہٕ۔ {شہزادے...: یا، مقدس شہزادٕ}","1. توتہِ بوزو، اے یعقوب میانہِ خادم۔ تہٕ اسرائیل، یس میہ منتخب چُھ:\n2. یِتھٕ پٲٹھـ̡ چُھہ خداوند ونان یُس تُہہِ بنوو، تہٕ تُہٕندِس رحمس مَنٛز بنوُن چُھ، {یُس} چُھہ تۅہہِ مدد کرِ۔ اے یعقوب، میانہِ خادم، خوفزدہ گژھ نہ۔ تہٕ ژے، یسوُن، یُس میہ چُھس ژٲرمُت۔\n3. یێمہِ سٍتـ̡ بہٕ تراوٕ تٔمِس سٍتـ̡ آب تہٕ خۄشٕک زمینہِ پى۪ٹھ۔ بہٕ تراوٕ پنُن روح تہٕ چانہِ اولادن پى۪ٹھ۔\n4.\\tتہٕ تِم گژھن گاسہٕ منز، آبہٕ وتہٕ وِلہٕ پٲٹھۍ۔\n5. اکھ وَنُن چُھس، بہٕ چُھس خداوند سُند۔ تہٕ بیاکھ کرِ یعقوب ناوٕ سٍتـ̡ وَنُن۔ تہٕ بیٛاکھ کرِ خداوند سٍتـ̡ اتھہٕ سٍتـ̡ تہٕ اسرٲیلِس ناوٕ سٍتـ̡ {پانَس} کٔرِتھ۔\n6. یِتھٕ پٲٹھۍ چُھ خداوند اسرائیلُک بادشاہ تہٕ تٔمۍ سُند نجات دِنہٕ وول لشکرن ہُند رب فرماوُن۔ بہٕ چھُس {چھُس} گۄڈنیُک، تہٕ بہٕ چھُس {چھُس} ٲخٕر؛ تہٕ میانہِ سٍتـ̡ چُھنہٕ کانہہ خدا۔\n7. تہٕ کُس کرِ میہ بُلاونہٕ تہٕ اعلان کرِ، تہٕ میانہِ خٲطرٕ ترتیب دِنہٕ، یێلہِ مے قدیم لُکھ مقرر کٔرۍمٕتۍ؟ تہٕ یِم چیز یِنہٕ وٲلۍ، تہٕ یِنہٕ وٲلۍ، تِم گژھن تِمن ہاونہٕ۔\n8.\\tژیہ نہ کھوژُن، نہ کھوژُن: کیا میہ چھہ نہ تمہِ وقتہٕ پیٹھے ژے وونمُت، تہٕ اعلان کورمُت؟ تم چھہِ میٲنۍ گواہ تہِ۔ کیا میہ سیتۍ چھا کانہہ خدا؟ آ، {چُھ} چُھ نہٕ خدا؛ میہ چھیہ نہ پتاہ {کنہہ تہِ}۔ {خدایہ؛ I: Heb۔ راک وغیرہ}\n9.\\tیِم چھِ تِم سارِنٕے بےکار بٔنِتھ۔ تہٕ تِمن ہٕندِس لذیذ چیزن ہُند فٲیدٕ گژھِ نہٕ۔ تہٕ تِم چھِ پنٕنۍ گواہ ؛ تِم چھِ نہٕ وُچھان تہٕ نہ زانان چھِ؛ تاکہ تِم گژھن شرمندٕ۔ {لذیذ: ہیب۔ پسندیدٕ}\n10.\\tکُس چُھ دیوتا بنوومُت، یا کُس چھُ کھٔنِتھ بٔنِتھ بَنٲومُت {یُس} کُنہِ فٲیدٕ دِنہٕ آمُت چھُ؟\n11. وچھ تٔمۍ سٕندِس سارِنٕے سٲتھی گژھن شرمندٕ: تہٕ کامہِ وٲلۍ، تِم چھِ انسانن ہٕندِس سارِنٕے سٍتـ̡ جمع کرنہٕ یِن، تِم گژھن کھڑا گژھن۔ {توتہِ} تِم گژھن کھوژان، {تہٕ} تِم گژھن اِکہٕ وٹہٕ شرمندٕ۔\n12.\\tچمگار چھہ دۅشوے ژیلہِ منز کٲم کران تہ ہتھو سٍتۍ بناوان تہ پننہِ نرِ ہندِ طاقتہٕ سٍتۍ کٲم کران: آ، تس چھہ فاقہ، تہٕ تسُند طاقت چھہ کم گژھان: سہ چھہ نہ آب چیوان تہ بے ہوش گژھان۔ {ٹونگس سۭتۍ: یا، کلہٕ سۭتۍ}\n13.\\tچھان چھُ {پنُن} قاعدہٕ پھٔہلاوان۔ سہ چھہ یہ اکھ سطر سیتۍ کڈان۔ سُہ چُھ اتھ ہوٲیی جہازٕ سٍتۍ فٹ کران، تہٕ سُہ چُھ یہ کمپاس سٍتۍ کڈان تہٕ انسان سٕنزِ خوبصورتی مطٲبق انسان سٕنزِ شکلہٕ پتہٕ بناوان ۔ تاکہ یہ روزِ گرس منز۔\n14.\\tسُہ چُھ أمِس دِودار کُلِس کُلِس مَنٛز کُلِس تہٕ کُلِس کُلِس سٍتـ̡ رٔٹِتھ دِوان۔ {مضبوط: یا، ہمت نِن}\n15.\\tتیلہِ گژھہِ انسان سٍتـ̡ دزُن، تکیازِ سُہ کرِ اتھ نِش تہٕ پانس گرم کرُن۔ آ، سُہ چُھ دِوان تہٕ روٹی چُھ دِوان۔ آ، سُہ چُھ اکھ دیوتا بناوان، تہٕ پوجا کران {یہ}؛ سُہ چُھ اتھ اکھ کھٔنِتھ شبیہہ بناوان، تہٕ اتھ پیٹھ پیوٚو۔\n16. سُہ چُھ اَمہِ سُند کُنہِ حِصہٕ نارس مَنٛز زالان۔ اَمہ منزٕ چُھ سُہ ماز کھیوان۔ سُہ چُھ بُنِتھ تہٕ مطمئن: آ، سُہ چُھ گرم کران، تہٕ ونان، آہا، بہٕ چُھس گرم گومُت، مے چُھ نار وُچھمُت:\n17.\\tتہٕ یێمہِ سٍتـ̡ چُھہ سُہ خدا بناوان، حتیٰ کہ سُہ چُھ تٔمِس کُن پۯاوان، تہٕ أمِس سٍتـ̡ دُعا کران تہٕ وَنُن چُھ، مے بچاو۔ تۅہہ چھہ میانہِ خدا۔\n18.\\tتِمن چُھنہٕ پتاہ تہٕ نہ سمجُن: تِکیازِ تِمن چُھ تِمن أچھ بند کٔرمٕژ، یُس نہٕ تِم وُچھِتھ ہیکان۔ {تہٕ} تِمن ہٕندِس دِلَس سٍتۍ، یُس نہٕ تِم سمجِتھ ہیکان۔ {بند: ہیب۔ daubed}\n19.\\tتہٕ کٲنسہ تہِ چُھہ نہٕ پننِس دِلس مَنٛز زانان تہٕ نہ چُھہ یہ ونُن زِ میہ چُھہ امیُک اکھ حصہٕ نارس منز زٲلمُت۔ آ، میہ تہِ چھُ اَمہ ہٕندِس کولس پیٹھ روٹی پٔنِتھ۔ مے چُھس ماز بٔنِتھ کھیوٚمُت، تہٕ بہٕ کٔرٕ اَمہ ہُند باقیُک مُشکِل؟ کیا بہٕ پیوٚو کُلِس کُلِس پیٹھ؟ {غور کرُن...: ہیب۔ تٔمۍ سٕندِس دِلس پیٹھ سیٹ کٔرِتھ} {سٹاک...: ہیب۔ یُس کُلِس منز یوان چھُ؟}\n20.\\tسُہ چُھ سوٗر کھٮ۪وان: دھوکہٕ دِل دِل چُھ أمِس پتھ کُن پھیرمُت، زِ سُہ ہیکہِ نہٕ پنُن روح نجات دِتھ، تہٕ نہ ہیکہِ یہ ؤنِتھ، {کیا چھُنہ} میٲنِس دچھنہِ اتھس منز کانہہ اپُز؟\n21.\\tیعقوب تہٕ اسرٲیل، یِم یاد تھاوُن۔ تکیازِ ژے چُھس میٲنۍ خادم: مے چُھہ ژے بنوومُت۔ ژٕ چُھکھ میٲنۍ خادم: اے اسرائیل، ژٕ گژھ نہٕ میہ مشراونہٕ۔\n22. میہ کٔر گٔنِس اوبرٕکۍ پٲٹھۍ، چانہِ گۅناہ تہٕ اوبرٕکۍ پٲٹھۍ، چانہِ گۅناہ مُلٲوِتھ: میہ کُن واپس۔ تکیازِ مے چُھ ژے نجات دِژمٕژ۔\n23.\\tگیو، اے آسمان۔ یێلہِ چُھہ خداوند کٔرِمُت: اے زمینہِ ہٕندِس بٔنِمِس حصس کٔرِو، اے پہاڑ تہٕ اَتھ مَنٛز موجود پرٮ۪تھ کُلِس سٍتـ̡ گٮ۪وُن، تکیازِ خداوند چُھ یعقوب نجات دِژمُت، تہٕ کٔرٕن اسرٲیلِس مَنٛز پانس جلال دِنہٕ۔\n24. یِتھٕ پٲٹھـ̡ چُھہ خداوند یُس تُہُند نجات دِنہٕ وول چُھ، تہٕ یُس ژے رحمہٕ پى۪ٹھٕ بنوومُت چُھ، بہٕ چُھس خداوند یُس سارِنٕے چیز بناوان چُھ، بہٕ چُھس خداوند یُس سارِنٕے چیز بناوان چُھہ؛ یُس کُنی آسمانس پھٔہلِتھ چُھ؛ یُس پانَے زمینہٕ پھٔہلٲوِتھ چھُ؛\n25.\\tیُس اپُزٮ۪ن ہٕندِس نشانس مایوس کران چھُ، تہٕ دیوانگن پاگل بناوان چھُ۔ یُس عقلمند {انسان} پتھ کُن پھیران چھُ، تہٕ تِمن ہٕندِس علمس بیوقوف بناوان چھُ؛\n26. یُس پننِس خادم سٕندِس کلامٕچ تصدیق کرِ، تہٕ تٔمۍ سٕندِس رسولن ہٕندِس مشورس پیٹھ عمل کرِ۔ یُس یروشلمس ونان چُھ، تہٕ یُس روزُن روزُن؛ تہٕ یہوداہ کِس شہرس مَنٛز یِیہِ تعمیر کرنہٕ، تہٕ بہٕ کٔرٕ تِمن ہٕنزِ خراب جایہِ تُلنہٕ: {گٔژھمُت...: ہیب۔ فضلہٕ}\n27. یُس سرٛنِس سٍتـ̡ ونان چُھ، خشک گژھ تہٕ بہٕ کٔرٕ چانہِ دریاوٕ خشک کٔرِتھ:\n28.\\tیُس کورس سُند وَنُن چُھ، {سُہ چُھ} میون چرواہ چُھ، تہٕ کرِ میانہِ سارِنٕے خوشی پورٕ، یێتھ تہِ وَنُن یروشلم، تہٕ یێلہِ تہِ وَنُن زِ تُہۍ گژھہِ تعمیر کرنہٕ۔ تہٕ مندرس مَنٛز یِیہِ تُہٕنز بُنیاد تراونہٕ۔","1. یِتھٕ پٲٹھـ̡ چُھ خداوند پننِس مسح کرنہٕ آمتس مُتلق کورس، یُس میہ دٔچھُن اتھہٕ رٔٹِتھ چُھ، تٔمِس برونہہ کُن قومن زیر کرنہٕ خٲطرٕ چُھہ ونان ۔ تہٕ بہٕ کٔرٕ بادشاہن ہٕنزِ کمر یلہٕ، أمِس برونہہ کنہِ زٕ پنہٕ دار دروازٕ کھولنہٕ خٲطرٕ۔ تہٕ دروازٕ گژھن نہٕ بند کرنہٕ؛ {have...: یا، مضبوٗط کٔرِتھ}\n2. بہٕ گژھٕ ژےٚ برونہہ کُن، تہٕ کٔرٕ ٹیلہٕ جاے سیدٕ: بہٕ پھٹراوٕ پیتلٕکۍ دروازٕ ٹُکرٕ ٹُکرٕ تہٕ ششتٕرٕچ سلاخہٕ ژٔٹِتھ ژٔٹِتھ:\n3. تہٕ بہٕ دِیہ ژے انہِ گٹہِ ہُند خزانہٕ، تہٕ پوشیدٕ مقامن ہُند پوشیدٕ دولت، یُتھ ژے زانہٕ زِ بہٕ چُھس، خدا، یُس تُہٕندِس ناوٕ سٍتـ̡ بلاوان چُھ، {چُھہ} اسرٲیلُک خدا۔\n4.\\tیعقوب سٕندِ خٲطرٕ تہٕ اسرٲیلِس میانہِ منتخب کرنہٕ خٲطرٕ، مے چُھہ ژے چانہِ ناوٕ سٍتـ̡ بُلاونہٕ آمُت، مے چُھہ ژے ناو تھوومُت، حالانکہ ژے چھے نہٕ مے زانان۔\n5. بہٕ چُھس خداوند تہٕ {چُھ} بییہ کانہہ تہِ، {چُھنہ} میانہِ علاوٕ چُھہ نہٕ کانہہ خدا: مے چُھہ ژے رٔٹمُت، حالانکہ ژے چُھہ نہٕ مے زانان:\n6. تاکہ تِم گژھن آفتاب کھسنہٕ سٍتـ̡ تہٕ مغرب سٍتـ̡ زانن زِ میانہِ علاوٕ چُھہ نہٕ کانہہ تہِ۔ بہٕ چُھس {خدا}، تہٕ {اَتہِ چُھ} نہٕ بیٚیہِ کانٛہہ تہِ۔\n7. بہٕ چُھس گاش بناوان، تہٕ اندھیرا پٲدٕ کران: بہٕ چُھس امن بناوان، تہٕ بدی پٲدٕ کران: بہٕ چُھس خداوند یِم سٲری {چیز} کران۔\n8. اے آسمانہٕ پیٹھٕ پۯاوُن، تہٕ آسمانن تراوُن نیکی تہٕ زمینہٕ یلہٕ تراوُن، تہٕ یِم گژھن نجات دِنہٕ، تہٕ نیکی گژھن اِکہٕ وٹہٕ پٲدٕ کرنہٕ۔ میہ چھہ خدایہ یہ تخلیق کورمُت۔\n9. یُس پننِس خالقس سٍتـ̡ جدوجہد کران چُھ، تٔمِس سٍتـ̡ ہُند افسوس چُھ! {گژھِ} کٔرِو برتن ہٕندِس برتن سٍتۍ {کوشش}۔ کیا میژِ وَنُن یُس یہِ بناوان چُھ، ژٕ کیا چُھکھ بناوان؟ یا چانہِ کامہِ، أمِس چُھنہٕ اتھہٕ؟\n10.\\tیُس مٲلِس کُنہِ سٍتـ̡ دِنہٕ آمُت چھُ؟ یا زنانہِ نِش کیا چھُکھ ژیہ دِژمُت؟\n11. یِتھٕ پٲٹھـ̡ چُھہ خداوند، یُس اسرٲیلُک پاک تہٕ تٔمۍ سُند بناون وول چُھہ ونان زِ میانین نیچوین مُتلق یِنہٕ والین چیزن مُتلق پرژھ میہ تہٕ میانین اتھن ہٕنزِ کامہِ مُتلق کٔرِو میہ حُکُم۔\n12. میہ بنوو زمین، تہٕ اَتھ پیٹھ انسان بنوومُت: مے چُھس پنٕنـ̡ اَتھٕ تہٕ تِہٕندِس سارِنٕے لشکرس پۯاوُن حُکُم۔\n13. مے چُھس نیکی سٍتـ̡ پرورش کٔرمٕژ، تہٕ بہٕ کَرٕ تٔمۍ سٕنزِ سارِنٕے وتہٕ ہٕنزِ وَتہٕ ہٕنز ہدایت: سُہ کرِ میون شہر بَناوُن، تہٕ سُہ تراوِ میٲنۍ قٲد، نہ قٲمتس تہٕ نہ انعامہٕ خٲطرٕ، سُہ چُھ ونان ۔ {ڈایریکٹ: یا، سیود کٔرِو}\n14. یِتھٕ پٲٹھۍ چُھ خداوند فرماوان زِ مصرٕچ محنت، تہٕ ایتھوپیاہٕچ تجارت تہٕ صابین ہٕنز، قد دار نفر گژھن توے نِش یِن، تہٕ تِم گژھن تۅہہِ پتہٕ یِن۔ تِم گژھن زنجیرن منز یِن، تہٕ تِم گژھن تۅہہِ نِش دُعا کرنہٕ، {ونِتھ} یِمن منز خدا چُھہ توے سٍتـ̡ دُعا کرنہٕ۔ تہٕ {چُھ} بییہٕ کنہہ نہٕ، {چُھ} نہٕ خدا۔\n15. پٔزۍ پٲٹھـ̡ چُھہ تُہُند خدا یُس پَنُن پان ژوٗرِ تھاوان چُھ، اے اسرٲیلُک خدا، نجات دِنہٕ وول۔\n16.\\tتِم گژھن شرمندہ تہٕ پریشان تہِ، یِم سارِنٕے گٔژھن اِکہٕ وٹہٕ بُت بناون وٲلۍ۔\n17. {مگر} اسرٲیلِس گژھہِ خداوند سٕندِس سٍتـ̡ ابدی نجات سٍتـ̡ نجات دِنہٕ یُن: تێہہ گژھہِ نہٕ شرمندہ سپدُن تہٕ نہ گژھہِ دنیاہس سٍتـ̡ بے انتہا پریشان کرنہٕ۔\n18.\\tیِتھٕ پٲٹھـ̡ چُھہ خداوند یُس اسمانن بنوومُت چُھ، خدایہ پانہ یمۍ زمینہِ بنوو تہ بنوو۔ تمۍ چھہ یہ قایم کورمُت، تمۍ بنوو نہ یہ بیکار بنوومُت، تمۍ بنوو یہ آباد کرنہ خاطرہ: بہٕ چُھس خداوند چُھس؛ تہٕ {تَتہِ} چھُنہٕ بیٚیہِ کانٛہہ تہِ۔\n19. میہ چُھہ نہٕ ژوٗرِ پٲٹھۍ، زمینہِ ہٕندِس تاریک مقامس منز کتھ کٔرمٕژ: مے ووٚن نہٕ یعقوب سٕندِس بیولس سٍتـ̡ بێکار، بہٕ چُھس یعقوب سٕندِس بُلِس سٍتـ̡ کتھ کران، بہٕ چُھس یِمن چیزن ہُند اعلان کران چُھس۔\n20. پان جمع کٔرِو تہٕ یِو؛ یُس قومن نِش ژٔلِتھ چھُ، تِمن چھُنہٕ کانہہ علم یُس تِمن ہٕنزِ بُتھِ ہٕندِس لٔکرِ سٍتـ̡ دُعا کٔرِتھ چھُ، تہٕ تِمن ہٕندِس خدایس دُعا کٔرِتھ دُعا کٔرِتھ یُس نہٕ بچٲوِتھ ہیکان۔\n21.\\tوَنُن تہٕ أنِو نزدیک۔ آ، تِم رٔلِتھ مشورہٕ: قدیم زمانہٕ پیٹھٕ کٔمۍ چھُ یہِ اعلان کوٚرمُت؟ {کٔم} چھُ اَمہِ وقتہٕ پٮ۪ٹھٕ یہِ وَننہٕ آمُت؟ {کیا چُھ} نہٕ میہ خداوند؟ تہٕ {چُھ} میانہِ علاوٕ چُھنہٕ کانہہ خدا۔ اکھ عادل خدا تہٕ نجات دِنہٕ وول؛ {اتہِ} چھُنہٕ میانہِ علاوٕ کانٛہہ تہِ۔\n22.\\tمیہ کُن وُچھِو، تہٕ رٔٹِتھ رٔٹِو، زمینہِ ہٕندِس سارِنٕے اندس سٍتـ̡ رٔٹِو، کیازِ بہٕ چُھس خدا، تہٕ بییہ چُھہ نہٕ کانہہ تہِ۔\n23.\\tمیہ چھہ پانس قسم، یہ لفظ چھہ میانہِ ٲسس منزہ نیران، تہ واپس، زِ پرتھ کۅٹھہِ گژھہِ میانہِ خاطرہ نمُن، پرتھ کانہہ زبان کرِ قسم۔\n24. یێلہِ چُھہ یێلہِ یێلہِ خداوند سٕندِس سٍتـ̡ چُھہ میہ نیکی تہٕ طاقت حٲصِل کٔرِتھ، {حتیٰ کہ} تہِ گژھہِ أمِس نِش یِنہٕ۔ تہٕ یُس أمِس خلاف ناراض آسہِ تِمن گژھن شرمندٕ۔ {یقینا...: یا، یقینا سُہ میانہِ بارس منز ونان، خداوند سٕندِس مَنٛز چُھ تمام نیکی تہٕ طاقت} {راستی: ہیب۔ نیکی }\n25. خداوند سٕندِس سٍتـ̡ گژھہِ اسرٲیلٕچ سارِنٕے اولادٕ انصاف کرنہٕ تہٕ جلال حٲصِل کرنہٕ۔","1.\\tبیل کُن کٔرِتھ، نیبو کٔرِتھ تہٕ تِہٕندِس بُتَس ٲس درندَن تہٕ چارواین پیٹھ: چانہِ گاڑِ آسہٕ گٔبۍ بٔرِتھ۔ {تِم چھِ} تھکہٕ مٕتۍ {درندٕ} خٲطرٕ بوج۔\n2. تِم چھِ اَکہٕ وٹہٕ نِوان تہٕ تِم چھِ اَکہٕ وٹہٕ نَمان۔ تِم ہیوٚک نہٕ بوجھ تُلِتھ، مگر پانہٕ گٔیہِ قٲد۔ {پانہٕ: ہیب۔ تہنز روح}\n3. اے یعقوب سٕندِس گرس تہٕ اِسرٲیلِچ سارِنٕے باقٕے باقٕے یِم یِم یٔڈ پى۪ٹھٕ پى۪ٹھہٕ پى۪ٹھہٕ پى۪ٹھٕ پى۪ٹھہٕ پى۪ٹھـ̡ پى۪ٹھـ̡ پى۪ٹھہٕ پى۪ٹھـ̡ پى۪ٹھہٕ پى۪\n4.\\tتہِ {حتی} بُزرگ تام میہ {am} him؛ تہٕ {حتیٰ کہ} بہٕ تُلِتھ مَس تُلِتھ {ژے}: مے چُھس بنوومُت، تہٕ بہٕ کرٕ برداش۔ بہٕ تہِ کرٕ تُلِتھ تہٕ دِیہٕ {ژے}۔\n5.\\tژیہ کمہِ سٍتۍ تشبیہ دِوان تہٕ میہ برابر بناوِتھ تہٕ میہ ہیو ہیو بٔنِتھ؟\n6.\\tتِم چھِ سۄنہٕ سٍتـ̡ س� تہٕ سُہ چُھ اتھ اکھ خدا بناوان: تِم چھِ پٮ۪وان، آ، تِم چھِ پوجا کران۔\n7.\\tتِم چھِ أمِس پھیکس پیٹھ تھپھ کٔرِتھ، تِم چھِ أمِس تُلِتھ تہٕ أمِس پننہِ جایہِ تھوان، تہٕ سُہ چُھ کھڑا گژھان۔ پننہِ جایہ گژھہِ نہ سہ ہٹاونہ آمت: آ، {اکھ} کرِ أمس فریاد دِتھ، توتہِ ہیکہِ نہ تس جواب دِتھ، تہ نہ ہیکہِ تس پننہِ مصیبت نشہِ بچٲوتھ۔\n8.\\tیہ یاد تھاوُن تہٕ پانس ہٲوِو انسان: اے بدمعاشو۔\n9.\\tپرانہِ چیزن یاد تھاوُن: کیازِ بہٕ چھُس خدا، تہٕ بییہ چھُنہٕ کانہہ تہِ۔ {بہٕ چھُس} خدایا، تہٕ {میہ ہیو چُھنہ} کانہہ تہِ،\n10.\\tشروع پیٹھے تہٕ قدیم زمانہٕ پیٹھٕ {تِم چیز} یِم نہٕ {وُنیُک} کرنہٕ آمٕتۍ چھِ، وَنُن زِ میون مشورٕ روزِ قٲیِم، تہٕ بہٕ کٔرٕ پنٕنۍ سورے خوشی حٲصِل:\n11.\\tمشرقہٕ پیٹھٕ أکِس بدمعاش جاناوارس بلاوُن، یُس شخٕص دوٗرِ مُلکہٕ پیٹھٕ میانہِ مشورٕ انجام دِوان چھُ: آ، مے چھُ کتھ کٔرمٕژ، بہٕ تہِ کرٕ یہِ پوٗرٕ کرنہٕ۔ میہ چھہ ارادہ کورمُت، بہٕ تہِ کرِ یہِ۔ {یہ...: ہیب۔ میانہِ مشورٕ}\n12.\\tمیہ بوزو، اے مضبوط، یُس نیکی نِش دور چھُ:\n13. بہٕ چُھس پنُن نیکی نزدیک انان۔ یہِ گژھِ نہٕ دور تہٕ میٲنۍ نجات روزِ نہٕ رُکاونہٕ: تہٕ بہٕ تھاوٕ صیہونَس مَنٛز نجات پننہِ جلال خٲطرٕ۔","1.\\tبِہُن، تہٕ بِہِتھ بِہِتھ کُنہِ تختس منز، اے کلدانن ہٕنزِ کورِ، تکیازِ ژے گژھِ نہٕ وُنہٕ نرم تہٕ نازک وننہٕ یُن۔\n2.\\tگِلہٕ کٔرِتھ رٔٹِتھ کھٮ۪نہٕ: پَنٕنہِ زنٛگہٕ کٔرِو نٮ۪بر کٔرِتھ، زنٛگہٕ کٔرِو نٮ۪بر کٔرِتھ، دٔریاوَن اَپارِ کٔرِتھ۔\n3.\\tچانۍ ننگہ گژھہِ بے نقاب کرنہٕ، آ، چانۍ شرم گژھہِ وچھنہٕ: بہٕ کرٕ انتقام، تہٕ بہٕ میلہٕ نہٕ ژے سٍتـ̡ انسانس سٍتـ̡۔\n4. {یوتام زَن} سٲنـ̡ نجات دِنہٕ وول، لشکرن ہُند رب {چُھ} تٔمۍ سُند ناو، یُس اسرٲیلُک پاک چُھ۔\n5. بِہتھ ژھۄپہٕ، تہٕ ژے گٔژھِو انہِ گٹہِ منز، اے چالڈین ہٕنزِ کورِ، تکیازِ ژے گژھِ نہٕ وُنہٕ وُننہٕ یِن، سلطنتن ہٕنز خاتون۔\n6. بہٕ اوسُس پننین لوکن سٍتـ̡ ناراض گومُت، مے کٔر پنُن وراثت آلودہ تہٕ دِژُن تِم پننِس اتھس مَنٛز: ژے کٔر نہٕ تِمن رحم۔ پرانہِ کُ\n7.\\tتہٕ ژے ووٚن، بہٕ روزٕ ہمیشہٕ خٲطرٕ زنانہٕ: {یێلہِ} ژے کٔر نہٕ یِم {چیز} پننِس دِلَس پیٹھ تھوو، تہٕ نہ کٔرٕن اَمیُک ٲخری اند۔\n8.\\tتێلہِ بوزو وۅنۍ یہ {ژے} یُس لذتن منز دِنہٕ آمُت چھُ، یُس لاپرواہی سان روزان چُھ، یُس تۅہہِ دِلس منز ونان چُھس، بہٕ چُھس تہٕ بییہ کانہہ تہِ چُھہ نہٕ میانہِ سٍتـ̡ ۔ بہٕ بہٕ بِہتھ نہٕ بیواہ سٍتۍ، تہٕ نہ بہٕ پتاہ زِ شُرین ہٕندِ راوُن:\n9.\\tمگر یِم زٕ چیز یِن ژے أکِس دۅہس منز أکِس لمحس منز، شُرین ہٕندِ ضایع تہٕ بیواہ آسنہٕ کِنۍ، تِم گژھن تۅہہِ سٍتـ̡ پننہِ کمال سٍتـ̡ تۅہہِ سٍتـ̡\n10.\\tکیازِ ژے چُھہ پننہِ بدکاری پیٹھ بھروسہٕ کورمُت: ژے چُھہ وونمُت، کانہہ تہِ چُھہ نہٕ میہ وُچھان۔ چانۍ حکمت تہٕ تُہند علم، یہ چُھ ژےٚ گمراہ کٔرمٕژ۔ تہٕ ژے چُھس پننِس دِلس منز ووٚنمُت، بہٕ چُھس {چُھ}، تہٕ میانہِ علاوٕ بییہ کانہہ تہِ۔ {بد اخلاق...: یا، ژیہ پھیُرُن}\n11.\\tتێلہِ گژھہِ بُردی تہِ یێلہِ۔ ژے گژھہِ نہ پتاہ زِ یہ کتہِ پیٹھہ نیران چھُ، تہٕ تۅہہِ پیٹھ گژھہِ شرارت۔ ژیہ ہٮکہٕ نہٕ یہ بند کٔرِتھ، تہٕ یُس نہٕ ژیہ پتاہ آسہِ، تہٕ یُس نہٕ ژیہ پتاہ آسہِ۔ {پیٹھ...: ہیب۔ صبحُک صُبح} {پُٹ: ہیب۔ کفارہ}\n12. وُنۍ کھڑا گژھِو پنہٕ نِس طلسمَس سٍتۍ، تہٕ پنٕنٮ۪ن جادوگرن ہٕنزِ بٔڑِس تعدادس سٍتۍ، یِمن مَنٛز ژے پننہِ جوانی پیٹھٕ محنت کٔرمٕژ۔ اگر تہِ آسہِ تیلہِ گژھہِ تۅہہ فایدہ حٲصل کٔرتھ، اگر تہِ آسہِ۔\n13. تُہۍ چھِو پنٕنٮ۪ن مشورن ہٕندِس بٔڑِس سٍتـ̡ تھکان گٔمٕتـ̡ ۔ وۅنۍ گژھن نجومی، ستارہ وچھن والۍ، ماہانہٕ پیشین گویی کرن والۍ، تھوٚد تھوٚد تہٕ ژے بچاوُن تِمن {یِمن چیزو نِش} یِم تۄہہِ پیٹھ یِنہٕ۔ {نجومی: ہیب۔ آسمانک ناظرین} {ماہانہ...: ہیب۔ یُس ریتن متعلق علم دِوان چھُ}\n14. وچھ تِم گژھن کُنہِ کُنہِ کُنہِ ہٕندِس پٲٹھۍ۔ نار دِیہِ تِمن دزان۔ تِم گژھن نہٕ پانس نارٕ کہِ طاقتہٕ نِش بچاوُن: {تتہِ} گژھِ نہٕ گرم کرنہٕ خٲطرٕ {تہٕ نہ} نار بِہنہٕ خٲطرٕ۔ {پانہٕ: ہیب۔ تہنز روح}\n15.\\tیِتھٕ پٲٹھۍ گژھن تِم تۅہہِ سٍتـ̡ یِمن سٍتـ̡ تۅہہِ سٍتـ̡ محنت کٔرمٕژ آسہِ، تِم گژھن پرٮ۪تھ أکِس سٍتـ̡ پننِس کوٹھس کُن پھیران۔ کانہہ تہِ کرِ نہ ژیہ بچاو۔","1. اے یعقوب سٕندِس گھرس سٍتـ̡ یُس اسرٲیلُک ناو چُھہ وننہٕ آمُت، تہٕ یُس یہوداہ کِس آبہٕ سٍتـ̡ نیران چُھ، یُس خداوند سٕندِ ناوٕ سٍتـ̡ قسم کھیوان چُھ، تہٕ چُھہ نہٕ حقیقتس سٍتـ̡ تہٕ نیکی سٍتـ̡ سٍتـ̡ دِنہٕ آمُت۔\n2. تِکیازِ تِم چِھ پانس مقدس شہرُک وَنان۔ لشکرن ہُند رب {چُھ} تٔمۍ سُند ناو۔\n3. میہ چھہ گۅڈنچہ چیزن ہند اعلان شروع پیٹھے کورمُت۔ تہٕ تِم دراو میانہِ ٲسہِ منز، تہٕ مے ہٲوۍ تِم۔ میہ کٔر اچانک {تِم}، تہٕ تِم آیہِ گٔیہِ۔\n4.\\tکیازِ میہ ٲس پتاہ زِ ژیہ چھکھ ضد کران تہ تہنز گردن چھیہ ششتر تہ تۅہہِ چھیہ پیتل۔ {ضد: ہیب۔ ہارڈ}\n5.\\tمیہ چھہ شروع پیٹھے تہِ ژے اعلان کورمُت۔ امہ برونہہ زِ یہ سپدُن میہ ہٲو ژےٚ: یێلہِ ژے وَنُن زِ میانہِ بُتَن چُھ یِم کٔرمٕتۍ، تہٕ میٲنۍ کھٔنِتھ بُت، تہٕ میٲنۍ پگلہٕ بُتٕچ بُت، تہٕ میٲنۍ پگھلِمٕژ بُتٕہ چُھ تِمن ہُند حُکُم دِژمُت۔\n6. ژے بوزمُت، یہ سورُے وُچھو۔ تہٕ کیا تُہۍ کٔرِو نہٕ اعلان کٔرِتھ؟ میہ ہٲوۍ ژے امہ وقتہٕ نٔوۍ چیز، پوشیدٕ چیز تہِ، تہٕ ژے ٲس نہٕ تمن خبر۔\n7. تِم چھِ وُنۍ تخلیق کرنہٕ آمٕتۍ، تہٕ نہٕ گۅڈٕ پیٹھٕ۔ تمہ دۅہہ برونہہ تہِ ییلہ نہ تم بوزان آسہِ۔ میہ گژھہِ یہ ونُن، وچھ میہ ٲس تمن زانان۔\n8.\\tآ، ژے بوز نہٕ۔ آ، ژیہ ٲس نہ خبر۔ آ، تمہِ وقتہٕ پیٹھٕ اوس نہٕ تُہند کَن کھولنہٕ آمُت: تکیازِ مےٚ ٲس پتاہ زِ ژٕ کٔرِکھ واریاہ غداری، تہٕ اوسُس رحمہٕ پیٹھٕ بدکار وننہٕ آمُت۔\n9.\\tپننہِ ناوٕ خٲطرٕ کٔرٕ بہٕ پنُن غصہٕ ژٔٹِتھ تہٕ پننہِ تعریفہٕ خٲطرٕ بہٕ کٔرٕ ژےٚ ژےٚ ژٹنہٕ خٲطرٕ۔\n10. وچھ میہ چُھ ژے صاف کٔرمٕژ، مگر رۄپہٕ سٍتـ̡ نہٕ۔ مے چُھکھ ژے مصیبت کِس بھٹس منز ژارنہٕ آمُت۔ {سۭتۍ...: یا، رۄپہٕ خٲطرٕ}\n11.\\tپننہِ خاطرہ، {حتیٰ کہ} پننہِ خاطرہ، کیا بہٕ کرٕ {یہ}: کیازِ {میون ناو} کِتھہ پاٹھۍ گژھہِ آلودہ سپدُن؟ تہٕ بہٕ دِیہ نہٕ پنُن جلال بییِس دِنہٕ۔\n12. اے یعقوب تہٕ اسرٲیل، میانہِ بُلاونہٕ آمُت، مے بوزُن۔ میہ {am} him؛ بہٕ چھُس {چھُس} گۄڈنیُک، بہٕ تہِ چھُس ٲخری تہِ۔\n13.\\tمیانہِ اتھہ تہِ ترٲو زمینچ بنیاد تہ میون دچھُن اتھہ چھہ آسمانس تام وۅتھان۔ {ییلہ بہ} تمن بلاوان چھہ، تم چھہِ اکوٹہ کھڑا گژھان۔ {میانۍ...: یا، میانہِ دچھنہِ اتھہ ہند اتھہ پھٔہلِتھ چھُ}\n14. تم سٲری جمع گژھو تہٕ بوزو۔ یِمو منزٕ کُس چھُ یِمن {چیزن ہُند} اعلان کورمُت؟ خداوند چُھ أمِس محبت کٔرمٕژ: سُہ کرِ بابل سٍتـ̡ پنٕنۍ خوشی تہٕ تٔمۍ سٕنز نٔر آسہِ کلدانس پیٹھ۔\n15.\\tمیہ چھہ کتھ کرمژ۔ آ، مے چُھس بُلوومُت: بہٕ چُھس سُہ أنِمُت، تہٕ سُہ کرِ پنٕنۍ وَتھ خۄشحال ۔\n16. یێلہِ سٍتـ̡ یێلہِ سٍتـ̡ سٍتـ میہ چھیہ نہ شروع پیٹھے ژوٗرِ پٲٹھۍکتھ کٔرمژ۔ یێمہِ وقتہٕ سٍتـ̡ چُھہ یێلہِ سٍتـ̡ میہ تہٕ وۆنـ̡ خداوند خدا تہٕ تٔمۍ سٕندِس روٝحہِ سٍتـ̡ چُھہ میہ سوزمُت۔\n17. یِتھٕ پٲٹھۍ چُھ خداوند یُس تُہُند نجات دِنہٕ وول، اسرٲیلُک پاک چُھہ فرماوان۔ بہٕ چُھس خداوند تُہند خدا یُس ژے فٲیدٕ حٲصل کرُن ہیچھناوان چُھ، یُس ژے وتہِ وتہِ پکناوان چُھ، یُس ژے گژھُن گژھُن۔\n18.\\tکاش ژے میانہِ حُکمن بوزمُت! تیلہ آسہ ہا چانۍ امن دریاوکۍ پٲٹھۍ، تہٕ چانۍ نیکی سمندرٕچ لہرن ہٕندۍ پٲٹھۍ:\n19.\\tتۅہہِ ہُند بیول تہِ اوس سیکہِ ہیوٗ تہٕ تۅہہِ ہٕندِس بٔرِس ہٕندۍ پٲٹھۍ۔ تٔمۍ سُند ناو گژھہِ نہ ژٹنہٕ آمُت تہٕ نہ گژھہِ میہ برونہہ کُن ختم کرنہٕ یُن۔\n20.\\tبابل منزٕ نیرِو، ژٔلِو کلدِین نِش، گٮ۪ونٕچ آوازٕ سٍتـ̡ ؤنِو، یہِ وَنُن {حتیٰ کہ} زمینہٕ کِس اندس تام۔ تُہۍ چھِو ونان زِ خداوند چھُ پنُن خادم یعقوب نجات دِژمُت۔\n21.\\tتہٕ تِمو ہیوٚت نہٕ تِمن صحرا کِنۍ نِنہٕ، تٔمۍ دِژ تِمن ہٕندِ خٲطرٕ کنہِ کٔنہِ منزٕ آب وسان۔\n22. خداوند چُھ ونان زِ بدکارن سٍتـ̡ چُھہ کانہہ امن ۔","1. بوزو، اے جزیرٕ، میانہِ خٲطرٕ؛ تہٕ بوزو، اے لوکو، دور پیٹھ۔ خداوند چُھ میہ رحمہٕ پیٹھٕ بُلاونہٕ آمُت۔ میانہِ ماجہ ہٕندِ اندرٕ کٔرِتھ چھُ تٔمۍ میون ناو ہیوٚتمُت۔\n2. تہٕ تٔمۍ بنوو میون اوس تیز تلوار ہیوٗ ۔ پننہ اتھہ کس ژھایہ منز چھُس میہ ژوٗر تھوومُت، تہٕ بنووُن میہ اکھ پالش شنڈ۔ تمۍ چھہ میہ پننہِ لۅتہِ منز ژوٗر تھوومت۔\n3. تہٕ وۆنُن مے، اے اسرائیل، تہٕ چُھہ میٲنۍ خادم، یێمہِ سٍتـ̡ بہٕ تسبیح سپدِ۔\n4. اَمہِ پَتہٕ ووٚنمُت، بہٕ چُھس بیکار محنتہٕ کٔرمٕژ، بہٕ چُھس پنُن طاقت بیکار تہٕ بیکار: {توتہِ} یێلہِ چُھہ میون فٲصلہٕ خداوند سٍتـ̡ تہٕ میون کٲم چُھہ پننِس خداہس سٍتـ̡ ۔ {میون کٲم: یا، میون انعام}\n5. تہٕ وُن، خداوند چُھ ونان یُس میہ رحمہٕ پى۪ٹھہٕ پى۪ٹھہٕ بنوومُت چُھ، یعقوب دُبارٕ پانس نِش اننہٕ خٲطرٕ، یۆدوے نہٕ اسرٲیلـ̡ جمع کرنہٕ آمُت، توتہِ گژھہٕ بہٕ خداوند سٕندِس نظرس مَنٛز جلال حٲصل تہٕ میون خدا آسہِ میٲنۍ طاقت۔ {حالانکہ...: یا، زِ اسرائیل گژھہِ أمس نِش جمع کرنہٕ، تہٕ بہٕ ہیٛکہٕ وغیرہ}\n6.\\tتہٕ وۆنُن زِ یہِ چُھہ ہلکہٕ کتھ زِ ژٕ گژھہِ یعقوب سٕندِ قبیلہٕ زندٕ کرنہٕ خٲطرٕ تہٕ اسرٲیلِچ محفوٗظ بحال کرنہٕ خٲطرٕ میٲنۍ خادم بٔنِتھ، تہٕ بہٕ دِیہ ژے غیر قومن ہٕندِ خٲطرٕ گاش تہٕ یُتھ ژٕ ہێکہِ زمینہٕ کِس اندس تام میٲنۍ نجات دِنہٕ۔ {یہ چھُ...: یا، ژیہ چھکھ تمہ کھوتہ ہلکہ ہلکہ یُس ژیہ کرُن، وغیرہ} {محفوظ: یا، ویرانی}\n7. یِتھٕ پٲٹھـ̡ چُھ خداوند یُس اسرٲیلُک نجات دِنہٕ وول چُھ، {تہٕ} تٔمِس سٍتـ̡ یُس انسان حقارت کران چُھ، یٔمِس قوم نفرت کران چُھ، بادشاہن ہٕندِس خادمَس سٍتـ̡ گژھن بادشاہن وُچھن تہٕ وُچھن، شہزادٕ تہِ پوٗزا کرٕن، یُس خداوند سٕندِ سٍتـ̡ وفادار چُھ، {تہٕ} اسرٲیلُک پاک چُھ، تہٕ سُہ کرِ تُہُند انتخاب۔ {یُس انسان...: یا، یُس روحس منز حقارت چھُ}\n8. یِتھٕ پٲٹھۍ چُھ خداوند فرماوان، أکِس قابل قبول وقتس مَنٛز چُھہ مے تُہٕنز بوزمٕژ، تہٕ نجات کِس أکِس دۅہہٕ مَنٛز کٔر بہٕ ژےٚ مدد۔ تہٕ بہٕ کرٕ ژے رژھراونہٕ تہٕ ژے دِیہٕ لوکن ہٕندِ عہدٕ خٲطرٕ، زمینہٕ قٲیم کرنہٕ خٲطرٕ، ویران میراثن ہُند وارث حٲصل کرنہٕ خٲطرٕ۔ {قٲئم: یا، تھزر}\n9.\\tیُتھ ژے قٲدٮ۪ن ؤنِتھ نیرِو۔ تِمن ہٕندِس اندِپِس منز چھِ، تِمن ہٕندِس پانس ہٲوِو۔ تِم گژھن وَتن مَنٛز کھٮ۪وان، تہٕ تِہٕندِ مرگہٕ آسن سارِنٕے تھدٮ۪ن جاین پیٹھ۔\n10. تِمن گژھِ نہٕ فاقہٕ تہٕ نہ ترش۔ نہ تمن گرمی تہٕ نہ تاپھ تہٕ یُس تمن پیٹھ رحم کرِ، سُہ کرِ تمن رہنمٲیی تہٕ آبہٕ کِس چشمہٕ سٍتـ̡ تہِ۔\n11. تہٕ بہٕ بناوٕ پنٕنۍ تمام پہاڑ اکھ وتھ، تہٕ میٲنۍ شاہراہ گژھن تھزر۔\n12.\\tوچھو یِم دور پیٹھٕ یِن: تہٕ یِم شمال تہٕ مغرب پیٹھٕ یِن۔ تہٕ یِم چھِ سِنیم کِس سرزمینہٕ پیٹھ۔\n13.\\tگیو، اے آسمان۔ تہٕ خۅش روزُن، اے زمین؛ تہٕ گٮ۪وُن، اے پہاڑ، تکیازِ خداوند چُھ پننین لوکن تسلی دِژمُت، تہٕ کرِ پننین مصیبتن پیٹھ رحمت۔\n14. مگر صییونن ووٚن زِ خداوند چُھ میہ ترٲومُت، تہٕ میون رب چُھ مٔشِد گومُت۔\n15.\\tکیا زنانہِ ہیکہِ پنُن چوسُن شُر مٔشِد کٔرِتھ، زِ تٔمِس گژھہِ نہٕ پننِس رحمس پیٹھ رحم کرُن؟ آ، تِم ما مٔشِد گٔژھِتھ، توتہٕ بہٕ کَرٕ نہٕ ژےٚ مٔشِد۔ {یہ...: ہیب۔ رحم دِنہٕ نِش}\n16.\\tوچھ میہ چھیہ ژے پننین اتھن پیٹھ کھٔنتھ کھٔنتھ۔ چانۍ دیوار چھیہ میہ برونہہ کنہِ لگاتار آسان۔\n17. تُہٕندِ شُرِ گژھن جلدی کَرُن؛ تُہند تباہ کرن وول تہٕ یِمو تۅہہِ برباد کٔرۍ، تم گژھن ژےٚ نِش نیرن۔\n18.\\tپَنٕنۍ أچھ تُلِتھ تُلِو، تہٕ وُچھِو: یِم سٲری چھِ پانس اَکہٕ وٹہٕ جمع گٔژھان، {تہٕ} ژے نِش یِوان۔ {As} خداوند چُھس ونان زِ بہٕ چُھس زندٕ روزان، ژٕ پٔزۍ پٲٹھۍ، یِمن سارِنٕے سٍتـ̡ پٲٹھۍ، یِتھٕ پٲٹھـ̡ أکِس مہرنہِ ہٕندِس پٲٹھۍ۔\n19.\\tتۅہہِ ہٕندِس ویران مقامس تہٕ تۅہہِ ہٕنزِ بربادی ہٕنزِ زمینہٕ آسہِ وُنہِ تہِ بسکینن ہٕندِ وجہ سٍتـ̡ سٮ۪ٹھاہ تنگ تہٕ یِمو ژے نِنہٕ آمٕژ آسہِ تِم گژھن دور ۔\n20.\\tیِم شُرۍ یِم ژے یِمن ہٕندِس بییِس راونہٕ پتہٕ تہٕ یِمن ہٕندِس کَنَس مَنٛز دُبارٕ وَنُن، یُس جاے چھُ میانہِ خٲطرٕ سٮ۪ٹھاہ مُشکِل: مے دِیُن جاے یُتھ بہٕ روزُن۔\n21. تیلہٕ چُھہ ژٕ پننِس دِلس منز وَنُن، یِم کٔمۍ چِھ مے زامٕتۍ، یہ وُچھِتھ زِ بہٕ چُھس پنٕنـ̡ شُرِ راوٕنـ̡ تہٕ بہٕ چُھس ویران تہٕ قید، تہٕ یور یور پھیران چُھس؟ تہٕ یِم کٔمۍ پرورش کٔرۍمٕتۍ؟ وچھ میہ کُنی کُنی۔ یِمَن کَتہِ {ٲس} تِم {ٲس}؟\n22. یِتھٕ پٲٹھـ̡ چُھہ خداوند خدایہِ فرماوان، وُچھِتھ بہٕ تُلِتھ پنُن اَتھٕ قومن کُن تُلِتھ تہٕ لُکن برونہہ کُن پنُن معیار قٲیم کٔرِتھ، تہٕ تِم أنِن تُہٕندِس نیچوِس نِش تہٕ تُہٕنزِ کورِ یِن تِمن ہٕندِس پھیکس پیٹھ تُلنہٕ۔ {آرمز: ہیب۔ بوسم}\n23. تہٕ بادشاہ آسن تُہند دودھ دِنہٕ وول مول، تہٕ تِہٕنزِ بینہٕ آسہٕ تُہٕنزِ دٲر دِنہٕ واجنہِ موج، تِم گژھن تۅہہِ برونہہ کُن سجدہ کٔرِتھ تہٕ تۅہہِ ہٕندِس کھورِ ہٕنز گرد ژٔٹِتھ۔ تہٕ ژے گژھہِ پتاہ زِ بہٕ چُھس خداوند چُھس، تِکیازِ تِم گژھن نہٕ میانہِ انتظارس منز شرمندٕ۔ {نرسنگ فادرز: ہیب۔ پرورش کرُن} {ملکہٕ: ہیب۔ شہزادی}\n24.\\tشِکار گژھہِ طاقتور نِش نِنہٕ یُن، یا حلال قٲد یِنہٕ یِنہٕ؟ {قانونی...: ہیب۔ عادلن ہُند قید}\n25. مگر خداوند چُھ یِتھٕ پٲٹھۍ ونان زِ طاقتور سٕندِ قٲدی تہِ یِن نِنہٕ، تہٕ خوفناک سُند شِکار یِن نجات دِنہٕ، تکیازِ بہٕ کرٕ تٔمِس سٍتـ̡ یُس تۅہہِ سٍتـ̡ مُتصادم آسہِ، تہٕ بہٕ کرٕ تُہند شُرِ بچاونہٕ۔ {قیدی: ہیب۔ قید}\n26. تہٕ بہٕ کٔرٕ تِمن کھٮ۪ن یِم تۅہہِ سٍتـ̡ ظلم کران چھِ۔ تہٕ تِم گژھن پننِس خونس سٍتـ̡ شرابہٕ سٍتـ̡ شراب، تہٕ سارنٕے ماز گژھہِ معلوم زِ بہٕ چُھس خداوند تُہند نجات دِنہٕ وول تہٕ تُہند نجات دِنہٕ وول، یعقوب سُند طاقتور ۔ {مٔٹھۍ: یا، نٔو}","1.\\tیتھے پاٹھۍ چھہ خداوند فرماوان، چانہِ ماجہ ہندِ طلاقک بل کتہِ چھہ، یُس میہ ترٲومُت چھُ؟ یا میانیو کُس قرض دِنہٕ والہٕ {یہ} چُھہ یِمن میہ ژےٚ کٕنمُت چُھ؟ وُچھو، تۅہہ کٔر پننین بدکارن کِنۍ پان کٕنُن، تہٕ پننہِ گناہ کِنۍ چھیہ چانۍ موج کٔرِتھ۔\n2. ییلہ بہٕ آو، {اوسا نہ} کانہہ انسان؟ ییلہ میہ فون کٔر، {اوسا} کانہہ جواب دِنہٕ خٲطرٕ؟ کیا میون اتھہ چھا ژھوٚٹ گومت، زِ یہ ہیکہِ نہ رٔٹِتھ؟ نتہٕ چُھس نہٕ میہ کانہہ طاقت دِنہٕ خٲطرٕ؟ وُچھ، میانہِ ملامت سٍتۍ چھُس بہٕ سمندرس خشک کران، بہٕ چھُس دریاوَن بیابان بناوان: تِہٕنزِ گاڈٕ چھِ بدبو، تکیازِ {اتہِ} چُھنہٕ آب تہٕ ترشہٕ سٍتۍ مران۔\n3.\\tبہٕ چُھس آسمانس سیاہ پوش لاگان تہٕ بہٕ چھُس تِمن ہُند پوشہٕ بناوان ۔\n4. خداوند خداین دِژ مے عالمن ہٕنز زبان دِژمٕژ، یُس بہٕ زانہٕ زِ سُہ چُھہ صبحٲے وۅتھان تہٕ سُہ چُھس میٲنۍ کَن بوزنہٕ خٲطرٕ وُچھان۔\n5. خداوند خداین چُھ میٲنۍ کَن کھولمُت، تہٕ بہٕ اوسُس نہٕ بغاوت کٔرمُت، تہٕ نہ پھیُر پتھ کُن۔\n6.\\tمیہ دِژ پَنُن کمر تہٕ تِمن کُن پنُن گِلہٕ یِم مَس ژٹِتھ ژٔٹِتھ: مے کٔر نہٕ پنُن بُتھ شرم تہٕ تھوکُن نِش ژوٗر۔\n7. خداوند خدا کرِ میانہِ مدد۔ لہذا گژھ نہ میہ پریشان: لہذا کیا میہ چھہ پنن بُتھ چمک ہیو تھوومُت، تہٕ میہ چھیہ پتاہ زِ میہ گژھہِ نہ شرمندہ۔\n8. {سُہ چُھ} نزدیک یُس میہ جواز پیش کران چُھ؛ میہ سیتۍ کُس کرِ مقابلہ؟ چلو أسۍ اَکہٕ وَٹہٕ کھڑا: میون مُخٲلِف کُس چُھ؟ سہ گژھہِ میہ نزدیک۔ {میٲنۍ ...: ہیب۔ میانہِ مقصدُک مالک؟}\n9. وُچھِو، خداوند خدا کَرِ میانہِ مدد۔ کُس {چُھ} سُہ {یُس} میہ مذمت کرِ؟ لو، تِم سارِنٕے گژھن پوشاک ہیوٗ وٲنسہِ۔ کیم کھیٚیہِ تِم کھٮ۪وان۔\n10. یُس خداوند سٕندِس سٍتـ̡ خوفزدہ چُھ، یُس پنہٕ نـ̡ خادم سٕنزِ آوازِ ہٕنز فرمانبرداری کران چُھ، یُس انہِ گٹہِ منز پکان چُھ، تہٕ گاش چُھہ نہٕ؟ سُہ گژھہِ خداوند سٕندِس ناوس پیٹھ بھروسہٕ کرُن، تہٕ روزُن پننِس خدایس پیٹھ۔\n11.\\tوُچھو اے سارِوٕے یُس نار زالان چُھ، یُس چنگارو سٍتـ̡ چُھہ دِژمُت: پَنٕنـ̡ نارٕ کِس گاشس مَنٛز پٔکِو، تہٕ تِمن چِنگارن مَنٛز یُس ژٔلِتھ چُھہ دِژمُت۔ یہ گژھہِ ژیہ میانہِ اتھہ۔ ژیہ گژھہِ غمس منز لوٚگتھ۔","1. یُس نیکی پَتہٕ پَتہٕ یِنہٕ وٲلۍ، یُس خداوند ژھاران چھُ، تِم کٔنہِ کُن وُچھِو، تہٕ کُنہِ کُنہِ کُن وُچھِو۔\n2.\\tپنُن مول ابراہیم تہٕ سارہ کُن وُچھِو، تکیازِ میہ کٔر تس کُنی زٲنِتھ تہٕ دُعا دِژمُت تہٕ ہُریر کٔرِتھ۔\n3. خداوند کرِ صییونس تسلی دِنہٕ: سُہ کرِ تٔمۍ سٕنزِ سارِنٕے فضول جاین تسلی دِنہٕ۔ تہٕ سُہ بناوِ أمِس بیابان عدن ہٕندۍ پٲٹھۍ، تہٕ تٔمۍ سُند صحرا خداوند سٕندِس باغس ہیوٗ بَناوُن۔ اَتھ منز میلہِ خوشی تہٕ خوشی ، شُکرگزاری تہٕ راگٕچ آواز۔\n4. میانہِ کتھ بوزو، میانہِ لوکو۔ تہٕ اے میانہِ قوم، میانہِ طرفہٕ گژھہِ اکھ قانون نیرُن، تہٕ بہٕ کرٕ پنُن فٲصلہٕ لوکن ہٕندِ گاشہٕ خٲطرٕ آرام کرنہٕ۔\n5. میٲنۍ نیکی {چِھ} نزدیک۔ میٲنۍ نجات گٔیہِ نیبر، تہٕ میٲنۍ ہتھیار کرِ لوکن ہُند فیصلہٕ۔ جزیرٕ گژھن میانہِ انتظار، تہٕ میانہِ نرِ پیٹھ گژھن تم بھروسہٕ۔\n6. پَنٕنۍ أچھ تُلِو آسمانس کُن، تہٕ بۄنہٕ کُن زمینس کُن وُچھِو، تِکیازِ آسمانہٕ گژھہِ دوٚہہِ ہٕندۍ پٲٹھۍ، تہٕ زمین گژھہِ پوشاک ہٕندۍ پٲٹھۍ، تہٕ یِتھٕ پٲٹھۍ روزن وٲلۍ یِتھے پٲٹھۍ مرن: مگر میٲنۍ نجات روزِ ہمیشہٕ خٲطرٕ، تہٕ میٲنۍ نیکی گژھِ نہٕ ختم۔\n7. اے یُس نیکی زانان چُھ، تِم لُکھ یِمن ہٕندِس دِلس مَنٛز میٲنۍ شریعت چُھ، میہ بوزو۔ تُہۍ گژھ نہٕ انسانن ہٕنزِ ملامت نِش خوفزدہ تہٕ نہ گژھ تہندِ ملامت نِش خوف۔\n8.\\tکیازِ کیم کھیٚیہِ یِمن پلوٕکۍ پٲٹھۍ، تہٕ کیمہٕ کھٮ۪یہِ یِمن ییرٕکۍ پٲٹھۍ، مگر میٲنۍ نیکی روزِ ہمیشہٕ خٲطرٕ، تہٕ میٲنۍ نجات روزِ نسل در پیر۔\n9. بیدار گژھُن، بیدار گژھُن، طاقتہٕ تھاوُن، اے خداوند سٕنزِ نٔرۍ؛ بیدار، یتھہ پاٹھۍ پرانہِ زمانس منز، پرانہِ نسلن منز۔ {آرٹ} ژیہ چھُنہٕ راحابس ژٹمُت، {تہٕ} ڈریگن زخمی کورمُت؟\n10. {آرٹ} ژے نہٕ سُہ یُس سمندرس خشک کورمُت، عظیم سرٛنُک آب۔ یمۍ سمندرچ گہرایی بنیوو فدیہ دِنہٕ خٲطرٕ اکھ وتھ؟\n11. تێمہِ کِنۍ گژھہِ خداوند سُند نجات دِنہٕ وول واپس، تہٕ گیوُن ہٮ۪تھ یِنہٕ۔ تہٕ تِمن ہٕندِس کلس پیٹھ آسہِ ابدی خوشی: تِمن گژھن خوشی تہٕ خوشی حٲصل۔ {تہٕ}غم تہٕ ماتم ژٔلِتھ ژٔلِتھ۔\n12. بہ، {حتیٰ کہ} بہٕ، {چُھ} سُہ یُس ژے تسلی دِوان چُھ: یُس ژے کھوژان چُھہ أکِس انسانس {یُس} مرُن، تہٕ انسان سُند نیچو {یُس} گاسہٕ بنہٕ ییہِ۔\n13.\\tتہٕ خداوند پنہٕ نِس بناون وٲلِس مٔشِد یُس آسمانن پھٔہلٲوِتھ تہٕ زمینٕچ بُنیاد ترٛٲوِتھ چھُ۔ تہٕ ظالم سٕندِ غصہٕ کِنۍ اوس پریتھ دۅہہ مسلسل کھوژان، زن سُہ اوس تباہ کرنہٕ خٲطرٕ تیار؟ تہٕ ظالم سُند غصہٕ کتہِ چھُ؟ {ٲس...: یا، بنوو پان تیار}\n14.\\tقیدی جلاوطنی چُھ جلدی کران زِ سُہ گژھہِ یلہٕ تراونہٕ یُن، تہٕ سُہ گژھِ نہٕ گۅڈِ مَنٛز مَرُن، تہٕ نہ گژھِ تٔمۍ سٕنزِ روٹی ناکام۔\n15. مگر بہٕ چُھس خداوند تُہند خدا، یُس سمندرس تقسیم کٔر، یٔمۍ سٕنزِ لہرٕ گٔژِھتھ گٔیہِ: لشکرن ہُند رب چھُ تٔمۍ سُند ناو۔\n16. تہٕ مے چُھس پنٕنۍ کتھ چانہِ ٲسِس مَنٛز تھوومٕژ، تہٕ بہٕ چُھس ژے پننہِ اتھہٕ کِس ژھایہِ ساے مَنٛز تھوٚومُت، یُتھ بہٕ آسمانہٕ لاگُن، تہٕ زمینٕچ بُنیاد تراوٕ تہٕ صییونس وَنُن زِ ژٕ چُھکھ میٲنۍ لوک۔\n17. بیدار گژھو، بیدار گژھو، وۅتھُن، اے یروشلم، یُس خداوند سٕندِ اتھہٕ سٍتـ̡ تٔمۍ سٕندِس قہر ہُند پیالہ چُھہ، ژے چُھکھ لرزنہٕ کِس پیالہِ ہٕندِس ڈٔرِس چُھس، {تہٕ} کٔرِتھ ژٔٹِتھ کٔرِتھ۔\n18.\\t{یِمَن سارِنٕے نیچوین مَنٛز چُھنہٕ کانہہ تہِ رہنُمٲیی کرُن}۔ نہ چھہ کانہہ {یُس} یُس أمس سارِنٕے نیچوین ہٕندِس اتھہٕ سٍتۍ رٔٹِتھ رٔٹِتھ آسہِ۔\n19. یِم زٕ {چیز} چھِ توے نِش آمٕتۍ۔ کُس کرِ چانہِ خٲطرٕ افسوس؟ ویرانی، تہٕ تباہی، تہٕ قحط، تہٕ تلوار: بہٕ کمہٕ سٕندِ ذریعہٕ کرٕ ژے تسلی دِنہٕ؟ {are...: Heb. ہوا} {تباہی: Heb. بریکنگ}\n20. تُہٕندِس نیچوِس چُھہ بیہوش گٔمٕتۍ، تِم چِھہ سارِنٕے سڑکن ہٕندِس سرس پیٹھ، جالہِ مَنٛز جنگلی داند ہٕندۍ پٲٹھۍ: تِم چِھہ خداوند سٕندِ قہر سٍتـ̡ بٔرِتھ، یُس تُہٕندِس خدایہ سٕندِ ملامت سٍتـ̡ چُھہ بٔرِتھ۔\n21.\\tتێلہِ بوزو یہ وۆن، ژے مصیبت تہٕ شرابہ، مگر شرابہٕ سٍتـ̡ نہٕ:\n22. یِتھٕ پٲٹھـ̡ چُھہ تُہُند رب خداوند تہٕ تُہُند خدا چُھہ پننِس لُکہٕ سٍتـ̡ وَنُن چُھہ تُہٕندِس اَتھٕ سٍتـ̡ لرزُن پیالہ کٔڈِتھ تہٕ یێمہِ سٍتـ̡ چُھہ پننہِ قہر ہٕندِس پیالہٕ سٍتـ̡ ژٔٹِتھ ژٔلِتھ ژٔٹِتھ تہٕ تُہٕندِس خداہس سٍتـ̡ چُھہ تُہٕندِس اَتھٕ سٍتـ̡ لرزُن پی ژے گژھ نہ بییہ یہ چیون:\n23.\\tمگر بہٕ دِیہ یہ تِمن ہٕندِس اتھس منز یُس تۅہہِ مُتٲثِر کران چھُ۔ یِمو چُھس پننِس روحس ووٚنمُت، نمُن، یُتھ أسۍ اپارِ نیرِتھ، تہٕ ژے چھُکھ پنُن لاش زمینہٕ پٲٹھۍ، تہٕ سڑکہِ ہٕندِس پٲٹھۍ، تِمن ہٕندِ خٲطرٕ یُس اپارِ گٔیہِ۔","1. بیدار، بیدار؛ اے صیہون، پَنُن طاقت تھٲوِو۔ اے یروشلم، مقدس شہر، پَنٕنۍ خوبصوٗرت پَلَو لٲگِو، تِکیازِ اَمہِ پتہٕ یِنہٕ نہٕ ژےٚ مُختٔلِف تہٕ ناپاک یِنہٕ۔\n2. پنُن پان ژٔٹِو گردِ نِش۔ وۅتھ، {تہٕ} بِہتھ اے یروشلم: اے صیون سٕنزِ قٲدی کورِ ہٕنزِ گردنہٕ نِش یلہٕ تراوُن۔\n3. یِتھٕ پٲٹھۍ چُھ خداوند فرماوان زِ تم چُھ پان کٕننہٕ آمُت۔ تہٕ تُہۍ یِیہِ پونٛسہٕ ورٲے نجات دِنہٕ۔\n4.\\tیِتھٕ پٲٹھـ̡ خداوند چُھ ونان زِ میانہِ لُکھ گٔیہِ برونہہٕ مصرس مَنٛز روزنہٕ خٲطرٕ۔ تہٕ اسیرین کٔر تمن پیٹھ بغٲر وجہہ ظلم۔\n5.\\tتێلہِ چُھہ یێلہِ کیا چُھہ، خداوند چُھہ ونان زِ میانہِ لُکھ چُھہ کُنہِ کُنہِ سٍتـ̡ نِنہ یِم تِمن پیٹھ حکمرٲنی کران چھِ، تِم چھِ تِمن کرٛٮ۪کہٕ دِنہٕ خٲطرٕ بناوان، خداوند چُھ وَنان۔ تہٕ میون ناو چُھ پریتھ دۅہہ مسلسل توہین کرنہٕ یوان۔\n6.\\tتێلہِ گژھہِ میانہِ لوکن میون ناو زانن: تێمہِ دۅہہ گژھہِ {تِمن پتاہ زِ بہٕ چُھس} سُہ یُس کتھ کران چُھس: وُچھو، {یہ} چُھس۔\n7. یُس بشارت دِوان چھُ، یُس امن شایع کران چھُ، تٔمۍ سٕندِس قدمن پیٹھ کوتاہ خوبصورت۔ یُس نیکی ہٕنز خوشخبری دِوان چُھ، یُس نجات شایع کران چُھ؛ یُس صییونس ونان چُھ، تُہند خدا چُھ بادشاہ!\n8. تُہٕندِس چوکیدار تُلِن آواز۔ آوازِ سٍتـ̡ گٮ۪ون تِم اِکہٕ وٹہٕ گٮ۪ون: تِکیازِ تِم گژھن أچھ رلٲوِتھ وُچھن، یێلہِ خداوند دُبارٕ صییون اَنِ۔\n9. یێلہِ وُچھِو یِکہٕ وَٹہٕ گٮ۪وُن، یێلہِ ہٕندِس لُکن ہٕندِس دِلچس، یێلہِ چُھہ یِمن ہٕندِس لُکہٕ سٍتـ̡ رٔٹِتھ دِژمُت۔\n10. خداوند چُھ سارِنٕے قومن ہٕندِس نظرس منز پنُن پاک نٔر نِش بَنٲومُت۔ تہٕ زمینہِ ہٕندِس سارِنٕے اندس سٍتـ̡ وُچھن سانہِ خدایہِ سٕنز نجات ۔\n11. ژٔلِو، ژٔلِو، تتہِ نِش نیرِو، کُنہِ تہِ ناپاک {چیز} ہُند اَتھٕ لگٲوِو۔ تٔمۍ سٕندِس منزٕ نیرِو۔ تم گژھو پاک یُس خداوند سٕندِ بانہٕ رٔٹِتھ چھُ۔\n12. تِکیازِ تُہۍ گژھِو نہٕ جلدی کٔرِتھ نیرِتھ، تہٕ نہ ژٔلِتھ نیرِو، تِکیازِ خداوند گژھِ تۅہہِ برونہہ کُن۔ تہٕ اسرٲیلُک خدا آسہِ تُہند بدلہٕ۔ {be...: Heb. جمع کٔرِو ژےٚ جمع کٔرِتھ}\n13.\\tوچھ، میون خادم گژھہِ ہوشیاری سان ورتاوُن، سُہ گژھہِ تھزرس تہٕ تعریف، تہٕ سٮ۪ٹھاہ تھد۔ {ڈیل...: یا، خوشحال}\n14.\\tیتھے پاٹھۍ گٔیہ تۅہہ حیران۔ تٔمۍ سُند شکلہٕ اوس کٲنٛسہِ تہِ انسانہٕ سٕندِ کھۅتہٕ زیادٕ خراب تہٕ تٔمۍ سٕنز شکل ٲس انسانن ہٕندِس نیچو کھۅتہٕ زیادٕ۔\n15. یِتھے پٲٹھۍ کرِ سُہ واریاہن قومن ہُند چھُکُن۔ بادشاہ گژھن أمِس نِش بنٛد کٔرِتھ: یُس نہٕ تِمن وننہٕ آمُت اوس، تِم گژھن وُچھن؛ تہٕ {یہ} یُس نہٕ تِمو بوزمُت اوس تِم غور کرُن۔","1. سانہِ رپورٹس پیٹھ کٔمۍ چُھ یقین کورمُت؟ تہٕ خداوند سٕنز نٔر کٔمِس خٲطرٕ چھُ ظٲہر سپدان؟ {رپورٹ: یا، نظریہ؟: ہیب۔ بوزُن؟}\n2. تکیازِ سُہ گژھہِ تس برونہہ کنہِ نرم کُلِس ہٕندۍ پٲٹھۍ، تہٕ خشک زمینہٕ منزٕ موٗل ہٕندۍ پٲٹھۍ، أمِس چھُنہٕ کانہہ شکل تہٕ خوبصورتی ۔ تہٕ ییلہ أسۍ أمس وُچھو، {تتہِ} چھُنہٕ کانہہ خوبصورتی یُس اسہِ أمِس خواہش۔\n3. أمِس چھُ حقارت تہٕ مردَن ہٕندِ نِش رد کرنہٕ آمُت۔ غمُک شخٕص تہٕ غمُک وٲقف: تہٕ أسۍ چھِ أمِس نِش بُتھ ژوٗرِ تھاوان۔ أمِس ٲس حقارت کرنہٕ آمٕژ، تہٕ أسۍ ٲسۍ نہٕ أمِس احترام کٔرۍمٕتۍ۔{أسۍ ژوٗرِ...: نتہٕ، سُہ اوس تٔمۍ سُند بُتھ اسہِ نِش ژوٗر تھوومُت: ہیب۔ بُتھِس نِش بُتھِس پوشہِ ہٕندۍ پٲٹھۍ، نتہٕ اسہِ نِش}\n4.\\tیقینا چھُ تٔمۍ سانہِ غم برداشت کٔرمٕژ، تہٕ سٲنۍ غم تُلِتھ تہٕ أسۍ أسۍ أمِس مُتٲثِر، خدایہ سٕندِ دٔسۍ تہٕ مُتٲثِر گٔژھمٕتۍ۔\n5.\\tمگر سُہ اوس سانہِ گناہ کِنۍ زخم گومُت، سُہ اوس سانہِ ظلمن ہٕندِ خٲطرٕ زخم دِنہٕ آمُت: سانہِ امن ہُند عذاب۔ تہٕ تٔمۍ سٕنزِ پٹیو سٍتۍ چھِ أسۍ شفا بخشان۔ {زخمی: یا، اذیت} {سٹرایپس: ہیب۔ bruise}\n6. أسۍ سارِنٕے ہٕندِس پٲٹھۍ، کۅکرِ ہٕندِس پٲٹھۍ، گٔیہِ گٔمٕتۍ۔ اسہِ چھُ پرٮ۪تھ أکِس پننہِ وتہِ کُن پھیرمُت۔ تہٕ خداوند چُھ اسہِ سارِنٕے ہُند بدکار أمِس پیٹھ تھوومُت۔ {لیڈ...: ہیب۔ اسہِ سارِنٕے ہٕندِس سٍتـ̡ مِلنہٕ خٲطرٕ بٔنِتھ\n7.\\tأمِس آو ظُلم کرنہٕ، تہٕ سُہ آو مُتٲثِر کرنہٕ، توتہِ چُھ نہٕ أمِس چُھہ کُنہِ\n8.\\tسُہ آو جیلہٕ منزٕ تہٕ فیصلہٕ نِش نِنہٕ: تہٕ کُس کرِ پننہِ نسلُک اعلان؟ تکیازِ سُہ آو زندٕ سٕندِ سرزمینہٕ نِش ژٹنہٕ: میانین لوکن ہٕنزِ سرکشی سٍتـ̡ آو سُہ مارنہٕ۔ {جیل پیٹھ...: یا، پریشانی تہٕ فیصلہٕ سٍتۍ دور: مگر، وغیرہ} {کیا سُہ اوس...: ہیب۔ أمِس اوس ٹاس دِنہٕ آمُت}\n9. تہٕ تٔمۍ بنوو پنٕنۍ قبر بدکارن سٍتۍ، تہٕ امیرن سٍتـ̡ پننِس مرنس سٍتـ̡۔ تکیازِ تمۍ اوس نہ کانہہ تشدد کورمُت، نہ اوس تس ٲسس منز کانہہ دھوکہ۔ {موت: ہیب۔ موت}\n10.\\tتوتہِ آو خداوند سُند زخم دِنہٕ خٲطرٕ خۅش کرنہٕ۔ سُہ چُھ غمس مَنٛز ترٛٲومُت: یێلہِ تُہۍ تٔمۍ سٕندِس روحس گۅنہٕ خٲطرٕ نذرانہٕ دِیُو، سُہ وُچھِہِ پنہٕ نِس دۅہس زیٹھراوُن، تہٕ خداوند سٕنز خوشی گژھہِ تٔمِس اتھس مَنٛز۔ {توہ...: یا تٔمۍ سُند روح کرِ نذرانہ دِنہٕ}\n11.\\tسُہ گژھہِ پننہِ روحٕچ مصیبت وُچھان، {تہٕ} گژھہِ مطمئن: تٔمۍ سٕندِ علمہٕ سٍتـ̡ کرِ میون نیک خادم واریاہن ہُند جواز ثٲبت کرنہٕ۔ تکیازِ سُہ کرِ تِمن ہٕندِ بدکار برداش۔\n12. تێمہِ کِنۍ کرٕ بہٕ أمِس {اکھ حصہٕ}بٔڈِس سٍتـ̡ تقسیم، تہٕ سُہ کرِ غنیمت طاقتورن سٍتـ̡ تقسیم۔ تکیازِ تٔمۍ چُھ پنُن روح موتس تام تروومُت: تہٕ سُہ اوس مجرمَن سٍتۍ شمار کرنہٕ آمُت۔ تہٕ تٔمۍ کٔر واریاہن ہُند گۅناہ تہٕ کٔرٕن ناکارن ہٕندِ خٲطرٕ شفاعت۔","1.\\tگیو، اے بنجر ژے {یُس} نہٕ برداشت کٔرِتھ۔ گٮ۪وُن گٮ۪وُن، تہٕ بَڑِ کٔرِتھ کٔرِو، یُس نہٕ شُرِ ہٕندِس شُرِ سٍتـ̡ دِنہٕ آمُت چُھہ، خداوند چُھ فرماوان زِ یێلہِ بێیہِ ہٕندِس شُرِ سٍتـ̡ چُھہ بێرانن ہٕندِس شُرِس کھۅتہٕ زیادٕ آسان۔\n2. پَنٕنہِ خیمہٕ ہٕنز جاے بٔڑٲوِو تہٕ تِم تھاوٕن پنٕنٮ۪ن بستی ہٕندِس پردٕ ہٕندِس پردٕ سٍتـ̡ پَنٕنـ̡ دٔرِتھ تہٕ پَنٕنـ̡ پَنٕنـ̡ دٔرِو پَنٕن\n3. تِکیازِ تُہۍ گژھِو دٔچھنِس تہٕ کھوورِ طرفہٕ پھٔٹِتھ۔ تہٕ تُہُند بُل بَنہِ غیر قومن ہٕندِس وٲرثس منز، تہٕ بَناوِ ویران شہرن منز بسنہٕ۔\n4. خوفہٕ نہٕ کرُن۔ تکیازِ ژیہ گژھہِ نہ شرمندہ گژھُن، تہٕ نہ گژھہِ پریشان۔ تکیازِ ژے گژھِ نہٕ شرمندہ کرنہٕ: کیازِ ژے گژھِ پننہِ جوانی ہٕنز شرمندگی مٔشِد گٔژھِتھ، تہٕ پنٕنۍ بیواہ آسنٕچ ملامت گژھِ نہٕ مزید یاد۔\n5. تُہٕندِس خالقس سٍتـ̡ چُھہ تُہند خانٛدار؛ میزبانن ہُند رب {چُھ} تٔمۍ سُند ناو؛ تہٕ تُہند نجات دِنہٕ وول اسرٲیلُک پاک۔ سُہ گژھہِ سارِنٕے زمینُک خدا وننہٕ یُن۔ {میکر: ہیب۔ میکرز}\n6. یِکیازِ خداوند چُھہ ژےٚ أکِس زنانہٕ سٕندِس طورس پیٹھ بُلاونہٕ آمُت یُس روحس مَنٛز غمگسار آسہِ، تہٕ جوانی ہٕنزِ خانٛدارِنہِ ہٕندِس طورس پیٹھ، یێلہِ تہٕ ژے انکار کرنہٕ آو، چُھہ تُہند خدا۔\n7.\\tژیہ ترٲومژ۔ مگر بہٕ کٔرٕ ژےٚ سٮ۪ٹھاہ رحمتہٕ سٍتۍ۔\n8.\\tرژھ کھنڈ شرارتس منز تھوو میہ ژے نِش کُنہِ کالس پنُن بُتھ ژوٗر۔ مگر بہٕ کٔرٕ بہٕ تُہٕندِس نجات دِنہٕ وٲلِس خداوند سٍتـ̡ چُھہ ژے سٍتـ̡ رحم کٔرِتھ۔\n9.\\tاَتھ مۅکھہٕ چُھہ نوح سُند آب میانہِ خٲطرٕ: یِتھٕ پٲٹھۍ چُھس میہ قسمہ کورمُت زِ نوح سُند آب گژھہِ نہٕ زمینہِ پیٹھ۔ یێلہِ چُھس میہ قسمہ کورمُت زِ بہٕ کرٕ نہٕ ژے سٍتـ̡ شرارت، تہٕ نہ کرٕ ژے ملامت کرنہٕ۔\n10. تکیازِ پہاڑ گژھن نیرن، تہٕ پہاڑ گژھن ہٹاونہٕ۔ مگر میٲنۍ مہربانی گژھہِ نہٕ ژے نِش ژلہٕ، تہٕ نہ گژھِ میانہِ امنُک عہد ختم کرنہٕ، خداوند یُس توے پیٹھ رحم کران چُھ، چُھ ونان ۔\n11.\\tاے مُصیبت زدہ تہٕ وُپھ وُپھ تہٕ تسلی دِنہٕ آمٕژ، وچھ بہٕ تھاوٕ چانۍ کٔنہِ خوبصورت رنگہٕ سٍتۍ، تہٕ چانۍ بُنیاد تراوٕ نیلم سٍتۍ۔\n12.\\tتہٕ بہٕ بناوٕ چانہِ دٲرِ تہٕ چانہِ کاربنکلن ہٕندِ دروازٕ تہٕ چانہِ سارِنٕے خۅش کن کنن ہٕنز۔\n13. تہٕ تُہٕندِس سارِنٕے شُرِس یِن خداوند سٕندِ سٍتـ̡ ہیچھناونہٕ یُن۔ تہٕ بٔڈ آسہِ تہندٮ۪ن شُرین ہُند سکون۔\n14.\\tنیکی سٍتـ̡ گژھہِ تُہۍ قایم سپدٕنـ̡ تہٕ ظلمہٕ نِش دور روزُن۔ تِکیازِ ژے گژھِ نہٕ خوفہٕ تہٕ دہشت نِش۔ تکیازِ یہ گژھہِ نہ ژیہ نزدیک۔\n15.\\tیِم گژھن یِمن ہٕندِس سٍتـ̡ یکوٹہٕ جمع گژھن، {مگر} میانہِ ذریعہٕ نہٕ: یُس تہِ تۅہہِ خٕلاف جمع گژھہِ سُہ گژھہِ تۅہہِ ہٕندِ خٲطرٕ۔\n16. وچھ میہ بنوو سُہ لوہار یُس نارس مَنٛز ژیلہٕ وُپھ دِوان چُھ، تہٕ یُس پننہِ کامہِ خٲطرٕ اکھ آلہٕ دِوان چُھ۔ تہٕ مے چھُ تباہ کرنہٕ خٲطرٕ ضایع کرن وول تخلیق کوٚرمُت۔\n17. یُس نہٕ تۅہہِ خٕلاف بناونہٕ یِنہٕ وول کانٛہہ تہِ ہتھیار گژھِ نہٕ کامیاب سپدِتھ۔ تہٕ پرٮ۪تھ کانہہ زبان یُس تۅہہِ خلاف فیصلس منز کھڑا گژھہِ، تہٕ ژے کرِ مذمت۔ یہِ چُھ خداوند سٕندِس خادمَن ہُند میراث، تہٕ تِہٕنز نیکی چھے میانہِ سٍتـ̡ ۔","1.\\tپریتھ کانہہ یُس ترشہ آسہِ، یُس نہٕ پٲنسہٕ آسہِ، آبس کُن یُس نہٕ پٲنسہٕ آسہِ۔ یِو یِمو مٔلِتھ کھٮ۪وان تہٕ کھٮ۪وان چھُ؛ آ، آ، پٲنسہٕ ورٲے تہٕ قۭمتہٕ ورٲے ہیٚنۍ شراب تہٕ دۄد۔\n2. تۅہہ کیازِ چھِو پونسہٕ خرچ کران یُس نہٕ روٹی چُھ؟ تہٕ تۅہہِ ہٕنزِ محنتہٕ یُس نہٕ تسلی دِوان چھُ؟ میانہِ کُن بوزُن تہٕ یُس اصل چُھ، تہٕ پنُن روح گژھہِ موٹاپے سٍتـ̡ خۅش کرنہٕ۔ {خرچ: ہیب۔ وزن}\n3. پَنُن کَن کٔرِو تہٕ یِمو کُن یِن: بوزو، تہٕ تُہُند روح روزِ زندٕ۔ تہٕ بہٕ کَرٕ ژے سٍتـ̡ دٲیرٕ سٍتـ̡ داؤد سٕنزِ رحمتہٕ سٍتـ̡ ابدی عہد کرنہٕ۔\n4.\\tوچھو میہ دِژمُت سُہ عوامس خٲطرٕ اکھ گواہ، اکھ رہنُما تہٕ عوامُک کمانڈر۔\n5. وُچھِو، تُہۍ کٔرِو أکِس قومس بُلاونہٕ یُس نہٕ تۅہہ پتاہ چُھ، تہٕ قومن {یُس} نہٕ زانان چُھہ تہٕ تُہۍ گژھِ تُہٕندِس خدایہِ سٕندِ سٍتـ̡ تہٕ اسرٲیلـ̡ کِس پاک سٍتـ̡ ژٔلِتھ ژٔلِتھ ۔ تکیازِ تٔمۍ کٔر تۅہہِ ہٕنز حمد کرنہٕ۔\n6. یێلہِ سُہ لبنہٕ یِنہٕ سٍتـ̡ خداوند سٕندِس سٍتـ̡ ژھانڈِو، تێلہِ کٔرِو أمِس نِش بُلاونہٕ:\n7. بدکار گژھہِ پننہِ وتھ ترٲوِتھ تہٕ بدکار گژھہِ پنُن خیال تہٕ سُہ گژھہِ خداوند کُن واپس، تہٕ تس گژھہِ تس پیٹھ رحم کرنہٕ۔ تہٕ سٲنِس خدایہِ سٕندِس سٍتـ̡ سٍتـ� {بدکار ...: ہیب۔ بدکار انسان} {وافر پٲٹھۍ...: ہیب۔ معافی خٲطرٕ ضرب کٔرِو}\n8.\\tمیانہِ خیالہٕ چُھہ نہٕ تُہند خیال تہٕ نہ چُھہ تُہٕندِس وتہٕ سٍتـ̡ میٲنۍ وتہٕ، خداوند چُھ فرماوان۔\n9. یِتھٕ پٲٹھۍ چھُ آسمانہٕ زمینہٕ کھۅتہٕ تھوٚد، تِتھے پٲٹھۍ چھِ میانہِ وتہٕ تہٕ میانہِ خیالہٕ تہٕ میانہِ خیالہٕ تہِ چھِ تُہندِ خیالہٕ کھوتہٕ تھد۔\n10. یێلہِ چُھہ روٗد وسان تہٕ اسمانہٕ پیٹھٕ شین وسان تہٕ تتہِ واپس، بلکہ چُھ زمینس آب دِوان تہٕ کُل دِوان تہٕ کُلۍ دِوان تہٕ کُلۍ دِوان تہٕ کھٮ۪نہٕ وٲلِس روٹی دِیہِ۔\n11.\\tیِتھے پٲٹھـ̡ گژھہِ میون کلام یُس میانہِ ٲسہِ منزٕ نیرِ، سُہ گژھہِ نہٕ میہ نِش واپس، مگر سُہ کرِ سُہ یُس بہٕ یژھان چُھس پورٕ کرُن، تہٕ سُہ گژھہِ تتھ چیزس مَنٛز یُس میہ سوزمُت اوس۔\n12. تِکیازِ تُہۍ گژھِو خوشی سٍتـ̡ نیرِتھ، تہٕ امن سٍتـ̡ نیرُن: پہاڑ تہٕ بالہٕ ژٔٹِتھ ژٔٹِتھ تہٕ میدانٕکۍ سٲری کُلۍ ژَرِ پوٚپ پٲٹھۍ۔\n13.\\tکانٹہٕ بدلہٕ ییہِ فر کُلِس کھسنہٕ، تہٕ بٔرِس بدلہٕ گژھہِ مِرٹُل کُلِس کھسنہٕ، تہٕ یہِ گژھہِ خداوند سٕندِ خٲطرٕ ناو، یُس نہٕ ژٹنہٕ یِنہٕ یِنہٕ۔","1. یِتھٕ پٲٹھـ̡ چُھ خداوند فرماوان، یێلہِ رٔٹِو تہٕ انصاف کٔرِو، تێلہِ چُھہ میٲنۍ نجات یِنہٕ وٲلِس سٍتـ̡ تہٕ میٲنۍ نیکی ظٲہر سپدٕنـ̡ ۔ {فیصلہ: یا، مساوات}\n2. بابرکت {چُھ} انسان {یُس} یہِ کران چُھ، تہٕ انسان سُند نیچو {یُس} چُھ اتھ تھپھ کٔرِتھ۔ یُس سبت سبت آلودہ کرنہٕ نِش بچاوان چُھ، تہٕ تٔمۍ سُند اتھٕ چُھ کُنہِ تہِ بُرٕ کرنہٕ نِش بچاوان۔\n3.\\tیُس اجنبی سُند نیچو یُس خداہس سٍتـ̡ رٔلِتھ چُھہ، سُہ گژھہِ کتھ کرُن، یُس خداوند چُھس میہ پننین لوکن نِش الگ کورمُت، تہٕ نہ گژھہِ خواجہ سرا سُند ونُن، وُچھ، بہٕ چُھس اکھ خشک کُل۔\n4. یِتھٕ پٲٹھۍ چُھ خداوند تِمن خواجہ سرا سٍتـ̡ ونان یِم میانہِ سبت دۅہہٕ تھاوان چِھ، تہٕ تِمن چیزن ہُند انتخاب چُھ کران یِم میانہِ مرضی ہٕندِس عہدس رٹان چھِ۔\n5. بہٕ تہِ دِیہ تِمن پننِس گرس تہٕ پننین دیوارن مَنٛز نیچوین تہٕ کورِ ہٕندِ کھوتہٕ بہتر جاے تہٕ ناو: بہٕ دِیہ تِمن اکھ ابدی ناو، یُس نہٕ ژٹنہٕ ییہِ۔\n6. یُس پرٲنس سٍتـ̡ رٔلِتھ چُھہ، یُس خداوند سٕندِس ناوس سٍتـ̡ رٔلِتھ چُھ، تہٕ خداوند سٕندِس ناوس سٍتـ̡ محبت کٔرِتھ، تہٕ یُس سبت دۅہہٕ چُھہ آلودہ کرنہٕ نِش بچاوان تہٕ میانہِ عہد رٔٹِتھ چُھہ ۔\n7. بہٕ تہٕ بہٕ تِم پننِس مقدس پہاڑس پیٹھ أنِتھ، تہٕ تِمن ہٕندِس دُعا کِس گرس مَنٛز خۅش کٔرِتھ: تِہٕنزِ دزنہٕ نذرانہ تہٕ تِہٕنزِ قربانی یِن میانہِ قربان گاہس پیٹھ قبول کرنہٕ۔ تکیازِ میون گرٕ گژھہِ سارنٕے لوکن ہٕندِ خٲطرٕ دعاہُک گرٕ وننہٕ یُن۔\n8.\\tخداوند خدا یُس اسرٲیلِس کُن کٔرِتھ یُس جمع کران چُھ، توتہِ کٔرٕ بہٕ أمِس نِش جمع کرنہٕ یِنہٕ والٮ۪ن سٍتـ̡ یِمن سٍتـ̡ جمع کرنہٕ آمُت۔ {امہ علاوٕ...: ہیب۔ تٔمۍ سٕندِس اجتماعس تام}\n9.\\tاے سارِوٕے کھہہٕ درندٕ، یِمو سارِنٕے جنگلَس مَنٛز کھٮ۪نہٕ خٲطرٕ۔\n10.\\tتٔمۍ سٕندِ چوکیدار چھِ انہِ: تِم چھِ سارِنٕے جٲہل، تِم چھِ سارِنٕے کُنٕنۍ ہوٗنۍ، تِم چھِ نہٕ بھونکِتھ ہیکان۔ شوٚنگتھ، شوٚنگتھ، شونگُن خۅش کران۔ {شوٚنگتھ: یا، خواب وچھان، یا نندر منز کتھ کران}\n11.\\tآ، {تِم چھہِ}لالچی ہونۍ {یُس} زانہہ تہِ ہیکہِ نہٕ کٲفی ٲسِتھ، تہٕ تِم {چھِ} چرواہ {یِم} ہیکن نہٕ سمجِتھ: تِم سارِوٕے چھِ پننہِ وتہِ کُن نظرِ تھاوان، پرٮ۪تھ کانہہ پننہِ فٲیدٕ خٲطرٕ، پننہِ طرفہٕ ۔ {لالچ: ہیب۔ بھوک مضبوط} {ہیکن...: ہیب۔ زان زِ مطمئن گژھُن نہٕ}\n12.\\tیِمو چُھہ یِمن ہٕندِس شرابس سٍتـ̡ أنـ̡ بہٕ اَنـ̡ شراب، تہٕ أسـ̡ پَنُن پان بٔرِتھ شراب۔ تہٕ پگہہ آسہِ از دۅہک پٲٹھۍ، {تہٕ} واریاہ زیادٕ۔","1. نیک چھہ ختم سپدان، تہٕ کانہہ تہِ انسان چھہ نہ دلس پیٹھ تراوان: تہٕ رحم دل چھہ نہ نیران، کانہہ تہِ چھہ نہ یہ خیال کران زِ نیکوکار چھہ بدی نشہِ دور سپدان۔ {رحمت...: ہیب۔ رحم دِنہٕ وٲلۍ، یا، خدای} {منز...: یا، تتھ چیزس نِش یُس بد چُھ}\n2. سُہ گژھِ امنَس مَنٛز دٲخل: تِم گژھن پننِس بسترس مَنٛز آرام کَرُن، {پرٮ۪تھ أکِس} پَکُن پَکُن پَکُن۔ {دٲخل کٔرِو: یا، گٔژھِو} {پننِس منز...: یا، أمِس برٛونٛہہ}\n3.\\tمگر یێلہِ، زَناکارٕ سٕندِس بُلِس سٍتـ̡ بێیہِ تہٕ کُنہِ سٍتـ̡ بێیہِ سٍتـ̡ ۔\n4.\\tکمہِ سٍتۍ چھِو تۅہہ پانس سیتۍ واٹھ دِوان؟ کٔمۍ سٕندِس خلاف چُھکھ بٔڈۍ تھپھ کٔرِتھ، {تہٕ} زبان کٔڈِتھ؟ {کیا تُہۍ چھِو نہٕ گناہ ہٕندِ بچہٕ، اپزُک بیج،\n5. پرٮ۪تھ سبز کُلِس تَل بُتلہٕ بُت دِیُن، وادی مَنٛز شُرِ مارُن؟ {سۭتۍ...: یا، بلوطس منٛز}\n6. نالہٕ کِس ہموار {کنن} منز {چُھ} تُہند حصہٕ؛ تِم چِھہ تۅہہِ سٍتـ̡ چُھہ تُہٕندِس سٍتـ̡ چُھہ تُہٕندِس سٍتـ̡ چُھہ تُہٕندِس سٍتـ̡ چُھہ تُہٕندِس سٍتـ̡ چُھہ تُہٕندِس سٍتـ� کیا میہ پزیا یمن منز آرام میلُن؟\n7.\\tأکِس تھدِ تہٕ تھدِ بالس پیٹھ چھُکھ ژے پنُن بسترٕ بٔنِتھ، تتہِ تہِ چھُکھ قربانی دِنہٕ خٲطرٕ وۅتھان۔\n8.\\tدروازن پٔتۍ تہٕ چُھکھ ژے پنُن یاداشت قٲیم کٔرِتھ، کیازِ ژے چھُکھ میانہِ کھۅتہٕ بییہِ أکِس سٍتـ̡ پان دریافت کورمُت، تہٕ وُچھمُت۔ ژے چُھکھ پنُن بسترٕ بٔڑٲومُت، تہٕ تِمن سٍتـ̡ چُھکھ عہد کورمُت۔ ژے اوس تِہُند بسترہ خۅش کران ییتہِ ژیہ وُچھمُت۔ {بنوو...: یا کٔرِتھ تہندِ کھۅتہٕ بٔڈ پانس خٲطرٕ} {کتہِ...: یا، ژے کٔر جاے فراہم}\n9.\\tتہٕ ژے کٔرِکھ بادشاہس نِش مرہم دِتھ، تہٕ پنٕنۍ عطر بڑٲوٕن، تہٕ پنٕنۍ رسولن سوزٕکھ دوٗر دور، تہٕ کٔرٕکھ پنُن پان جہنمس کُن ذلیل کرنہٕ۔ {توہ...: یا، ژے عزت کٔرتھ}\n10.\\tژہ چھکھ پننہِ وتہِ ہنزِ عظمتس منز تھکان گومت۔ {توتہِ} ووٚن نہ، کانہہ وۅمید چھیہ نہ: ژے لٔبِتھ پننہِ اتھہِ ہنز زندگی۔ تَمہِ کِنۍ گٔیہِ نہٕ تۅہہ غم۔ {زندگی: یا، زندٕ}\n11.\\tتہٕ کٔمِس سٍتـ̡ چُھہ ژے کھوژمُت یا کھوژمُت، تہٕ ژے چُھکھ نہٕ میہ یاد، تہٕ نہ کورُکھ یہ پننِس دِلس سٍتـ̡ تھوومُت؟ کیا میہ چھہ نہ پرانہِ زمانہ تہِ پرسکون گومت، تہ ژیہ چھکھ نہ میہ کھوژان؟\n12. بہٕ کٔرٕ چانہِ نیکی تہٕ چانہِ کامہِ ہُند اعلان۔ تِکیازِ تِم ہیکَن نہٕ تۅہہِ فٲیدٕ دِتھ۔\n13.\\tییلہ ژیہ فریاد دِو، تۅہہِ گژھہِ پننہِ کمپنیہِ نجات دِنۍ۔ مگر واو نِیہِ تِم سارِنٕے نِش۔ باطل کرِ {تِم}: مگر یُس میٲنس پیٹھ بھروسہٕ کرِ، سُہ گژھہِ زمینُک مالک، تہٕ میانہِ مقدس پہاڑُک وارث۔\n14.\\tتہٕ وَنُن، وَتھ تراوُن، وَتھ تیار کٔرِو، میانہِ لوکَن ہٕنزِ وتہِ نِش رُکاوٹ تُلِو۔\n15. یِتھٕ پٲٹھۍ چُھ تٔمۍ سُہ تھدِ تہٕ تھدِ سُہ ونان یُس ابدی زندگی منز روزان چُھ، یٔمۍ سُند ناو {چُھ} پاک چُھ۔ بہٕ چُھس تٔمِس سٍتـ̡ تھدِ تہٕ مُقدس مقامس مَنٛز روزان، یُس عاجزن ہُند روح زندٕ کرنہٕ خٲطرٕ، تہٕ پشیمان لوکن ہُند دِل زندٕ کرنہٕ خٲطرٕ۔\n16.\\tکیازِ بہٕ روزٕ نہٕ ہمیشہٕ خٲطرٕ مقابلہٕ، تہٕ نہ روزٕ بہٕ ہمیشہٕ غصہٕ: تکیازِ روح گژھہِ میانہِ برونہہ کُن ناکام گژھُن، تہٕ یُس روحہٕ میہ بنٲومُت چھُ۔\n17.\\tتٔمۍ سٕنزِ لالچ بدکاری ہٕندِس بدکار سٍتـ̡ گۆو میہ شرارت تہٕ دِژُن أمِس دِلٕچ وتہِ پٲٹھۍ۔ {frowardly: Heb. پتھ کُن}\n18.\\tمیہ وچھ تٔمۍ سٕنزِ وتہٕ تہٕ بہٕ کرٕ أمِس تہٕ تسٕندِس ماتم کرن والٮ۪ن ہٕنز رہبری تہِ۔\n19. بہٕ چُھس چپُھک پھل بناوان۔ خداوند چُھ فرماوان زِ امن یُس دوٗر چُھ، تہٕ یُس نزدیکی چُھ، خداوند چُھ فرماوان۔ تہٕ بہٕ کٔرٕ أمِس ٹھیٖک۔\n20.\\tمگر بدکار چھہِ پریشان سمندرکۍ پٲٹھۍ، ییلہ یہ آرام ہیکہِ نہ کٔرتھ، یمۍ سُند آبہٕ رٔٹِتھ تہٕ میژِ تراوان چھُ۔\n21. {اَتہِ چُھنہٕ امن}، میانہِ خدایہ چُھ بدکارن سٍتـ̡ وَنان۔","1. بَڑِ کٔرِتھ کٔرِو نہٕ، پَنٕنۍ آواز تُلِتھ تُلِتھ تہٕ میانٮ۪ن لوٗکن ہٲوِو تِہٕنزِ گۅناہ تہٕ یعقوب سٕندِس گرس تہٕ تِہٕندِس گۅناہ ہٕندِس گۅنہٕ سٍتـ̡ ہٲوِو۔ {بَڑِ پٲٹھۍ: ہیب۔ گٹہٕ سۭتۍ}\n2. توتہِ چھِ تِم میہ دۅہٕ تلاش کران، تہٕ میانہِ وتہٕ زاننس منز خوش گژھان، أکِس قومہٕ سٕندِ حثیتہٕ یٔمۍ نیکی کٔرمٕژ چھِ، تہٕ پننِس خدایہ سٕندِ حکمس تراوان چھُنہٕ: تِم چھِ میانہِ نِش انصاف ہٕندِ حکمہٕ منگان۔ تِم چھِ خدایس نِش واتنس منز خوشی گژھان۔\n3.\\tاسہِ کیازِ چھہِ روزُن روزُن، تہٕ ژیہ چھہ نہ وچھان؟ {کیازِ} اسہِ چھُ پنُن روح مُتٲثِر کوٚرمُت، تہٕ ژےٚ چھُنہٕ کانہہ علم؟ وُچھِو، روزٕ کِس دۅہہٕ چُھہ تۅہہ خوشی حٲصل کٔرِتھ، تہٕ پنٕنۍ تمام محنتہٕ کٔرِو۔ {محنت: یا، تِم چیز یِمن سٍتـ̡ تُہۍ دِوان چھِو: ہیب۔ غم}\n4. وُچھِو، تُہۍ چھِو کشمکش تہٕ بحثہٕ خٲطرٕ روزٕ تھاوان، تہٕ بدکٲری ہٕندِس مٹھی سٍتـ̡ مارنہٕ خٲطرٕ، تہٕ پَنٕنۍ آواز تھزرس پیٹھ بوزنہٕ خٲطرٕ روزٕ تھاوُن۔ {تۅہہ کرُن...: یا، تم روزٕ نہٕ از دۅہہ}\n5. کیا یہ چھا تیوٗت روزٕ یُس مےٚ چُھ ژٲرمُت؟ اکھ دۅہ چھہ انسان سندِ روحس تکلیف دِنۍ؟ {کیا یہ} چھُنہٕ پنُن کلہٕ بُلش پٲٹھۍ نوٚمُت، تہٕ بۄٹہٕ پلو تہٕ سوٗر پھٔہلاونہٕ خٲطرٕ؟ کیا ژٕ چُھکھ اتھ روزٕ تہٕ خداوند سٕندِ خٲطرٕ اکھ قابل قبول دۅہ؟ {اکھ دۅہ...: یا اکس دۅہس خٲطرٕ تسند روح تکلیف دِنہِ؟}\n6. {کیا یہ} چھُنہٕ سُہ روزٕ یُس مےٚ چُھ ژٲرمُت؟ بدکاری ہٕندِس بندس یلہٕ تراونہٕ خٲطرٕ، گوٚب بوج ہٹاوُن، تہٕ مظلومن آزاد کرنہٕ خٲطرٕ، تہٕ یُس پرٮ۪تھ کُنہِ جولہٕ پھُٹراوُن؟ {ہیوب...: ہیب۔ یِمن ہٕندِس بنڈلَس ﴿ ﴿﴿﴾ ﴿﴾ پھُٹمُت}\n7. کیا یہ چُھہ نہٕ پَنُن روٹی فاقہٕ مَنٛز دِنہٕ یِوان، تہٕ یِم غریبَن کٔڑِتھ کٔرِتھ چھِو تُہٕندِس گَرَس مَنٛز أنِتھ؟ ییلہ ژیہ ننگہِ وُچھِو، تہٕ تُہۍ چھِو أمِس ؤلِتھ دِوان۔ تہٕ یُس نہٕ ژے پنُن پان پننہِ مازٕ نِش ژوٗرِ تھاوُن؟ {کاسٹ ...: یا، مُتٲثِر}\n8. تیلہٕ گژھہِ تُہند گاش صبحٕکۍ پٲٹھۍ، تہٕ تُہند صحت گژھہِ جلدٕے پھُلِتھ، تہٕ تُہٕنز نیکی گژھہِ پانس برونہہ کُن۔ خداوند سُند جلال گژھہِ تُہند انعام۔ {be...: Heb. ژیہ جمع کرُن}\n9. تَمہِ پَتہٕ کٔرِو تُہۍ پُلاونہٕ تہٕ خداوند دِیہِ جواب۔ ژیہ کرِ روُن، تہٕ سُہ وَنُن، یتہِ بہٕ چھُس۔ یێلہِ ژے ژیہ ژٔٹِتھ ژٔلِتھ تہٕ بےکار کٔرِتھ تہٕ کُنہِ\n10.\\tتہٕ اگر ژیہ پنُن روح فاقہٕ مُتلق کڈِتھ تہٕ مُصیبت زدہ روحس تسٕندِس سٍتـ̡ تیلہ گژھہِ تہند گاش گمنامی منز وۅتھان تہ تہند اندھیرا گژھہِ دوپہرس ہندۍ پاٹھۍ:\n11. تہٕ خداوند کرِ تۅہہِ لگاتار رہنمایی تہٕ خشک سالی مَنٛز کرِ تُہٕندِس روحس مُطمعہٕ، تہٕ پنٕنۍ أڈجہِ موٚٹِتھ تہٕ تہٕ تُہٕندِس آبہٕ سٍتـ̡ بٔنِتھ تہٕ آبہٕ کِس چشمہٕ ہٕندۍ پٲٹھۍ، یٔمِس آبہٕ سٍتـ̡ نہٕ وسان آسہِ۔ {خشک سالی: حب۔ خشک سالی} {ناکام: Heb. اپُز، یا، دھوکہٕ}\n12. تہٕ یِم آسن تِم بَناوٕن: تُہۍ کٔرِو واریہن نسلن ہٕنز بُنیاد تُلنہٕ۔ تہٕ ژے یِیہِ وَننہٕ یِن، دَرٕچ مرمت کَرن وول، وَتہٕ بَناوُن وَتہٕ بَناوُن۔\n13. یێلہِ ژے پَنُن کھۄر سبت نِش پھیُرِو، {مُقدس} دۅہہٕ پَنُن خوشی کرنہٕ نِش۔ تہٕ سبت وَنُن چُھہ خۅش ، خداوند سُند پاک، عزت؛ تہٕ کٔرِو أمِس احترام، نہ پنٕنۍ وَتھ کٔرِتھ، نَہ کٔرِو پنٕنۍ خوشی حٲصِل کٔرِتھ، تہٕ نہ کٔرِو پَنٕنۍ کَتھٕ کَرٕن:\n14. تیلہِ گژھ توے خداوند سٕندِس سٍتـ̡ پانس خۅش کرُن؛ تہٕ بہٕ کرٕ ژے زمینہِ ہٕندِس تھزرس پیٹھ سوار تہٕ ژے یعقوب سٕندِ مٲلہِ سٕندِ وراثتس سٍتـ̡ کھٲرناوُن، تکیازِ خداوند سٕندِ ٲسس چُھ کتھ کٔرمٕژ۔","1. وُچھِو، خداوند سُند اَتھٕ چُھنہٕ ژھوٚٹمُت، یُس نہٕ بچٲوِتھ ہیکو نہٕ۔ نہ چھہ تسند کُن گوٚب، سہ بوزان ہیکہِ نہ:\n2. مگر تۅہہِ ہٕندِس خدایس سٍتـ̡ چُھہ تۅہہِ سٍتـ̡ بُتھ ژوٗر کورمُت، یُس نہٕ سُہ بوزِ۔ {ہیو ہیو ہٲومُت: یا، چھُ سُہ ژوٗرِ تھوومُت}\n3. تِکیازِ تُہٕندِ اَتھٕ چھِ خونہٕ سٍتـ̡ ناپاک گٔمٕتـ̡ تہٕ تُہٕنزِ اونگجہِ گٔیہِ بدکٲری سٍتـ̡ چانہِ چپنہِ چھہ اپُز بولمت، چانۍ زبان چھیہ گڑبڑ کٔرمژ۔\n4.\\tکانہہ تہِ چھہ نہ انصاف منگان تہ نہ چھہ کانہہ تہِ حقیقژ ہنز درخواست کران: تم چھہِ باطل پاٹھۍ پژھ کران تہ اپُز بولان۔ تِم چھِ شرارتُک تصور کران، تہٕ بدکاری پٲدٕ کران۔\n5.\\tتِم چھِ کۅکرِ ہٕندِ ٹھوٗل کڈان تہٕ یُس ٹھوٗل کھٮ۪وان چُھ، سُہ چُھ یُس ٹھوٗل کھٮ۪وان چُھ، سُہ چُھ پھُٹان تہٕ یُس کُنہِ ٹھوٗل کھٮ۪وان چُھ، سُہ چُھ پھُٹان۔ {کاکاٹریس': یا، ایڈرز} {کٔرِتھ...: یا، چھُکُن چھُکھ تِتھۍ پٲٹھۍ زِ تتہِ چھُ اکھ وائپر بریک آوٹ کٔرِتھ}\n6.\\tتِہٕندِ جال گژھِ نہٕ پَلَو بَنٕن، تہٕ تِمن ہٕندِس کامہِ سٍتـ̡ چھِ تِمن ہٕندِس اَتھَس مَنٛز۔\n7. تِہٕندِس کھۅر چھِ بُرِس کُن ژلان، تہٕ تِم چھِ معصوم خوُن تراونٕچ جلدی کران: تِہُند خیال چھُ بدکٲری ہُند خیال۔ ضایع تہٕ تباہی چِھ تہندِس وتن منز۔ {تباہی: ہیب۔ بریکنگ}\n8. امنُک وتھ یُس نہٕ تِم زانان چھِ؛ تہٕ یِمن ہٕندِس گژھنس منز چُھنہٕ کانہہ فیصلہٕ: تِمو چھِ یِمن ہٕندِس وَتہٕ وَتہٕ بنٲومٕتۍ: یُس تہِ اَتھ منز گژھِ، سُہ چُھنہٕ امن زانان۔ {فیصلہ: یا، صحیح}\n9. تَمہِ کِنۍ چُھ اَسہ نِش فٲصلہٕ دوٗر آسان، تہٕ نہ چُھ اسہِ سٍتـ̡ انصاف حٲصِل سپدان: أسـ̡ چُھہ گاشُک انتظار کران، مگر وُچھِو گُمبٲری ۔ گاش خاطرہ، {مگر} چھہِ اسۍ اندپکس منز پکان۔\n10.\\tأسۍ چھِ اَنٮ۪ن ہٕندۍ پٲٹھۍدیوار ژھانڈان تہٕ أسۍ چھِ اَکھ اچھ ہٕندۍ پٲٹھۍ: أسۍ چھِ رٲژ ہٕندۍ پٲٹھۍدُپہرس ٹھوکر کھسان۔ {أسؠ چھِ} ویران جاین مَردٕ {انسان}۔\n11.\\tأسۍ چھہِ سارِنٕے ریچھ ہٕندۍ پٲٹھۍ، تہٕ کۅترن ہٕندۍ پٲٹھۍ ماتم کران: أسۍ چھِ فیصلہٕ ژھاران، مگر {اتہِ} چھُنہٕ کانہہ تہِ۔ نجات خٲطرٕ، {مگر} چُھ یہِ اسہِ نِش دور۔\n12. تکیازِ سانہِ گناہ چِھہ ژے برونہہ کُن بٔڈِتھ تہٕ سانہِ گۅناہ چھِ اسہِ خلاف گوٲہی دِوان: کیازِ سانہِ گناہ چھِ اسہِ سٍتـ̡ ۔ تہٕ {یوتام زَن} سانین بدکارین متعلق چھِ، أسۍ چھِ تِم زانان۔\n13. خداوند سٕنز خلاف ورزی تہٕ اپُز کٔرِتھ، تہٕ سٲنِس خدایہِ نِش دور گژھُن، ظلم تہٕ بغاوت کٔرِتھ، دِلہٕ سٍتـ̡ اپزٕچ کتھ کٔرِتھ تہٕ دِلہٕ سٍتـ̡ کٔرِتھ۔\n14. تہٕ فیصلہٕ چُھ پتھ کُن پھیرنہٕ یوان، تہٕ انصاف چُھ دور کھڑا گژھان: کیازِ سچائی چِھ سڑکہِ منز پیوان تہٕ انصاف ہیکہِ نہٕ اژِتھ۔\n15. آ، پزر چھہ ناکام سپدان۔ تہٕ یُس {یُس}بدی نِش نیران چُھ، سُہ چُھ پانس شِکار بناوان: تہٕ خداوند وُچھ {یہ}، تہٕ أمِس چُھ ناراض زِ {اَتہِ} اوس نہٕ کانہہ فیصلہٕ۔ {maketh...: یا، چُھ پاگل شمار کرنہٕ آمُت} {یہ ناپسند...: ہیب۔ یہ اوس تٔمۍ سٕنٛزن نظرن منٛز بدکار}\n16.\\tتہٕ وُچھ زِ {اَتہِ} اوس نہٕ کانہہ شُدٕ تہٕ حٲران زِ {اَتھ منز چُھنہٕ کانہہ شفاعت کرن وول}، تێمہِ کِنۍ دِژ تٔمِس نٔر نجات دِنہٕ۔ تہٕ تٔمۍ سٕنز نیکی ٲس أمس برقرار تھاوان۔\n17. تکیازِ تٔمۍ لٲگِتھ نیکی ہٕندِس پٲٹھۍ، تہٕ پننِس کلس پیٹھ نجات ہُند ہیلمٹ لٲگتھ۔ تہٕ تٔمۍ لٲگِتھ انتقامٕکۍ پلو، تہٕ لوٚگ پوشہٕ ہٕندۍ پٲٹھۍ جوش۔\n18.\\tتِمن ہٕندِس اعمال مطٲبق کرِ سُہ پننین دشمنن ہُند غصہٕ، دُشمن ہُند بدلہٕ۔ جزیرن پیٹھ کرِ سہ معاوضہٕ۔ {اعمال: ہیب۔ معاوضہٕ}\n19. یِتھے پٲٹھۍ گژھن تِم مغرب پیٹھٕ خداوند سٕندِ ناوُک خوف تہٕ آفتاب کھسنہٕ سٍتـ̡ تٔمۍ سٕندِس جلال سٍتـ̡ کھوژان۔ یێلہِ دُشمن سٍتـ̡ سٔہلاب ہٕندۍ پٲٹھـ̡ اژِہ، خداوند سُند روح تُلِہ أمِس خٕلاف اکھ معیار تُلِتھ۔ {لفٹ...: یا، تراوُن سُہ ژلُن}\n20. تہٕ نجات دِنہٕ وول گژھہِ صییونس مَنٛز، تہٕ یعقوبس مَنٛز یِمن ہٕندِس خطا نِش پھیرِ۔\n21. یێلہِ چُھہ میانہِ سٍتـ̡ تِمن سٍتـ̡ میٲنۍ عہد چُھ، خداوند چُھ فرماوان۔ خداوند چُھ ونان زِ میون روح یُس ژے پیٹھ چُھ، تہٕ میٲنۍ کلام یُس میہ تێنہِ ٲسس منز تراومُت چُھ، سُہ گژھہِ نہٕ چانہِ ٲسِس منز، تہٕ نہ چُھہ چانہِ بُلہٕ سٕندِ ٲسہِ منزٕ نیرِتھ، تہٕ نہ چُھہ تُہنزِ اولادٕ سٕندِ ٲسہِ منزٕ نیرِتھ، تہٕ چُھہ تُہٕندِ بُلہٕ سٕندِ بُلہٕ سٕندِ ٲسہِ منزٕ نیرِتھ، یێلہِ تہٕ ہمیشہٕ خٲطرٕ۔","1. ووتھ، چمک؛ تِکیازِ تُہُند گاش چُھ آمُت، تہٕ خداوند سُند جلال چُھ توے پیٹھ پٲدٕ گومُت۔ {چمک...: یا، روشن گژھُن؛ تکیازِ تُہند گاش چُھ یِوان}\n2.\\tتێلہِ وُچھِو انہِ گٹہِ زمینہِ سٍتـ̡ تہٕ لُکن ہٕندِس سٍتـ̡ گٔیہِ سٍتـ̡ انہِ گٹہِ، مگر خداوند گژھہِ توے پیٹھ وُتھ، تہٕ تٔمۍ سُند جلال گژھہِ توے پیٹھ۔\n3. تہٕ غیر قومہٕ یِن تُہٕندِس گاشس مَنٛز، تہٕ بادشاہ یِن تُہٕندِس ظٲہِرٕ کِس گاشس کُن۔\n4. پَنٕنۍ أچھ تُلِتھ تہٕ وُچھِو: تِم سارِنٕے پان جمع کٔرِتھ، تِم چھِ تۅہہِ نِش یِوان: تُہٕندِس نیچوِس یِن دوٗرِ پیٹھٕ یِنہٕ، تہٕ تُہٕنزِ کورِ یِن دۄدٕ دِنہٕ۔\n5. تیلہ گژھہِ ژیہ وُچھِتھ تہٕ یکوٹہ وسان تہٕ تُہند دِل گژھہِ خوف، تہٕ بٔڈِتھ گژھہِ۔ تِکیازِ سمندرٕچ کثرت گژھہِ توے سٍتـ̡ تبدیل کرنہٕ، غیر قومن ہٕندِ فوج یِن توے نِش۔ {کثرت...: یا سمندرُک شور گژھہِ ژے کُن پھیرُن} {فورس: یا، دولت}\n6. اونٹَن ہُند بٔڈ بٔڈِتھ چُھہ تۅہہِ مدیان تہٕ ایفاہ ہٕندِس دٔرِس سٍتـ̡ ؤلِتھ ۔ شیبا پیٹھٕ یِن سٲری یِن: تِم أنِن سۄن تہٕ بخور ۔ تہٕ تِم کرِ خداوند سٕندِ حمد ہاونہٕ۔\n7. کیدارٕکۍ سارِنٕے ریوڑ یِن ژےٚ نِش جمع کرنہٕ، نیبایوتھٕکۍ مینڈٕ یِن تۅہہِ ہٕنز خدمت کرنہٕ، تِم یِن میانہِ قربان گاہِ پیٹھ قبولیت حٲصل کٔرِتھ، تہٕ بہٕ کٔرٕ پننہِ جلال کِس گرس ہٕنز تعریف۔\n8.\\tیم {یُس} کُس چھہِ اوٚبرکۍ پاٹھۍ وڈان تہ دارِ کُن کۅترِ ہندۍ پاٹھۍ وڈان۔\n9. یٔقیٖنی جزیرٕ گژھن میانہِ خٲطرٕ، تہٕ ترشِش سٕندِ جہازٕ گۅڈٕ پٲٹھۍ، تُہٕندِس نیچوِس دوٗرِ پیٹھٕ تہٕ تِہُند سۄنہٕ أنِتھ، خداوند تُہٕندِس خدایہ سٕندِس ناوس پیٹھ، تہٕ اسرٲیلِکِس پاک سٕندِس ناوس پیٹھ، کیازِ تٔمۍ چُھ تُہٕندِس جلال سٍتـ̡ دِژمُت۔\n10. تہٕ اَپرٮ۪ن ہٕندِ نیچو بناوِ تُہٕندِس دیوارس تہٕ تِہٕندِ بادشاہ کٔرِن تۅہہِ ہٕنز خدمت، تکیازِ میہ دِژ ژے پننہِ قٕسمس سٍتـ̡ تہٕ میہ کٔر ژے پیٹھ رحم۔\n11. تێمہِ کِنۍ گژھن چانہِ دروازٕ لگاتار یلہٕ روزن۔ تِم گژھن نہ دۅہ تہٕ رٲژ بند کرنہٕ۔ یُتھ {انسان} ہیکن توے نِش غیر قومن ہُند فوج أنِتھ، تہٕ {یُس} تِہند بادشاہ {یِن} انن۔ {فورس: یا، دولت}\n12. یُس قوم تہٕ بادشاہی یُس نہٕ تۅہہِ خدمت کرِ، سُہ گژھِ ختم سپدِ۔ آ، {تِم} قومن گژھن بالکل ضایع۔\n13.\\tلبنانُک جلال گژھہِ ژے نِش، فر کُلِ، دیودار کُلِس تہٕ ڈبہٕ یکوٹہٕ میانہِ مقدس مقامچ جاے خوبصورتی بخشنہٕ خٲطرٕ۔ تہٕ بہٕ بناوٕ پننین قدمن ہٕنز جاے شاندار۔\n14.\\tتِمن ہٕندِس نیچوِس تہِ یِم تۅہہِ سٍتـ̡ دِژمٕژ چھِ۔ تہٕ یِم سٲری تۅہہِ حقارت کران چھِ، تِم گژھن تۅہہِ ہٕندِس قدمن ہٕندِس تلوبس پیٹھ نمُن۔ تہٕ تِم وَنَن تۅہہِ خداوند سُند شہر، اسرٲیلِک مقدس سُند صیون۔\n15.\\tییلہ ژے ترٲوتھ تہٕ نفرت کرنہٕ آمٕژ، یێلہِ نہٕ کانہہ تہِ انسان ژے وُچھمُت، بہٕ بناوٕ ژے اکھ ابدی عظمت، واریہن نسلن ہٕنز خوشی۔\n16. تہٕ ژٕ گژھ غیر قومن ہُند دۄد تہٕ بادشاہن ہُند سینہ چوسُن، تہٕ ژے گژھہِ معلوم زِ بہٕ چُھس خداوند تُہند نجات دِنہٕ وول تہٕ تُہند نجات دِنہٕ وول تہٕ یعقوب سُند طاقتور چُھس۔\n17. پیتلہٕ خٲطرٕ بہٕ اَنہٕ سۄن، تہٕ ششتٕرٕ خٲطرٕ تہٕ لٔکرِ ہٕندِ خٲطرٕ تہٕ کنن ہٕندِ خٲطرٕ ششتٕر، بہٕ کَرٕ چانہِ افسرن تہٕ چانہِ سٍتـ̡ نیکی تہِ۔\n18.\\tتُہنزِ زمینہِ مَنٛز گژھِ نہٕ تشدد بوزنہٕ یُن، تہٕ تُہنزن سرحدن اندر گژھہِ نہٕ تباہی تہٕ تباہی۔ مگر ژے وَنُن پنٕنـ̡ دیوارن نجات تہٕ پنٕنـ̡ دروازن تعریف۔\n19.\\tآفتاب گژھہِ نہ دۅہلہٕ تُہند گاش۔ نہ چُھہ گاشہٕ سٍتـ̡ ژیہ گاش دِنہٕ، مگر خداوند آسہِ تۅہہِ خٲطرٕ ابدی گاش، تہٕ تُہند خدا آسہِ تُہند جلال ۔\n20. تُہند آفتاب گژھہِ نہٕ وُنہِ ڈوبُن۔ تُہند زون گژھہِ نہ پانس پتھ کُن، تکیازِ خداوند آسہِ تُہند ابدی گاش، تہٕ تُہند ماتم ہُند دۅہ گژھہِ ختم۔\n21. تُہٕندِ لوٗکھ تہِ گژھن سارِنٕے صٔحیح: تِم گژھن ہمیشہٕ خٲطرٕ زمینُک وٲرث، میانہِ کُلِچ شاخ، میانہِ اتھن ہٕنز کٲم، یُتھ بہٕ گٔژھِتھ گٔژھِ۔\n22. لۄکُٹ بَنہِ ساس، تہٕ لۄکُٹ بَنُن اکھ مضبوٗط قوم: بہٕ خداوند کرِ پننِس وقتس مَنٛز جلدٕ۔","1. خداوند خدا سُند روح {چُھ} میانہِ پیٹھ؛ تِکیازِ خداوند چُھہ میہ عاجزن تام خوشخبری دِنہٕ خٲطرٕ مسح کورمُت۔ تٔمۍ چھُ مے سوزمُت زِ دِل پھُٹمٕتۍ چھِ، قٲدٮ۪ن آزٲدی ہُند اعلان کرنہٕ خٲطرٕ، تہٕ یِمن ہٕندِ خٲطرٕ قٲد خانہٕ کھولنہٕ خٲطرٕ سوزمُت۔\n2. خداوند سُند قابل قبول ؤری تہٕ سانہِ خدایہ سٕندِ انتقامُک دوہ اعلان کرُن۔ تِمن سارِنٕے ماتم تسلی دِنہٕ خٲطرٕ؛\n3. تِمن خٲطرٕ مقرر کرُن یُس صییونس مَنٛز ماتم کران چُھ، تِمن دِنہٕ خٲطرٕ خوٗبصوٗرتی، ماتم خٲطرٕ خوشی ہُند تیٖل تہٕ گۄبٕرِ ہٕندِس روحس خٲطرٕ تعریفُک لباس۔ یُتھ زن تِمن نیکی ہٕندِ کُلۍ وننہٕ یِن، خداوند سُند پودٕ لاگُن، یُتھ سُہ گژھہِ تسُند جلال کرنہٕ۔\n4. تہٕ تِم کرِ پرانہِ ویران تعمیر کرنہٕ، تِم کرِ پرانہِ ویران تُلنہٕ، تہٕ تِم کرِ ویران شہرن ہٕنز مرمت ، واریہن نسلن ہٕندِس ویران۔\n5.\\tتہٕ اَپرَن ہٕندِس کھورِ کھٮ۪نہٕ خٲطرٕ کھٮ۪نہٕ یِن، تہٕ غٲر ملکی سٕندِ نیٚچوِ گژھن تُہٕندِ ہل تہٕ تُہٕندِس انگورٕ سٕندِس دَرٕس سٍتـ̡ ۔\n6. مگر یِو یِن خداوند سٕندِ پادٕرۍ ناو دِنہٕ: {انسان} یِن تۅہہِ سٲنِس خدایہ سٕندِ وزیرِ وَنُن، تہٕ تِہٕندِس جلال سٍتـ̡ پٲٹھـ̡ پى۪ٹھ۔\n7. پننہِ شرم خٲطرٕ {ژیہ آسہِ} دوٚگنہٕ۔ تہٕ افراتفری سٍتـ̡ گژھن تِم پننِس حصس سٍتـ̡ خۅش گژھن: تێمہِ مۄکھٕ آسہِ تِمن ہٕندِس سرزمینس مَنٛز دۄگنہٕ حٲصِل: تِمن ہٕندِ خٲطرٕ آسہِ ابدی خوشی۔\n8. میہ چُھس خدایہ سُند فیصلہٕ محبت کران، بہٕ چُھس زالنہٕ خٲطرٕ ڈکیتی سٍتـ̡ نفرت۔ تہٕ بہٕ کَرٕ تِہٕنزِ کامہِ سٍتـ̡ سٍتـ̡ ہدایت، تہٕ بہٕ کَرٕ تِمن سٍتـ̡ اکھ ابدی معاہدٕ۔\n9. تہٕ تِہُند اولادٕ گژھہِ غیر قومن مَنٛز زاننہٕ یِن، تہٕ تِہٕندِس اولادس مَنٛز یُس یِمن وُچھان چُھ، یێمہِ سٍتـ̡ خداوند سٕندِ دِنہٕ آمُت چُھ۔\n10. بہٕ کَرٕ خداوند سٕندِس سٍتـ̡ سٮ۪ٹھاہ شاد، میون روح روزِ پننِس خداہس مَنٛز خۄش۔ تِکیازِ تٔمۍ چھُ مےٚ نجات ہٕنٛدِ پلو لٲگِمٕتۍ، أمۍ چھُ مےٚ نیکی ہٕنٛدِ پلو لٲگِتھ، یِتھ پٲٹھۍ مہرازٕ چھُ پانَس زیور سجاوان، تہٕ یِتھ پٲٹھۍ مہریٚنۍ چھِ پنٕنۍ جوٲہِر سجاوان۔ {ڈیکیتھ: ہیب۔ پادٕرۍ سٕندِس طورس پیٹھ ڈیکیتھ\n11. یێلہِ زَن زٔمیٖن پَنٕنہِ کُلۍ نیران چُھ، تہٕ یێلہِ باغ چُھ یِم اتھ مَنٛز ووپداونہٕ آمٕتۍ چِھ، سُہ چُھ پھۅل نیران۔ یێلہِ کَرِ خداوند خدایہِ سارِنٕے قومن برونہہ کُن نیکی تہٕ تعریف۔","1. صہیون سٕندِ خاطرٕ بہٕ روزٕ نہٕ پنُن سکون، تہٕ یروشلم خٲطرٕ بہٕ روزٕ نہٕ آرام یوتام نہٕ تٔمِچ نیکی گاش ہٕندۍ پٲٹھۍ، تہٕ امیُک نجات چراغٕکۍ پٲٹھۍ، یُس دزنہٕ ییہِ۔\n2. تہٕ غیر قومن وُچھن تُہٕنز نیکی تہٕ سارِنٕے بادشاہن ہٕندِ جلال سٍتـ̡ تہٕ یێلہِ یێلہِ نٔوِس ناوٕ سٍتـ̡ وننہٕ یُن، یُس خداوند سٕندِ ٲسِس ناو دِیہِ۔\n3. تُہۍ گژھِو خداوند سٕندِس اتھس مَنٛز جلال ہُند تاج تہٕ پننِس خدایہ سٕندِس اتھس مَنٛز شٲہی تاج تہِ آسُن۔\n4. ژے گژھِ نہٕ مزید ترک کرنہٕ آمُت وننہٕ۔ تُہٕندِس سرزمینس یِیہِ نہٕ وُنہٕ ویران قرار دِنہٕ، مگر ژے یِیہِ حفزیبہ تہٕ تُہٕنز زمین بیولاہ وننہٕ، تکیازِ خداوند چُھ توے سٍتـ̡ خوش گژھان، تہٕ تُہٕنزِ زمینہِ گژھہِ خاندر کرنہٕ۔ {حفزیبہ: یعنی میٲنۍ خوشی چھیہ تس منز} {بیولا: یعنی خانٛدر}\n5. یِتھٕ کٔنۍ زَن اَکھ جوان کُنوارِس سٍتـ̡ خاندر کٔرِتھ، {یِتھٕ کٔنـ̡ تُہٕندِس نیچوِس سٍتـ̡ خاندر کٔرِتھ، تہٕ یِتھٕ کٔنہِ مہرازٕ مہرِنہِ سٍتـ̡ شاد سپدِ، {یێلہِ} چُھہ تُہند خدا ژے سٍتـ̡ شاد سپدِ۔ {یتھ کٔنۍ...: ہیب۔ مہرازٕ سٕنزِ خوشی سٍتۍ}\n6. اے یروشلم، میہ چُھہ چانہِ دیوارن پیٹھ چوکیدار تھوومُت، یُس نہٕ دۅہہٕ تہٕ رٲژ ہُند امن تھاوُن: یُس خداوند سُند ذکر کران چُھ، ژھۄپہٕ تھاوُن نہٕ، {بناو...: یا، چُھہ خداوند سٕندِ یادداشت}\n7. تہٕ تٔمِس دِیُن نہٕ آرام یوتام نہٕ سُہ قایم کرِ، تہٕ یوتام نہٕ سُہ یروشلم زمینس مَنٛز تعریف کرِ۔ {باقی: ہیب۔ خاموشی}\n8.\\tخداوند چُھ پننہِ دچھنہِ اتھہٕ سٍتـ̡ تہٕ پننہِ طاقتہٕ کہِ نرِ سٍتـ̡ حلف کورمُت، یێلہِ بہٕ چُھس نہٕ تُہند ماز تہٕ دِنہٕ یُس تہندٮ۪ن دُشمن ہٕندِ خٲطرٕ ماز بنہٕ خٲطرٕ۔ تہٕ اجنبی سٕندِ نیچوۍ گژھن نہٕ تُہند شراب، ییمہ خٲطرٕ ژے محنت کٔرمٕژ: {یقینا...: ہیب۔ اگر بہٕ دِوان وغیرہ}\n9. مگر یُس یہ جمع کرُن چُھ، تم گژھن اتھ کھٮ۪ن، تہٕ خداوند سٕنز حمد کرٕنۍ۔ تہٕ یِمو یِمو یہِ اَکہٕ وٹہٕ اَننہٕ آمُت چھُ، تِم گژھن میانہِ پاکیزگی ہٕندِس دربارس مَنٛز چیٚنہٕ۔\n10. گیٹ منزہ گژھُن، گٔژھِو۔ لوکن ہٕنز وتھ تیار کرو۔ کٔرِتھ کٔرِو شاہراہ؛ کٔنۍ کٔرِو جمع لوٗکَن ہٕندِ خٲطرٕ تُلِو اکھ معیار۔\n11. وُچھِو، خداوند چُھ دُنِیاہٕکِس اندس تام اعلان کوٚرمُت، وَنُن چُھہ صیہون سٕنزِ کورِ سٍتـ̡ وُچھِو، تێہٕنزِ نجات چھے یێلہِ۔ وچھ تٔمۍ سُند ثواب تہٕ أمس برونہہ کُن تٔمۍ سٕنز کٲم۔ {کٲم: یا، معاوضہٕ}\n12. تہٕ تِم وَنَن تِمن مُقدس لُکہٕ، خداوند سٕندِ نجات دِنہٕ آمٕژ، تہٕ تُہہِ یِیہِ بُلاونہٕ یُن، یُس نہٕ تراونہٕ آمُت چُھ۔","1.\\tیہ کُس چھہ یُس ادوم پیٹھہ یُس بوزرہ پیٹھہ رنٛگ کٔرِتھ یوان چھُ؟ یہِ {یعنی} چھُ پننِس لباسس منز شاندار، پننہ طاقتہٕ ہٕنزِ عظمتس منز سفر کٔرِتھ؟ بہٕ چُھس یُس نیکی سٍتـ̡ کتھ کران چُھس، نجات دِنہٕ خٲطرٕ طاقتور۔ {شاندار: ہیب۔ ڈیکڈ}\n2.\\tژیہ کیازِ چھکھ پننہِ پلوس منز وۄزل تہ چانۍ پلو یُس شرابس منز وۅتلان چھُ؟\n3.\\tمیہ چھہ تنہا شراب پریسس پیٹھ لوٚگمت۔ تہٕ لُکن منز اوس نہٕ کانہہ تہِ: کیازِ بہٕ کرٕ تِمن پننِس شَرارتس منز تہٕ پننِس غصس منز لتہٕ لتہٕ دِنہٕ۔ تہٕ تِہُند خوُن یِن میانٮ۪ن پلون پٮ۪ٹھ چھُکُن، تہٕ بہٕ کٔرٕ پنٕنۍ تمام پلو داغ۔\n4.\\tانتقامُک دۅہ چُھہ میٲنس دلس منز، تہٕ میانہِ نجات دِنُک ؤری آو آمُت۔\n5.\\tتہٕ میہ وُچھ، تہٕ {تتہِ} اوس نہٕ کانہہ تہِ مدد۔ تہٕ بہٕ اوسُس تعجب زِ اتھ منز چُھہ نہٕ کانہہ تہِ رژھراونہٕ خٲطرٕ: تێمہِ مۅکھہ دِژ میانہِ نٔرِ پانس نجات دِنہٕ۔ تہٕ میون غصہٕ، أمۍ کوٚر مےٚ برقرار تھاون۔\n6. تہٕ بہٕ کرٕ پننِس شَرارتہٕ سٍتـ̡ لُکن ہٕندِس شرابس منز، تہٕ بہٕ کَرٕ تِہُند طاقت زمینس پیٹھ۔\n7. بہٕ کَرٕ خداوند سٕنزِ محبتہٕ ہُند ذِکر، تہٕ خداوند سٕندِ حمد سٍتـ̡ یُس خداوند اسہِ دِژمُت چُھ، تہٕ اِسرٲیلِس گرس سٍتـ̡ سٍتـ̡ بێیہِ سٍتـ\n8.\\tتکیازِ تٔمۍ ووٚن، یێلہِ تِم چھِ میٲنۍ لوک، بچہٕ {یُس} چُھہ نہٕ اپُز، تێلہِ اوس سُہ تِہُند نجات دِنہٕ وول۔\n9. تِمن ہٕندِس سارِنٕے عذابَس سٍتـ̡ گۆو سُہ مُتٲثِر، تہٕ تٔمۍ سٕندِس حضوری فرشتن بچٲو تِم پننہِ محبتس تہٕ رحمس سٍتـ̡ تِم نجات دِنہٕ۔ تہٕ تٔمۍ کٔر تِم نِش تہٕ تُلِتھ تِم سارِنٕے پرانہِ دۅہہٕ۔\n10.\\tمگر تِمو کٔر بغاوت تہٕ تٔمۍ سٕندِس روٝحہِ پاک سٍتـ̡ ناراض کٔرِتھ تہٕ تِمن خلاف لوٚڑُن سُہ تہندِس دُشمن سٍتـ̡ ۔\n11.\\tاَمہ پَتہٕ اوس أمِس پرانہِ زمانہٕ یاد، موسیٰ تہٕ تٔمۍ سٕندِس لُکہٕ سٍتـ̡ کتہِ چُھہ سُہ یُس سمندرٕ منزٕ پنہٕ نِس ریوڑس سٍتـ̡ رٔٹِتھ تُلِتھ دِژمُت؟ سُہ کتہِ چُھ یُس پنُن روح القدس پانس اندر تھوو؟ {چرواہ: یا، چرواہ}\n12. یێمہِ سٍتـ̡ موسىٰ سٕندِ دچھنہِ اتھہٕ سٍتـ̡ تِمن برونہہ کُن آب تقسیم کٔرِتھ پانس اکھ ابدی ناو بنوو؟\n13.\\tییمہ سٍتـ̡ تِمن سٍتـ̡ بیابانن منز گُرِ ہٕندۍ پٲٹھۍ، {یہ} پزِ نہٕ تِمن ٹھوکر کھسُن؟\n14. یُتھ زن اکھ جانور وادی مَنٛز وسان چُھ، خداوند سٕندِ روٝحہِ دِژ أمِس آرام دِنہٕ: یِتھٕ کٔنۍ کٔر ژے پنٕنـ̡ لوکن ہٕنز قیادت کٔرِتھ، یێلہِ پَنُن پان اکھ شاندار ناو بَناوُن۔\n15. آسمانہٕ پیٹھٕ وُچھِو، تہٕ وُچھِو پنٕنۍ پاکیزگی تہٕ پننہِ عظمتٕچ بستی پیٹھ: کتہِ چُھہ تُہند جوش تہٕ طاقت، چانہِ أندرن ہٕنز آواز تہٕ پننہِ رحمتُک آواز کتہِ چُھہ؟ کیا تِم چھا روکاونہٕ آمٕتۍ؟ {آواز: یا، کثیر}\n16. بلاشبہ چُھہ تُہۍ سٲنـ̡ باپ ، یێلہِ زَن ابراہیم چُھہ اسہِ نِش لاعلم، تہٕ اسرٲیل چُھہ نہٕ اسہِ تسلیم کران: اے خداوند، چُھہ سون مول ، سون نجات دِنہٕ وول ۔ تُہند ناو {چُھ} ازلی پیٹھ۔ {سون نجات دِنہٕ وول...: یا، سون نجات دِنہٕ وول چُھ تُہند ناو}\n17. اے خداوند، ژے کیازِ کور اسہِ پننہِ وتہِ نِش گمراہ کرنہٕ، {تہٕ} چُھکھ سون دِل پننہِ خوفہٕ نِش سخٕت کٔرِتھ؟ پَنٕنٮ۪ن خادمَن ہٕندِ خٲطرٕ واپس، پنٕنۍ وراثتٕکۍ قبیلہٕ۔\n18.\\tتُہٕندِس پاکیزگی ہٕندِس لوکو چُھہ رٔٹِتھ رٔٹِتھ ژٔلِتھ تُہٕندِس مُخٲلِفس سٍتـ̡ ۔\n19. أسۍ چھِو تُہٕندِس سٍتـ̡ تِمن پیٹھ زانہہ تہِ حُکوٗمت کٔرِتھ۔ تِم ٲسۍ نہٕ تُہندِ ناوٕ سٍتۍ وننہٕ آمٕتۍ۔ {تِم...: ہیب۔ تُہند ناو آو نہٕ تمن پیٹھ وننہٕ}","1. اے یێلہِ ژے ژٔٹِتھ آسمانہٕ ژٔٹِتھ، یێلہِ تہٕ ژے وَسُن، یێلہِ تُہٕندِس حٲضِرَس سٍتـ̡ پہاڑ وَسنہٕ یِن،\n2. یێلہِ {یێلہِ} پگلُن نار دزان چُھ، سُہ چُھ آبس دپان دِوان، تُہند ناو چُھہ تُہندِ مُخٲلفن تام زاننہٕ خٲطرٕ، {یُتھ} قومن ہٕندِ موجودگی سٍتـ̡ لرزان۔ {پگھلُن...: ہیب۔ پگھلُن ہُند نار}\n3.\\tییلہ ژے خوفناک کٲم کٔرۍ، یُس نہ اسہِ وچھان اوس، ژے ووٚتھ تہ پہاڑ ووٚتھ تہِ ووٚتھ۔\n4.\\tتکیازِ دنیا کہ آغاز پیٹھے چُھ نہٕ انسانو بوزمُت، تہٕ نہ چُھہ کنن سٍتـ̡ بوزمُت، تہٕ نہ چُھہ اچھن وُچھمُت، اے خدایہ، ژے سٍتـ̡ کیا چُھ تٔمِس خٲطرٕ تیار کورمُت یُس أمِس انتظارس منز چُھ۔ {وُچھمُت...: یا وُچھمُت اکھ خدا، یُس أمِس خٲطرٕ کران چھُ، وغیرہ}\n5. تُہۍ چھِو تٔمِس سٍتـ̡ یُس خوش سپدان چُھہ تہٕ نیکی کَران چُھ، {یُس} چُھہ تُہٕندِس طریقس مَنٛز یاد تھاوان: وُچھِو، ژے چُھہ غصہٕ گٔژھان۔ تکیازِ اسہِ چھہ گۅنہہ کورمُت: تمن منز چھہ تسلسل، تہٕ أسۍ گژھہِ نجات دِنہٕ۔\n6.\\tمگر أسۍ سٲری چھہِ ناپاک {چیز} ہٕندۍ پٲٹھۍ، تہٕ سانہِ سارِنٕے نیکی چھِہ گندٕ رٔنگۍ ہٕندۍ پٲٹھۍ۔ تہٕ أسۍ سارِوٕے چھِ پنہٕ ؤتھر ہٕندۍ پٲٹھۍ موٚٹان۔ تہٕ سانہِ بدکاری، ہوہٕکۍ پٲٹھۍ، چھِ اسہِ نِش نِوان۔\n7. تہٕ کانہہ تہِ چُھہ نہٕ یُس تُہند ناو پکاران چُھ، یُس پانس پانس رٹنہٕ خٲطرٕ ہلکان دِوان چُھ، کیازِ ژے چُھکھ اسہِ نِش پنُن بُتھ ژوٗرِ تھوومُت، تہٕ چُھکھ سانہِ بدکاریو سٍتـ̡ اسہِ نِش ژوٗرمُت۔ {کھٮ۪نہٕ آمُت: ہیب۔ پگھلاونہٕ آمُت} {کیازِ: ہیب۔ اَتھٕ سٍتۍ }\n8. مگر وۆن، اے خداوند، چُھہ چُھہ سٲنـ̡ مول أسۍ چھِ میژِ تہٕ تُہۍ چھِو پنُن کمہار۔ تہٕ أسۍ سارِوٕے چھِ تُہندِ اَتھٕچ کٲم۔\n9. اے خداوند، غضب گژھ نہٕ ہمیشہٕ خٲطرٕ یاد تھاوُن: وُچھو، أسۍ چھِ تُہند سارِنٕے لوک۔\n10. تُہند مقدس شہر چُھ بیابان، صییون چُھ بیابان، یروشلم چُھ ویران۔\n11.\\tسون مقدس تہٕ سون خوبصورت گر، یَتھ منز سانٮ۪و مٲلو تۅہہِ تعریف کٔرۍ، چُھ نارٕ سٍتـ̡ زالنہٕ آمُت: تہٕ سانہِ سارِنٕے خۅش گٔیہِ تباہ کرنہٕ۔\n12. اے خداوند، کیا ژٕ کٔرِو یِمن {چیزن خٲطرٕ} پرہیز کٔرِتھ؟ ژٕ کٔرِکھ پنُن سکون، تہٕ اسہِ دِیہٕ وارِیاہ دَگ؟","1.\\tمیہ چھہ {تِمَن} یِمو {میانہِ خٲطرٕ} پرژھمُت چھُ؛ میہ چھہ نہ میہ وُچھمُت: میہ ووٚن، وچھ میہ وچھ، وچھ میہ تتھ قومس {یُس نہ} میانہِ ناوٕ سٍتۍ وننہ اوس آمت۔\n2. میہ چھہ سارِوٕے دۅہس پنُن اتھہ أکِس باغی لُکن تام پھٔہلٲومُت، یُس تِمن ہٕندِس خیالس پٔتِتھ پکان چھُ۔\n3. اکھ لُکھ یُس میہ بُتھِس پیٹھ لگاتار شرارت کران چھُ؛ یُس باغن منز قربانی دِوان چُھ، تہٕ سیرن ہٕندِس قربان گاہن پیٹھ بخور زالان۔ {on...: Heb. سیرن پیٹھ}\n4. یِم قبرن مَنٛز باقٕے روزان چھِ، تہٕ یادگارن مَنٛز روزان چھِ، یِم سورُک ماز کھیوان چھِ، تہٕ مکروہ چیز چُھ تِمن ہٕندِس بانس مَنٛز۔ {شوربہ: یا، ٹُکرٕ}\n5.\\tیُس ونان چھہِ، پانس سیتۍ کھڑا روزُن، میہ نش گژھ نہ۔ تکیازِ بہٕ چُھس ژے کھۅتہٕ پاکیز۔ یم چھہِ میٲنس نس منز اکھ دھواں، اکھ نار یُس سٲرۍسٕے دۅہس دزان چھُ۔ {نَس: یا، شَرار}\n6.\\tوچھو، {یہِ} چُھس میانہِ برونہہ کُن لیکھنہٕ آمُت: بہٕ روزٕ نہٕ ژھۄپہٕ، بلکہ دِیہٕ تِمن ہٕندِس سینس منز بدلہٕ،\n7. تُہٕندِس گناہ تہٕ چُھہ تُہٕندِس مٲلِس سٍتـ̡ یِمن ہٕندِس گۅڈنِس سٍتـ̡ بێزاری کٔرِتھ تہٕ تێلہِ چُھس بہٕ تِہٕنزِ گۅڈنِچ کٲم تہندِس سٍتـ̡ ہٕندِس سٍتـ̡ بێیہِ سٍتـ̡ کُنہِ سٍتـ̡ ہٕندِ\n8. یِتھٕ پٲٹھۍ چُھ خداوند فرماوان، یِتھٕ پٲٹھۍ چُھ نٔو شراب گٔژھتھ لبنہٕ آمُت، تہٕ {اَکہِ} چُھ ونان زِ یہ گژھ نہٕ تباہ کرنہٕ۔ اَتھ مَنٛز چھُ اَکھ نعمت: یِتھٕ پٲٹھۍ کَرٕ بہٕ پننٮ۪ن خادمَن ہٕندِ خٲطرٕ، یُتھ نہٕ بہٕ تِم سارِنٕے تباہ کٔرِتھ۔\n9. تہٕ بہٕ کٔرٕ یعقوب سٍتـ̡ اَکھ بیٛول تہٕ یہوداہ سٍتـ̡ میانین پہاڑن ہُند وٲرث۔ تہٕ میٲنۍ منتخب گژھن اَتھ وٲرثس منز، تہٕ میٲنۍ خادم روزن اتہِ روزن۔\n10.\\tتہٕ شیرون آسہِ ریوُن ہُند اکھ گۅڈ، تہٕ اچورٕچ وادی آسہِ میانین لُکن ہٕندِ خٲطرٕ یِمو میانہِ ژھانڈنہٕ آمٕژ آسہِ۔\n11.\\tمگر تم چھہِ یُس خداوند تراوان چھہِ، یُس میون مقدس پہاڑ مٔشِد کران چھہِ، یُس اتھ فوجہِ خٲطرٕ میز تیار کران چھہِ، تہٕ یُس اتھ تعدادس شراب پیش کران چھہِ۔ {ٹروپ: یا، گاڈ} {نمبر: یا، مینی، اکھ کافر دیوتا}\n12. تێمہِ کِنۍ کٔرٕ بہٕ ژےٚ تلوارِ سٍتـ̡ گنزراونہٕ، تہٕ تۅہہ سارِوٕے کٔرِو ذبح کرنہٕ خٲطرٕ نمُن: کیازِ ییلہ میہ بُلاونہٕ آمُت، تہٕ ژے دِژ نہٕ جواب۔ ییلہ میہ کتھ کٔر، ژیہ بوز نہ۔ مگر میانین نظرن برونہہ کُن کٔر بد کار، تہٕ ژٲر {یہ} یتھ منز میہ خۅش گوو۔\n13. تێمہِ کِنۍ چُھ خداوند خدایہ یِتھٕ پٲٹھۍ ونان زِ وُچھِو میٲنۍ خادم کھٮ۪ن، مگر تُہۍ گژھہِ فاقہٕ تہٕ وُچھِو میٲنۍ خادم چیٚن، مگر تُہۍ گژھہِ ترش: وُچھِو میٲنۍ خادم خۅش گٔژھن، مگر تُہۍ گژھہِ شرمندٕ۔\n14.\\tوُچھِو میٲنۍ خادم دِل سٕندِ خوشی خٲطرٕ گٮ۪وُن، مگر تُہۍ کٔرِو دِل دِل کِس غمس خٲطرٕ فرٮ۪و، تہٕ روحہٕ سٕندِ پریشٲنی خٲطرٕ کرٛٮ۪کھ کٔرِو۔ {پریشانی: ہیب۔ بریکنگ}\n15. تہٕ تُہۍ تراوُن پنُن ناو میانِس ژٲرِس سٍتـ̡ لعنت، کیازِ خداوند خدا کرِ ژے مارُن، تہٕ پنہٕ نٕنـ̡ خدمتگارن بێیہِ ناوٕ سٍتـ̡ وَنُن:\n16. یُس زمینس مَنٛز پانس برکت دِوان چُھ، سُہ کرِ پانس سچٲیِس خدایس سٍتـ̡ برکت دِنہٕ۔ تہٕ یُس زمینس مَنٛز قَسم چُھ کَرُن سُہ سُہ سُہ خدایہِ سٕندِ سٍتـ̡ قَسم کَ تکیازِ گۅڈنچہ پریشانی چھیہ مشراونہ آمژ، تہ امہ مۅکھہ زِ یم چھہِ میانین اچھن نِش پوشید۔\n17. تکیازِ وچھو بہٕ نوو آسمان تہٕ اکھ نٔو زمین بناوان، تہٕ گۅڈنِچ ییہ نہٕ یاد تھاونہٕ، تہٕ نہ گژھہِ ذہنس منز یِنہٕ۔ {آ...: ہیب۔ دلس پیٹھ آو}\n18.\\tمگر یُس بہٕ تخلیق کران چھُس تہٕ یُس بہٕ تخلیق کران چھُس، یێلہِ بہٕ یروشلیم خۅش کران تہٕ تٔمۍ سٕندِس لُکن ہٕنز خوشی بناوان۔\n19. تہٕ بہٕ گژھہٕ یروشلمس مَنٛز شاد تہٕ پننین لوکن مَنٛز خوشی حٲصِل کٔرِتھ، تہٕ وَنُن ہٕنز آواز گژھہِ نہٕ تس مَنٛز بوزنہٕ، تہٕ روونٕچ آواز گژھہِ نہٕ۔\n20.\\tاَمہِ پتہٕ گژھِ نہٕ کانہہ بُزرگ یُس پنٕنـ̡ دۅہ بٔرِتھ آسہِ، تکیازِ شُر گژھہِ ہتھ وُہُر مرُن۔ مگر گۅنہگار {ہتھ وُہُر} گژھہِ لعنت۔\n21. تہٕ تِم گژھن مکانہٕ بَناوٕن، تہٕ روزَن {تِم}۔ تہٕ تِم کٔرِن انگور باغ، تہٕ تِمن ہُند پھل کھٮ۪ن۔\n22.\\tتِم گژھِ نہٕ تعمیر کٔرِتھ، تہٕ بییِس منز روزن۔ تِم گژھن نہٕ لاگُن، تہٕ بیاکھ کھٮ۪ن: تکیازِ کُلِس ہُند دۅہ چُھہ میانین لوکن ہُند دۅہ، تہٕ میانہِ منتخب گژھن واریاہس کالس پننین اتھن ہٕنزِ کامہِ ہُند لُطف۔ {شیل لانگ ...: ہیب۔ تِم کرِ واریاہس کالس جٲری روزُن، نتہٕ گٔژھِتھ گٔژھِن}\n23.\\tتِم گژھن نہٕ بیکار محنت کٔرِتھ تہٕ نہ گژھن مصیبت پٲدٕ کرنہٕ۔ تِکیازِ تِم چھِ خداوند سٕندِ بابرکت سٕندِ اولاد، تہٕ تِمن سٍتـ̡ تِہٕندِس اولاد۔\n24. تہٕ یِہ سپدِ زِ تِمن بُلاونہٕ برٛونٛہہ، بہٕ دِیہٕ جواب۔ تہٕ ییلہ تم وُنہِ تہِ کتھ کران چھِ، بہٕ بوز بہٕ۔\n25.\\tرامہٕ ہُند تہٕ کۅکرِ کھٮ۪نہٕ یِنہٕ یِنہٕ والہِ تہٕ سٕہہ کھٮ۪یہِ دانٛد ہیوٗ گاسہٕ تہٕ گردِ آسہِ ناگ سُند ماز۔ خداوند چُھ ونان زِ تِم گژھن نہٕ میٲنِس سارِنٕے مقدس پہاڑس مَنٛز تکلیف دِنہٕ تہٕ تباہ کرنہٕ۔","1. یِتھٕ پٲٹھـ̡ چُھہ خداوند ونان، اسمانُک تخت چُھہ میٲنۍ تخت، تہٕ زمین چُھہ میٲنۍ قدمن ہُند پٲٹھۍ: سُہ گرٕ کتہِ چُھہ یُس ژے میانہِ خٲطرٕ بناوان چُھ؟ تہٕ میانہِ آرام کرنٕچ جاے کَتہِ چھِ؟\n2. یِمن سارِنٕے {چیز} چِھہ میانہِ اتھہٕ سٍتـ̡ بنوومُت، تہٕ یِم سارِنٕے {چیز} چِھہ، خداوند چُھ فرماوان: مگر بہٕ چُھس یێمِس {انسان} کُن وُچھان، {حتیٰ کہ} یُس غریب تہٕ پشیمان روح چُھ، تہٕ میانہِ کلامَس سٍتـ̡ تھرتھر کرُن۔\n3.\\tیُس داند ماران چھہ سہ چھہ انسان ماران۔ یُس کُنہِ کۅکرِ ہُند قربانی دِوان چُھ، {یِتھٕ پٲٹھۍ} ژٹِتھ کٔرِتھ ہُونۍ سٕنز گردن ژٹِتھ۔ یُس قربانی دِوان چُھ، {یِتھٕ پٲٹھۍ چُھہ سُہ سورُک خوُن پیش کٔرِتھ}؛ یُس بخور زالان چُھ، {یِتھٕ پٲٹھۍ} تٔمۍ کُنہِ بُت برکت دِوان۔ آ، تِمو چُھ پنٕنۍ وتہٕ ژٲرمٕژ، تہٕ تِہُند روح چُھ پننین مکروہ چیزن پیٹھ خوش گژھان۔ {لیمب: یا، بچہ} {برنتھ: ہیب۔ اکھ یادگار بناوان}\n4. بہٕ تہِ کرٕ تِہُند وہم تہٕ تِمن ہُند خوف تہٕ تِمن پیٹھ اننہٕ۔ تکیازِ ییلہ میہ فون کٔرۍ، کٲنسہِ اوس نہ جواب دوان۔ ییلہ میہ کتھ کٔر، تِمو بوز نہٕ، مگر تِمو کٔر میانہِ نظرن برونہہ کُن بُر، تہٕ ژٲرکھ {یہ} یتھ منز میہ خۅش گوو۔{فریب : یا، آلات}\n5. خداوند سُند کلام بوزو، یُس تٔمۍ سٕندِس کلامس سٍتـ̡ تھران چُھ، تۅہہِ بٲے یِمو تۅہہِ سٍتـ̡ نفرت کٔرِتھ، یِمو میانہِ ناوٕ خٲطرٕ ژےٚ کٔڑِتھ کٔرِتھ، ووٚن زِ خداوند گژھہِ جلال حٲصل کرنہٕ، مگر سُہ گژھہِ تۅہہِ ہٕنزِ خوشی ہُند ظٲہر تہٕ تِم گژھن شرمندٕ۔\n6.\\tشہرٕ منزٕ شورٕچ آواز، مندرٕ منزٕ اکھ آواز، خداوند سٕنز آواز یُس پننین دُشمنن بدلہٕ دِوان چھُ۔\n7.\\tامہ برونہہ زِ سۅ کٔرِتھ دِژٕ۔ تٔمۍ سٕنٛز دَگ یِنہٕ برٛۄنٛہہ، أمِس زاے اکھ مرد شُر۔\n8.\\tیژھہ کتھ کٔمۍ بوزمٕژ؟ یِتھۍ چیز کٔمۍ چھِ وُچھمٕتۍ؟ کیا زمین ییہ اکہ دۅہس منز پٲدٕ کرنہٕ؟ {یا} کیا اکھ قوم یکوٹہٕ پٲدٕ گژھہٕ؟ تکیازِ ییلہ زیون مصیبت کٔر، سۅ کٔر پنٕنۍ شُرۍ۔\n9.\\tکیا بہٕ زیٚنہٕ خٲطرٕ اَننہٕ تہٕ زیٚنہٕ ہُند سبب نہٕ؟ خداوند چُھ ونان: کیا بہٕ کرٕ پٲدٕ تہٕ بند کرُن؟ تُہند خدایہ چُھ وَنان۔ {نہ...: یا، پیدٕ نہٕ؟}\n10. یروشلمس سٍتـ̡ خوش گژھو، تہٕ أمِس سٍتـ̡ گژھِو خۅش یُس أمِس سٍتـ̡ محبت کران چُھ، أمِس سٍتـ̡ کٔرِو خوشی مۅکھہٕ، یێلہِ سارِنٕے سٍتـ̡ یُس أمِس سٍتـ̡ ماتم کران چُھہ:\n11.\\tیُتھ ژیہ چوسُن، تہٕ تسٕندِس تسلی دِنہٕ سٍتـ̡ تسٕندِس سینس سٍتـ̡ تسلی دِنہٕ خٲطرٕ مطمئن۔ تاکہ تُہۍ گژھِو دۄدٕ کٔرِتھ، تہٕ تٔمۍ سٕنزِ عظمتٕچ کثرت سٍتۍ خۅش گٔژھِو۔ {کثرت: یا، چمک}\n12.\\tیِتھٕ پٲٹھـ̡ چُھہ خداوند فرماوان، وُچھِتھ بہٕ دِیہٕ أمِس دریاوٕکۍ پٲٹھۍ، تہٕ غیر قومن ہُند جلال یێلہِ وسوُن نالہٕ ہٕندۍ پٲٹھۍ، تێلہِ گژھہِ ژۆس، تہٕ یێلہِ کٔرِو تٔمِس کۅٹھن پیٹھ بٔرِتھ۔\n13. یِتھٕ پٲٹھۍ یٔمۍ سٕنزِ ماجہ تسلی دِوان چھِ، تِتھے پٲٹھۍ کٔرٕ بہٕ ژےٚ تسلی دِوان۔ تہٕ یروشلمس مَنٛز یِیہِ تسلی دِنہٕ۔\n14.\\tتہٕ یێلہِ یێلہِ تُہُند دِل خۅش گژھہِ، تہٕ تُہٕنزِ أڈجہِ گژھہِ کُلہِ ہٕندۍ پٲٹھۍ، تہٕ خداوند سُند اَتھٕ گژھہِ پننین بندن سٍتـ̡ زاننہٕ، تہٕ تٔمۍ سٕندِس دُشمنن سٍتـ̡ گژھہِ غصہٕ۔\n15. یێلہِ زِ خداوند ییہ نارٕ ہیتھ تہٕ پنٕنـ̡ رتھن ہٕندِ پٲٹھۍ، یێلہِ پَنُن غصہٕ سٍتـ̡ تہٕ تٔمۍ سٕنز ملامت نارٕ سٍتـ̡ دِنہٕ۔\n16.\\tیِکیازِ نار تہٕ تلوار سٍتـ̡ کرِ خداوند سارِنٕے مازس سٍتـ̡ درخواست کرنہٕ: تہٕ خداوند سٕندِ مارنہٕ یِنہٕ وٲلِس سٍتـ̡ گژھہِ واریاہ زیادٕ۔\n17. یُس پانس پاک کران چُھ، تہٕ پانس پاکیزہ کٔرِتھ باغس مَنٛز، سورُک ماز کھٮ۪وان، تہٕ مکروہ تہٕ گگر یِن اِکہٕ وٹہٕ کھٮ۪نہٕ، خداوند چُھ فرماوان۔ {پَتہٕ...: یا، اَکہِ پتہٕ اَکہِ}\n18.\\tکیازِ بہٕ چُھس تِہٕنزِ کٲم تہٕ تِہٕندِس خیالس زانان: یِہ گژھہِ یِنہٕ تہٕ بہٕ سارِنٕے قومن تہٕ زبانہٕ جمع کٔرِتھ۔ تہٕ تِم یِن تہٕ میٲنۍ جلال وُچھن۔\n19.\\tتہٕ بہٕ سوزٕ تِمن مَنٛز اکھ نشانہٕ، تہٕ یِمو منزٕ ژلنہٕ یِنہٕ وٲلِس قومن کُن، ترشِش، پُل تہٕ لُد، یِم کمان کھینِتھ چھِ، تُبَل تہٕ جاوان، یِمو نہٕ میٲنۍ شہرت بوزمٕژ آسہِ، تہٕ نہ چھُ میون جلال وُچھمُت۔ تہٕ تِم کرن غیر قومن مَنٛز میانہِ جلال ہُند اعلان۔\n20. تہٕ تِم أنِن تُہٕندِس سارِنٕے بٲے سارِوٕے قومن منزٕ گُرٮ۪ن تہٕ رتھَن منز، تہٕ خچرن پیٹھ، تہٕ تیز درندرن پیٹھ، میٲنِس مقدس پہاڑ یروشلمس کُن نذرانہ انن، یِتھ کٔنۍ زن بنی اسرائیل خداوند سٕندِس گرس مَنٛز پاک بانس مَنٛز نذرانہ انان۔ {لٹرز: یا، کوچز}\n21. تہٕ بہٕ نِہ تِمن منز پادٕرین ہٕندِ خٲطرٕ تہٕ لاوِین ہٕندِ خٲطرٕ، خداوند چُھ فرماوان۔\n22. یِتھٕ پٲٹھـ̡ نۆو آسمانہٕ تہٕ نٔو زمین، یُس بہٕ بناوُن، یێلہِ روزِ میانہِ برونہہ کُن، خداوند چُھ ونان تِتھے پٲٹھـ̡ روزِ تُہند اولاد تہٕ تُہند ناو روزُن۔\n23. تہٕ یہِ گژھہِ سپدِ، اَکہِ نوِ زوٗنہِ پیٹھٕ بییِس زوٗنہِ تام، تہٕ اَکہِ سبت پیٹھٕ بییِس سبت تام، سارِنٕے ماز گژھہِ میانہِ برونہہ کُن عبادت کرنہٕ، خداوند چُھ فرماوان۔ {اَکہِ نٔوِس پیٹھ...: ہیب۔ نوِ زوٗنہِ پیٹھٕ تٔمۍ سٕنزِ نوِ زوٗنہِ تام، تہٕ سبت پیٹھٕ سبت تام}\n24. تہٕ تِم گژھن نیرِ، تہٕ یِمن نفرن ہٕندِس لاشہٕ وُچھِن یِمو میانہِ خلاف زیادتی کٔرمٕژ چھِ، تِکیازِ تِہُند کیمہٕ گژھِ نہٕ مَرُن، تہٕ تِہُند نار گژھہِ نہٕ ژھیتہٕ۔ تہٕ تِم گژھن سارِنٕے ماز سٍتـ̡ نفرت۔"];
